window.ARH_LESSONS = [
  {"id": 1, "title": "Числа-перевёртыши", "src": "ВсОШ 2023/24 · 6 класс · №3", "ico": "🔁", "explain": ["Аня записала трёхзначное число, Яна — то же число наоборот. Сумма получилась 443. Как найти разность?", "Запишем число Ани буквами: АБВ. Это не произведение, а разрядная запись: А сотен, Б десятков, В единиц.", "Сложим: АБВ + ВБА = (100А+В)+(100В+А) + 20Б = 101·(А+В) + 20·Б.", "Последняя цифра суммы 443 — тройка. Значит, А+В оканчивается на 3, но А+В < 10 (переносов нет) → А+В = 3.", "Числа: 172 и 271. Разность = 271 − 172 = 99. Заметь: 99 = 99·(В − А) — разность ВСЕГДА кратна 99!", "Проверь сам: разность любых перевёртышей = 99·(разность крайних цифр). Покрути цифры и убедись: 99, 198, 297…"], "check": {"q": "Разность трёхзначного числа и его перевёртыша всегда делится на…", "choices": ["9", "11", "99", "100"], "ans": 2, "exp": "99·(А−В): сотни и единицы «съедают» друг друга, остаётся кратное 99."}, "tasks": [{"q": "Сумма числа и его перевёртыша равна 303. Найдите разность большего и меньшего чисел.", "kind": "choice", "choices": ["99", "108", "297", "1010"], "ans": 0, "unit": null, "hints": ["303 = 101·(А+В) + 20·Б — подбери Б.", "303 − 20·Б должно делиться на 101: Б = 0, А+В = 3.", "А+В = 3 → крайние цифры 1 и 2 → разность 99."], "sol": "303 = 101·3 + 20·0 → А+В=3, Б=0 → числа 102 и 201, разность 99."}, {"q": "Разность числа и его перевёртыша равна 396. Чему равна разность крайних цифр (|А − В|)?", "kind": "unit", "unit": "", "ans": 4, "tol": 0, "hints": ["Разность всегда равна 99·(А − В).", "396 : 99 = ?", "396 : 99 = 4."], "sol": "396 = 99·4 → |А − В| = 4. Например, 513 и 315."}], "subj": "math"},
  {"id": 2, "title": "Голуби и клетки — Дирихле", "src": "приём ВсОШ · «гарантированно»", "ico": "🕊", "explain": ["Классика: 10 голубей, 7 клеток. Архимед спрашивает: сколько голубей ГАРАНТИРОВАННО окажутся в одной клетке?", "Чтобы «избежать» совпадения, сажаем голубей по одному в каждую клетку: 7 голубей — 7 клеток, нигде нет пары.", "Принцип Дирихле: если n предметов разложить по m ячейкам и n > m, то хотя бы в одной ячейке не меньше ⌈n/m⌉ предметов.", "Почему «гарантированно»? Самое «равномерное» размещение — по одному. Если и при нём есть пара — пара будет всегда.", "Тренировка глаза: 13 носков, 6 цветов → в какой-то паре цветов минимум ⌈13/6⌉ = 3 носка одного цвета."], "check": {"q": "25 учеников, 12 месяцев рождения. Сколько учеников гарантированно родились в один месяц?", "choices": ["2", "3", "12", "13"], "ans": 1, "exp": "⌈25/12⌉ = 3: даже при самых «честных» 12 месяцах (по 2 ученика) останется 25−24 = 1 лишний."}, "tasks": [{"q": "В классе 28 учеников. Сколько учеников гарантированно родились в один и тот же месяц?", "kind": "unit", "unit": "", "ans": 3, "tol": 0, "hints": ["Предметы — ученики, ячейки — месяцы (их 12).", "⌈28/12⌉ = ?", "28 : 12 = 2,33… → округляем вверх: 3."], "sol": "⌈28/12⌉ = 3. Даже если в каждый месяц попало бы не больше 2, поместилось бы лишь 24 — значит, где-то есть 3."}, {"q": "В коробке 40 карандашей 7 цветов. Сколько карандашей одного цвета гарантированно найдётся?", "kind": "unit", "unit": "", "ans": 6, "tol": 0, "hints": ["Ячейки — цвета (7), предметы — карандаши (40).", "⌈40/7⌉ = ?", "40 : 7 = 5,71… → 6."], "sol": "⌈40/7⌉ = 6: если бы каждого цвета было не больше 5, всего было бы не больше 35 < 40."}], "subj": "math"},
  {"id": 3, "title": "Улитки в ячейках", "src": "ВсОШ 2023/24 · 6 класс · №2", "ico": "🐌", "explain": ["В вершинах семиугольника — ячейки. В одну положили 64 улитки. Каждый час улитки каждой ячейки поровну расходятся в две соседние.", "Час 1: из стартовой ячейки 32 улитки ушли влево и 32 вправо. В ней самой — 0.", "Час 2: из каждой занятой ячейки снова делим пополам. Видишь закономерность: заняты только «чётные» позиции от старта.", "Час 3, час 4, час 5… Не гадай — просто «прокрути» процесс и выпиши числа.", "Через 5 часов в оранжевой ячейке (на расстоянии трёх шагов от старта — через две промежуточные вершины) оказалось 10 улиток — это и есть ответ задачи ВсОШ."], "check": {"q": "В процессе «улитки расходятся пополам» сумма улиток во всех ячейках…", "choices": ["растёт", "падает", "не меняется", "зависит от формы"], "ans": 2, "exp": "Половина ушла влево, половина вправо — ничего не потерялось: сумма постоянна (здесь 64)."}, "tasks": [{"q": "Шестиугольник, 64 улитки в одной вершине. Через 4 часа сколько улиток в противоположной вершине? Подумай о чётности!", "kind": "choice", "choices": ["0", "10", "20", "32"], "ans": 0, "unit": null, "hints": ["После нечётного часа заняты «нечётные» вершины, после чётного — «чётные».", "4 часа — чётное число: заняты вершины с чётным номером от старта.", "Противоположная вершина имеет НЕчётный номер → пуста."], "sol": "При чётном числе часов улитки только в вершинах с чётным номером от старта; противоположная — нечётная → там 0."}, {"q": "Семиугольник, 128 улиток в стартовой вершине. Через 5 часов сколько улиток в вершине «через две» (как в примере)?", "kind": "unit", "unit": "", "ans": 20, "tol": 0, "hints": ["В примере было 64 улитки → 10. Улиток стало вдвое больше (128).", "Процесс линеен: всё вырастет в 2 раза.", "10 · 2 = 20."], "sol": "Удвоение старта удваивает все числа по шагам: было 10 при 64, станет 20 при 128."}], "subj": "math"},
  {"id": 4, "title": "Конфеты: чёт — правда, нечёт — ложь", "src": "ВсОШ 2023/24 · 6 класс · №6", "ico": "🍬", "explain": ["Ваня, Стёпа и Лёша взяли конфеты. Правило: взявший НЕчётное число — соврал, взявший чётное — сказал правду. Кто сколько взял?", "Шаг 1. Смотрим на Лёшу. Он говорит «я взял одну». Если бы он сказал правду, у него было бы чётное число — но 1 нечётное. Противоречие!", "Шаг 2. Допустим, Стёпа прав (у него чётное). Тогда «вместе нечётное» — правда. Но Ваня сказал «вместе 6» — тогда Ваня соврал (у него нечётное).", "Шаг 3. Значит, Стёпа соврал (у него нечётное), а «вместе нечётное» — ложь: вместе ЧЁТНОЕ число. Тогда Ваня прав (у него чётное, вместе 6).", "Шаг 4. Единственный вариант: Лёша 3, Стёпа 1, Ваня 2. Проверяем: 3 нечёт → Лёша соврал ✓, 1 нечёт → Стёпа соврал ✓, 2 чёт → Ваня прав ✓."], "check": {"q": "Почему Лёша не мог сказать правду?", "choices": ["он жадный", "1 — нечётное, а правду говорят только с чётным числом", "он сказал два слова", "6 делится на 2"], "ans": 1, "exp": "Правда доступна только владельцу чётного числа, а фраза «у меня 1» требует числа 1 — нечётного. Противоречие."}, "tasks": [{"q": "В примере сколько конфет оказалось у Лёши?", "kind": "unit", "unit": "", "ans": 3, "tol": 0, "hints": ["Лёша соврал → у него нечётное, не 1.", "Сумма у всех — 6.", "3 + 1 + 2 = 6 — единственный расклад."], "sol": "Лёша 3, Стёпа 1, Ваня 2. Проверь по правилу чётности — всё сходится."}, {"q": "А сказал: «У нас вместе 5 конфет». Б сказал: «Я взял одну». Правило то же: чёт — правда, нечёт — ложь. Могут ли оба говорить правду?", "kind": "choice", "choices": ["Да", "Нет"], "ans": 1, "unit": null, "hints": ["Если оба правы — у обоих чётное число конфет.", "Сумма двух чётных чисел — чётная.", "А утверждает нечётную сумму 5 — противоречие!"], "sol": "Правда → чётные количества → сумма чётная. Но А говорит «5» — нечётное. Значит, оба правы быть не могут."}], "subj": "math"},
  {"id": 5, "title": "Круговой турнир", "src": "ВсОШ 2023/24 · 6 класс · №8", "ico": "♟", "explain": ["5 школьников сыграли круговой турнир: каждый с каждым — по разу. Победа 5 очков, ничья — по 2. Всего набрано 46 очков.", "Шаг 1. Победы Насти: не меньше 2 (на 2 больше Саши, а у Саши не меньше 0). Юля сыграла 4 партии, значит побед у неё не больше 4; раз Юля опережает Настю на 2, у Насти побед не больше 2.", "Шаг 2. Оценка с двух сторон: не меньше 2 и не больше 2 — значит, у Насти ровно 2 победы, у Юли 4, у Саши 0. Проверка: 2 победы по 5 очков и 2 ничьи по 2 очка дают Насте 12 очков — сходится с подсчётом ниже.", "Шаг 3. Считаем очки: Настя 2·5 + 2 + 0 = 12. Юля 4·5 = 20. Вместе 32.", "Приём: «оценка с двух сторон» — победы не меньше X и не больше X → ровно X. Потом честный подсчёт очков."], "check": {"q": "Сколько всего партий сыграно в турнире из 5 игроков (каждый с каждым)?", "choices": ["5", "10", "20", "25"], "ans": 1, "exp": "Пар — C(5,2) = 5·4/2 = 10: из каждого игрока выходит 4 партии, но каждая посчитана дважды."}, "tasks": [{"q": "Турнир играли Настя, Юля, Саша и ещё двое — Антон и Гордей. Всего набрано 46 очков. Сколько очков набрали Антон и Гордей вместе?", "kind": "unit", "unit": "", "ans": 14, "tol": 0, "hints": ["Сначала очки Насти: 2 победы + 1 ничья + 1 поражение.", "Настя 12, Юля 20 — вместе 32.", "46 − 32 = ?"], "sol": "Настя: 2·5+2+0 = 12; Юля: 4·5 = 20; остальные: 46 − 32 = 14."}, {"q": "В другом турнире из 6 игроков каждый сыграл с каждым один раз. Сколько всего было партий?", "kind": "unit", "unit": "", "ans": 15, "tol": 0, "hints": ["Каждый из 6 сыграл с 5 другими.", "Но партия посчитана дважды (А с Б и Б с А).", "6·5/2 = ?"], "sol": "6·5/2 = 15 партий — классический подсчёт «рукопожатий»."}], "subj": "math"},
  {"id": 6, "title": "Оценка и пример: посёлки", "src": "ВсОШ 2025/26 · 6 класс · №7", "ico": "🏘", "explain": ["100 посёлков с номерами 1…100. Дорога между двумя есть, если сумма номеров делится на 5. Минимум дорог добавить, чтобы все были связаны?", "Пары остатков, дающие в сумме 0 (mod 5): (0,0), (1,4), (2,3). Вот и вся «карта дорог»!", "Значит, сеть распадается на 3 «острова»: кратные 5; остатки 1 и 4; остатки 2 и 3. Внутри острова — всё связано, между островами — ничего.", "Оценка: чтобы связать 3 отдельных острова, нужно минимум 3 − 1 = 2 дороги.", "Пример: построили 2 дороги между островами — теперь из любого посёлка можно добраться до любого. Оценка + пример = ответ 2."], "check": {"q": "На сколько «островов» распадается сеть посёлков в примере?", "choices": ["2", "3", "5", "100"], "ans": 1, "exp": "Острова: {кратные 5}, {остатки 1 и 4}, {остатки 2 и 3} — всего 3 компоненты."}, "tasks": [{"q": "Сколько компонент связности в сети посёлков 1…100 (делимость на 5)?", "kind": "unit", "unit": "", "ans": 3, "tol": 0, "hints": ["Пары остатков с суммой, кратной 5: (0,0), (1,4), (2,3).", "Остаток 0 — остров; 1∪4 — остров; 2∪3 — остров.", "Их три."], "sol": "Три компоненты: кратные 5; остатки 1 и 4; остатки 2 и 3."}, {"q": "Посёлки с номерами 1…20: дорога, если сумма номеров делится на 4. Какое минимальное число дорог надо добавить, чтобы связать все посёлки?", "kind": "unit", "unit": "", "ans": 2, "tol": 0, "hints": ["Пары остатков mod 4 с суммой 0: (0,0), (1,3), (2,2).", "Острова: {0}, {2}, {1 и 3} — три компоненты.", "Три острова связывают 2 дорогами."], "sol": "Три компоненты → нужно 2 дороги. Оценка: меньше нельзя (дорога склеивает максимум два острова)."}], "subj": "math"},
  {"id": 7, "title": "Переливания", "src": "классика · переливания", "ico": "🫗", "explain": ["Кувшины 3 л и 5 л, отмерить ровно 4 л. Секрет — переливать, пока источник не опустеет или приёмник не наполнится.", "План: 1) наполни 5 л; 2) перелей в 3 л — в 5 л осталось 2; 3) вылей 3 л; 4) перелей 2 л из 5 л в 3 л; 5) наполни 5 л; 6) долей 3 л доверху — в 5 л останется 4 л.", "Так работают все переливания: меняй, что в кувшинах, по шагам и следи за остатками.", "Если есть большая кастрюля, можно копить литры: 5 л в кастрюлю, потом отмерь ещё 1 л и долей — получится 6 л."], "check": {"q": "Можно ли кувшинами 3 л и 5 л отмерить ровно 4 л?", "choices": ["Нет", "Да"], "ans": 1, "exp": "Да: 5→3, вылей 3, 2→3, набери 5, долей в 3 — в 5 останется 4."}, "tasks": [{"q": "Сколько шагов (налить/перелить/вылить) нужно, чтобы отмерить ровно 4 л кувшинами 3 л и 5 л?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["1) набери 5 л; 2) перелей в 3 л — остаток 2 л;", "3) вылей 3 л; 4) перелей 2 л в 3 л;", "5) набери 5 л; 6) долей в 3 л — осталось 4 л."], "sol": "6 шагов: налить 5, перелить в 3, вылить 3, перелить 2, налить 5, долить в 3 → в 5 остаётся 4 л."}, {"q": "Можно ли, имея кувшины 3 л и 5 л и большую кастрюлю, отмерить ровно 7 л?", "kind": "choice", "choices": ["Нет", "Да"], "ans": 1, "tol": 0, "hints": ["7 = 5 + 2.", "2 л отмеряем кувшинами: 5→3, остаток 2 л.", "Вылей 5 л в кастрюлю и добавь отмеренные 2 л."], "sol": "Да: 5 л в кастрюлю + 2 л (остаток после 5→3) = 7 л."}], "subj": "math"},
  {"id": 8, "title": "Взвешивания: фальшивая монета", "src": "классика · взвешивания", "ico": "⚖️", "explain": ["Одна монета фальшивая и легче. Чашечные весы без гирь — сравниваем кучки.", "Из 3 монет: положи по одной на чашки. Если весы в равновесии — фальшивая третья, иначе — лёгкая на поднявшейся чашке. Одно взвешивание!", "Из 9 монет: раздели на 3 кучки по 3. Взвесь две кучки — узнаешь, где лёгкая, потом за 1 взвешивание найди её внутри кучки. Итого 2.", "Каждое взвешивание делит варианты на 3 части. 9 монет = 3² → 2 взвешивания, 27 монет = 3³ → 3 взвешивания."], "check": {"q": "Среди 3 монет одна легче. Сколько взвешиваний нужно минимум?", "choices": ["1", "2", "3"], "ans": 0, "exp": "Одно: взвесь две — равновесие или лёгкая чашка укажут фальшивку."}, "tasks": [{"q": "Среди 9 монет одна легче. Сколько взвешиваний минимум?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Раздели 9 на 3 кучки по 3.", "Взвесь две кучки — найдёшь нужную тройку.", "В тройке фальшивку найдёт ещё одно взвешивание."], "sol": "9 = 3² → 2 взвешивания: 3 кучки по 3, затем 1 взвешивание в найденной кучке."}, {"q": "Среди 27 монет одна легче. Сколько взвешиваний минимум?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["27 = 3·9.", "Сначала найди девятку с фальшивкой — 1 взвешивание.", "Потом как в задаче про 9 монет — ещё 2."], "sol": "27 = 3³ → 3 взвешивания."}], "subj": "math"},
  {"id": 9, "title": "Делимость: признаки", "src": "ВсОШ-стиль · делимость", "ico": "➗", "explain": ["Признаки делимости: на 2 — чётное, на 5 — кончается на 0 или 5, на 3 — сумма цифр делится на 3, на 9 — сумма цифр делится на 9.", "Пример: 1236. Сумма цифр 1+2+3+6 = 12, 12 делится на 3 → 1236 делится на 3.", "Признаки на 3 и 9 работают всегда: число и его сумма цифр дают один и тот же остаток при делении на 3 и на 9.", "Полезно при олимпиадных вопросах «делится или нет?» — не считай в столбик, считай сумму цифр."], "check": {"q": "Делится ли 7 236 на 3?", "choices": ["Нет", "Да"], "ans": 1, "exp": "7+2+3+6 = 18, 18 делится на 3 → делится."}, "tasks": [{"q": "Сколько чисел от 1 до 100 делятся на 6?", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Числа, кратные 6: 6, 12, …, 96.", "96 : 6 = 16."], "sol": "Кратные 6 до 100: 96 : 6 = 16 чисел."}, {"q": "Делится ли 2 019 на 9?", "kind": "choice", "choices": ["Да", "Нет"], "ans": 1, "tol": 0, "hints": ["Сложи цифры: 2+0+1+9 = 12.", "12 не делится на 9.", "Значит, 2019 не делится на 9."], "sol": "2+0+1+9 = 12, 12 не кратно 9 → не делится."}], "subj": "math"},
  {"id": 10, "title": "Средняя скорость", "src": "физика-стиль · движение", "ico": "🚴", "explain": ["Средняя скорость — НЕ среднее арифметическое скоростей! Это весь путь, делённый на всё время.", "Если полпути ехали 30 км/ч, а вторую половину 20 км/ч: средняя = 2·30·20/(30+20) = 24 км/ч.", "Формула для двух равных половин пути: v = 2·v₁·v₂/(v₁+v₂) — гармоническое среднее.", "Всегда проверяй: средняя скорость меньше, чем (v₁+v₂)/2, ведь на медленном участке время больше."], "check": {"q": "Половину пути ехали 12 км/ч, половину — 6 км/ч. Средняя скорость?", "choices": ["8", "9", "12", "18"], "ans": 0, "exp": "2·12·6/(12+6) = 144/18 = 8 км/ч."}, "tasks": [{"q": "Половину пути 30 км/ч, половину 20 км/ч. Найди среднюю скорость.", "kind": "unit", "ans": 24, "tol": 0.05, "hints": ["v = 2·v₁·v₂/(v₁+v₂).", "2·30·20 = 1200; 30+20 = 50.", "1200 : 50 = 24."], "sol": "v = 2·30·20/(30+20) = 1200/50 = 24 км/ч."}, {"q": "Половину пути 40 км/ч, половину 60 км/ч. Средняя скорость?", "kind": "unit", "ans": 48, "tol": 0.05, "hints": ["2·40·60 = 4800; 40+60 = 100.", "4800 : 100 = 48."], "sol": "v = 2·40·60/(40+60) = 4800/100 = 48 км/ч."}], "subj": "phys"},
  {"id": 11, "title": "Рукопожатия", "src": "классика · комбинаторика", "ico": "🤝", "explain": ["10 человек пожали друг другу руки по одному разу. Сколько всего рукопожатий?", "Каждый жмёт руку 9 другим, но рукопожатие считает двое — делим на 2: 10·9/2 = 45.", "Формула: n человек → n·(n−1)/2 рукопожатий.", "Это же число «пар»: сколько пар из класса, сколько матчей в турнире в один круг и т.п."], "check": {"q": "Сколько рукопожатий, если 10 человек пожали друг другу руки?", "choices": ["45", "90", "100"], "ans": 0, "exp": "10·9/2 = 45."}, "tasks": [{"q": "Сколько рукопожатий среди 12 человек?", "kind": "unit", "ans": 66, "tol": 0, "hints": ["Каждый из 12 жмёт руку 11 другим.", "12·11 = 132 — но каждое рукопожатие посчитано дважды.", "132 : 2 = 66."], "sol": "12·11/2 = 66 рукопожатий."}, {"q": "Сколько рукопожатий среди 8 человек?", "kind": "unit", "ans": 28, "tol": 0, "hints": ["8·7 = 56.", "Делим на 2."], "sol": "8·7/2 = 28 рукопожатий."}], "subj": "math"},
  {"id": 12, "title": "Остатки при делении", "src": "ВсОШ-стиль · остатки", "ico": "🧮", "explain": ["Остаток — то, что остаётся после деления: 17 : 5 = 3 и остаток 2. Числа с одинаковым остатком удобно группировать.", "Сколько чисел от 1 до 40 дают остаток 2 при делении на 5? Это 2, 7, 12, …, 37 — каждое пятое число.", "Считаем по шагам: (последнее − первое) : 5 + 1 = (37 − 2) : 5 + 1 = 7 + 1 = 8 чисел.", "Остатки решают задачи «делится на», расписания и перекладывания: группируй по остатку — как в задаче про посёлки.", "Проверь иначе: остаток 2 при делении на 5 дают числа, оканчивающиеся на 2 или 7. Посчитай их от 1 до 40 — снова 8."], "check": {"q": "Остаток при делении 47 на 5 равен…", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "45 делится на 5, значит 47 − 45 = 2."}, "tasks": [{"q": "Сколько чисел от 1 до 40 дают остаток 2 при делении на 5?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Это числа 2, 7, 12, …, 37.", "Шаг 5: (37 − 2) : 5 + 1", "35 : 5 + 1 = 8."], "sol": "(37 − 2)/5 + 1 = 8 чисел с остатком 2."}, {"q": "Сколько чисел от 1 до 100 делятся на 7?", "kind": "unit", "ans": 14, "tol": 0, "hints": ["Это кратные 7: 7, 14, …, 98.", "98 : 7 = 14.", "Ответ: 14 чисел."], "sol": "Кратные 7 до 100: 98 : 7 = 14 чисел."}], "subj": "math"},
  {"id": 13, "title": "Чётность: суммы и произведения", "src": "классика · чёт-нечёт", "ico": "🔀", "explain": ["Правила: чёт + чёт = чёт, нечёт + нечёт = чёт, чёт + нечёт = нечёт. Произведение чётно, если ХОТЯ БЫ один множитель чётный.", "Почему важно? Задачи «можно ли?» решаются проверкой чётности до и после действия.", "Сумма 1+2+…+99: среди чисел от 1 до 99 нечётных ровно 50. Сумма 50 нечётных — чётная (пары 1+3, 5+7…).", "Произведение 1·2·3·…·100 содержит множитель 2, поэтому оно чётное — даже проверять не надо.", "Следи за чётностью количества: нечётное число нечётных слагаемых даёт нечётную сумму."], "check": {"q": "Сумма двух нечётных чисел…", "choices": ["чётная", "нечётная"], "ans": 0, "exp": "Нечёт + нечёт = чёт: например, 3+5=8."}, "tasks": [{"q": "Сумма 1+2+3+…+99 — чётная или нечётная?", "kind": "choice", "choices": ["Чётная", "Нечётная"], "ans": 0, "tol": 0, "hints": ["Сколько среди чисел 1..99 нечётных?", "Их 50 — сумма чётна (пары 1+3, 5+7…)."], "sol": "Нечётных 50 → сумма чётная. (По формуле: 99·50 = 4950 — чётное.)"}, {"q": "Произведение 1·2·3·…·100 чётно?", "kind": "choice", "choices": ["Да", "Нет"], "ans": 0, "tol": 0, "hints": ["Среди множителей есть 2.", "Произведение с чётным множителем — чётное."], "sol": "Множитель 2 делает произведение чётным."}], "subj": "math"},
  {"id": 14, "title": "Сколько прямоугольников", "src": "ВсОШ-стиль · клетки", "ico": "▦", "explain": ["Сколько прямоугольников (по линиям сетки) в прямоугольнике 3×4 клетки? Считать вручную — долго, есть формула.", "Прямоугольник задаётся парой вертикальных и парой горизонтальных линий сетки.", "Линий вертикальных: 4 (у 3 клеток), горизонтальных: 5. Пар вертикальных: 4·3/2 = 6, пар горизонтальных: 5·4/2 = 10.", "Прямоугольников: 6·10 = 60. Формула для доски n×m клеток: C(n+1,2)·C(m+1,2).", "Проверь на полоске 1×3: вертикальных пар C(2,2)=1, горизонтальных C(4,2)=6 → 6 прямоугольников: 3 «одинарных», 2 «двойных», 1 «тройной»."], "check": {"q": "Сколько прямоугольников в полоске 1×3 клетки?", "choices": ["3", "6", "9", "12"], "ans": 1, "exp": "C(2,2)·C(4,2) = 1·6 = 6."}, "tasks": [{"q": "Сколько прямоугольников (по линиям сетки) в прямоугольнике 2×3 клетки?", "kind": "unit", "ans": 18, "tol": 0, "hints": ["Вертикальных линий 3, горизонтальных 4.", "Пар вертикальных C(3,2)=3, горизонтальных C(4,2)=6.", "3·6 = 18."], "sol": "C(3,2)·C(4,2) = 3·6 = 18 прямоугольников."}, {"q": "Сколько прямоугольников в квадрате 4×4 клетки?", "kind": "unit", "ans": 100, "tol": 0, "hints": ["Линий по 5 в каждом направлении.", "Пар: C(5,2)=10 и C(5,2)=10.", "10·10 = 100."], "sol": "C(5,2)·C(5,2) = 10·10 = 100."}], "subj": "math"},
  {"id": 15, "title": "Встреча и погоня", "src": "ВсОШ-стиль · движение", "ico": "🏃", "explain": ["Навстречу — скорости складываются: время встречи = расстояние ÷ (v₁+v₂).", "Пример: 90 км, навстречу 20 и 25 км/ч → скорость сближения 45, время 90:45 = 2 часа.", "Погоня: если один догоняет другого, скорости вычитаются: время = разрыв ÷ (v₁−v₂).", "По течению реки скорость складывается с течением, против — вычитается: v+u и v−u.", "Если по течению 18, а против 12: (18+12)/2 = 15 — собственная скорость, (18−12)/2 = 3 — скорость течения."], "check": {"q": "Два бегуна бегут навстречу, расстояние 10 км, скорости 3 и 2 км/ч. Через сколько часов встретятся?", "choices": ["1", "2", "3", "5"], "ans": 1, "exp": "10:(3+2) = 2 часа."}, "tasks": [{"q": "Расстояние 90 км, навстречу едут 20 км/ч и 25 км/ч. Через сколько часов встретятся?", "kind": "unit", "ans": 2, "tol": 0.05, "hints": ["Скорость сближения 20+25 = 45 км/ч.", "90 : 45 = 2."], "sol": "t = 90:(20+25) = 90:45 = 2 часа."}, {"q": "Катер по течению идёт 18 км/ч, против течения 12 км/ч. Какова скорость течения (км/ч)?", "kind": "unit", "ans": 3, "tol": 0.05, "hints": ["Собственная скорость v, течение u: v+u=18, v−u=12.", "Сложи уравнения: 2v=30 → v=15.", "u = 18−15 = 3."], "sol": "(18−12):2 = 3 км/ч — скорость течения."}], "subj": "math"},
  {"id": 16, "title": "Проценты: скидки и наценки", "src": "ВсОШ-стиль · проценты", "ico": "🏷️", "explain": ["Процент — сотая доля: 20% это 0,2. Скидка 20% от 2000 = 2000·0,2 = 400, новая цена 1600.", "Скидки и наценки применяются К ТЕКУЩЕЙ цене — последовательно!", "Пример: цена 2000, наценка +10% → 2200; затем скидка −10% уже от 2200 → 2200·0,9 = 1980.", "Заметь: +10% и потом −10% — НЕ возвращают к 2000, получается 1980. Проценты «работают» от новой базы.", "Считай в два шага: сначала новый процент от текущей цены, потом вычитай/прибавляй."], "check": {"q": "Цена 100, наценка +20%. Новая цена?", "choices": ["120", "80", "102", "200"], "ans": 0, "exp": "100·1,2 = 120."}, "tasks": [{"q": "Товар стоил 2000, скидка 20%. Новая цена?", "kind": "unit", "ans": 1600, "tol": 0, "hints": ["20% от 2000 = 400.", "2000 − 400 = 1600."], "sol": "2000·0,8 = 1600."}, {"q": "Цена 2000: сначала +10%, затем −10% от новой. Итоговая цена?", "kind": "unit", "ans": 1980, "tol": 0, "hints": ["+10% → 2200.", "−10% от 2200 = 220.", "2200 − 220 = 1980."], "sol": "2000·1,1 = 2200; 2200·0,9 = 1980."}], "subj": "math"},
  {"id": 17, "title": "Дни недели и остатки", "src": "ВсОШ-стиль · остатки", "ico": "📅", "explain": ["Дни недели повторяются каждые 7 дней — это «часы с 7 делениями». Через 7 дней будет тот же день.", "Через 10 дней = через 1 неделю + 3 дня: день сдвинется на 3.", "Сегодня понедельник (№1). Через 10 дней: 1 + 10 = 11; 11 − 7 = 4 → четвёртый день — четверг.", "Удобно считать остаток от деления числа дней на 7: 10 = 7·1 + 3, значит +3 дня.", "Через 30 дней: 30 = 7·4 + 2 → +2 дня от понедельника → среда."], "check": {"q": "Сегодня понедельник. Какой день будет через 7 дней?", "choices": ["Понедельник", "Вторник", "Суббота", "Воскресенье"], "ans": 0, "exp": "7 дней — полная неделя, день тот же."}, "tasks": [{"q": "Сегодня понедельник. Какой день будет через 10 дней?", "choices": ["Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота", "Воскресенье"], "ans": 3, "tol": 0, "hints": ["10 = 7 + 3 — сдвиг на 3 дня.", "Понедельник +3 = четверг."], "sol": "10 ≡ 3 (по модулю 7): понедельник + 3 дня = четверг.", "kind": "choice"}, {"q": "Сегодня понедельник. Какой день будет через 30 дней?", "choices": ["Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота", "Воскресенье"], "ans": 2, "tol": 0, "hints": ["30 = 28 + 2 — сдвиг на 2 дня.", "Понедельник + 2 = среда."], "sol": "30 ≡ 2 (mod 7): понедельник + 2 дня = среда.", "kind": "choice"}], "subj": "math"},
  {"id": 18, "title": "Квадраты и кубы", "src": "классика · степени", "ico": "🟩", "explain": ["Квадрат числа — число, умноженное на себя: 5² = 25. Куб — умноженное трижды: 2³ = 8.", "Точные квадраты до 100: 1, 4, 9, 16, 25, 36, 49, 64, 81, 100 — это квадраты 1..10, их 10.", "Кубы до 100: 1, 8, 27, 64 — это кубы 1..4, их 4. Дальше 5³=125 уже больше 100.", "Полезно знать наизусть квадраты до 15 и кубы до 5 — ускоряет олимпиадные задачи.", "Запоминай пары: 12²=144, 13²=169, 14²=196, 15²=225."], "check": {"q": "Квадрат какого числа равен 81?", "choices": ["8", "9", "10", "11"], "ans": 1, "exp": "9·9 = 81."}, "tasks": [{"q": "Сколько точных квадратов среди чисел от 1 до 100?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["Квадраты 1², 2², …, 10².", "10² = 100 — последний."], "sol": "Квадраты 1..10: ровно 10 чисел."}, {"q": "Сколько точных кубов среди чисел от 1 до 100?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["1³, 2³, 3³, 4³ = 1, 8, 27, 64.", "5³ = 125 уже больше 100."], "sol": "Кубы 1..4: 4 числа."}], "subj": "math"},
  {"id": 19, "title": "Числа-палиндромы", "src": "ВсОШ-стиль · запись числа", "ico": "🔁", "explain": ["Палиндром читается одинаково слева направо и справа налево: 121, 2002.", "Трёхзначный палиндром — число вида aba, где a от 1 до 9, b от 0 до 9.", "Цифру a можно выбрать 9 способами, b — 10 способами. Палиндромов: 9·10 = 90.", "Двузначные палиндромы — числа aa: a от 1 до 9 → их 9 (11, 22, …, 99).", "Четырёхзначные вида abba: a 9 способов, b 10 → тоже 90."], "check": {"q": "Число 989 — палиндром?", "choices": ["Да", "Нет"], "ans": 0, "exp": "989 читается одинаково в обе стороны."}, "tasks": [{"q": "Сколько трёхзначных палиндромов (например, 121)?", "kind": "unit", "ans": 90, "tol": 0, "hints": ["Вид aba.", "a — 9 способов (1..9), b — 10 способов."], "sol": "9·10 = 90 трёхзначных палиндромов."}, {"q": "Сколько двузначных палиндромов?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Вид aa.", "a от 1 до 9."], "sol": "11, 22, …, 99 — всего 9."}], "subj": "math"},
  {"id": 20, "title": "Секрет умножения на 11", "src": "классика · устный счёт", "ico": "✖️", "explain": ["Умножить двузначное число на 11 — просто: раздвинь цифры и впиши их сумму.", "45·11: цифры 4 и 5, сумма 9 → 4 9 5 = 495. Верно? 45·11 = 495, да!", "Если сумма больше 9 — переноси единицу: 58·11: 5+8=13 → 5(13)8 = 638.", "Почему так? 45·11 = 45·10 + 45 = 450 + 45 = 495. Сумма цифр «встаёт» в середину.", "Потренируйся: 63·11 = 693 (6+3=9). И 37·11 = 407 — с переносом: 3+7=10 → 407."], "check": {"q": "45·11 = ?", "choices": ["450", "495", "504", "945"], "ans": 1, "exp": "4 (4+5) 5 → 495."}, "tasks": [{"q": "63·11 = ?", "kind": "unit", "ans": 693, "tol": 0, "hints": ["Цифры 6 и 3.", "Сумма 6+3 = 9 в середину."], "sol": "6(6+3)3 = 693."}, {"q": "37·11 = ?", "kind": "unit", "ans": 407, "tol": 0, "hints": ["3+7 = 10 — больше 9.", "Переносим: 3+1=4, в середине 0."], "sol": "3+7=10 → 407."}], "subj": "math"},
  {"id": 21, "title": "Числа из цифр без повторов", "src": "ВсОШ-стиль · комбинаторика", "ico": "🔑", "explain": ["Сколько двузначных чисел можно составить из цифр 1..5, не повторяя цифры?", "Первую цифру выбираем 5 способами. Вторую — из оставшихся 4 цифр.", "Итого 5·4 = 20 чисел. Это правило умножения: каждый следующий выбор уменьшает число вариантов.", "Трёхзначные без повторов: 5·4·3 = 60. Первая цифра не может быть 0 — здесь цифры 1..5, всё хорошо.", "Помни: порядок важен, поэтому просто перемножаем убывающие числа вариантов."], "check": {"q": "Сколько двузначных чисел можно составить из цифр 1,2,3 без повторов?", "choices": ["3", "6", "9", "12"], "ans": 1, "exp": "3·2 = 6."}, "tasks": [{"q": "Сколько двузначных чисел можно составить из цифр 1,2,3,4,5, не повторяя цифры?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Первая цифра — 5 способов.", "Вторая — 4 способа."], "sol": "5·4 = 20."}, {"q": "Сколько трёхзначных чисел можно составить из цифр 1,2,3,4,5 без повторов?", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Первая — 5, вторая — 4, третья — 3.", "5·4·3 = 60."], "sol": "5·4·3 = 60."}], "subj": "math"},
  {"id": 22, "title": "Периметр фигур на клетках", "src": "ВсОШ-стиль · геометрия", "ico": "▭", "explain": ["Периметр фигуры на клетчатой бумаге — число внешних сторон клеток (сторона клетки = 1).", "У прямоугольника 3×4 клетки внешних сторон по периметру: 2·(3+4) = 14.", "Не путай с площадью: площадь = 3·4 = 12 клеток, а периметр считает границу.", "Для «фигурок» из клеток обходи границу и считай каждую внешнюю сторону.", "Квадрат 5×5: периметр 2·(5+5) = 20, площадь 25."], "check": {"q": "Периметр полоски 1×5 клеток?", "choices": ["6", "10", "12", "20"], "ans": 2, "exp": "2·(1+5) = 12."}, "tasks": [{"q": "Периметр прямоугольника 3×4 клетки?", "kind": "unit", "ans": 14, "tol": 0, "hints": ["P = 2·(a+b)", "2·(3+4) = 14."], "sol": "2·(3+4) = 14."}, {"q": "Периметр квадрата 5×5 клеток?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["P = 4·a", "4·5 = 20."], "sol": "4·5 = 20."}], "subj": "math"},
  {"id": 23, "title": "Время на часах: модуль 24", "src": "ВсОШ-стиль · время", "ico": "🕐", "explain": ["Часы — круг на 12 или 24 деления. Через 24 часа будет то же время (сутки).", "Сейчас 7:00. Через 50 часов: 50 = 24·2 + 2 → сдвиг на 2 часа → 9:00.", "Считаем остаток от деления часов на 24 — «часовые» остатки.", "Если перевалило за полночь — просто отнимаем 24, пока не получим время от 0 до 23.", "7:00 + 100 часов: 100 = 24·4 + 4 → 7+4 = 11:00."], "check": {"q": "Сейчас 7:00. Какое время будет через 24 часа?", "choices": ["7:00", "8:00", "6:00", "12:00"], "ans": 0, "exp": "24 часа — ровно сутки, время то же."}, "tasks": [{"q": "Сейчас 7:00. Который час будет через 50 часов?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["50 = 48 + 2 — два дня и 2 часа.", "7 + 2 = 9."], "sol": "50 mod 24 = 2 → 7:00 + 2 ч = 9:00."}, {"q": "Сейчас 7:00. Который час будет через 100 часов?", "kind": "unit", "ans": 11, "tol": 0, "hints": ["100 = 96 + 4.", "7 + 4 = 11."], "sol": "100 mod 24 = 4 → 7:00 + 4 ч = 11:00."}], "subj": "math"},
  {"id": 24, "title": "Цепочки сравнений", "src": "классика · логика", "ico": "📏", "explain": ["Сравнения «выше/ниже», «тяжелее/легче» складываются в цепочку: если A выше B, а B выше C, то A выше C.", "Строим цепочку неравенств и сразу видим порядок: A > B > C.", "Запиши все условия одной строкой, соединяя звенья: A>B, B>C → A>B>C.", "Кто выше всех — первый в цепочке, кто ниже всех — последний.", "Если сравнений не хватает для полного порядка, отвечай только на то, что следует из цепочки."], "check": {"q": "X легче Y, а Y легче Z. Кто тяжелее всех?", "choices": ["X", "Y", "Z"], "ans": 2, "exp": "X < Y < Z — тяжелее всех Z."}, "tasks": [{"q": "A выше B, B выше C. Кто выше всех?", "choices": ["A", "B", "C"], "ans": 0, "tol": 0, "hints": ["Цепочка: A > B > C."], "sol": "A > B > C — выше всех A.", "kind": "choice"}, {"q": "A выше B, B выше C, C выше D. Кто ниже всех?", "choices": ["A", "B", "C", "D"], "ans": 3, "tol": 0, "hints": ["Цепочка: A > B > C > D.", "Ниже всех — последний."], "sol": "A > B > C > D — ниже всех D.", "kind": "choice"}], "subj": "math"},
  {"id": 25, "title": "Двоичная система", "src": "Информатика · кодирование", "ico": "💻", "explain": ["Машины считают только нулями и единицами — это двоичная система.", "Число 101₂ = 1·4 + 0·2 + 1·1 = 5. Справа налево: единицы, двойки, четвёрки…", "Сколько кодов дают n бит? 2ⁿ: 1 бит — 2, 2 бита — 4, 3 бита — 8.", "Чтобы закодировать 8 вариантов, нужно 3 бита: 2³ = 8."], "check": {"q": "Сколько вариантов кодирует 4 бита?", "choices": ["4", "8", "16", "32"], "ans": 2, "exp": "2⁴ = 16 вариантов."}, "tasks": [{"q": "Сколько бит нужно для 8 разных вариантов?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["1 бит — 2, 2 — 4, 3 — 8.", "2³ = 8."], "sol": "3 бита дают 2³ = 8 вариантов."}, {"q": "Как записывается число 6 в двоичной системе?", "kind": "choice", "choices": ["101", "110", "011", "111"], "ans": 1, "tol": 0, "hints": ["6 = 4 + 2.", "4 — это 100₂, плюс двойка → 110₂."], "sol": "6 = 110₂."}], "subj": "inf"},
  {"id": 26, "title": "Алгоритмы: угадай и максимум", "src": "Информатика · алгоритмы", "ico": "🧩", "explain": ["Алгоритм — точный порядок действий, который приводит к цели.", "Бинарный поиск: вопросы «да/нет» каждый раз делят варианты пополам.", "Угадать число от 1 до 16 — log₂16 = 4 вопроса.", "Найти максимум среди n чисел — n−1 сравнение: каждое проигравшее выбывает."], "check": {"q": "Число вопросов «да/нет» для угадывания 1..16?", "choices": ["2", "3", "4", "16"], "ans": 2, "exp": "16 → 8 → 4 → 2 → 1 — 4 деления."}, "tasks": [{"q": "Сколько вопросов «да/нет» нужно, чтобы угадать число от 1 до 16?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Каждый вопрос делит варианты пополам.", "2⁴ = 16."], "sol": "4 вопроса (бинарный поиск)."}, {"q": "Сколько сравнений нужно, чтобы найти максимум среди 8 чисел?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Каждое число, кроме максимума, должно проиграть.", "8 − 1 = 7."], "sol": "7 сравнений."}], "subj": "inf"},
  {"id": 27, "title": "Количество программ: шаги +1/+2", "src": "Информатика · динамика", "ico": "🪜", "explain": ["Исполнитель умеет делать шаги +1 или +2. Сколько способов дойти до n?", "До 1 — 1 способ. До 2 — 2 способа: 1+1 и 2.", "Чтобы попасть на ступень n, нужно прийти с n−1 (шаг +1) или с n−2 (шаг +2).", "Значит, f(n) = f(n−1) + f(n−2) — числа Фибоначчи: 1, 1, 2, 3, 5, 8…"], "check": {"q": "Сколько способов дойти до 3 шагами +1/+2?", "choices": ["2", "3", "4", "5"], "ans": 1, "exp": "1+1+1, 1+2, 2+1 — три способа."}, "tasks": [{"q": "Сколько способов дойти от 0 до 4 шагами +1/+2?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["f(0)=1, f(1)=1, f(2)=2.", "f(3)=3, f(4)=5."], "sol": "1,1,2,3,5 → 5 способов до 4."}, {"q": "Сколько способов дойти от 0 до 5 шагами +1/+2?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Продолжи ряд 1,1,2,3,5.", "Следующее: 5+3 = 8."], "sol": "f(5) = f(4)+f(3) = 5+3 = 8."}], "subj": "inf"},
  {"id": 28, "title": "Логика: И, ИЛИ, НЕ", "src": "Информатика · логика", "ico": "🔲", "explain": ["В логике значения 0 (ложь) и 1 (истина).", "И — 1 только когда оба 1. ИЛИ — 1 когда хотя бы одно 1. НЕ — меняет на противоположное.", "Таблица И: 1 И 0 = 0. Таблица ИЛИ: 0 ИЛИ 1 = 1.", "Порядок: сначала НЕ и И, потом ИЛИ (как умножение и сложение)."], "check": {"q": "Чему равно 1 И 0?", "choices": ["0", "1"], "ans": 0, "exp": "И истинно только при двух единицах."}, "tasks": [{"q": "Чему равно (1 И 0) ИЛИ 1?", "choices": ["0", "1"], "ans": 1, "tol": 0, "hints": ["Сначала И: 1 И 0 = 0.", "Потом ИЛИ: 0 ИЛИ 1 = 1."], "sol": "(1 И 0) ИЛИ 1 = 0 ИЛИ 1 = 1.", "kind": "choice"}, {"q": "Чему равно НЕ (1 И 0)?", "choices": ["0", "1"], "ans": 1, "tol": 0, "hints": ["1 И 0 = 0.", "НЕ 0 = 1."], "sol": "НЕ(0) = 1.", "kind": "choice"}], "subj": "inf"},
  {"id": 29, "title": "Счёт до 10: складываем и вычитаем", "src": "Начальная школа · 1 класс", "ico": "🍎", "explain": ["Считать — значит соединять части в целое или убирать часть.", "Сложение: 3 + 2 = 5. Положи 3 пальца, добавь ещё 2 — стало 5.", "Вычитание: 5 − 2 = 3. Было 5, убрали 2 — осталось 3.", "Совет Архимеда: считай вслух и на пальцах, пока не станет легко."], "check": {"q": "Сколько будет 3 + 2?", "choices": ["4", "5", "6"], "ans": 1, "exp": "3 и ещё 2 — это 5."}, "tasks": [{"q": "Сколько будет 4 + 4?", "kind": "choice", "choices": ["6", "7", "8", "9"], "ans": 2, "tol": 0, "hints": ["Четыре и ещё четыре.", "4,5,6,7,8."], "sol": "4 + 4 = 8."}, {"q": "На ветке было 6 птичек, 2 улетели. Сколько осталось?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Было 6, улетели 2.", "6 − 2 = 4."], "sol": "6 − 2 = 4 птички."}], "subj": "jun"},
  {"id": 30, "title": "Сложение и вычитание до 100", "src": "Начальная школа · 2 класс", "ico": "🧮", "explain": ["Складывать до 100 удобно по разрядам: сначала десятки, потом единицы.", "Пример: 25 + 37. Десятки: 20+30 = 50. Единицы: 5+7 = 12. Вместе: 50+12 = 62.", "Вычитание: 60 − 24. Сначала 60−20 = 40, потом 40−4 = 36.", "Если единиц не хватает — «займи» десяток, как в тетради."], "check": {"q": "Сколько будет 25 + 37?", "choices": ["52", "62", "72"], "ans": 1, "exp": "20+30 = 50, 5+7 = 12, 50+12 = 62."}, "tasks": [{"q": "Сколько будет 60 − 24?", "kind": "choice", "choices": ["34", "36", "38", "46"], "ans": 1, "tol": 0, "hints": ["60 − 20 = 40.", "40 − 4 = 36."], "sol": "60 − 24 = 36."}, {"q": "Сколько будет 48 + 15?", "kind": "unit", "ans": 63, "tol": 0, "hints": ["40+10 = 50, 8+5 = 13.", "50 + 13 = 63."], "sol": "48 + 15 = 63."}], "subj": "jun"},
  {"id": 31, "title": "Таблица умножения", "src": "Начальная школа · 3 класс", "ico": "✖️", "explain": ["Умножение — это быстрое сложение одинаковых чисел: 4·3 = 3+3+3+3 = 12.", "Таблица умножения — это 9 строк по 9 чисел. Учи понемногу: сначала 2 и 5.", "Умножение на 9: 9·6 = 54. Подсказка: 9·5 = 45, плюс 9 → 54.", "Деление — обратное действие: если 7·8 = 56, то 56:7 = 8."], "check": {"q": "Сколько будет 4 × 3?", "choices": ["7", "12", "14"], "ans": 1, "exp": "4·3 — это 3+3+3+3 = 12."}, "tasks": [{"q": "Сколько будет 7 × 8?", "kind": "unit", "ans": 56, "tol": 0, "hints": ["7·4 = 28, а 28·2 = 56.", "Проверь по таблице."], "sol": "7 · 8 = 56."}, {"q": "45 конфет раздали 5 ребятам поровну. Сколько у каждого?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Раздели 45 на 5.", "5·9 = 45."], "sol": "45 : 5 = 9."}], "subj": "jun"},
  {"id": 32, "title": "Доли и задачи в два действия", "src": "Начальная школа · 4 класс", "ico": "🍰", "explain": ["Доля — это часть целого: половина (1/2), четверть (1/4).", "Четверть числа — раздели его на 4: четверть от 100 = 100:4 = 25.", "В задачах в два действия сначала найди первое, потом второе.", "Пример: половина пирога стоит 30 ₽. Весь пирог = 30·2 = 60 ₽."], "check": {"q": "Найди четверть числа 100.", "choices": ["20", "25", "40"], "ans": 1, "exp": "100 : 4 = 25."}, "tasks": [{"q": "Сколько минут в 2 часах?", "kind": "choice", "choices": ["60", "100", "120", "200"], "ans": 2, "tol": 0, "hints": ["В одном часе 60 минут.", "2 · 60 = 120."], "sol": "2 часа = 120 минут."}, {"q": "Половина пирога стоит 30 рублей. Сколько стоит весь пирог?", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Весь пирог — две половины.", "30 · 2 = 60."], "sol": "Весь пирог стоит 60 рублей."}], "subj": "jun"},
  {"id": 33, "title": "Плотность: тяжелее или легче", "src": "Физика · 5–6 класс · Плотность", "ico": "🪨", "subj": "phys", "explain": ["Плотность показывает, сколько массы в единице объёма: ρ = m : V.", "Единицы — грамм на кубический сантиметр (г/см³): у воды 1, у железа ~7,8, у пробки ~0,2.", "Если плотность больше — вещество «тяжелее»: железный брусок тонет, пробка всплывает.", "Из плотности и объёма находим массу: m = ρ · V. Из массы и плотности — объём: V = m : ρ.", "Запомни треугольник: масса наверху, плотность и объём внизу — закрывай неизвестное."], "check": {"q": "Брусок объёмом 3 см³ имеет массу 6 г. Какова его плотность? (в г/см³)", "choices": ["1", "2", "3", "6"], "ans": 1, "exp": "ρ = 6 : 3 = 2 г/см³."}, "tasks": [{"q": "Тело объёмом 2 см³ имеет массу 10 г. Плотность? (в г/см³)", "kind": "unit", "ans": 5, "tol": 0, "hints": ["ρ = m : V.", "10 : 2 = 5."], "sol": "ρ = 10 : 2 = 5 г/см³."}, {"q": "Плотность вещества 2 г/см³, объём 5 см³. Найди массу (в г).", "kind": "unit", "ans": 10, "tol": 0, "hints": ["m = ρ · V.", "2 · 5 = 10."], "sol": "m = 2 · 5 = 10 г."}]},
  {"id": 34, "title": "Сила тяжести и вес", "src": "Физика · 5–6 класс · Силы", "ico": "🍎", "subj": "phys", "explain": ["Земля притягивает все тела. Сила этого притяжения — сила тяжести.", "Она зависит от массы: F = m · g, где g ≈ 10 Н/кг (ускорение свободного падения).", "Пример: тело массой 5 кг притягивается с силой 5 · 10 = 50 Н.", "Вес — сила, с которой тело давит на опору. В покое вес равен силе тяжести.", "На Луне g ≈ 1,6 Н/кг — там тело весит в 6 раз меньше."], "check": {"q": "Какова сила тяжести, действующая на тело массой 3 кг? (в Н, g = 10)", "choices": ["3", "13", "30", "300"], "ans": 2, "exp": "F = 3 · 10 = 30 Н."}, "tasks": [{"q": "Сила тяжести на тело массой 20 кг? (в Н, g = 10)", "kind": "unit", "ans": 200, "tol": 0, "hints": ["F = m · g.", "20 · 10 = 200."], "sol": "F = 20 · 10 = 200 Н."}, {"q": "Какова масса тела, если сила тяжести 150 Н? (в кг, g = 10)", "kind": "unit", "ans": 15, "tol": 0, "hints": ["m = F : g.", "150 : 10 = 15."], "sol": "m = 150 : 10 = 15 кг."}]},
  {"id": 35, "title": "Давление твёрдых тел", "src": "Физика · 5–6 класс · Давление", "ico": "🧱", "subj": "phys", "explain": ["Давление — сила, приходящаяся на единицу площади: p = F : S.", "Одна и та же сила давит сильнее, если площадь меньше. Поэтому нож острый, а лыжи широкие.", "Единица давления — паскаль (Па): 1 Па = 1 Н на 1 м².", "Если знаешь давление и площадь, сила: F = p · S. Площадь: S = F : p.", "Пример: сила 100 Н на площадь 2 м² даёт давление 50 Па."], "check": {"q": "Сила 60 Н действует на площадь 2 м². Каково давление? (в Па)", "choices": ["30", "60", "120", "12"], "ans": 0, "exp": "p = 60 : 2 = 30 Па."}, "tasks": [{"q": "Сила 100 Н на площадь 5 м². Давление? (в Па)", "kind": "unit", "ans": 20, "tol": 0, "hints": ["p = F : S.", "100 : 5 = 20."], "sol": "p = 100 : 5 = 20 Па."}, {"q": "Давление 40 Па, площадь 3 м². Найди силу (в Н).", "kind": "unit", "ans": 120, "tol": 0, "hints": ["F = p · S.", "40 · 3 = 120."], "sol": "F = 40 · 3 = 120 Н."}]},
  {"id": 36, "title": "Закон Ома", "src": "Физика · 5–6 класс · Электричество", "ico": "💡", "subj": "phys", "explain": ["По проводнику течёт ток. Его сила зависит от напряжения и сопротивления.", "Закон Ома: I = U : R. Ток (А) = напряжение (В) ÷ сопротивление (Ом).", "Из закона можно найти напряжение: U = I · R. И сопротивление: R = U : I.", "Пример: 6 В и сопротивление 2 Ом дают ток 3 А.", "Осторожно: ток больше там, где меньше сопротивление — это знают все электрики."], "check": {"q": "Напряжение 6 В, сопротивление 2 Ом. Какова сила тока? (в А)", "choices": ["2", "3", "4", "12"], "ans": 1, "exp": "I = 6 : 2 = 3 А."}, "tasks": [{"q": "Ток 2 А, сопротивление 3 Ом. Напряжение? (в В)", "kind": "unit", "ans": 6, "tol": 0, "hints": ["U = I · R.", "2 · 3 = 6."], "sol": "U = 2 · 3 = 6 В."}, {"q": "Напряжение 12 В, ток 3 А. Сопротивление? (в Ом)", "kind": "unit", "ans": 4, "tol": 0, "hints": ["R = U : I.", "12 : 3 = 4."], "sol": "R = 12 : 3 = 4 Ом."}]},
  {"id": 37, "title": "Энергия и работа", "src": "Физика · 5–6 класс · Энергия", "ico": "⚡", "subj": "phys", "explain": ["Энергия — способность тела совершать работу. Чем больше энергия, тем больше работы можно сделать.", "Потенциальная энергия поднятого тела: E = m · g · h (масса, g ≈ 10, высота).", "Кинетическая энергия — энергия движения: чем быстрее и тяжелее, тем она больше.", "Работа: A = F · s — сила умножить на путь. Мощность: N = A : t — работа за единицу времени.", "Энергия не исчезает — она переходит из одного вида в другой (закон сохранения)."], "check": {"q": "Груз 2 кг подняли на 10 м. Потенциальная энергия? (в Дж, g = 10)", "choices": ["20", "200", "2000", "12"], "ans": 1, "exp": "E = 2 · 10 · 10 = 200 Дж."}, "tasks": [{"q": "Груз 3 кг на высоте 5 м. Потенциальная энергия? (в Дж, g = 10)", "kind": "unit", "ans": 150, "tol": 0, "hints": ["E = m·g·h.", "3 · 10 · 5 = 150."], "sol": "E = 3·10·5 = 150 Дж."}, {"q": "Работа 300 Дж совершена за 10 секунд. Мощность? (в Вт)", "kind": "unit", "ans": 30, "tol": 0, "hints": ["N = A : t.", "300 : 10 = 30."], "sol": "N = 300 : 10 = 30 Вт."}]},
  {"id": 38, "title": "Молекулы и формулы", "src": "Химия · 5–6 класс · Вещества", "ico": "🧪", "subj": "chem", "explain": ["Вещества состоят из молекул, а молекулы — из атомов.", "Формула показывает состав: H₂O — 2 атома водорода и 1 кислород, всего 3 атома.", "Индекс (маленькая цифра) — сколько атомов этого элемента в молекуле.", "Если индекса нет — атом один. O₂ — это два атома кислорода в одной молекуле газа.", "CO₂ — углекислый газ: 1 углерод и 2 кислорода."], "check": {"q": "Сколько атомов в молекуле CO₂?", "choices": ["2", "3", "4", "1"], "ans": 1, "exp": "C — 1 атом + O₂ — 2 атома = 3."}, "tasks": [{"q": "Сколько атомов в молекуле H₂O?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["2 водорода и 1 кислород.", "2 + 1 = 3."], "sol": "В H₂O три атома."}, {"q": "Сколько атомов водорода в молекуле CH₄ (метан)?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Индекс после H — 4.", "Четыре атома водорода."], "sol": "В CH₄ четыре атома водорода."}]},
  {"id": 39, "title": "Молярная масса", "src": "Химия · 5–6 класс · Масса веществ", "ico": "⚖️", "subj": "chem", "explain": ["Масса атома очень мала, поэтому химики считают порциями — молями.", "1 моль — это 6·10²³ частиц (число Авогадро). Удобно считать такими порциями.", "Молярная масса M — масса одного моля вещества в граммах. Для вещества её находят как сумму атомных масс всех атомов в формуле (атомные массы берут из таблицы Менделеева).", "Пример: у воды H₂O — M = 2·1 + 16 = 18 г/моль. У кислорода O₂ — 32 г/моль.", "Масса порции: m = M · n, где n — количество моль."], "check": {"q": "Какова молярная масса воды H₂O? (в г/моль)", "choices": ["16", "18", "20", "10"], "ans": 1, "exp": "M = 2·1 + 16 = 18 г/моль."}, "tasks": [{"q": "Молярная масса CO₂? (в г/моль, C=12, O=16)", "kind": "unit", "ans": 44, "tol": 0, "hints": ["12 + 2·16.", "12 + 32 = 44."], "sol": "M = 12 + 2·16 = 44 г/моль."}, {"q": "Масса 2 моль воды? (в г, M = 18 г/моль)", "kind": "unit", "ans": 36, "tol": 0, "hints": ["m = M · n.", "18 · 2 = 36."], "sol": "m = 18 · 2 = 36 г."}]},
  {"id": 40, "title": "Массовая доля раствора", "src": "Химия · 5–6 класс · Растворы", "ico": "🥤", "subj": "chem", "explain": ["Раствор — смесь вещества (например, соли) и растворителя (воды).", "Массовая доля показывает, сколько вещества в растворе: ω = m(вещества) : m(раствора) · 100%.", "Масса раствора = масса вещества + масса воды.", "Пример: 10 г соли в 100 г раствора → ω = 10 : 100 · 100% = 10%.", "Осторожно: не путай массу вещества и массу раствора!"], "check": {"q": "В 100 г раствора 10 г соли. Массовая доля соли? (в %)", "choices": ["1", "10", "90", "100"], "ans": 1, "exp": "ω = 10 : 100 · 100% = 10%."}, "tasks": [{"q": "В 200 г раствора 20 г сахара. Массовая доля? (в %)", "kind": "unit", "ans": 10, "tol": 0, "hints": ["20 : 200 · 100%.", "0,1 · 100 = 10."], "sol": "ω = 20:200·100% = 10%."}, {"q": "Сколько соли в 50 г 10%-го раствора? (в г)", "kind": "unit", "ans": 5, "tol": 0, "hints": ["m = ω · m(раствора).", "0,1 · 50 = 5."], "sol": "m = 0,1 · 50 = 5 г."}]},
  {"id": 41, "title": "Уравнения реакций", "src": "Химия · 5–6 класс · Реакции", "ico": "⚗️", "subj": "chem", "explain": ["Химическая реакция — превращение одних веществ в другие.", "В реакции 2H₂ + O₂ → 2H₂O: водород сгорает в кислороде, получается вода.", "Коэффициенты подбирают так, чтобы атомов каждого элемента слева и справа было поровну.", "Слева 4 водорода (2·2) и 2 кислорода. Справа в 2H₂O: 4 водорода и 2 кислорода — всё сходится.", "Закон сохранения массы: сколько было атомов, столько и осталось — они лишь перестроились."], "check": {"q": "В реакции 2H₂ + O₂ → ?H₂O. Какой коэффициент перед водой?", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "4 атома водорода слева → 2 молекулы воды."}, "tasks": [{"q": "В реакции 2H₂O₂ → 2H₂O + ?O₂. Коэффициент перед кислородом?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Слева 4 кислорода (2·2).", "В 2H₂O — 2 кислорода.", "Осталось 2 — это 1 молекула O₂."], "sol": "2H₂O₂ → 2H₂O + O₂."}, {"q": "В реакции N₂ + ?H₂ → 2NH₃. Коэффициент перед водородом?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Справа 6 атомов водорода (2·3).", "Молекула H₂ даёт 2 атома.", "6 : 2 = 3."], "sol": "N₂ + 3H₂ → 2NH₃."}]},
  {"id": 42, "title": "Газы: молярный объём", "src": "Химия · 5–6 класс · Газы", "ico": "🎈", "subj": "chem", "explain": ["Газы легко сжимаются и заполняют весь сосуд. При одинаковых условиях в равных объёмах газов — одинаковое число молекул.", "Один моль любого газа при нормальных условиях (н.у., 0 °C) занимает 22,4 литра — это молярный объём.", "Объём газа: V = 22,4 · n, где n — количество моль.", "Пример: 2 моль кислорода займут 22,4 · 2 = 44,8 литра.", "Так считают, сколько газа выделится в реакции."], "check": {"q": "Какой объём занимает 1 моль газа при обычных условиях? (в л)", "choices": ["22,4", "11,2", "44,8", "24"], "ans": 0, "exp": "Молярный объём газа — 22,4 л."}, "tasks": [{"q": "Какой объём займут 2 моль газа? (в л)", "kind": "unit", "ans": 44.8, "tol": 0.05, "hints": ["V = 22,4 · n.", "22,4 · 2 = 44,8."], "sol": "V = 22,4 · 2 = 44,8 л."}, {"q": "Какой объём займут 0,5 моль газа? (в л)", "kind": "unit", "ans": 11.2, "tol": 0.05, "hints": ["22,4 · 0,5.", "11,2."], "sol": "V = 22,4 · 0,5 = 11,2 л."}]},
  {"id": 43, "title": "Обыкновенные дроби: складываем", "src": "ВсОШ-стиль · дроби", "ico": "🍕", "subj": "math", "explain": ["Дробь — это часть целого: 3/4 — три части из четырёх.", "Складывать можно, только когда знаменатели одинаковые: 1/4 + 2/4 = 3/4.", "Если знаменатели разные, приводим к общему: 1/2 + 1/4 = 2/4 + 1/4 = 3/4.", "Общий знаменатель — число, которое делится на оба знаменателя (НОК).", "Целое можно записать дробью: 1 = 4/4. Поэтому 3/4 + 1 = 3/4 + 4/4 = 7/4."], "check": {"q": "Сколько будет 2/5 + 1/5?", "choices": ["3/5", "3/10", "2/10"], "ans": 0, "exp": "Знаменатели одинаковые: (2+1)/5 = 3/5."}, "tasks": [{"q": "Сколько будет 1/4 + 2/4?", "kind": "unit", "ans": 0.75, "tol": 0.01, "hints": ["(1+2)/4 = 3/4.", "3/4 = 0,75."], "sol": "3/4 = 0,75."}, {"q": "Сколько будет 1/2 + 1/4? (ответ десятичной дробью)", "kind": "unit", "ans": 0.75, "tol": 0.01, "hints": ["1/2 = 2/4.", "2/4 + 1/4 = 3/4."], "sol": "1/2 + 1/4 = 3/4 = 0,75."}]},
  {"id": 44, "title": "Проценты: находим число", "src": "ВсОШ-стиль · проценты", "ico": "🏷️", "subj": "math", "explain": ["Процент — это сотая часть: 1% = 1/100. Вся величина — 100%.", "Чтобы найти процент от числа: раздели на 100 и умножь на число процентов.", "10% от 300 = 300 : 100 · 10 = 30. Или проще: 10% — это десятая часть, 300:10 = 30.", "Удобные доли: 50% — половина, 25% — четверть, 20% — пятая часть.", "Проверка: скидка 20% от 500 = 500 : 5 = 100 рублей."], "check": {"q": "Сколько будет 10% от 300?", "choices": ["3", "30", "300", "15"], "ans": 1, "exp": "300 : 100 · 10 = 30."}, "tasks": [{"q": "Найди 20% от 500.", "kind": "unit", "ans": 100, "tol": 0, "hints": ["20% — это 1/5.", "500 : 5 = 100."], "sol": "500 · 0,2 = 100."}, {"q": "Найди 25% от 80.", "kind": "unit", "ans": 20, "tol": 0, "hints": ["25% — это 1/4.", "80 : 4 = 20."], "sol": "80 · 0,25 = 20."}]},
  {"id": 45, "title": "НОД и НОК", "src": "ВсОШ-стиль · делимость", "ico": "🔗", "subj": "math", "explain": ["НОД — наибольший общий делитель: самое большое число, на которое делятся оба.", "Пример: делители 12: 1,2,3,4,6,12. Делители 18: 1,2,3,6,9,18. НОД(12,18) = 6.", "НОК — наименьшее общее кратное: самое маленькое число, которое делится на оба.", "Кратные 6: 6,12,18,24… Кратные 8: 8,16,24… НОК(6,8) = 24.", "НОД помогает сокращать дроби, НОК — приводить к общему знаменателю."], "check": {"q": "Найди НОД чисел 12 и 18.", "choices": ["3", "6", "9", "36"], "ans": 1, "exp": "Общие делители 1,2,3,6 — наибольший 6."}, "tasks": [{"q": "Найди НОД чисел 24 и 36.", "kind": "unit", "ans": 12, "tol": 0, "hints": ["24 = 2³·3, 36 = 2²·3².", "Общее: 2²·3 = 12."], "sol": "НОД(24,36) = 12."}, {"q": "Найди НОК чисел 4 и 6.", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Кратные 4: 4,8,12…", "Кратные 6: 6,12…", "Первое общее — 12."], "sol": "НОК(4,6) = 12."}]},
  {"id": 46, "title": "Среднее арифметическое", "src": "ВсОШ-стиль · статистика", "ico": "📊", "subj": "math", "explain": ["Среднее арифметическое — это «поровну на всех»: сложи все числа и раздели на их количество.", "Пример: оценки 4, 5, 3 → (4+5+3) : 3 = 12 : 3 = 4.", "Среднее всегда между самым маленьким и самым большим числом.", "Если знаешь среднее и количество, можно найти сумму: сумма = среднее · количество.", "Это удобно для проверки: средняя скорость, средний балл, средний рост."], "check": {"q": "Найди среднее чисел 4, 5, 3.", "choices": ["3", "4", "5", "12"], "ans": 1, "exp": "(4+5+3):3 = 12:3 = 4."}, "tasks": [{"q": "Найди среднее чисел 6, 8, 10, 12.", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Сумма: 6+8+10+12 = 36.", "Чисел 4.", "36 : 4 = 9."], "sol": "36 : 4 = 9."}, {"q": "Средний балл 5 оценок равен 4. Какова их сумма?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Сумма = среднее · количество.", "4 · 5 = 20."], "sol": "4 · 5 = 20."}]},
  {"id": 47, "title": "Масштаб и пропорции", "src": "ВсОШ-стиль · геометрия", "ico": "🗺️", "subj": "math", "explain": ["Масштаб 1:100 означает: 1 см на карте = 100 см (1 м) в реальности.", "Чтобы найти реальный размер: измерь на плане и умножь на второе число масштаба.", "5 см на плане 1:100 → 5 · 100 = 500 см = 5 м.", "Пропорция — равенство двух отношений: 2:3 = 4:6. Произведение крайних равно произведению средних.", "Пропорции решают задачи «во сколько раз больше» и пересчёты рецептов."], "check": {"q": "Масштаб 1:100, на плане отрезок 5 см. Сколько это в реальности? (в см)", "choices": ["5", "50", "500", "100"], "ans": 2, "exp": "5 · 100 = 500 см."}, "tasks": [{"q": "Масштаб 1:1000, на плане 3 см. Реальная длина? (в см)", "kind": "unit", "ans": 3000, "tol": 0, "hints": ["Умножь на 1000.", "3 · 1000 = 3000."], "sol": "3 · 1000 = 3000 см."}, {"q": "Реши пропорцию: x : 5 = 8 : 10. Чему равен x?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Произведение крайних = произведению средних.", "10x = 40.", "x = 4."], "sol": "x = 5·8/10 = 4."}]},
  {"id": 48, "title": "Архимедова сила", "src": "Физика · 5–6 класс · Плавание", "ico": "🛶", "subj": "phys", "explain": ["На тело в жидкости или газе действует выталкивающая сила — сила Архимеда.", "Она равна весу вытесненной жидкости: F = ρ·g·V, где V — объём погружённой части.", "Если сила Архимеда больше веса тела — тело всплывает; меньше — тонет; равна — плавает внутри.", "Корабли плавают, потому что их корпус вытесняет много воды — сила Архимеда огромна.", "Вспомни корону Гиерона: объём погружённого тела легко измерить по поднятию воды."], "check": {"q": "Кусок дерева объёмом 2 л погружён в воду. Масса вытесненной воды 2 кг. Сила Архимеда? (в Н, g=10)", "choices": ["2", "10", "20", "200"], "ans": 2, "exp": "F = m·g = 2·10 = 20 Н."}, "tasks": [{"q": "Тело вытесняет 3 кг воды. Сила Архимеда? (в Н, g=10)", "kind": "unit", "ans": 30, "tol": 0, "hints": ["F = m·g.", "3 · 10 = 30."], "sol": "F = 3 · 10 = 30 Н."}, {"q": "Какая часть айсберга обычно скрыта под водой?", "kind": "choice", "choices": ["Маленькая — 1/10", "Большая — около 9/10", "Ровно половина"], "ans": 1, "tol": 0, "hints": ["Лёд чуть легче воды.", "Почти весь объём льда под водой.", "Около 90%."], "sol": "Под водой около 9/10 айсберга."}]},
  {"id": 49, "title": "Электрические цепи", "src": "Физика · 5–6 класс · Электричество", "ico": "🔌", "subj": "phys", "explain": ["Электрическая цепь: источник → провод → прибор → обратно к источнику.", "При последовательном соединении ток один на всех, а сопротивления складываются: R = R₁+R₂.", "При параллельном — напряжение одно, а ток делится между ветвями.", "Общее сопротивление двух одинаковых ламп параллельно вдвое меньше одной.", "Короткое замыкание — путь без сопротивления: ток огромный, цепь опасна."], "check": {"q": "Два резистора 2 Ом и 3 Ом соединены последовательно. Общее сопротивление? (в Ом)", "choices": ["5", "6", "1,2", "2"], "ans": 0, "exp": "Последовательно: 2+3 = 5 Ом."}, "tasks": [{"q": "Две одинаковые лампы по 6 Ом соединены параллельно. Общее сопротивление? (в Ом)", "kind": "unit", "ans": 3, "tol": 0.1, "hints": ["Параллельно одинаковых — пополам.", "6 : 2 = 3."], "sol": "R = 6/2 = 3 Ом."}, {"q": "Резисторы 4 Ом и 6 Ом последовательно. Общее сопротивление? (в Ом)", "kind": "unit", "ans": 10, "tol": 0, "hints": ["Последовательно складываем.", "4 + 6 = 10."], "sol": "R = 4 + 6 = 10 Ом."}]},
  {"id": 50, "title": "Равномерное движение", "src": "Физика · 5–6 класс · Движение", "ico": "🚴", "subj": "phys", "explain": ["Равномерное движение — скорость не меняется: за равные времена одинаковые пути.", "Путь: S = v · t. Скорость: v = S : t. Время: t = S : v.", "Единицы: км/ч, м/с. 1 м/с = 3,6 км/ч.", "Пример: 60 км/ч · 2 ч = 120 км.", "График пути — прямая линия: чем круче, тем больше скорость."], "check": {"q": "Велосипедист едет 15 км/ч. Сколько км за 4 часа?", "choices": ["45", "60", "75", "30"], "ans": 1, "exp": "S = 15·4 = 60 км."}, "tasks": [{"q": "Поезд прошёл 120 км за 3 часа. Скорость? (в км/ч)", "kind": "unit", "ans": 40, "tol": 0, "hints": ["v = S : t.", "120 : 3 = 40."], "sol": "v = 120 : 3 = 40 км/ч."}, {"q": "Самолёт летит 800 км/ч. Сколько км за 2 часа?", "kind": "unit", "ans": 1600, "tol": 0, "hints": ["S = v · t.", "800 · 2 = 1600."], "sol": "S = 800 · 2 = 1600 км."}]},
  {"id": 51, "title": "Нагревание и охлаждение", "src": "Физика · 5–6 класс · Теплота", "ico": "🔥", "subj": "phys", "explain": ["Чтобы нагреть тело, нужна энергия. Чтобы остудить — энергия уходит.", "Количество теплоты: Q = c·m·Δt, где c — удельная теплоёмкость, m — масса, Δt — изменение температуры.", "У воды большая теплоёмкость: c = 4200 Дж/(кг·°C) — вода долго греется и долго остывает.", "1 кг воды на 1°C — это 4200 Дж = 4,2 кДж.", "Поэтому климат у морей мягче: вода сглаживает перепады температуры."], "check": {"q": "Сколько тепла нужно, чтобы нагреть 1 кг воды на 10°C? (в кДж, c = 4200)", "choices": ["4,2", "42", "420", "4200"], "ans": 1, "exp": "Q = 4200·1·10 = 42000 Дж = 42 кДж."}, "tasks": [{"q": "Нагрев 2 кг воды на 10°C. Сколько тепла? (в кДж)", "kind": "unit", "ans": 84, "tol": 0.5, "hints": ["Q = 4200·2·10.", "84000 Дж = 84 кДж."], "sol": "Q = 4200·2·10 = 84000 Дж = 84 кДж."}, {"q": "Удельная теплоёмкость воды в Дж/(кг·°C)?", "kind": "unit", "ans": 4200, "tol": 0, "hints": ["Это константа воды.", "4200."], "sol": "c воды = 4200 Дж/(кг·°C)."}]},
  {"id": 52, "title": "Кислород и горение", "src": "Химия · 5–6 класс · Реакции", "ico": "🔥", "subj": "chem", "explain": ["Горение — реакция вещества с кислородом, при которой выделяется тепло и свет.", "Для горения нужны: горючее вещество, кислород и температура воспламенения.", "Продукты полного горения углеводородов — углекислый газ CO₂ и вода H₂O.", "Метан: CH₄ + 2O₂ → CO₂ + 2H₂O. Слева и справа всё сходится.", "Тушить пожар можно, перекрыв кислород (пена, одеяло) или охладив."], "check": {"q": "Что обязательно нужно для горения?", "choices": ["Кислород", "Азот", "Вода", "Стекло"], "ans": 0, "exp": "Горение — реакция с кислородом."}, "tasks": [{"q": "В реакции CH₄ + 2O₂ → CO₂ + ?H₂O. Коэффициент перед водой?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Слева 4 водорода.", "В H₂O два водорода.", "4 : 2 = 2."], "sol": "CH₄ + 2O₂ → CO₂ + 2H₂O."}, {"q": "Какой газ поддерживает горение?", "kind": "choice", "choices": ["Углекислый газ", "Кислород", "Азот", "Водород"], "ans": 1, "tol": 0, "hints": ["Без него огонь гаснет.", "Кислород."], "sol": "Горение поддерживает кислород."}]},
  {"id": 53, "title": "Вода — растворитель", "src": "Химия · 5–6 класс · Растворы", "ico": "💧", "subj": "chem", "explain": ["Вода — самый известный растворитель: в ней растворяются соль, сахар, многие газы.", "Раствор = растворённое вещество + растворитель (вода).", "Масса раствора равна сумме масс: m(раствора) = m(вещества) + m(воды).", "Насыщенный раствор — больше вещества уже не растворяется при этой температуре.", "Горячая вода растворяет больше сахара и соли, чем холодная."], "check": {"q": "В 300 г воды растворили 100 г сахара. Масса раствора? (в г)", "choices": ["200", "300", "400", "100"], "ans": 2, "exp": "300 + 100 = 400 г."}, "tasks": [{"q": "В 150 г воды растворили 50 г соли. Масса раствора? (в г)", "kind": "unit", "ans": 200, "tol": 0, "hints": ["Сложи воду и соль.", "150 + 50 = 200."], "sol": "150 + 50 = 200 г."}, {"q": "Что из этого хорошо растворяется в воде?", "kind": "choice", "choices": ["Песок", "Сахар", "Масло", "Железо"], "ans": 1, "tol": 0, "hints": ["Песок оседает, масло всплывает.", "Сахар исчезает в воде."], "sol": "Сахар растворяется в воде."}]},
  {"id": 54, "title": "Металлы и кислоты", "src": "Химия · 5–6 класс · Реакции", "ico": "⚡", "subj": "chem", "explain": ["Кислоты — едкие вещества: лимонный сок, уксус — слабые кислоты.", "Активные металлы (цинк, железо, магний) реагируют с кислотами.", "При реакции выделяется газ водород H₂: Zn + 2HCl → ZnCl₂ + H₂.", "Осторожно: с кислотами работают в защитных очках и перчатках.", "Индикаторы (лакмус) краснеют в кислоте и синеют в щёлочи."], "check": {"q": "Какой газ выделяется при реакции цинка с кислотой?", "choices": ["Кислород", "Водород", "Азот", "Углекислый"], "ans": 1, "exp": "Zn + 2HCl → ZnCl₂ + H₂ — водород."}, "tasks": [{"q": "В реакции Mg + 2HCl → MgCl₂ + ?. Что выделяется?", "kind": "choice", "choices": ["H₂", "O₂", "Cl₂", "CO₂"], "ans": 0, "tol": 0, "hints": ["Металл + кислота дают водород.", "H₂."], "sol": "Mg + 2HCl → MgCl₂ + H₂."}, {"q": "Лакмус в кислоте становится…", "kind": "choice", "choices": ["Синим", "Красным", "Зелёным"], "ans": 1, "tol": 0, "hints": ["Кислая среда — красный.", "Лакмус краснеет."], "sol": "Лакмус в кислоте красный."}]},
  {"id": 55, "title": "Цикл «пока»", "src": "Информатика · алгоритмы", "ico": "🔁", "subj": "inf", "explain": ["Цикл «пока» выполняет действия, пока условие истинно.", "Пример: x = 1; пока x < 50: x = x·2. x растёт: 1, 2, 4, 8, 16, 32, 64 — стоп.", "Важно, чтобы условие когда-нибудь стало ложным, иначе — бесконечный цикл.", "Считай шаги: сколько раз выполнилось тело цикла, прежде чем условие нарушилось.", "Циклы экономят программисту тысячи одинаковых строк."], "check": {"q": "Сколько раз выполнится тело цикла «x=1; пока x<50: x=x·2»?", "choices": ["5", "6", "7", "8"], "ans": 1, "exp": "1→2→4→8→16→32→64: тело выполнилось 6 раз."}, "tasks": [{"q": "Сколько раз выполнится «i=1; пока i≤5: i=i+1»?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["i пробегает 1,2,3,4,5.", "5 раз."], "sol": "5 раз."}, {"q": "Что произойдёт, если в цикле «пока i>0» не менять i?", "kind": "choice", "choices": ["Цикл закончится сам", "Бесконечный цикл", "Ошибка сразу"], "ans": 1, "tol": 0, "hints": ["Условие всегда истинно.", "Цикл не остановится."], "sol": "Получится бесконечный цикл."}]},
  {"id": 56, "title": "Массивы: поиск и среднее", "src": "Информатика · алгоритмы", "ico": "📋", "subj": "inf", "explain": ["Массив — список чисел: [4, 6, 8, 10]. У каждого элемента есть номер (индекс).", "Сумму элементов считаем, складывая по очереди; среднее = сумма : количество.", "Поиск максимума: сравниваем каждое число с лучшим найденным.", "Поиск числа: перебираем элементы, пока не найдём нужный (линейный поиск).", "Проверка: в [4,6,8,10] сумма 28, среднее 7, максимум 10."], "check": {"q": "Найди среднее массива [4, 6, 8, 10].", "choices": ["6", "7", "8", "28"], "ans": 1, "exp": "(4+6+8+10):4 = 28:4 = 7."}, "tasks": [{"q": "Найди максимум в массиве [3, 7, 1, 9, 5].", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Сравнивай попарно.", "9 больше всех."], "sol": "Максимум = 9."}, {"q": "Найди сумму массива [2, 4, 6, 8].", "kind": "unit", "ans": 20, "tol": 0, "hints": ["2+4 = 6, +6 = 12, +8 = 20."], "sol": "2+4+6+8 = 20."}]},
  {"id": 57, "title": "Сортировка пузырьком", "src": "Информатика · алгоритмы", "ico": "🫧", "subj": "inf", "explain": ["Сортировка упорядочивает список — например, по возрастанию.", "Пузырёк: проходим по списку и меняем соседей местами, если они в неправильном порядке.", "После каждого прохода самое большое число «всплывает» в конец.", "Для n чисел нужно не больше n−1 проходов.", "Пример: [3,1,2] → [1,3,2] → [1,2,3]: два прохода."], "check": {"q": "Сколько проходов гарантированно нужно, чтобы отсортировать 4 числа пузырьком?", "choices": ["2", "3", "4", "1"], "ans": 1, "exp": "n−1 = 3 прохода."}, "tasks": [{"q": "Сколько проходов нужно для 6 чисел?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["n − 1.", "6 − 1 = 5."], "sol": "6 − 1 = 5 проходов."}, {"q": "После первого прохода пузырька по [5,2,1,4] куда встанет 5?", "kind": "choice", "choices": ["В начало", "В конец", "В середину"], "ans": 1, "tol": 0, "hints": ["Самый большой «всплывает».", "5 встанет в конец."], "sol": "5 окажется последним."}]},
  {"id": 58, "title": "Графы: связи и маршруты", "src": "Информатика · алгоритмы", "ico": "🕸️", "subj": "inf", "explain": ["Граф — это точки (вершины) и линии между ними (рёбра).", "Дороги между городами, друзья в сети, схема метро — всё это графы.", "Степень вершины — сколько рёбер из неё выходит.", "В полном графе из n вершин рёбер: n·(n−1)/2 (каждый с каждым).", "Путь — последовательность рёбер; кратчайший ищут алгоритмом (поиск в ширину)."], "check": {"q": "Сколько рёбер в полном графе из 5 вершин (каждая связана с каждой)?", "choices": ["10", "15", "20", "5"], "ans": 0, "exp": "5·4/2 = 10 рёбер."}, "tasks": [{"q": "Сколько рёбер в полном графе из 4 вершин?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["n·(n−1)/2.", "4·3/2 = 6."], "sol": "4·3/2 = 6 рёбер."}, {"q": "В графе из 6 вершин каждая соединена с каждой. Сколько рёбер?", "kind": "unit", "ans": 15, "tol": 0, "hints": ["6·5/2.", "15."], "sol": "6·5/2 = 15 рёбер."}]},
  {"id": 59, "title": "Геометрические фигуры", "src": "Начальная школа · 1–2 класс", "ico": "🔷", "subj": "jun", "explain": ["Фигуры вокруг нас: круг, квадрат, треугольник, прямоугольник.", "У квадрата 4 стороны и 4 угла, все стороны равны.", "У треугольника 3 стороны и 3 угла.", "Прямоугольник — как квадрат, но стороны могут быть разными.", "Круг — без углов; мячик и тарелка — круги."], "check": {"q": "Сколько сторон у квадрата?", "choices": ["3", "4", "5"], "ans": 1, "exp": "У квадрата 4 стороны."}, "tasks": [{"q": "Сколько углов у треугольника?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Треугольник — три угла."], "sol": "У треугольника 3 угла."}, {"q": "Какая фигура без углов?", "kind": "choice", "choices": ["Квадрат", "Круг", "Треугольник"], "ans": 1, "tol": 0, "hints": ["Катится как мячик.", "Круг."], "sol": "Круг без углов."}]},
  {"id": 60, "title": "Часы и время", "src": "Начальная школа · 2–3 класс", "ico": "⏰", "subj": "jun", "explain": ["В одном часе 60 минут, в одной минуте 60 секунд.", "Полчаса — это 30 минут, четверть часа — 15 минут.", "В сутках 24 часа.", "Если минутная стрелка на 12 — ровно час: 3:00.", "Через 15 минут после 2:45 будет 3:00."], "check": {"q": "Сколько минут в одном часе?", "choices": ["60", "100", "30"], "ans": 0, "exp": "В часе 60 минут."}, "tasks": [{"q": "Сколько минут в половине часа?", "kind": "unit", "ans": 30, "tol": 0, "hints": ["Половина от 60.", "60 : 2 = 30."], "sol": "Полчаса = 30 минут."}, {"q": "Сколько часов в одних сутках?", "kind": "unit", "ans": 24, "tol": 0, "hints": ["День и ночь вместе.", "24 часа."], "sol": "В сутках 24 часа."}]},
  {"id": 61, "title": "Длина и масса", "src": "Начальная школа · 2–3 класс", "ico": "📏", "subj": "jun", "explain": ["Длину измеряют: миллиметры, сантиметры, метры, километры.", "В 1 метре 100 сантиметров, в 1 километре 1000 метров.", "Массу измеряют: граммы, килограммы, тонны.", "В 1 килограмме 1000 граммов, в 1 тонне 1000 килограммов.", "Проверь себя: 2 м = 200 см, 3 кг = 3000 г."], "check": {"q": "Сколько сантиметров в 1 метре?", "choices": ["10", "100", "1000"], "ans": 1, "exp": "1 м = 100 см."}, "tasks": [{"q": "Сколько граммов в 1 килограмме?", "kind": "unit", "ans": 1000, "tol": 0, "hints": ["Килограмм — большая тысяча.", "1000 г."], "sol": "1 кг = 1000 г."}, {"q": "Сколько метров в 1 километре?", "kind": "unit", "ans": 1000, "tol": 0, "hints": ["Километр — тысяча метров.", "1000 м."], "sol": "1 км = 1000 м."}]},
  {"id": 62, "title": "Находим часть числа", "src": "Начальная школа · 3–4 класс", "ico": "🍰", "subj": "jun", "explain": ["Часть числа находим делением: половина — раздели на 2, треть — на 3, четверть — на 4.", "Половина от 90: 90 : 2 = 45.", "Треть от 60: 60 : 3 = 20.", "Четверть от 100: 100 : 4 = 25.", "Если часть — две трети: сначала треть, потом умножь на 2: 2/3 от 60 = 40."], "check": {"q": "Найди половину числа 90.", "choices": ["35", "45", "50"], "ans": 1, "exp": "90 : 2 = 45."}, "tasks": [{"q": "Найди треть числа 60.", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Треть — раздели на 3.", "60 : 3 = 20."], "sol": "60 : 3 = 20."}, {"q": "Найди 2/3 от числа 60.", "kind": "unit", "ans": 40, "tol": 0, "hints": ["Сначала треть: 60:3 = 20.", "Две трети: 20·2 = 40."], "sol": "60 · 2/3 = 40."}]},
  {"id": 63, "title": "Комикс: Барсик и рыбки", "src": "Начальная школа · комикс · счёт до 10", "ico": "🐟", "subj": "jun", "comic": [{"who": "arch", "say": "Знаешь, Барсик целый день сидит у пруда и считает рыбок. Но у него лапки! Он никак не может сосчитать больше трёх.", "note": "Сегодня мы научим Барсика считать — а заодно и ты научишься. Рыбки в пруду плавают по одной, и мы будем их пересчитывать.", "emo": "smile", "cap": "Тёплое утро у пруда. Кот Барсик сторожит рыбок.", "with": ["cat"], "prop": ""}, {"who": "cat", "say": "Мяу… я умею до трёх. Раз, два, три — и всё! Рыбки такие быстрые…", "emo": "sad", "cap": "Барсик вздыхает: считать он умеет только до трёх.", "with": [], "prop": ""}, {"who": "arch", "say": "Не беда. Считать — это просто называть числа по порядку: один, два, три, четыре, пять. Давай потренируемся на рыбках в пруду!", "note": "В пруду плавают 3 рыбки, и к ним приплывут ещё 2. 3 и 2 вместе — это 5. Число 5 записывается так: 5.", "emo": "smile", "cap": "Архимед объясняет, как считать по порядку.", "with": ["cat"], "prop": ""}, {"who": "fish", "say": "Бульк! Не бойся, я не дам Барсику меня съесть — я буду учиться считать вместе с тобой!", "emo": "wow", "cap": "Рыбка вызывается помочь считать рыбок.", "with": [], "prop": ""}, {"who": "arch", "say": "Отлично! Посмотри на пруд: сначала приплыли 3 рыбки, потом ещё 2. Сколько всего рыбок?", "note": "Складываем: 3 + 2 = 5. Считаем по порядку после трёх: четыре, пять. Всего 5 рыбок. Запомни: когда предметы соединяются — мы складываем, знак «плюс».", "emo": "wow", "cap": "3 рыбки и ещё 2 — сколько всего?", "with": ["cat"], "prop": "3 + 2 = ?"}, {"who": "cat", "say": "Мяу! Пять! Я понял! Три рыбки и ещё две — это пять рыбок. Ура, я умею считать до пяти!", "emo": "smile", "cap": "Барсик радуется: получилось пять!", "with": [], "prop": "3 + 2 = 5!"}, {"who": "arch", "say": "Молодец, Барсик! А теперь проверь себя: если к 4 рыбкам приплывут ещё 3, сколько станет?", "note": "Подсказка: считай после четырёх: пять, шесть, семь. Или представь 4 пальца и добавь ещё 3 — получится 7.", "emo": "think", "cap": "А теперь — проверь себя!", "with": ["cat", "fish"], "prop": "4 + 3 = ?"}], "check": {"q": "К 4 рыбкам приплыли ещё 3. Сколько стало рыбок?", "choices": ["6", "7", "8"], "ans": 1, "exp": "4 рыбки и ещё 3 — это 7 рыбок."}, "tasks": [{"q": "В пруду плавали 2 рыбки, приплыли ещё 3. Сколько рыбок стало?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Было 2 и приплыли ещё 3.", "2 + 3 = 5."], "sol": "2 + 3 = 5 рыбок."}, {"q": "У Барсика было 5 рыбок, он поймал ещё 4. Сколько стало?", "kind": "choice", "choices": ["8", "9", "10"], "ans": 1, "tol": 0, "hints": ["Считай после пяти: 6,7,8,9.", "5 + 4 = 9."], "sol": "5 + 4 = 9 рыбок."}], "scene": "pond"},
  {"id": 64, "title": "Комикс: Пропавшие пирожки", "src": "Начальная школа · комикс · вычитание", "ico": "🥧", "subj": "jun", "comic": [{"who": "arch", "say": "Ох, у нас пропажа! Бабушка испекла 8 пирожков и поставила на подоконник остывать. А когда вернулась — осталось 5!", "note": "Сегодня учимся вычитать — находить, сколько пропало. Если было 8, а стало 5, значит кто-то утащил 8 − 5 = 3 пирожка.", "emo": "sad", "cap": "На кухне переполох: пирожки пропали!", "with": [], "prop": ""}, {"who": "granny", "say": "Кто-то взял мои пирожки! Дети, помогите найти воришку!", "emo": "sad", "cap": "Бабушка просит детей помочь найти воришку.", "with": [], "prop": ""}, {"who": "pig", "say": "Хрю… а я знаю, кто их взял. Но сначала давайте посчитаем, сколько пропало. Это честно!", "emo": "wow", "cap": "Пятачок предлагает сначала посчитать пропажу.", "with": [], "prop": ""}, {"who": "arch", "say": "Правильно, Пятачок! Было 8 пирожков, осталось 5. Чтобы узнать, сколько пропало, отнимаем: 8 − 5.", "note": "Вычитание — это когда от целого убирают часть. 8 пирожков − 5 оставшихся = 3 пропавших. Знак «минус» означает «убрать».", "emo": "think", "cap": "Было 8, осталось 5 — отнимаем и находим 3.", "with": ["cat"], "prop": "8 − 5 = 3"}, {"who": "cat", "say": "Мяу… виноват. Я взял три пирожка, они были такие тёплые и вкусные! Простите меня, я больше не буду.", "emo": "sad", "cap": "Барсик сознаётся: он взял три пирожка.", "with": [], "prop": ""}, {"who": "arch", "say": "Барсик признался — и бабушка его простила! Проверь себя: было 7 пирожков, Барсик утащил 2. Сколько останется?", "note": "Отнимаем: 7 − 2 = 5. Считаем назад от семи: шесть, пять. Останется 5 пирожков.", "emo": "smile", "cap": "Все простили кота. А теперь проверь себя!", "with": ["cat"], "prop": "7 − 2 = ?"}], "check": {"q": "На тарелке было 7 пирожков, Барсик утащил 2. Сколько осталось?", "choices": ["4", "5", "6"], "ans": 1, "exp": "7 − 2 = 5 пирожков осталось."}, "tasks": [{"q": "Было 8 пирожков, осталось 5. Сколько пропало?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Было 8, стало 5.", "8 − 5 = 3."], "sol": "Пропало 8 − 5 = 3 пирожка."}, {"q": "Бабушка испекла 9 пирожков, съели 4. Сколько осталось?", "kind": "choice", "choices": ["4", "5", "6"], "ans": 1, "tol": 0, "hints": ["9 − 4.", "Считай назад: 8,7,6,5."], "sol": "9 − 4 = 5 пирожков."}], "scene": "kitchen"},
  {"id": 65, "title": "Комикс: Сундук с монетами", "src": "Начальная школа · комикс · десятки", "ico": "🪙", "subj": "jun", "comic": [{"who": "arch", "say": "Посмотри, что я нашёл под старой оливой — сундук с монетами! Но считать их очень долго, если по одной.", "note": "Сегодня секрет лёгкого счёта: складывать монеты десятками. Десять монет по одному рублю — это 10 рублей. Десять и ещё десять — 20.", "emo": "wow", "cap": "Под старой оливой Архимед нашёл сундук с монетами!", "with": ["coin"], "prop": ""}, {"who": "kid", "say": "Ух ты, монетки! Тут их, наверное, сто! Как же их пересчитать быстрее?", "emo": "wow", "cap": "Монет очень много — считать по одной долго.", "with": ["coin"], "prop": "монет очень много"}, {"who": "coin", "say": "Дзынь! Мы, монетки, любим, когда нас считают десятками. Собери нас в столбики по десять — и сразу будет видно, сколько рублей!", "emo": "smile", "cap": "Монетки просят считать их десятками.", "with": ["kid"], "prop": "считаем десятками!"}, {"who": "arch", "say": "Смотри: один столбик — 10 монет, это 10 рублей. Второй столбик — ещё 10. Вместе 10 + 10 = 20 рублей.", "note": "Считать десятками легко: 10, 20, 30, 40… Десять десятков — это 100. Так что в сундуке, где 10 столбиков по 10 монет, — ровно 100 рублей.", "emo": "smile", "cap": "10 монет — 10 рублей, ещё 10 — уже 20.", "with": ["kid"], "prop": "10 + 10 = 20"}, {"who": "kid", "say": "Значит, 3 столбика по 10 монет — это 30 рублей! А 5 столбиков — 50! Я понял секрет!", "emo": "wow", "cap": "Ты понял секрет: десятки считать легко!", "with": ["coin"], "prop": "10, 20, 30…"}, {"who": "arch", "say": "Блестяще! Теперь проверь себя: сколько рублей в 4 столбиках по 10 монет?", "note": "Считай десятками: 10, 20, 30, 40. Четыре столбика — это 40 рублей.", "emo": "think", "cap": "Проверь себя: сколько в 4 столбиках по 10?", "with": ["kid"], "prop": "4 × 10 = ?"}], "check": {"q": "Сколько рублей в 4 столбиках по 10 монет?", "choices": ["20", "40", "50"], "ans": 1, "exp": "4 столбика по 10 — это 40 рублей: 10, 20, 30, 40."}, "tasks": [{"q": "Сколько рублей в 3 столбиках по 10 монет?", "kind": "unit", "ans": 30, "tol": 0, "hints": ["3 раза по 10.", "10, 20, 30."], "sol": "3 · 10 = 30 рублей."}, {"q": "В сундуке 6 столбиков по 10 монет. Сколько это рублей?", "kind": "choice", "choices": ["16", "60", "100"], "ans": 1, "tol": 0, "hints": ["6 десятков.", "10,20,30,40,50,60."], "sol": "6 · 10 = 60 рублей."}], "scene": "coins"},
  {"id": 66, "title": "Комикс: Яблоки в саду", "src": "Начальная школа · комикс · сложение до 10", "ico": "🍎", "subj": "jun", "scene": "sad", "comic": [{"who": "arch", "say": "Пятачок, помоги посчитать урожай: в корзине уже 3 яблока, а на дереве висят ещё 4. Сколько всего яблок?", "cap": "Утро в саду: поспели яблоки.", "emo": "smile", "with": ["pig"], "prop": ""}, {"who": "pig", "say": "Хрю… три в корзине и четыре на дереве. Как же их сложить?", "cap": "Пятачок задумался.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Складываем части вместе: 3 яблока и ещё 4 — это 7. Когда части соединяются — мы складываем.", "cap": "Архимед объясняет сложение.", "emo": "smile", "with": ["pig"], "prop": "3 + 4 = 7", "note": "3 + 4 = 7. Считай после трёх: четыре, пять, шесть, семь."}, {"who": "pig", "say": "Понял! А если в корзине 5 яблок и я положу ещё 3 — сколько станет?", "cap": "Пятачок пробует сам.", "emo": "wow", "with": [], "prop": "5 + 3 = ?"}, {"who": "pig", "say": "Восемь! 5 плюс 3 — это 8! Я умею считать урожай!", "cap": "Пятачок радуется.", "emo": "smile", "with": ["arch"], "prop": "5 + 3 = 8"}, {"who": "arch", "say": "Молодец! Проверь себя: бабушка положила в корзину 5 яблок и ещё 3. Сколько яблок в корзине?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["pig"], "prop": "5 + 3 = ?"}], "check": {"q": "Бабушка положила в корзину 5 яблок и ещё 3. Сколько яблок в корзине?", "choices": ["7", "8", "9"], "ans": 1, "exp": "5 + 3 = 8 яблок."}, "tasks": [{"q": "В корзине было 4 яблока, бабушка добавила ещё 3. Сколько яблок стало?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Было 4 и добавили 3.", "4 + 3 = 7."], "sol": "4 + 3 = 7 яблок."}, {"q": "На дереве висело 2 яблока, Пятачок сорвал ещё 6. Сколько яблок сорвано?", "kind": "choice", "choices": ["7", "8", "9"], "ans": 1, "tol": 0, "hints": ["Сложи 2 и 6.", "2 + 6 = 8."], "sol": "2 + 6 = 8 яблок."}]},
  {"id": 67, "title": "Комикс: Морковки на грядке", "src": "Начальная школа · комикс · вычитание до 10", "ico": "🥕", "subj": "jun", "scene": "ogorod", "comic": [{"who": "arch", "say": "На грядке росло 6 морковок. Бабушка выдернула 2 для супа. Сколько морковок осталось на грядке?", "cap": "Огород: морковки поспели.", "emo": "smile", "with": ["granny"], "prop": ""}, {"who": "granny", "say": "Шесть морковок, две я выдернула… как узнать, сколько осталось?", "cap": "Бабушка смотрит на грядку.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Когда часть убирают — мы отнимаем: 6 − 2 = 4. Четыре морковки остались расти.", "cap": "Архимед объясняет вычитание.", "emo": "smile", "with": ["granny"], "prop": "6 − 2 = 4", "note": "6 − 2 = 4. Считай назад: шесть, пять, четыре."}, {"who": "granny", "say": "А если было 8 морковок и Барсик утащит 3 — сколько останется?", "cap": "Бабушка придумала вопрос.", "emo": "think", "with": [], "prop": "8 − 3 = ?"}, {"who": "cat", "say": "Мяу… это я про морковки? Ладно: 8 без 3 — это 5!", "cap": "Барсик отвечает.", "emo": "smile", "with": ["granny"], "prop": "8 − 3 = 5"}, {"who": "arch", "say": "Верно! Проверь себя: на грядке было 8 морковок, 3 утащили. Сколько осталось?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["granny", "cat"], "prop": "8 − 3 = ?"}], "check": {"q": "На грядке было 8 морковок, 3 утащили. Сколько осталось?", "choices": ["4", "5", "6"], "ans": 1, "exp": "8 − 3 = 5 морковок."}, "tasks": [{"q": "На грядке росло 7 морковок, бабушка выдернула 3. Сколько осталось?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Отними 3 от 7.", "7 − 3 = 4."], "sol": "7 − 3 = 4 морковки."}, {"q": "Было 6 морковок, Барсик утащил 4. Сколько осталось?", "kind": "choice", "choices": ["2", "3", "4"], "ans": 0, "tol": 0, "hints": ["6 − 4 = ?", "6 − 4 = 2."], "sol": "6 − 4 = 2 морковки."}]},
  {"id": 68, "title": "Комикс: Звёзды на небе", "src": "Начальная школа · комикс · состав числа 10", "ico": "⭐", "subj": "jun", "scene": "cosmos", "comic": [{"who": "arch", "say": "Посмотри на ночное небо: уже горят 6 звёзд. Сколько ещё звёзд нужно зажечь, чтобы их стало 10?", "cap": "Ночь: Архимед и Ты смотрят на звёзды.", "emo": "smile", "with": ["kid"], "prop": ""}, {"who": "kid", "say": "Шесть звёзд… а до десяти не хватает… четырёх?", "cap": "Ребёнок считает звёзды.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Верно: 6 и 4 вместе дают 10. Если знаем часть и целое, вторую часть находим вычитанием: 10 − 6 = 4.", "cap": "Архимед объясняет состав числа.", "emo": "smile", "with": ["kid"], "prop": "6 + 4 = 10", "note": "6 + 4 = 10: 10 − 6 = 4."}, {"who": "kid", "say": "А если горят 3 звезды — сколько нужно, чтобы стало 10?", "cap": "Ребёнок пробует сам.", "emo": "wow", "with": [], "prop": "3 + ? = 10"}, {"who": "kid", "say": "Семь! 3 и 7 — это 10!", "cap": "Ребёнок радуется.", "emo": "smile", "with": ["arch"], "prop": "3 + 7 = 10"}, {"who": "arch", "say": "Отлично! Проверь себя: на небе горят 3 звезды. Сколько ещё нужно зажечь, чтобы стало 10?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["kid"], "prop": "3 + ? = 10"}], "check": {"q": "На небе горят 3 звезды. Сколько ещё нужно зажечь, чтобы стало 10?", "choices": ["6", "7", "8"], "ans": 1, "exp": "10 − 3 = 7 звёзд."}, "tasks": [{"q": "Горят 7 звёзд. Сколько нужно, чтобы стало 10?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["10 − 7 = ?", "10 − 7 = 3."], "sol": "10 − 7 = 3 звезды."}, {"q": "Горят 5 звёзд. Сколько нужно до 10?", "kind": "choice", "choices": ["3", "5", "6"], "ans": 1, "tol": 0, "hints": ["10 − 5 = ?", "10 − 5 = 5."], "sol": "10 − 5 = 5 звёзд."}]},
  {"id": 69, "title": "Комикс: Цыплята на дворе", "src": "Начальная школа · комикс · сложение до 20", "ico": "🐥", "subj": "jun", "scene": "ferma", "comic": [{"who": "granny", "say": "На дворе гуляют 12 цыплят, а из курятника выбежали ещё 6. Сколько цыплят теперь во дворе?", "cap": "Птичий двор: вылупились цыплята.", "emo": "smile", "with": ["kid"], "prop": ""}, {"who": "kid", "say": "Двенадцать и шесть… это больше двадцати? Давай посчитаем!", "cap": "Ребёнок считает цыплят.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Складываем: 12 + 6 = 18. Десятки к десяткам, единицы к единицам: 10 + 6 = 16, да ещё 2 = 18.", "cap": "Архимед объясняет сложение.", "emo": "smile", "with": ["kid"], "prop": "12 + 6 = 18", "note": "12 + 6 = 18: 10 + (2 + 6) = 18."}, {"who": "kid", "say": "А если во дворе 10 цыплят и прибегут ещё 7?", "cap": "Ребёнок пробует сам.", "emo": "wow", "with": [], "prop": "10 + 7 = ?"}, {"who": "kid", "say": "Семнадцать! 10 и 7 — это 17!", "cap": "Ребёнок радуется.", "emo": "smile", "with": ["granny"], "prop": "10 + 7 = 17"}, {"who": "arch", "say": "Молодец! Проверь себя: во дворе 10 цыплят, и прибежали ещё 7. Сколько цыплят стало?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["kid"], "prop": "10 + 7 = ?"}], "check": {"q": "Во дворе 10 цыплят, и прибежали ещё 7. Сколько цыплят стало?", "choices": ["16", "17", "18"], "ans": 1, "exp": "10 + 7 = 17 цыплят."}, "tasks": [{"q": "Во дворе гуляли 11 цыплят, прибежали ещё 5. Сколько стало?", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Сложи 11 и 5.", "11 + 5 = 16."], "sol": "11 + 5 = 16 цыплят."}, {"q": "Гуляли 12 цыплят, прибежали ещё 3. Сколько стало?", "kind": "choice", "choices": ["14", "15", "16"], "ans": 1, "tol": 0, "hints": ["12 + 3 = ?", "12 + 3 = 15."], "sol": "12 + 3 = 15 цыплят."}]},
  {"id": 70, "title": "Комикс: Мячи в магазине", "src": "Начальная школа · комикс · вычитание до 20", "ico": "🧸", "subj": "jun", "scene": "magazin", "comic": [{"who": "granny", "say": "В магазине на полке лежало 14 мячей. За день продали 3. Сколько мячей осталось на полке?", "cap": "Магазин игрушек.", "emo": "smile", "with": ["kid"], "prop": ""}, {"who": "kid", "say": "Четырнадцать мячей, три продали… надо отнять!", "cap": "Ребёнок считает.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Продали — значит убрали: 14 − 3 = 11. Одиннадцать мячей осталось.", "cap": "Архимед объясняет вычитание.", "emo": "smile", "with": ["kid"], "prop": "14 − 3 = 11", "note": "14 − 3 = 11: отнимаем единицы."}, {"who": "kid", "say": "А если было 18 мячей и продадут 5?", "cap": "Ребёнок пробует сам.", "emo": "wow", "with": [], "prop": "18 − 5 = ?"}, {"who": "kid", "say": "Тринадцать! 18 без 5 — это 13!", "cap": "Ребёнок радуется.", "emo": "smile", "with": ["granny"], "prop": "18 − 5 = 13"}, {"who": "arch", "say": "Верно! Проверь себя: на полке было 18 мячей, продали 5. Сколько осталось?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["kid"], "prop": "18 − 5 = ?"}], "check": {"q": "На полке было 18 мячей, продали 5. Сколько осталось?", "choices": ["12", "13", "14"], "ans": 1, "exp": "18 − 5 = 13 мячей."}, "tasks": [{"q": "Было 16 мячей, продали 4. Сколько осталось?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["16 − 4 = ?", "16 − 4 = 12."], "sol": "16 − 4 = 12 мячей."}, {"q": "Было 20 мячей, продали 5. Сколько осталось?", "kind": "choice", "choices": ["14", "15", "16"], "ans": 1, "tol": 0, "hints": ["20 − 5 = ?", "20 − 5 = 15."], "sol": "20 − 5 = 15 мячей."}]},
  {"id": 71, "title": "Комикс: Цыплята парами", "src": "Начальная школа · комикс · умножение на 2", "ico": "🐥", "subj": "jun", "scene": "ferma", "comic": [{"who": "granny", "say": "Цыплята любят гулять парами: 3 пары цыплят вышли во двор. Сколько это цыплят?", "cap": "Во дворе гуляют пары цыплят.", "emo": "smile", "with": ["pig"], "prop": ""}, {"who": "pig", "say": "Хрю… пара — это два. Три пары — это сколько?", "cap": "Пятачок размышляет.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Умножение — это быстрое сложение одинаковых пар: 3 пары по 2 цыплёнка — это 2 + 2 + 2 = 6. Записываем: 3 · 2 = 6.", "cap": "Архимед объясняет умножение.", "emo": "smile", "with": ["pig"], "prop": "3 · 2 = 6", "note": "3 · 2 = 6: три раза по два."}, {"who": "pig", "say": "А 4 пары цыплят — это сколько?", "cap": "Пятачок пробует сам.", "emo": "wow", "with": [], "prop": "4 · 2 = ?"}, {"who": "pig", "say": "Восемь! 4 пары — это 8 цыплят!", "cap": "Пятачок радуется.", "emo": "smile", "with": ["granny"], "prop": "4 · 2 = 8"}, {"who": "arch", "say": "Молодец! Проверь себя: во двор вышли 4 пары цыплят. Сколько цыплят?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["pig"], "prop": "4 · 2 = ?"}], "check": {"q": "Во двор вышли 4 пары цыплят. Сколько всего цыплят?", "choices": ["6", "8", "10"], "ans": 1, "exp": "4 · 2 = 8 цыплят."}, "tasks": [{"q": "Во дворе гуляют 5 пар цыплят. Сколько цыплят?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["5 пар по 2.", "5 · 2 = 10."], "sol": "5 · 2 = 10 цыплят."}, {"q": "Во дворе гуляют 2 пары цыплят. Сколько цыплят?", "kind": "choice", "choices": ["3", "4", "6"], "ans": 1, "tol": 0, "hints": ["2 пары по 2.", "2 · 2 = 4."], "sol": "2 · 2 = 4 цыплёнка."}]},
  {"id": 72, "title": "Комикс: Морковки поровну", "src": "Начальная школа · комикс · деление поровну", "ico": "🥕", "subj": "jun", "scene": "ogorod", "comic": [{"who": "granny", "say": "Бабушка собрала 12 морковок и хочет разложить их поровну в 3 корзины. Сколько морковок в каждой корзине?", "cap": "Урожай морковки.", "emo": "smile", "with": ["cat", "pig"], "prop": ""}, {"who": "pig", "say": "Хрю! Делить поровну — это честно! Но как?", "cap": "Пятачок задумался.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Делим поровну: 12 : 3 = 4. Разложим по одной: в каждую корзину по 4 морковки.", "cap": "Архимед объясняет деление.", "emo": "smile", "with": ["pig", "cat"], "prop": "12 : 3 = 4", "note": "12 : 3 = 4: проверка 4 · 3 = 12."}, {"who": "cat", "say": "Мяу… а если бабушка соберёт 18 морковок и разложит в 3 корзины?", "cap": "Барсик спрашивает.", "emo": "wow", "with": [], "prop": "18 : 3 = ?"}, {"who": "pig", "say": "Шесть! 18 : 3 = 6 — в каждой корзине по 6!", "cap": "Пятачок радуется.", "emo": "smile", "with": ["cat"], "prop": "18 : 3 = 6"}, {"who": "arch", "say": "Верно! Проверь себя: бабушка разложила 18 морковок поровну в 3 корзины. Сколько в каждой?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["pig", "cat"], "prop": "18 : 3 = ?"}], "check": {"q": "Бабушка разложила 18 морковок поровну в 3 корзины. Сколько морковок в каждой?", "choices": ["5", "6", "7"], "ans": 1, "exp": "18 : 3 = 6 морковок."}, "tasks": [{"q": "9 морковок разложили поровну в 3 корзины. Сколько в каждой?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["9 : 3 = ?", "9 : 3 = 3."], "sol": "9 : 3 = 3 морковки."}, {"q": "16 морковок разложили поровну в 4 корзины. Сколько в каждой?", "kind": "choice", "choices": ["3", "4", "5"], "ans": 1, "tol": 0, "hints": ["16 : 4 = ?", "16 : 4 = 4."], "sol": "16 : 4 = 4 морковки."}]},
  {"id": 73, "title": "Комикс: Игрушки на полках", "src": "Начальная школа · комикс · умножение на 3", "ico": "🧸", "subj": "jun", "scene": "magazin", "comic": [{"who": "arch", "say": "В магазине на каждой полке стоят по 3 игрушки. На трёх полках — сколько всего игрушек?", "cap": "Магазин игрушек.", "emo": "smile", "with": ["kid"], "prop": ""}, {"who": "kid", "say": "Три полки, на каждой по три…", "cap": "Ребёнок считает.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Умножаем: 3 полки по 3 игрушки — это 3 + 3 + 3 = 9. Записываем: 3 · 3 = 9.", "cap": "Архимед объясняет умножение.", "emo": "smile", "with": ["kid"], "prop": "3 · 3 = 9", "note": "3 · 3 = 9: три раза по три."}, {"who": "kid", "say": "А если игрушки стоят на 4 полках по 3?", "cap": "Ребёнок пробует сам.", "emo": "wow", "with": [], "prop": "4 · 3 = ?"}, {"who": "kid", "say": "Двенадцать! 4 · 3 = 12!", "cap": "Ребёнок радуется.", "emo": "smile", "with": ["arch"], "prop": "4 · 3 = 12"}, {"who": "arch", "say": "Молодец! Проверь себя: на 4 полках стоят по 3 игрушки. Сколько всего игрушек?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["kid"], "prop": "4 · 3 = ?"}], "check": {"q": "На 4 полках стоят по 3 игрушки. Сколько всего игрушек?", "choices": ["10", "12", "14"], "ans": 1, "exp": "4 · 3 = 12 игрушек."}, "tasks": [{"q": "На 2 полках стоят по 3 игрушки. Сколько всего игрушек?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["2 полки по 3.", "2 · 3 = 6."], "sol": "2 · 3 = 6 игрушек."}, {"q": "На 5 полках стоят по 3 игрушки. Сколько всего игрушек?", "kind": "choice", "choices": ["12", "15", "18"], "ans": 1, "tol": 0, "hints": ["5 · 3 = ?", "5 · 3 = 15."], "sol": "5 · 3 = 15 игрушек."}]},
  {"id": 74, "title": "Комикс: Половина яблока", "src": "Начальная школа · комикс · доли", "ico": "🍎", "subj": "jun", "scene": "sad", "comic": [{"who": "arch", "say": "У нас 8 яблок. Пятачок хочет угостить друга — отдать ему ПОЛОВИНУ яблок. Сколько яблок он отдаст?", "cap": "Сад: яблоки для друзей.", "emo": "smile", "with": ["pig"], "prop": ""}, {"who": "pig", "say": "Половина — это поровну на двоих: 8 яблок на двоих…", "cap": "Пятачок размышляет.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Половина — это целое, разделённое на 2: 8 : 2 = 4. А четверть — на 4 части: 8 : 4 = 2.", "cap": "Архимед объясняет доли.", "emo": "smile", "with": ["pig"], "prop": "8 : 2 = 4", "note": "Половина: 8 : 2 = 4. Четверть: 8 : 4 = 2."}, {"who": "pig", "say": "А если яблок 12 и надо отдать четверть?", "cap": "Пятачок спрашивает.", "emo": "think", "with": [], "prop": "12 : 4 = ?"}, {"who": "pig", "say": "Три! Четверть от 12 — это 3 яблока!", "cap": "Пятачок радуется.", "emo": "smile", "with": ["arch"], "prop": "12 : 4 = 3"}, {"who": "arch", "say": "Отлично! Проверь себя: найди четверть от 12 яблок.", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["pig"], "prop": "12 : 4 = ?"}], "check": {"q": "Найди четверть от 12 яблок.", "choices": ["2", "3", "4"], "ans": 1, "exp": "12 : 4 = 3 яблока."}, "tasks": [{"q": "Найди половину от 10 яблок.", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Половина — раздели на 2.", "10 : 2 = 5."], "sol": "10 : 2 = 5 яблок."}, {"q": "Найди четверть от 16 яблок.", "kind": "choice", "choices": ["3", "4", "5"], "ans": 1, "tol": 0, "hints": ["Четверть — раздели на 4.", "16 : 4 = 4."], "sol": "16 : 4 = 4 яблока."}]},
  {"id": 75, "title": "Комикс: Покупки Тебя", "src": "Начальная школа · комикс · задачи в 2 действия", "ico": "🧸", "subj": "jun", "scene": "magazin", "comic": [{"who": "arch", "say": "У Тебя было 50 рублей. Ты купил мишку за 20 рублей и мячик за 10 рублей. Сколько денег осталось?", "cap": "Магазин игрушек.", "emo": "smile", "with": ["kid"], "prop": ""}, {"who": "kid", "say": "Потратил 20 и 10… сначала посчитаю, сколько потратил всего!", "cap": "Ребёнок планирует.", "emo": "think", "with": [], "prop": ""}, {"who": "arch", "say": "Задача в два действия: сначала узнай, сколько потрачено: 20 + 10 = 30. Потом отними от 50: 50 − 30 = 20. Осталось 20 рублей.", "cap": "Архимед объясняет два действия.", "emo": "smile", "with": ["kid"], "prop": "50 − 30 = 20", "note": "Действие 1: 20 + 10 = 30. Действие 2: 50 − 30 = 20."}, {"who": "kid", "say": "А если у меня 80 рублей, а куплю я за 30 и за 20?", "cap": "Ребёнок пробует сам.", "emo": "wow", "with": [], "prop": "80 − 50 = ?"}, {"who": "kid", "say": "Потрачу 30 + 20 = 50, останется 80 − 50 = 30 рублей!", "cap": "Ребёнок радуется.", "emo": "smile", "with": ["granny"], "prop": "80 − 50 = 30"}, {"who": "arch", "say": "Молодец! Проверь себя: было 80 рублей, купили игрушку за 30 рублей и ещё за 20. Сколько осталось?", "cap": "А теперь — проверь себя!", "emo": "smile", "with": ["kid"], "prop": "80 − 50 = ?"}], "check": {"q": "Было 80 рублей, купили игрушку за 30 рублей и ещё за 20. Сколько денег осталось?", "choices": ["20", "30", "40"], "ans": 1, "exp": "30 + 20 = 50; 80 − 50 = 30 рублей."}, "tasks": [{"q": "Было 60 рублей, потратили 20 и 10. Сколько осталось?", "kind": "unit", "ans": 30, "tol": 0, "hints": ["Сначала сколько потрачено?", "20 + 10 = 30; 60 − 30 = 30."], "sol": "60 − (20 + 10) = 30 рублей."}, {"q": "Было 90 рублей, потратили 40 и 30. Сколько осталось?", "kind": "choice", "choices": ["20", "30", "40"], "ans": 0, "tol": 0, "hints": ["40 + 30 = 70.", "90 − 70 = 20."], "sol": "90 − (40 + 30) = 20 рублей."}]},
  {"id": 76, "title": "Сложение и вычитание столбиком", "ico": "➕", "src": "Математика · 5–6 класс · Сложение и вычитание многозначных чисел", "explain": ["Многозначные числа складывают и вычитают столбиком, по разрядам: единицы под единицами, десятки под десятками, сотни под сотнями.", "2345 + 678: сначала 5 + 8 = 13 — пишем 3, а 1 переносим в десятки; дальше 4 + 7 + 1 = 12 — пишем 2 и переносим 1; затем 3 + 6 + 1 = 10 — пишем 0 и переносим 1; в разряде тысяч 2 + 1 = 3. Итог: 2345 + 678 = 3023.", "При вычитании, если цифра уменьшаемого мала, «занимаем» десяток у следующего разряда: 5000 - 2345 = 2655.", "Совет Архимеда: проверяй себя обратным действием — сложи результат с вычитаемым: 2655 + 2345 = 5000, всё сходится!"], "check": {"q": "Сколько будет 4126 + 574?", "choices": ["4690", "4700", "4600"], "ans": 1, "exp": "По разрядам: 6 + 4 = 10 — пишем 0 и переносим 1; 2 + 7 + 1 = 10 — снова перенос; 1 + 5 + 1 = 7, а 4 списываем → 4126 + 574 = 4700."}, "tasks": [{"q": "Сколько будет 5000 - 2345?", "kind": "unit", "ans": 2655, "tol": 0, "hints": ["Занимаем тысячу у числа 5000: в единицах 10 - 5 = 5.", "Остаётся 9 десятков и 9 сотен: 9 - 4 = 5, 9 - 3 = 6, потом 4 - 2 = 2."], "sol": "5000 - 2345 = 2655; проверка: 2655 + 2345 = 5000."}, {"q": "В библиотеке на одной полке 1268 книг, а на другой — 1744 книги. Сколько книг на двух полках?", "kind": "choice", "choices": ["3012", "3002", "2012"], "ans": 0, "tol": 0, "hints": ["Сложи по разрядам: 8 + 4 = 12 — пишем 2, единицу переносим.", "Продолжай: 6 + 4 + 1 = 11 и 2 + 7 + 1 = 10 — не теряй переносы."], "sol": "1268 + 1744: 8 + 4 = 12, 6 + 4 + 1 = 11, 2 + 7 + 1 = 10, 1 + 1 + 1 = 3 → на двух полках 1268 + 1744 = 3012 книг."}], "subj": "math"},
  {"id": 77, "title": "Признаки делимости на 2, 5 и 10", "ico": "➗", "src": "Математика · 5–6 класс · Признаки делимости на 2, 5 и 10", "explain": ["Число делится на 2, если оно чётное (кончается на 0, 2, 4, 6 или 8); на 5 — если кончается на 0 или 5; на 10 — только если кончается на 0.", "480 делится и на 2, и на 5, и на 10: 480 : 2 = 240, 480 : 5 = 96, 480 : 10 = 48.", "А вот 125 делится только на 5: 125 : 5 = 25, ведь последняя цифра 5, а само число нечётное.", "Совет Архимеда: не считай всё число — достаточно посмотреть на его последнюю цифру!"], "check": {"q": "Какое из чисел делится и на 2, и на 5, и на 10?", "choices": ["305", "462", "500"], "ans": 2, "exp": "500 оканчивается на 0, значит, оно чётное и кратное 5: 500 : 2 = 250, 500 : 5 = 100, 500 : 10 = 50."}, "tasks": [{"q": "Сколько чисел от 1 до 100 делятся на 10?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["Это числа 10, 20, 30, …, 100.", "Каждое десятое число делится на 10: 100 : 10 = 10."], "sol": "Числа 10, 20, …, 100 — всего 100 : 10 = 10 чисел."}, {"q": "Какое число делится на 5, но НЕ делится на 2?", "kind": "choice", "choices": ["246", "275", "360"], "ans": 1, "tol": 0, "hints": ["Посмотри на последнюю цифру каждого числа.", "На 5 — цифра 0 или 5; на 2 — только чётная цифра."], "sol": "275 оканчивается на 5 → 275 : 5 = 55, но 275 — нечётное, значит, на 2 оно не делится."}], "subj": "math"},
  {"id": 78, "title": "НОД и НОК: находим общее", "ico": "🔢", "src": "Математика · 5–6 класс · НОД и НОК", "explain": ["НОД двух чисел — самое большое число, на которое делятся оба; НОК — самое маленькое число, которое делится на оба.", "НОД(12, 18) = 6: общие делители чисел 12 и 18 — это 1, 2, 3 и 6, выбираем наибольший.", "НОК(4, 6) = 12: кратные 4 — это 4, 8, 12, 16…, кратные 6 — 6, 12, 18…; первое общее кратное — 12.", "Совет Архимеда: НОК можно найти через НОД: умножь числа и подели на НОД, например 4 · 6 : 2 = 12."], "check": {"q": "Найди НОК(6, 8).", "choices": ["14", "24", "48"], "ans": 1, "exp": "Кратные 6: 6, 12, 18, 24…; кратные 8: 8, 16, 24… — первое общее кратное 24, значит, НОК(6, 8) = 24."}, "tasks": [{"q": "Найди НОД(18, 24).", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Делители 18: 1, 2, 3, 6, 9, 18.", "Делители 24: 1, 2, 3, 4, 6, 8, 12, 24 — возьми наибольший общий."], "sol": "Общие делители 18 и 24 — 1, 2, 3, 6; 18 = 6 · 3, 24 = 6 · 4 → НОД(18, 24) = 6."}, {"q": "Два фонаря мигают: один каждые 3 секунды, другой — каждые 4 секунды. Через сколько секунд они мигнут одновременно снова?", "kind": "choice", "choices": ["7", "12", "24"], "ans": 1, "tol": 0, "hints": ["Нужно число, которое делится и на 3, и на 4.", "Наименьшее такое число — это НОК(3, 4)."], "sol": "НОК(3, 4) = 12, ведь 3 · 4 = 12 — это первое общее кратное → фонари мигнут вместе через 12 секунд."}], "subj": "math"},
  {"id": 79, "title": "Сложение и вычитание дробей", "ico": "🍕", "src": "Математика · 5–6 класс · Обыкновенные дроби: сложение и вычитание", "explain": ["Если у дробей одинаковый знаменатель, складывай (или вычитай) только числители, а знаменатель оставляй без изменения.", "2/7 + 3/7 = 5/7: две седьмых и ещё три седьмых — это пять седьмых.", "5/8 - 2/8 = 3/8. А если числитель стал равен знаменателю, как 7/7, — это целая единица.", "Совет Архимеда: представь пиццу, разрезанную на одинаковые куски, — знаменатель показывает, сколько всего кусков, и он не меняется."], "check": {"q": "Сколько будет 3/8 + 4/8?", "choices": ["7", "7/8", "7/16"], "ans": 1, "exp": "Числители складываем: 3 + 4 = 7, а знаменатель 8 остаётся → 3/8 + 4/8 = 7/8."}, "tasks": [{"q": "Пирог разрезали на 9 равных кусков. Маша съела 2/9 пирога, а Петя — 3/9. Сколько кусков пирога осталось?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Съели 2/9 + 3/9 = 5/9 — это 5 кусков из 9.", "Осталось 9 - 5 = 4 куска."], "sol": "2/9 + 3/9 = 5/9; 9/9 - 5/9 = 4/9 → осталось 4 куска."}, {"q": "Сколько будет 7/10 - 3/10?", "kind": "choice", "choices": ["4/10", "10/10", "4/20"], "ans": 0, "tol": 0, "hints": ["Числители вычитаем: 7 - 3.", "Знаменатель 10 не меняется."], "sol": "7 - 3 = 4, знаменатель прежний → 7/10 - 3/10 = 4/10."}], "subj": "math"},
  {"id": 80, "title": "Умножение и деление дробей", "ico": "✖️", "src": "Математика · 5–6 класс · Умножение и деление обыкновенных дробей", "explain": ["Чтобы умножить дроби, перемножь числители и знаменатели; чтобы разделить — умножь первую дробь на перевёрнутую вторую.", "Умножение: 2/3 · 3 = (2 · 3) : 3 = 2 — целое число 3 записываем как 3/1 и считаем как обычно.", "Деление: 3/4 : 3/8 = 3/4 · 8/3 = 24/12 = 2 — поделить на 3/8 — всё равно что умножить на 8/3.", "Совет Архимеда: сокращай дроби до умножения, а не после — числа станут маленькими и считать будет легко."], "check": {"q": "Сколько будет 2/3 · 3/8?", "choices": ["5/11", "1/8", "1/4"], "ans": 2, "exp": "Сокращаем тройки, потом 2 и 8: 2/3 · 3/8 = 1/4; проверка без сокращения: 2 · 3 = 6, 3 · 8 = 24, 6/24 = 1/4."}, "tasks": [{"q": "Сколько будет 2/5 · 10?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Десять запиши как дробь 10/1.", "2 · 10 = 20, 5 · 1 = 5: получается 20/5."], "sol": "2/5 · 10 = 20/5 = 4, ведь 20 : 5 = 4."}, {"q": "Сколько будет 3/5 : 2/5?", "kind": "choice", "choices": ["3/2", "6/25", "2/3"], "ans": 0, "tol": 0, "hints": ["Переверни вторую дробь: 2/5 → 5/2.", "3/5 · 5/2 = 15/10 — сократи на 5."], "sol": "3/5 : 2/5 = 3/5 · 5/2 = 15/10 = 3/2."}], "subj": "math"},
  {"id": 81, "title": "Десятичные дроби", "ico": "🧾", "src": "Математика · 5–6 класс · Десятичные дроби: сложение и вычитание", "explain": ["Десятичные дроби складывают и вычитают столбиком так, чтобы запятая стояла под запятой; у 2,5 можно приписать нуль: 2,50.", "2,5 + 1,75 = 4,25: записываем 2,50 над 1,75 — сотые: 0 + 5 = 5, десятые: 5 + 7 = 12 (единица в уме), единицы: 2 + 1 + 1 = 4.", "При вычитании запятую тоже держим под запятой: 5,3 - 1,8 = 3,5.", "Совет Архимеда: приписывай нули справа, чтобы после запятой было поровну цифр, — и ошибки исчезнут."], "check": {"q": "Сколько будет 3,2 + 2,85?", "choices": ["5,05", "6,05", "6,85"], "ans": 1, "exp": "3,20 + 2,85: сотые 0 + 5 = 5, десятые 2 + 8 = 10 — единица в уме, единицы 3 + 2 + 1 = 6 → 3,2 + 2,85 = 6,05."}, "tasks": [{"q": "Сколько будет 9 − 3,25?", "kind": "choice", "choices": ["5,75", "6,25", "5,25"], "ans": 0, "tol": 0, "hints": ["Девятку запиши как 9,00 — вычитай столбиком.", "9,00 − 3,25 = 5,75 (занимаем единицу у девятки)."], "sol": "9,00 − 3,25 = 5,75."}, {"q": "Маша прошла 1,8 км до парка и ещё 0,75 км по парку. Сколько километров она прошла всего?", "kind": "choice", "choices": ["2,55", "1,05", "9,3"], "ans": 0, "tol": 0, "hints": ["1,8 — это 1,80; складывай столбиком.", "Сотые: 0 + 5 = 5; десятые: 8 + 7 = 15 — единица в уме."], "sol": "1,80 + 0,75 = 2,55 → всего Маша прошла 1,8 + 0,75 = 2,55 км."}], "subj": "math"},
  {"id": 82, "title": "Проценты", "ico": "🏷️", "src": "Математика · 5–6 класс · Проценты: находим процент от числа", "explain": ["Процент — это одна сотая часть числа: 1% числа получается делением числа на 100.", "25% от 80 = 20, ведь 25% — это четверть числа: 80 : 4 = 20.", "10% от 150 = 15 (делим на 10), а 50% от 60 = 30 — это просто половина.", "Совет Архимеда: переводи процент в удобную дробь: 50% — это делить на 2, 25% — на 4, 10% — на 10, 20% — на 5."], "check": {"q": "Найди 20% от 40.", "choices": ["8", "2", "20"], "ans": 0, "exp": "20% — это пятая часть числа: 40 : 5 = 8 → 20% от 40 = 8."}, "tasks": [{"q": "Найди 25% от 200.", "kind": "unit", "ans": 50, "tol": 0, "hints": ["25% — это четверть числа.", "200 : 4 = 50."], "sol": "25% от 200 = 200 : 4 = 50."}, {"q": "В классе 30 учеников, из них 40% — девочки. Сколько девочек в классе?", "kind": "choice", "choices": ["12", "18", "24"], "ans": 0, "tol": 0, "hints": ["40% — это 40 сотых, то есть 0,4.", "30 · 40 : 100 = 1200 : 100 = 12."], "sol": "40% от 30 = 30 · 40 : 100 = 1200 : 100 = 12 девочек."}], "subj": "math"},
  {"id": 83, "title": "Пропорции", "ico": "🍎", "src": "Математика · 5–6 класс · Пропорции и задачи", "explain": ["Если две величины растут одинаково — вдвое больше, вдвое дороже — это прямая пропорция.", "2 яблока стоят 40 ₽, значит, одно стоит 40 : 2 = 20 ₽, а 5 яблок — 20 · 5 = 100 ₽.", "Можно решать через пропорцию: 2/40 = 5/x, отсюда x = 40 · 5 : 2 = 100.", "Совет Архимеда: сначала найди «цену одной штуки» или «путь за один час» — дальше всё решается одним умножением."], "check": {"q": "3 одинаковые ручки стоят 45 рублей. Сколько стоят 5 таких ручек?", "choices": ["75", "60", "90"], "ans": 0, "exp": "Одна ручка стоит 45 : 3 = 15 ₽, а пять ручек: 15 · 5 = 75 ₽ → 45 : 3 · 5 = 75."}, "tasks": [{"q": "3 кг яблок стоят 150 рублей. Сколько стоят 7 кг таких яблок?", "kind": "unit", "ans": 350, "tol": 0, "hints": ["Один килограмм стоит 150 : 3 = 50 ₽.", "Теперь умножь цену килограмма на 7."], "sol": "150 : 3 = 50 ₽ за килограмм; 50 · 7 = 350 ₽."}, {"q": "Поезд за 4 часа проехал 240 км. Сколько километров он проедет за 6 часов с той же скоростью?", "kind": "choice", "choices": ["300", "360", "480"], "ans": 1, "tol": 0, "hints": ["Скорость поезда: 240 : 4 = 60 км/ч.", "За 6 часов: 60 · 6 = 360 км."], "sol": "240 : 4 = 60 км/ч; за 6 часов поезд проедет 60 · 6 = 360 км."}], "subj": "math"},
  {"id": 84, "title": "Степень с натуральным показателем", "ico": "⚡", "src": "Математика · 7 класс · Степени", "explain": ["Степень aⁿ — это произведение n одинаковых множителей: 2³ = 2 · 2 · 2 = 8.", "При умножении степеней с одинаковым основанием показатели складываются: 2³ · 2² = 2⁵ = 32.", "При возведении степени в степень показатели перемножаются: (2²)³ = 2⁶ = 64.", "Совет Архимеда: не путай 2³ = 8 и 2 · 3 = 6 — показатель говорит, сколько раз число умножается само на себя."], "check": {"q": "Сколько будет 3² · 3²?", "choices": ["12", "36", "81"], "ans": 2, "exp": "Основания одинаковые, показатели складываем: 3² · 3² = 3⁴ = 81, ведь 9 · 9 = 81."}, "tasks": [{"q": "Чему равно (2²)³?", "kind": "unit", "ans": 64, "tol": 0, "hints": ["Показатели перемножаются: 2 · 3 = 6.", "2⁶ = 2 · 2 · 2 · 2 · 2 · 2 = 64."], "sol": "(2²)³ = 2⁶ = 64; можно и так: (2 · 2)³ = 4³ = 64."}, {"q": "Чему равно 5³?", "kind": "choice", "choices": ["15", "25", "125"], "ans": 2, "tol": 0, "hints": ["5³ — это 5 · 5 · 5.", "5 · 5 = 25, затем 25 · 5 = 125."], "sol": "5³ = 5 · 5 · 5 = 125."}], "subj": "math"},
  {"id": 85, "title": "Квадрат суммы и разности", "ico": "🟩", "src": "Математика · 7 класс · Формулы сокращённого умножения", "explain": ["(a + b)² = a² + 2ab + b²: квадрат суммы — это квадрат первого числа плюс удвоенное произведение плюс квадрат второго.", "(10 + 3)² = 10² + 2 · 10 · 3 + 3² = 100 + 60 + 9 = 169 — и правда, 13² = 169.", "Для разности знак у удвоенного произведения меняется: (a - b)² = a² - 2ab + b².", "Совет Архимеда: не путай (a + b)² с a² + b² — было бы 100 + 9 = 109, а верный ответ 169!"], "check": {"q": "Чему равно (20 + 1)²?", "choices": ["401", "420", "441"], "ans": 2, "exp": "(20 + 1)² = 20² + 2 · 20 · 1 + 1² = 400 + 40 + 1 = 441; проверка: 21² = 441."}, "tasks": [{"q": "Чему равно (30 + 2)²?", "kind": "unit", "ans": 1024, "tol": 0, "hints": ["30² = 900, 2 · 30 · 2 = 120, а 2² = 4.", "Сложи: 900 + 120 + 4 = 1024."], "sol": "(30 + 2)² = 900 + 120 + 4 = 1024; проверка: 32² = 1024."}, {"q": "Чему равно (50 - 1)²?", "kind": "choice", "choices": ["2499", "2401", "2601"], "ans": 1, "tol": 0, "hints": ["Формула квадрата разности: a² - 2ab + b².", "2500 - 2 · 50 · 1 + 1 = 2500 - 100 + 1."], "sol": "(50 - 1)² = 2500 - 100 + 1 = 2401; проверка: 49² = 2401."}], "subj": "math"},
  {"id": 86, "title": "Линейные уравнения", "ico": "⚖️", "src": "Математика · 7 класс · Линейные уравнения", "explain": ["Решить уравнение — найти x, при котором равенство верно. Переносим числа вправо, меняя знак, и делим на число перед x.", "2x + 3 = 11 → 2x = 11 - 3 = 8 → x = 8 : 2 = 4.", "Проверяем подстановкой: 2 · 4 + 3 = 11 — верно, значит, x = 4 найден правильно.", "Совет Архимеда: что делаешь с одной стороной уравнения — делай и с другой, тогда равенство не нарушится."], "check": {"q": "Реши уравнение 3x + 4 = 19.", "choices": ["4", "5", "6"], "ans": 1, "exp": "3x = 19 - 4 = 15, значит, x = 15 : 3 = 5; проверка: 3 · 5 + 4 = 19."}, "tasks": [{"q": "Реши уравнение 4x - 9 = 15.", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Перенеси 9 вправо с плюсом: 4x = 15 + 9.", "4x = 24, значит, x = 24 : 4."], "sol": "4x - 9 = 15 → 4x = 24 → x = 24 : 4 = 6; проверка: 4 · 6 - 9 = 15."}, {"q": "Реши уравнение 2x + 6 = 22.", "kind": "choice", "choices": ["7", "8", "9"], "ans": 1, "tol": 0, "hints": ["Сначала перенеси 6: 2x = 22 - 6.", "22 - 6 = 16, значит, x = 16 : 2 = 8."], "sol": "2x + 6 = 22 → 2x = 16 → x = 16 : 2 = 8; проверка: 2 · 8 + 6 = 22."}], "subj": "math"},
  {"id": 87, "title": "Сумма углов треугольника", "ico": "📐", "src": "Математика · 7 класс · Геометрия: сумма углов треугольника", "explain": ["Сумма углов любого треугольника равна 180°.", "Если два угла треугольника равны 40° и 60°, то третий угол: 180° - 40° - 60° = 80°.", "В прямоугольном треугольнике один угол 90°, поэтому два других угла вместе дают 90°.", "Совет Архимеда: сложи два известных угла и вычти сумму из 180° — третий угол найдётся в одно действие."], "check": {"q": "В треугольнике углы 35° и 45°. Чему равен третий угол?", "choices": ["80°", "90°", "100°"], "ans": 2, "exp": "35° + 45° = 80°, а третий угол: 180° - 80° = 100°."}, "tasks": [{"q": "Один угол треугольника равен 90°, другой — 30°. Найди третий угол.", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Сумма углов треугольника — 180°.", "90° + 30° = 120°, остаётся 180° - 120° = 60°."], "sol": "Третий угол: 180° - 90° - 30° = 60°."}, {"q": "В равнобедренном треугольнике угол при вершине равен 40°. Чему равен каждый угол при основании?", "kind": "choice", "choices": ["50°", "70°", "140°"], "ans": 1, "tol": 0, "hints": ["Углы при основании равнобедренного треугольника равны.", "На оба угла остаётся 180° - 40° = 140°."], "sol": "(180° - 40°) : 2 = 140° : 2 = 70° — каждый угол при основании равен 70°."}], "subj": "math"},
  {"id": 88, "title": "Квадратные корни", "ico": "√", "src": "Математика · 8–9 класс · Квадратные корни", "explain": ["Квадратный корень из числа a — это число, квадрат которого равен a: √49 = 7, потому что 7² = 49.", "√144 = 12, ведь 12 · 12 = 144.", "Корень из произведения равен произведению корней: √(25 · 4) = √25 · √4 = 5 · 2 = 10.", "Совет Архимеда: выучи квадраты чисел от 1 до 15 — корни тогда будешь видеть сразу."], "check": {"q": "Чему равен √121?", "choices": ["10", "11", "12"], "ans": 1, "exp": "√121 = 11, потому что 11 · 11 = 121 (а 10² = 100 и 12² = 144)."}, "tasks": [{"q": "Найди √(25 · 4).", "kind": "unit", "ans": 10, "tol": 0, "hints": ["√25 = 5, а √4 = 2.", "5 · 2 = 10; проверка: 25 · 4 = 100 = 10²."], "sol": "√(25 · 4) = √25 · √4 = 5 · 2 = 10."}, {"q": "Чему равен √169?", "kind": "choice", "choices": ["12", "13", "14"], "ans": 1, "tol": 0, "hints": ["Вспомни квадраты: 12² = 144, а 13² = 169.", "Значит, √169 = 13."], "sol": "√169 = 13, потому что 13 · 13 = 169."}], "subj": "math"},
  {"id": 89, "title": "Квадратные уравнения", "ico": "🔍", "src": "Математика · 8–9 класс · Квадратные уравнения", "explain": ["Уравнение x² = a имеет два корня: x = √a и x = -√a.", "x² = 81 → x = 9 или x = -9, ведь 9² = 81 и (-9)² = 81.", "Для уравнения x² + px + q = 0 ищем два числа: их сумма равна -p, а произведение равно q. Для x² - 5x + 6 = 0 это 2 и 3: (x - 2)(x - 3) = 0.", "Совет Архимеда: подставляй найденные корни в уравнение — если получается верное равенство, корень найден правильно."], "check": {"q": "Реши уравнение x² = 49.", "choices": ["x = 7", "x = -7", "x = 7 и x = -7"], "ans": 2, "exp": "7 · 7 = 49 и (-7) · (-7) = 49, поэтому корней два: x = 7 и x = -7."}, "tasks": [{"q": "Уравнение x² - 7x + 12 = 0. Чему равен его больший корень?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Подбери два числа с суммой 7 и произведением 12.", "Это 3 и 4: 3 + 4 = 7, а 3 · 4 = 12."], "sol": "3 + 4 = 7 и 3 · 4 = 12 → x² - 7x + 12 = (x - 3)(x - 4) = 0, корни 3 и 4; больший корень равен 4."}, {"q": "Уравнение x² - 11x + 30 = 0. Чему равен его меньший корень?", "kind": "choice", "choices": ["5", "6", "11"], "ans": 0, "tol": 0, "hints": ["Подбери два числа с суммой 11 и произведением 30.", "Это 5 и 6: 5 + 6 = 11, а 5 · 6 = 30."], "sol": "5 + 6 = 11 и 5 · 6 = 30 → x² - 11x + 30 = (x - 5)(x - 6) = 0, корни 5 и 6; меньший корень равен 5."}], "subj": "math"},
  {"id": 90, "title": "Теорема Пифагора", "ico": "🔺", "src": "Математика · 8–9 класс · Теорема Пифагора", "explain": ["В прямоугольном треугольнике квадрат гипотенузы равен сумме квадратов катетов: a² + b² = c².", "Катеты 3 и 4: 3² + 4² = 9 + 16 = 25 = 5², значит, гипотенуза равна 5.", "Катеты 6 и 8: 6² + 8² = 36 + 64 = 100 = 10², гипотенуза равна 10.", "Совет Архимеда: запомни пифагоровы тройки 3–4–5, 6–8–10 и 8–15–17 — они встречаются очень часто."], "check": {"q": "Катеты прямоугольного треугольника равны 9 и 12. Чему равна гипотенуза?", "choices": ["12", "15", "21"], "ans": 1, "exp": "c² = 9² + 12² = 81 + 144 = 225 = 15² → гипотенуза c = 15."}, "tasks": [{"q": "Катеты прямоугольного треугольника равны 8 и 15. Найди гипотенузу.", "kind": "unit", "ans": 17, "tol": 0, "hints": ["8² = 64, а 15² = 225.", "64 + 225 = 289 = 17²."], "sol": "c² = 8² + 15² = 64 + 225 = 289 = 17² → гипотенуза равна 17."}, {"q": "Гипотенуза прямоугольного треугольника равна 25, а один из катетов — 7. Чему равен второй катет?", "kind": "choice", "choices": ["18", "24", "32"], "ans": 1, "tol": 0, "hints": ["b² = c² - a² = 25² - 7².", "625 - 49 = 576 = 24²."], "sol": "b² = 25² - 7² = 625 - 49 = 576 = 24² → второй катет равен 24."}], "subj": "math"},
  {"id": 91, "title": "Арифметическая прогрессия", "ico": "📈", "src": "Математика · 8–9 класс · Арифметическая прогрессия", "explain": ["Арифметическая прогрессия — ряд чисел, в котором каждое следующее число получается прибавлением одного и того же числа d — разности.", "В ряду 2, 5, 8, 11, … разность d = 3, а пятый член a₅ = a₁ + 4d = 2 + 12 = 14.", "Сумму первых n членов считают по формуле Sₙ = n · (a₁ + aₙ) : 2: для первых пяти членов S₅ = 5 · (2 + 14) : 2 = 40.", "Совет Архимеда: формула aₙ = a₁ + (n - 1)d — главная: с её помощью найдёшь любой член прогрессии."], "check": {"q": "В прогрессии 1, 4, 7, 10, … найди шестой член a₆.", "choices": ["13", "16", "19"], "ans": 1, "exp": "Разность d = 3, значит, a₆ = a₁ + 5d = 1 + 5 · 3 = 1 + 15 = 16."}, "tasks": [{"q": "В прогрессии 3, 7, 11, 15, … найди пятый член a₅.", "kind": "unit", "ans": 19, "tol": 0, "hints": ["Разность: 7 - 3 = 4.", "a₅ = a₁ + 4d = 3 + 4 · 4 = 3 + 16."], "sol": "a₅ = a₁ + 4d = 3 + 4 · 4 = 3 + 16 = 19."}, {"q": "Найди сумму первых шести членов прогрессии 1, 3, 5, 7, …", "kind": "choice", "choices": ["25", "36", "42"], "ans": 1, "tol": 0, "hints": ["a₆ = a₁ + 5d = 1 + 5 · 2 = 11.", "S₆ = 6 · (a₁ + a₆) : 2 = 6 · (1 + 11) : 2."], "sol": "a₆ = 1 + 5 · 2 = 1 + 10 = 11; S₆ = 6 · (1 + 11) : 2 = 6 · 12 : 2 = 36."}], "subj": "math"},
  {"id": 92, "title": "Что изучает физика", "src": "Физика · 5–6 класс · Что изучает физика", "ico": "🔬", "subj": "phys", "explain": ["Физика изучает природу: из чего состоят тела и какие явления с ними происходят.", "Вещество — то, из чего сделано тело: гвоздь и проволока — тела, а железо, из которого они сделаны, — вещество.", "Явление — изменение в природе: таяние снега, гром, радуга, полёт мяча.", "Совет Архимеда: увидел молнию или услышал гром — спроси себя: это тело, вещество или явление?"], "check": {"q": "Дождь, гром, молния — это…", "choices": ["физические тела", "вещества", "физические явления"], "ans": 2, "exp": "Дождь, гром и молния — изменения в природе, то есть физические явления."}, "tasks": [{"q": "В списке «гвоздь, ржавление гвоздя, железо, молоток» сколько физических тел?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Тело — предмет, который нас окружает.", "Ржавление — явление, а железо — вещество.", "Остаются гвоздь и молоток."], "sol": "1 + 1 = 2: тела — гвоздь и молоток; ржавление — явление, железо — вещество."}, {"q": "Какое слово обозначает физическое явление?", "kind": "choice", "choices": ["Снежинка", "Таяние снега", "Лёд"], "ans": 1, "hints": ["Явление — процесс, изменение.", "При таянии снег превращается в воду."], "sol": "Таяние снега — явление, а снежинка и лёд — физические тела."}]},
  {"id": 93, "title": "Измерения: длина, масса, время", "src": "Физика · 5–6 класс · Измерения: длина, масса, время", "ico": "📏", "subj": "phys", "explain": ["Чтобы измерить величину, её сравнивают с единицей измерения: длину — в метрах, массу — в килограммах, время — в секундах.", "1 м = 100 см, значит 3 м = 3 · 100 = 300 см: чем крупнее единица, тем меньше число.", "1 кг = 1000 г, а 1 час = 60 минут: 2 кг = 2000 г, половина часа — 30 минут.", "Совет Архимеда: умножаешь на 100 — допиши два нуля, на 1000 — три. Проверь: 5 м = 500 см — верно?"], "check": {"q": "Сколько сантиметров в 3 метрах?", "choices": ["30 см", "300 см", "3000 см"], "ans": 1, "exp": "1 м = 100 см, значит 3 · 100 = 300 см."}, "tasks": [{"q": "Сколько сантиметров в 5 метрах?", "kind": "unit", "ans": 500, "tol": 0, "hints": ["1 м = 100 см.", "5 · 100 = ?"], "sol": "5 · 100 = 500 см."}, {"q": "Сколько граммов в 4 килограммах?", "kind": "choice", "choices": ["400 г", "4000 г", "40 000 г"], "ans": 1, "hints": ["1 кг = 1000 г.", "4 · 1000 = ?"], "sol": "1 кг = 1000 г, значит 4 · 1000 = 4000 г."}]},
  {"id": 94, "title": "Скорость движения", "src": "Физика · 5–6 класс · Скорость движения", "ico": "🏃", "subj": "phys", "explain": ["Скорость — какой путь проходит тело за единицу времени: v = S : t.", "Проехали 60 км за 2 часа: v = 60 : 2 = 30 км/ч.", "Идёшь в школу 4 км за 1 час — твоя скорость 4 км/ч, а велосипедист едет быстрее: около 15 км/ч.", "Совет Архимеда: путь дели на время — получишь скорость. Проверь: 100 км за 2 часа → 50 км/ч."], "check": {"q": "Лыжник прошёл 40 км за 4 часа. Какова его скорость?", "choices": ["10 км/ч", "36 км/ч", "44 км/ч"], "ans": 0, "exp": "v = S : t = 40 : 4 = 10 км/ч."}, "tasks": [{"q": "Велосипедист проехал 45 км за 3 часа. Его скорость? (в км/ч)", "kind": "unit", "ans": 15, "tol": 0, "hints": ["v = S : t.", "45 : 3 = ?"], "sol": "v = S : t = 45 : 3 = 15 км/ч."}, {"q": "Пешеход идёт со скоростью 5 км/ч. Какой путь он пройдёт за 4 часа?", "kind": "choice", "choices": ["9 км", "20 км", "1,25 км"], "ans": 1, "hints": ["Путь = скорость · время: S = v · t.", "5 · 4 = ?"], "sol": "S = v · t = 5 · 4 = 20 км."}]},
  {"id": 95, "title": "Магниты и притяжение", "src": "Физика · 5–6 класс · Магниты и притяжение", "ico": "🧲", "subj": "phys", "explain": ["Магнит притягивает железо и сталь, а дерево, стекло и пластик — нет.", "У магнита два полюса: северный (N) и южный (S). Одноимённые полюса отталкиваются, разноимённые — притягиваются.", "Земля — огромный магнит: поэтому стрелка компаса всегда показывает на север.", "Совет Архимеда: поднеси магнит к разным предметам дома — притянулся? Значит, в этом предмете есть железо."], "check": {"q": "Какие тела притягивает магнит?", "choices": ["Деревянные", "Железные", "Стеклянные"], "ans": 1, "exp": "Магнит притягивает железо и сталь — тела, в которых есть железо."}, "tasks": [{"q": "Два магнита поднесли северными полюсами друг к другу. Что произойдёт?", "kind": "choice", "choices": ["Притянутся", "Оттолкнутся", "Ничего"], "ans": 1, "hints": ["Полюса одинаковые — одноимённые.", "Одноимённые полюса отталкиваются."], "sol": "Северный и северный — одноимённые полюса, поэтому магниты отталкиваются."}, {"q": "Южный полюс одного магнита поднесли к северному полюсу другого. Что произойдёт?", "kind": "choice", "choices": ["Притянутся", "Оттолкнутся", "Не будут взаимодействовать"], "ans": 0, "hints": ["Юг и север — разные полюса.", "Разноимённые полюса притягиваются."], "sol": "N и S — разноимённые полюса, поэтому магниты притянутся."}]},
  {"id": 96, "title": "Свет и тень", "src": "Физика · 5–6 класс · Свет и тень", "ico": "🌞", "subj": "phys", "explain": ["Источник света светит сам: Солнце, лампочка, свеча, звёзды.", "Луна и зеркало не светят сами — они лишь отражают чужой свет.", "Свет распространяется по прямой, поэтому за непрозрачным предметом появляется тень.", "Совет Архимеда: в солнечный день встань спиной к Солнцу — твоя тень всегда «убегает» от него."], "check": {"q": "Что из перечисленного — источник света?", "choices": ["Луна", "Солнце", "Зеркало"], "ans": 1, "exp": "Солнце излучает свет само, а Луна и зеркало лишь отражают чужой свет."}, "tasks": [{"q": "Солнце светит слева от дерева. С какой стороны будет тень?", "kind": "choice", "choices": ["Слева от дерева", "Справа от дерева", "Над деревом"], "ans": 1, "hints": ["Свет идёт по прямой.", "Тень — там, куда свет не попадает, за предметом."], "sol": "Лучи идут слева направо, за деревом света нет — тень справа от дерева."}, {"q": "Когда тень от столба короче всего?", "kind": "choice", "choices": ["Утром", "В полдень", "Вечером"], "ans": 1, "hints": ["Утром и вечером Солнце стоит низко.", "Чем выше Солнце, тем короче тень."], "sol": "В полдень Солнце стоит высоко, лучи падают почти отвесно — тень самая короткая."}]},
  {"id": 97, "title": "Звук", "src": "Физика · 5–6 класс · Звук", "ico": "🔊", "subj": "phys", "explain": ["Звук — колебания воздуха, которые слышит ухо. Нет колебаний — нет звука.", "Громкость зависит от силы колебаний: ударишь по барабану сильнее — звук громче.", "Высота звука зависит от частоты колебаний: крылья комара колеблются чаще, чем голос льва, поэтому писк выше.", "Совет Архимеда: приложи пальцы к горлу и скажи «а-а-а» — почувствуешь дрожание голосовых связок: это и есть колебания."], "check": {"q": "Струна гитары звучит, потому что она…", "choices": ["нагревается", "колеблется", "светится"], "ans": 1, "exp": "Колеблющаяся струна передаёт колебания воздуху — рождается звук."}, "tasks": [{"q": "Если ударить по барабану сильнее, звук станет…", "kind": "choice", "choices": ["тише", "громче", "выше"], "ans": 1, "hints": ["Сильнее удар — больше размах колебаний.", "Больше размах колебаний — громче звук."], "sol": "Сильнее удар → колебания сильнее → звук громче."}, {"q": "Писк комара выше рычания льва, потому что крылья комара колеблются…", "kind": "choice", "choices": ["чаще", "реже", "так же"], "ans": 0, "hints": ["Высота звука зависит от частоты колебаний.", "Чаще колебания — выше звук."], "sol": "Чем чаще колеблется тело, тем выше звук: крылья комара делают сотни взмахов в секунду."}]},
  {"id": 98, "title": "Вода и её состояния", "src": "Физика · 5–6 класс · Вода и её состояния", "ico": "💧", "subj": "phys", "explain": ["Вода бывает в трёх состояниях: твёрдом (лёд), жидком (вода) и газообразном (пар).", "Лёд плавится при 0 °C, и вода замерзает тоже при 0 °C.", "Вода кипит при 100 °C: при кипении она превращается в пар, который поднимается вверх.", "Совет Архимеда: зимой на улице лёд не тает, потому что мороз ниже 0 °C — ниже точки плавления."], "check": {"q": "При какой температуре кипит вода? (в °C)", "choices": ["0", "50", "100"], "ans": 2, "exp": "Вода кипит при 100 °C, а лёд плавится при 0 °C."}, "tasks": [{"q": "При какой температуре плавится лёд? (в °C)", "kind": "unit", "ans": 0, "tol": 0, "hints": ["Вспомни, что происходит со льдом в тёплой комнате.", "Точка плавления льда совпадает с точкой замерзания воды."], "sol": "Лёд плавится при 0 °C — это точка плавления воды."}, {"q": "Пар — это вода в каком состоянии?", "kind": "choice", "choices": ["твёрдом", "жидком", "газообразном"], "ans": 2, "hints": ["Пар не имеет своей формы и заполняет всё пространство.", "Так ведут себя газы — как воздух."], "sol": "Пар — газообразное состояние воды: при кипении вода превращается в пар."}]},
  {"id": 99, "title": "Воздух", "src": "Физика · 5–6 класс · Воздух", "ico": "🎈", "subj": "phys", "explain": ["Воздух — смесь газов: в основном азот и кислород, есть в нём и другие газы.", "Воздух имеет вес: он давит на нас со всех сторон, просто мы этого не замечаем.", "Ветер — движущийся воздух: тёплый воздух поднимается вверх, а на его место приходит холодный.", "Совет Архимеда: помаши листом бумаги у лица — почувствуешь ветерок: это воздух, который ты привёл в движение."], "check": {"q": "Воздух — это…", "choices": ["один газ", "смесь газов", "жидкость"], "ans": 1, "exp": "Воздух — смесь газов: азота, кислорода, углекислого газа и других."}, "tasks": [{"q": "Что такое ветер?", "kind": "choice", "choices": ["движение воздуха", "движение воды", "движение облаков"], "ans": 0, "hints": ["Ветер не увидишь глазами.", "Это движение невидимого вещества вокруг нас."], "sol": "Ветер — движущийся воздух: тёплый поднимается вверх, холодный приходит на его место."}, {"q": "Почему тёплый воздух поднимается вверх?", "kind": "choice", "choices": ["Он тяжелее холодного", "Он легче холодного", "У него нет веса"], "ans": 1, "hints": ["Нагретый воздух расширяется.", "Расширился — стал легче холодного — всплывает вверх."], "sol": "Тёплый воздух легче холодного, поэтому поднимается вверх — как пробка в воде."}]},
  {"id": 100, "title": "Плотность", "src": "Физика · 7 класс · Плотность", "ico": "🧊", "subj": "phys", "explain": ["Плотность показывает, какая масса приходится на единицу объёма: ρ = m : V.", "Пример: масса 8 г, объём 2 см³ → ρ = 8 : 2 = 4 г/см³.", "Из плотности и объёма находим массу: m = ρ · V. Например, 2 г/см³ · 5 см³ = 10 г.", "Совет Архимеда: нарисуй треугольник m-ρ-V — масса наверху. Закрываешь неизвестное пальцем — остаётся нужная формула."], "check": {"q": "Масса тела 6 г, объём 3 см³. Какова плотность? (в г/см³)", "choices": ["0,5", "2", "18"], "ans": 1, "exp": "ρ = m : V = 6 : 3 = 2 г/см³."}, "tasks": [{"q": "Тело объёмом 3 см³ имеет массу 15 г. Плотность? (в г/см³)", "kind": "unit", "ans": 5, "tol": 0, "hints": ["ρ = m : V.", "15 : 3 = ?"], "sol": "ρ = m : V = 15 : 3 = 5 г/см³."}, {"q": "Плотность вещества 4 г/см³, объём 5 см³. Найди массу. (в г)", "kind": "choice", "choices": ["20", "1,25", "5"], "ans": 0, "hints": ["m = ρ · V.", "4 · 5 = ?"], "sol": "m = ρ · V = 4 · 5 = 20 г."}]},
  {"id": 101, "title": "Сила тяжести и вес тела", "src": "Физика · 7 класс · Сила тяжести и вес", "ico": "🏋️", "subj": "phys", "explain": ["Сила тяжести — сила, с которой Земля притягивает тело: F = m · g.", "g ≈ 10 Н/кг. Тело массой 3 кг притягивается с силой F = 3 · 10 = 30 Н.", "Вес — сила, с которой тело давит на опору или растягивает подвес; в покое вес равен силе тяжести.", "Совет Архимеда: подвесь груз к динамометру — он покажет вес в ньютонах: груз массой 1 кг ≈ 10 Н."], "check": {"q": "Сила тяжести, действующая на тело массой 4 кг? (в Н, g = 10)", "choices": ["4", "40", "400"], "ans": 1, "exp": "F = m · g = 4 · 10 = 40 Н."}, "tasks": [{"q": "Сила тяжести, действующая на тело массой 7 кг? (в Н, g = 10)", "kind": "unit", "ans": 70, "tol": 0, "hints": ["F = m · g.", "7 · 10 = ?"], "sol": "F = m · g = 7 · 10 = 70 Н."}, {"q": "Какова масса тела, если сила тяжести равна 120 Н? (в кг, g = 10)", "kind": "choice", "choices": ["12", "1,2", "1200"], "ans": 0, "hints": ["m = F : g.", "120 : 10 = ?"], "sol": "m = F : g = 120 : 10 = 12 кг."}]},
  {"id": 102, "title": "Давление твёрдых тел: сила и площадь", "src": "Физика · 7 класс · Давление твёрдых тел", "ico": "🎿", "subj": "phys", "explain": ["Давление — сила, приходящаяся на единицу площади: p = F : S. Единица давления — паскаль (Па).", "Пример: сила 60 Н действует на площадь 3 м² → p = 60 : 3 = 20 Па.", "Чем меньше площадь, тем больше давление: острый нож режет легко, а широкие лыжи не проваливаются в снег.", "Совет Архимеда: если площадь дана в см², переводи её в м²: 1 м² = 10 000 см². Не переведёшь — ответ будет в 10 000 раз больше!"], "check": {"q": "Сила 80 Н действует на площадь 4 м². Каково давление? (в Па)", "choices": ["320", "20", "84"], "ans": 1, "exp": "p = F : S = 80 : 4 = 20 Па."}, "tasks": [{"q": "Сила 100 Н действует на площадь 2 м². Давление? (в Па)", "kind": "unit", "ans": 50, "tol": 0, "hints": ["p = F : S.", "100 : 2 = ?"], "sol": "p = F : S = 100 : 2 = 50 Па."}, {"q": "Давление 40 Па создаётся силой на площади 5 м². Чему равна сила? (в Н)", "kind": "choice", "choices": ["8", "200", "45"], "ans": 1, "hints": ["F = p · S.", "40 · 5 = ?"], "sol": "F = p · S = 40 · 5 = 200 Н."}]},
  {"id": 103, "title": "Сила трения", "src": "Физика · 7 класс · Сила трения", "ico": "🧤", "subj": "phys", "explain": ["Трение возникает, когда одно тело скользит или катится по другому. Без трения нельзя было бы ни ходить, ни ездить.", "Различают трение покоя, скольжения и качения: катить тележку легче, чем тащить, поэтому у машин колёса.", "Сила трения тем больше, чем шершавее поверхности и чем сильнее тело прижато к опоре.", "Совет Архимеда: зимой дороги посыпают песком — песок делает поверхность шершавой, трение растёт и машины не скользят."], "check": {"q": "Что увеличивает силу трения?", "choices": ["Гладкая отполированная поверхность", "Шершавая поверхность", "Смазка (масло)"], "ans": 1, "exp": "Шершавые поверхности цепляются друг за друга сильнее — трение больше."}, "tasks": [{"q": "Что уменьшает силу трения?", "kind": "choice", "choices": ["Песок на дороге", "Шершавые поверхности", "Смазка (масло)"], "ans": 2, "hints": ["Смазка заполняет неровности поверхностей.", "Поверхности перестают цепляться — трение падает."], "sol": "Смазка заполняет неровности, поверхности меньше цепляются — сила трения уменьшается."}, {"q": "Груз массой 2 кг тянут по столу, сила трения 4 Н. Сверху положили ещё один такой же груз (масса стала 4 кг). Какой станет сила трения? (в Н)", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Сила прижатия груза к столу выросла вдвое.", "Сила трения пропорциональна силе прижатия.", "4 · 2 = ?"], "sol": "Сила прижатия выросла в 2 раза → трение выросло в 2 раза: 4 · 2 = 8 Н."}]},
  {"id": 104, "title": "Закон Паскаля и давление жидкости", "src": "Физика · 8–9 класс · Закон Паскаля и давление жидкости", "ico": "🌊", "subj": "phys", "explain": ["Давление жидкости на глубине: p = ρ · g · h, где ρ — плотность жидкости, g = 10 Н/кг, h — глубина.", "Вода: ρ = 1000 кг/м³. На глубине 2 м: p = 1000 · 10 · 2 = 20 000 Па = 20 кПа.", "Закон Паскаля: давление, созданное в жидкости или газе, передаётся во все стороны одинаково — так работает гидравлический домкрат.", "Совет Архимеда: ныряя глубже, чувствуешь давление в ушах — оно растёт с глубиной: чем больше h, тем больше p."], "check": {"q": "Каково давление воды на глубине 5 м? (в кПа, ρ = 1000 кг/м³, g = 10)", "choices": ["5", "50", "500"], "ans": 1, "exp": "p = ρ · g · h = 1000 · 10 · 5 = 50 000 Па = 50 кПа."}, "tasks": [{"q": "Давление воды на глубине 3 м? (в кПа, ρ = 1000 кг/м³, g = 10)", "kind": "unit", "ans": 30, "tol": 0, "hints": ["p = ρ · g · h.", "1000 · 10 · 3 = 30 000 Па.", "30 000 Па = 30 кПа."], "sol": "p = ρ · g · h = 1000 · 10 · 3 = 30 000 Па = 30 кПа."}, {"q": "В сосуде масло плотностью 900 кг/м³ налито до глубины 2 м. Каково давление на дно? (в кПа, g = 10)", "kind": "choice", "choices": ["18", "1,8", "180"], "ans": 0, "hints": ["Подставь плотность масла, а не воды.", "900 · 10 · 2 = 18 000 Па.", "18 000 Па = 18 кПа."], "sol": "p = ρ · g · h = 900 · 10 · 2 = 18 000 Па = 18 кПа."}]},
  {"id": 105, "title": "Закон Ома: ток и напряжение", "src": "Физика · 8–9 класс · Закон Ома", "ico": "🔋", "subj": "phys", "explain": ["Сила тока в проводнике зависит от напряжения и сопротивления — закон Ома: I = U : R.", "Пример: напряжение 12 В, сопротивление 6 Ом → I = 12 : 6 = 2 А.", "Из закона Ома следуют: напряжение U = I · R и сопротивление R = U : I.", "Совет Архимеда: треугольник U-I-R — напряжение наверху, ток и сопротивление внизу. Закрой неизвестное пальцем и получи формулу."], "check": {"q": "Напряжение 15 В, сопротивление 5 Ом. Сила тока? (в А)", "choices": ["3", "10", "0,3"], "ans": 0, "exp": "I = U : R = 15 : 5 = 3 А."}, "tasks": [{"q": "Напряжение 20 В, сила тока 4 А. Сопротивление? (в Ом)", "kind": "unit", "ans": 5, "tol": 0, "hints": ["R = U : I.", "20 : 4 = ?"], "sol": "R = U : I = 20 : 4 = 5 Ом."}, {"q": "Сила тока 3 А, сопротивление 7 Ом. Напряжение? (в В)", "kind": "choice", "choices": ["4", "10", "21"], "ans": 2, "hints": ["U = I · R.", "3 · 7 = ?"], "sol": "U = I · R = 3 · 7 = 21 В."}]},
  {"id": 106, "title": "Сила Архимеда", "src": "Физика · 8–9 класс · Сила Архимеда", "ico": "⛵", "subj": "phys", "explain": ["На тело, погружённое в жидкость или газ, действует выталкивающая сила — сила Архимеда: F = ρ_ж · g · V, где V — объём погружённой части.", "Пример: вода ρ = 1000 кг/м³, g = 10 Н/кг, объём 0,2 м³ → F = 1000 · 10 · 0,2 = 2000 Н.", "Если сила Архимеда больше веса тела — тело всплывает, меньше — тонет. Корабли плавают, потому что их подводная часть вытесняет огромный объём воды.", "Совет Архимеда: попробуй погрузить надувной мяч под воду и отпустить — почувствуешь, как вода выталкивает его вверх."], "check": {"q": "Тело объёмом 0,2 м³ полностью погружено в воду (ρ = 1000 кг/м³). Сила Архимеда? (в Н, g = 10)", "choices": ["200", "2000", "20000"], "ans": 1, "exp": "F = ρ · g · V = 1000 · 10 · 0,2 = 2000 Н."}, "tasks": [{"q": "Тело объёмом 0,5 м³ полностью погружено в воду (ρ = 1000 кг/м³). Сила Архимеда? (в Н, g = 10)", "kind": "unit", "ans": 5000, "tol": 0, "hints": ["F = ρ · g · V.", "1000 · 10 · 0,5 = ?"], "sol": "F = ρ · g · V = 1000 · 10 · 0,5 = 5000 Н."}, {"q": "Тело объёмом 0,5 м³ погружено в керосин (ρ = 800 кг/м³). Сила Архимеда? (в Н, g = 10)", "kind": "choice", "choices": ["400", "4000", "40000"], "ans": 1, "hints": ["Плотность керосина 800 кг/м³ — меньше, чем у воды.", "800 · 10 · 0,5 = 4000."], "sol": "F = ρ · g · V = 800 · 10 · 0,5 = 4000 Н."}]},
  {"id": 107, "title": "Механическая энергия", "src": "Физика · 8–9 класс · Механическая энергия", "ico": "🎢", "subj": "phys", "explain": ["Механическая энергия бывает двух видов: потенциальная — энергия поднятого тела, и кинетическая — энергия движения.", "Потенциальная: E = m · g · h. Груз 2 кг на высоте 5 м: E = 2 · 10 · 5 = 100 Дж.", "Кинетическая: E = m · v² : 2. Тело массой 2 кг со скоростью 2 м/с: E = 2 · 4 : 2 = 4 Дж (v² = 2 · 2 = 4).", "Совет Архимеда: подними камень и отпусти — потенциальная энергия переходит в кинетическую: энергия не исчезает, а лишь меняет свой вид."], "check": {"q": "Потенциальная энергия груза массой 3 кг на высоте 2 м? (в Дж, g = 10)", "choices": ["30", "60", "12"], "ans": 1, "exp": "E = m · g · h = 3 · 10 · 2 = 60 Дж."}, "tasks": [{"q": "Кинетическая энергия тела массой 4 кг, движущегося со скоростью 3 м/с? (в Дж)", "kind": "unit", "ans": 18, "tol": 0, "hints": ["Сначала v² = 3 · 3 = 9.", "E = 4 · 9 : 2.", "36 : 2 = 18."], "sol": "E = m · v² : 2 = 4 · (3 · 3) : 2 = 36 : 2 = 18 Дж."}, {"q": "Груз массой 5 кг подняли так, что его потенциальная энергия стала 150 Дж. На какую высоту его подняли? (в м, g = 10)", "kind": "choice", "choices": ["3", "30", "0,3"], "ans": 0, "hints": ["E = m · g · h, значит h = E : (m · g).", "5 · 10 = 50.", "150 : 50 = ?"], "sol": "h = E : (m · g) = 150 : (5 · 10) = 150 : 50 = 3 м."}]},
  {"id": 108, "title": "Вещества вокруг нас", "src": "Химия · 5–6 класс · Вещества вокруг нас", "ico": "🧂", "subj": "chem", "explain": ["Вещество — то, из чего состоят тела. Вода, поваренная соль, сахар и железо — это вещества.", "Смесь состоит из нескольких веществ: морская вода — смесь воды и соли, воздух — смесь газов, молоко — тоже смесь.", "Поваренная соль — чистое вещество, её формула NaCl: один натрий Na и один хлор Cl.", "Вещества различают по свойствам: вода кипит при 100 °C, железо притягивается магнитом и ржавеет, сахар растворяется в воде.", "Железный гвоздь — тело, а железо, из которого он сделан, — вещество."], "check": {"q": "Что из перечисленного — одно вещество, а не смесь?", "choices": ["Морская вода", "Воздух", "Поваренная соль", "Гранит"], "ans": 2, "exp": "Поваренная соль — это NaCl, одно вещество; морская вода, воздух и гранит — смеси."}, "tasks": [{"q": "Что из перечисленного — смесь?", "kind": "choice", "choices": ["Сахар", "Железо", "Морская вода", "Медь"], "ans": 2, "tol": 0, "hints": ["В смеси несколько веществ.", "Морская вода — вода + растворённая соль."], "sol": "Морская вода — смесь воды и соли."}, {"q": "В списке «вода, сахар, воздух, железо» сколько чистых веществ?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Воздух — смесь газов.", "Вода, сахар и железо — чистые вещества.", "1 + 1 + 1 = 3."], "sol": "Чистых веществ 3: вода, сахар, железо; 1 + 1 + 1 = 3."}]},
  {"id": 109, "title": "Смеси и их разделение", "src": "Химия · 5–6 класс · Смеси", "ico": "🍵", "subj": "chem", "explain": ["Смесь разделяют, используя различия в свойствах веществ.", "Песок и вода: песок не растворяется и оседает на дно — это отстаивание.", "Фильтрование: смесь пропускают через фильтр (бумагу, ткань) — твёрдые частицы остаются на нём, а вода проходит.", "Соль из солёной воды получают выпариванием: вода испаряется, соль остаётся на дне чашки.", "Магнитом удобно отделять железные опилки от песка."], "check": {"q": "Как отделить песок от воды?", "choices": ["Выпариванием", "Фильтрованием", "Магнитом", "Нагреванием"], "ans": 1, "exp": "Песчинки останутся на фильтре, а вода пройдёт сквозь него."}, "tasks": [{"q": "Как вернуть соль из солёной воды?", "kind": "choice", "choices": ["Фильтрованием", "Выпариванием", "Магнитом", "Отстаиванием"], "ans": 1, "tol": 0, "hints": ["Соль растворена — она прошла бы через фильтр.", "Воду нужно испарить."], "sol": "При выпаривании вода уходит, соль остаётся."}, {"q": "На фильтре осталось 10 г песка, а через фильтр прошло 90 г воды. Какова была масса смеси до разделения? (в г)", "kind": "unit", "ans": 100, "tol": 0, "hints": ["Масса смеси = песок + вода.", "10 + 90 = 100."], "sol": "10 + 90 = 100 г."}]},
  {"id": 110, "title": "Растворы", "src": "Химия · 5–6 класс · Растворы", "ico": "🍬", "subj": "chem", "explain": ["Раствор — однородная смесь вещества (сахара, соли) и воды.", "Массовая доля вещества в растворе: ω = m(вещества) : m(раствора) · 100%.", "10%-ный раствор — в каждых 100 г раствора 10 г вещества и 90 г воды.", "Пример: 20% от 200 г = 0,2 · 200 = 40 г сахара.", "Проценты — это сотые доли: 10% = 0,1, а 20% = 0,2."], "check": {"q": "Сколько граммов сахара в 100 г 10%-ного раствора?", "choices": ["1", "5", "10", "100"], "ans": 2, "exp": "0,1 · 100 = 10 г сахара."}, "tasks": [{"q": "Сколько граммов сахара в 200 г 20%-ного раствора?", "kind": "unit", "ans": 40, "tol": 0, "hints": ["20% = 0,2.", "0,2 · 200 = 40."], "sol": "0,2 · 200 = 40 г сахара."}, {"q": "В 80 г раствора содержится 20 г соли. Сколько граммов воды в этом растворе?", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Масса раствора = соль + вода.", "80 − 20 = 60."], "sol": "80 − 20 = 60 г воды."}]},
  {"id": 111, "title": "Признаки химических реакций", "src": "Химия · 5–6 класс · Химические реакции", "ico": "💥", "subj": "chem", "explain": ["Химическая реакция — превращение одних веществ в другие, новые вещества.", "Признаки реакции: изменение цвета, выделение газа, выпадение осадка, выделение тепла и света.", "Пример: уксус + сода → шипение и пузырьки газа CO₂.", "Ржавление железа: появляется бурый налёт — новое вещество, изменился цвет.", "Таяние льда и кипение воды — не химические реакции: вещество остаётся тем же."], "check": {"q": "Какой признак показывает, что идёт химическая реакция?", "choices": ["Выделение газа", "Таяние льда", "Кипение воды", "Растворение сахара"], "ans": 0, "exp": "Газ — новое вещество; таяние, кипение и растворение меняют только состояние вещества."}, "tasks": [{"q": "Почему скисание молока относят к химическим реакциям?", "kind": "choice", "choices": ["Меняется только форма", "Образуются новые вещества", "Оно только нагревается", "Ничего не происходит"], "ans": 1, "tol": 0, "hints": ["При химической реакции получаются новые вещества.", "В скисшем молоке появляются новые вещества с кислым вкусом."], "sol": "Скисание даёт новые вещества — это химическая реакция."}, {"q": "Ржавление железа, таяние снега, скисание молока. Сколько здесь химических реакций?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Таяние снега: вода остаётся водой.", "Ржавление и скисание образуют новые вещества.", "2 реакции."], "sol": "Химических реакций 2: ржавление железа и скисание молока."}]},
  {"id": 112, "title": "Безопасность на кухне и в лаборатории", "src": "Химия · 5–6 класс · Безопасность", "ico": "⚠️", "subj": "chem", "explain": ["В лаборатории и на кухне строго соблюдают правила безопасности.", "Нельзя пробовать вещества на вкус и нюхать их, поднося прямо к лицу.", "Нельзя смешивать незнакомые вещества — может начаться реакция с выделением тепла или газа.", "Пролитую кислоту или щёлочь убирает только взрослый — они едкие.", "Спиртовку гасят колпачком, а горячую посуду берут прихваткой."], "check": {"q": "Чего нельзя делать в лаборатории?", "choices": ["Мыть посуду", "Пробовать вещества на вкус", "Читать инструкцию", "Надевать перчатки"], "ans": 1, "exp": "Вещества могут быть ядовитыми — пробовать их на вкус нельзя."}, "tasks": [{"q": "На столе пролита кислота. Что нужно сделать?", "kind": "choice", "choices": ["Вытереть бумагой", "Сразу позвать взрослого", "Попробовать её на вкус", "Продолжить работу"], "ans": 1, "tol": 0, "hints": ["Кислота едкая и опасная.", "Пролитое вещество убирает взрослый."], "sol": "Пролитую кислоту убирает взрослый."}, {"q": "Как правильно погасить спиртовку?", "kind": "choice", "choices": ["Задуть её", "Накрыть колпачком", "Залить водой", "Помахать рукой"], "ans": 1, "tol": 0, "hints": ["Дуть на спиртовку опасно.", "Колпачок перекрывает доступ воздуха."], "sol": "Спиртовку гасят колпачком — пламя гаснет без доступа кислорода."}]},
  {"id": 113, "title": "Металлы и неметаллы", "src": "Химия · 5–6 класс · Металлы и неметаллы", "ico": "🧲", "subj": "chem", "explain": ["По свойствам различают простые вещества — металлы и неметаллы (элементы железа, меди, кислорода, серы). А сложные вещества, например вода или поваренная соль, состоят из разных элементов.", "Металлы: железо, медь, алюминий. Они блестят, проводят тепло и электрический ток, их можно гнуть.", "Неметаллы: кислород O₂, азот N₂, сера S, углерод C (уголь).", "Кислород и азот — газообразные неметаллы, сера и уголь — твёрдые.", "Из меди и алюминия делают провода, из железа — гвозди и инструменты."], "check": {"q": "Что из перечисленного — металл?", "choices": ["Кислород", "Сера", "Железо", "Углерод"], "ans": 2, "exp": "Железо — металл: блестит и проводит электрический ток."}, "tasks": [{"q": "Какой металл чаще всего используют для электрических проводов?", "kind": "choice", "choices": ["Медь", "Сера", "Кислород", "Стекло"], "ans": 0, "tol": 0, "hints": ["Это металл розового цвета.", "Он отлично проводит ток."], "sol": "Медные провода хорошо проводят электрический ток."}, {"q": "В списке «железо, кислород, алюминий, сера» сколько металлов?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Железо и алюминий — металлы.", "Кислород и сера — неметаллы.", "1 + 1 = 2 металла."], "sol": "Металлов 2: железо и алюминий; 1 + 1 = 2."}]},
  {"id": 114, "title": "Воздух: кислород и другие газы", "src": "Химия · 5–6 класс · Воздух", "ico": "💨", "subj": "chem", "explain": ["Воздух — смесь газов, а не одно вещество.", "В воздухе примерно 78% азота N₂ и 21% кислорода O₂.", "В 100 л воздуха — около 78 л азота и 21 л кислорода.", "Оставшийся примерно 1% — углекислый газ CO₂, аргон и другие газы.", "Кислород поддерживает горение: в чистом кислороде огонь горит ярче, чем в воздухе."], "check": {"q": "В каком газе тлеющая лучинка вспыхивает ярким пламенем?", "choices": ["В азоте", "В кислороде", "В углекислом газе", "В водяном паре"], "ans": 1, "exp": "Кислород поддерживает горение, а азот и CO₂ — нет."}, "tasks": [{"q": "Сколько примерно литров азота в 100 л воздуха?", "kind": "unit", "ans": 78, "tol": 0, "hints": ["Азота в воздухе около 78%.", "78% от 100 л = 78 л."], "sol": "78% от 100 л = 78 л азота."}, {"q": "Воздух — это…", "kind": "choice", "choices": ["Простое вещество", "Смесь газов", "Химическое соединение", "Жидкость"], "ans": 1, "tol": 0, "hints": ["В нём несколько разных газов.", "Азот, кислород, углекислый газ…"], "sol": "Воздух — смесь газов."}]},
  {"id": 115, "title": "Горение", "src": "Химия · 5–6 класс · Горение", "ico": "🔥", "subj": "chem", "explain": ["Горение — реакция вещества с кислородом, при которой выделяются тепло и свет.", "Для горения нужны три условия: горючее вещество, кислород и тепло (температура воспламенения).", "Уберите одно из условий — огонь погаснет: пламя накрывают одеялом или пеной, чтобы перекрыть кислород.", "Продукт полного горения угля и газа — углекислый газ CO₂: C + O₂ → CO₂.", "Вода тушит огонь, охлаждая его, но горящее масло водой заливать нельзя!"], "check": {"q": "Почему одеяло гасит огонь?", "choices": ["Оно охлаждает пламя", "Перекрывает доступ кислорода", "Убирает горючее", "Создаёт ветер"], "ans": 1, "exp": "Одеяло не пропускает кислород, а без кислорода горение прекращается."}, "tasks": [{"q": "Что необходимо для горения свечи?", "kind": "choice", "choices": ["Только тепло", "Горючее, кислород и тепло", "Только кислород", "Вода и воздух"], "ans": 1, "tol": 0, "hints": ["Топливо свечи — парафин.", "Нужны все три условия: топливо, кислород, тепло."], "sol": "Горению нужны горючее, кислород и тепло."}, {"q": "В реакции горения углерода C + O₂ → CO₂: сколько атомов в молекуле продукта CO₂?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["В CO₂ один углерод и два кислорода.", "1 + 2 = 3."], "sol": "1 + 2 = 3 атома в молекуле CO₂."}]},
  {"id": 116, "title": "Символы элементов и формулы", "src": "Химия · 7 класс · Химические формулы", "ico": "🔠", "subj": "chem", "explain": ["Химический элемент обозначают символом: H — водород, C — углерод, N — азот, O — кислород, Na — натрий, Fe — железо.", "Формула показывает состав молекулы: какие атомы и сколько их.", "Индекс — число атомов: O₂ — два атома кислорода, CO₂ — один углерод и два кислорода.", "Если индекса нет, атом один: H₂O — 2 атома водорода и 1 кислород, всего 1 + 2 = 3 атома.", "Не путай Na (натрий) и N (азот)!"], "check": {"q": "Сколько атомов в одной молекуле CO₂?", "choices": ["2", "3", "4", "1"], "ans": 1, "exp": "C — 1 атом + O₂ — 2 атома = 3 атома."}, "tasks": [{"q": "Сколько атомов в двух молекулах H₂O?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["В одной H₂O — 3 атома (2 + 1).", "3 · 2 = 6."], "sol": "В H₂O 3 атома; в двух молекулах 3 · 2 = 6 атомов."}, {"q": "Сколько атомов кислорода в двух молекулах CO₂?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["В одной молекуле CO₂ два атома кислорода.", "2 · 2 = 4."], "sol": "2 молекулы · 2 атома = 4 атома кислорода."}]},
  {"id": 117, "title": "Валентность и составление формул", "src": "Химия · 7 класс · Валентность", "ico": "🔗", "subj": "chem", "explain": ["Валентность — способность атома соединяться с другими атомами; у водорода она всегда 1.", "Постоянные валентности — у водорода H = 1 и кислорода O = 2. У углерода, азота и хлора она переменная: в CO₂ углерод четырёхвалентен (C = 4), в NH₃ азот трёхвалентен (N = 3), в HCl хлор одновалентен (Cl = 1).", "В H₂O два водорода дают 2 · 1 = 2 связи, и кислород тратит 2 — формула верна.", "В CO₂ углерод тратит 4 связи, а два кислорода принимают 2 · 2 = 4 — всё сходится.", "Валентность часто указывают римскими цифрами, например S(IV)."], "check": {"q": "Чему равна валентность кислорода в соединениях?", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "Кислород в соединениях всегда двухвалентен: O = 2."}, "tasks": [{"q": "Какова валентность углерода в CO₂?", "kind": "choice", "choices": ["2", "3", "4", "1"], "ans": 2, "tol": 0, "hints": ["Два кислорода принимают 2 · 2 = 4 связи.", "Углерод отдаёт все 4 связи."], "sol": "В CO₂ валентность углерода 4: 1 · 4 = 2 · 2."}, {"q": "Азот (валентность 3) соединяется с водородом (валентность 1) в аммиак NHₓ. Сколько атомов водорода x в молекуле?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Азот тратит все 3 связи.", "Каждый водород даёт одну связь.", "x = 3 : 1 = 3."], "sol": "x = 3 : 1 = 3, формула NH₃."}]},
  {"id": 118, "title": "Относительная молекулярная масса", "src": "Химия · 7 класс · Молекулярная масса", "ico": "⚖️", "subj": "chem", "explain": ["Относительная молекулярная масса Mr показывает, во сколько раз молекула тяжелее 1/12 атома углерода.", "Mr равна сумме атомных масс всех атомов в формуле.", "Mr(H₂O) = 2 · 1 + 16 = 2 + 16 = 18.", "Mr(CO₂) = 12 + 2 · 16 = 12 + 32 = 44.", "Mr(O₂) = 2 · 16 = 32, а Mr(NaCl) = 23 + 35 = 58."], "check": {"q": "Чему равна Mr(CO₂)? (C = 12, O = 16)", "choices": ["28", "32", "44", "56"], "ans": 2, "exp": "Mr(CO₂) = 12 + 2 · 16 = 12 + 32 = 44."}, "tasks": [{"q": "Чему равна Mr(H₂O)? (H = 1, O = 16)", "kind": "unit", "ans": 18, "tol": 0, "hints": ["2 атома водорода и 1 кислород.", "2 · 1 + 16 = 2 + 16 = 18."], "sol": "Mr(H₂O) = 2 · 1 + 16 = 18."}, {"q": "Чему равна Mr(NaCl)? (Na = 23, Cl = 35)", "kind": "unit", "ans": 58, "tol": 0, "hints": ["23 + 35.", "23 + 35 = 58."], "sol": "Mr(NaCl) = 23 + 35 = 58."}]},
  {"id": 119, "title": "Массовая доля элемента", "src": "Химия · 7 класс · Массовая доля", "ico": "📊", "subj": "chem", "explain": ["Массовая доля элемента показывает, какая часть массы вещества приходится на этот элемент.", "ω = масса всех атомов элемента : масса всей молекулы · 100%.", "Mr(MgO) = 24 + 16 = 40.", "Доля магния: 24 : 40 = 0,6 → 60%. Доля кислорода: 16 : 40 = 0,4 → 40%.", "Проверка: 60% + 40% = 100% — учтена вся масса вещества."], "check": {"q": "Какова массовая доля магния в оксиде MgO? (в %)", "choices": ["40", "50", "60", "24"], "ans": 2, "exp": "Mr(MgO) = 24 + 16 = 40; 24 : 40 = 0,6 = 60%."}, "tasks": [{"q": "Какова массовая доля кислорода в MgO? (в %)", "kind": "unit", "ans": 40, "tol": 0, "hints": ["Mr(MgO) = 24 + 16 = 40.", "16 : 40 = 0,4.", "40%."], "sol": "16 : (24 + 16) = 16 : 40 = 0,4 = 40%."}, {"q": "Какова массовая доля кислорода в SO₂? (S = 32, O = 16; в %)", "kind": "unit", "ans": 50, "tol": 0, "hints": ["Mr(SO₂) = 32 + 2 · 16 = 64.", "Масса кислорода: 2 · 16 = 32.", "32 : 64 = 0,5 = 50%."], "sol": "2 · 16 = 32; 32 : 64 = 0,5 = 50%."}]},
  {"id": 120, "title": "Массовая доля вещества в растворе", "src": "Химия · 8–9 класс · Растворы", "ico": "🧃", "subj": "chem", "explain": ["Массовая доля растворённого вещества: ω = m(вещества) : m(раствора) · 100%.", "Масса раствора = масса вещества + масса воды.", "10 г соли растворили в 90 г воды: масса раствора 10 + 90 = 100 г, ω = 10 : 100 = 10%.", "25 г соли в 75 г воды: масса раствора 100 г, ω = 25 : 100 = 25%.", "Если масса раствора 100 г, массовая доля в процентах равна массе вещества в граммах."], "check": {"q": "В 90 г воды растворили 10 г соли. Какова массовая доля соли? (в %)", "choices": ["1", "10", "90", "100"], "ans": 1, "exp": "10 : (10 + 90) = 10 : 100 = 0,1 = 10%."}, "tasks": [{"q": "В 75 г воды растворили 25 г соли. Какова массовая доля соли? (в %)", "kind": "unit", "ans": 25, "tol": 0, "hints": ["Масса раствора: 25 + 75 = 100 г.", "25 : 100 = 0,25.", "25%."], "sol": "25 : (25 + 75) = 25 : 100 = 0,25 = 25%."}, {"q": "Сколько граммов сахара в 400 г 25%-ного раствора?", "kind": "unit", "ans": 100, "tol": 0, "hints": ["25% = 0,25.", "0,25 · 400 = 100."], "sol": "0,25 · 400 = 100 г сахара."}]},
  {"id": 121, "title": "Количество вещества: моль", "src": "Химия · 8–9 класс · Количество вещества", "ico": "🧮", "subj": "chem", "explain": ["Моль — порция вещества, содержащая 6·10²³ частиц (число Авогадро).", "Масса одного моля — молярная масса M; численно равна Mr: M(H₂O) = 18 г/моль.", "Количество вещества: n = m : M.", "36 г воды: n = 36 : 18 = 2 моль.", "44 г CO₂ → n = 44 : 44 = 1 моль; 4 г H₂ → n = 4 : 2 = 2 моль."], "check": {"q": "Сколько моль воды в 36 г H₂O? (M = 18 г/моль)", "choices": ["1", "2", "3", "18"], "ans": 1, "exp": "n = 36 : 18 = 2 моль."}, "tasks": [{"q": "Сколько моль в 44 г CO₂? (M = 44 г/моль)", "kind": "unit", "ans": 1, "tol": 0, "hints": ["n = m : M.", "44 : 44 = 1."], "sol": "n = 44 : 44 = 1 моль."}, {"q": "Сколько моль водорода в 4 г H₂? (M = 2 г/моль)", "kind": "unit", "ans": 2, "tol": 0, "hints": ["n = m : M.", "4 : 2 = 2."], "sol": "n = 4 : 2 = 2 моль."}]},
  {"id": 122, "title": "Кислоты и основания: индикаторы", "src": "Химия · 8–9 класс · Кислоты и основания", "ico": "🌈", "subj": "chem", "explain": ["Кислоты — едкие вещества: HCl — соляная кислота, H₂SO₄ — серная.", "Основания-щёлочи: NaOH — гидроксид натрия, KOH. Они тоже едкие!", "Индикаторы — вещества, которые меняют цвет в кислой и щелочной среде.", "Лакмус: в кислоте красный, в щёлочи синий.", "Фенолфталеин: в щёлочи малиновый, в кислоте бесцветный. Вещества не пробуют на вкус — пользуются индикаторами!"], "check": {"q": "Какой цвет имеет лакмус в кислоте?", "choices": ["Синий", "Красный", "Зелёный", "Оранжевый"], "ans": 1, "exp": "В кислой среде лакмус краснеет."}, "tasks": [{"q": "В раствор капнули лакмус — он стал синим. Какова среда раствора?", "kind": "choice", "choices": ["Кислая", "Щелочная", "Нейтральная", "Газовая"], "ans": 1, "tol": 0, "hints": ["В кислоте лакмус красный.", "Синий цвет — признак щёлочи."], "sol": "Синий лакмус — признак щелочной среды."}, {"q": "Какая из формул обозначает кислоту?", "kind": "choice", "choices": ["NaOH", "HCl", "NaCl", "H₂O"], "ans": 1, "tol": 0, "hints": ["NaOH — основание (щёлочь).", "NaCl — соль, H₂O — вода."], "sol": "HCl — соляная кислота."}]},
  {"id": 123, "title": "Типы химических реакций", "src": "Химия · 8–9 класс · Типы реакций", "ico": "🔀", "subj": "chem", "explain": ["Реакция соединения: из двух веществ получается одно. 2H₂ + O₂ → 2H₂O.", "Реакция разложения: из одного вещества — несколько. CaCO₃ → CaO + CO₂.", "Реакция замещения: атом металла вытесняет другой из соединения. Fe + CuSO₄ → FeSO₄ + Cu.", "Реакция обмена: вещества обмениваются своими частями. AgNO₃ + NaCl → AgCl↓ + NaNO₃.", "Тип реакции определяют по числу исходных веществ и продуктов: сколько было — сколько стало."], "check": {"q": "Какой тип реакции: CaCO₃ → CaO + CO₂?", "choices": ["Соединение", "Разложение", "Замещение", "Обмен"], "ans": 1, "exp": "Одно вещество распадается на два — это разложение."}, "tasks": [{"q": "Какой тип реакции: 2H₂ + O₂ → 2H₂O?", "kind": "choice", "choices": ["Разложение", "Соединение", "Замещение", "Обмен"], "ans": 1, "tol": 0, "hints": ["Слева два вещества, справа одно.", "Два вещества соединяются в одно."], "sol": "Из двух веществ образуется одно — соединение."}, {"q": "Какой тип реакции: Fe + CuSO₄ → FeSO₄ + Cu?", "kind": "choice", "choices": ["Соединение", "Разложение", "Замещение", "Обмен"], "ans": 2, "tol": 0, "hints": ["Железо вытесняет медь из её соли.", "Один атом заменяет другой."], "sol": "Железо замещает медь в CuSO₄ — это замещение."}]},
  {"id": 124, "title": "Алгоритмы вокруг нас", "src": "Информатика · 5–6 класс · Алгоритмы вокруг нас", "ico": "🧭", "subj": "inf", "explain": ["Алгоритм — это точный порядок действий, который приводит к нужному результату. Как рецепт или инструкция.", "Собирая портфель, мы выполняем алгоритм: 1) взять дневник, 2) сложить учебники, 3) положить пенал, 4) свериться со списком.", "Порядок важен: сначала надевают носки, потом ботинки, а не наоборот — переставишь шаги, и результат испортится.", "Совет Архимеда: нумеруй действия по порядку. Если один пункт нельзя выполнить раньше другого — значит, порядок обязателен."], "check": {"q": "Сколько действий в алгоритме «приготовить бутерброд»: 1) взять хлеб, 2) намазать масло, 3) положить сыр, 4) накрыть вторым куском хлеба?", "choices": ["3", "4", "5", "2"], "ans": 1, "exp": "Действий четыре: 1) хлеб, 2) масло, 3) сыр, 4) накрыть — всего 4 действия."}, "tasks": [{"q": "В алгоритме «сделать салат» пять шагов: 1) помыть овощи, 2) почистить, 3) нарезать, 4) заправить, 5) перемешать. Под каким номером выполняется действие «перемешать»?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Пронумеруй шаги по порядку.", "Перемешивают в самом конце — после шага 4."], "sol": "Перемешивание — шаг 5: после «заправить» (4) идёт «перемешать» (5)."}, {"q": "В алгоритме «посадить дерево» перепутали шаги: полили землю, выкопали яму, поставили саженец. Какой шаг обязан идти первым?", "kind": "choice", "choices": ["Выкопать яму", "Полить землю", "Поставить саженец", "Засыпать землёй"], "ans": 0, "tol": 0, "hints": ["Яма нужна раньше, чем в неё что-то ставить.", "Поливают после посадки, а не до неё."], "sol": "Сначала копают яму: шаг «выкопать» раньше «поставить саженец» и «полить»."}]},
  {"id": 125, "title": "Блок-схемы", "src": "Информатика · 5–6 класс · Блок-схемы", "ico": "🔷", "subj": "inf", "explain": ["Блок-схема рисует алгоритм картинкой: овал — начало и конец, прямоугольник — действие, ромб — вопрос с ответом да/нет.", "Схема «выйти из дома»: овал «начало» → прямоугольник «взять ключи» → прямоугольник «выйти» → овал «конец».", "Ромб — развилка: стрелка «да» ведёт к одним действиям, стрелка «нет» — к другим. Например, вопрос «Идёт дождь?».", "Совет Архимеда: читай схему по стрелкам сверху вниз — каждая стрелка показывает, какое действие следующее."], "check": {"q": "В блок-схеме «пойти в школу» есть одна развилка с вопросом «Идёт дождь?»: если да — взять зонт, если нет — идти без зонта. Сколько ромбов-вопросов в этой схеме?", "choices": ["0", "1", "2", "3"], "ans": 1, "exp": "Одна развилка — один ромб-вопрос: 1 ромб."}, "tasks": [{"q": "В блок-схеме «сходить в магазин»: овал «начало», прямоугольник «взять деньги», прямоугольник «купить хлеб», овал «конец». Сколько прямоугольников (действий) в этой схеме?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Действия на схемах — прямоугольники.", "Их здесь два: «взять деньги» и «купить хлеб»."], "sol": "Прямоугольников 2: «взять деньги» и «купить хлеб»."}, {"q": "Какой фигурой на блок-схеме обозначают вопрос (условие с ответом да/нет)?", "kind": "choice", "choices": ["Овалом", "Прямоугольником", "Ромбом", "Стрелкой"], "ans": 2, "tol": 0, "hints": ["Овал — начало и конец, прямоугольник — действие.", "Вопрос похож на развилку дорог."], "sol": "Вопрос рисуют ромбом — из него выходят ветки «да» и «нет»."}]},
  {"id": 126, "title": "Кодирование и шифры", "src": "Информатика · 5–6 класс · Кодирование и шифры", "ico": "🔤", "subj": "inf", "explain": ["Код превращает сообщение в секретное. Шифр Цезаря сдвигает каждую букву на шаг: А→Б, Б→В, В→Г.", "Другой код — числовой: 1=А, 2=Б, 3=В, 4=Г, 5=Д… Тогда числа 2, 1, 5 — это буквы Б, А, Д → слово «БАД».", "Расшифровка — обратное действие: букве Б соответствует число 2, а числу 13 — буква Л.", "Совет Архимеда: держи кодовую таблицу перед глазами и заменяй по одной букве — не пропустишь и не перепутаешь."], "check": {"q": "Кодовая таблица: 1=А, 2=Б, 3=В, 4=Г, 5=Д. Какое слово записано числами 2, 1, 5?", "choices": ["БАЛ", "БАД", "ГАД", "ДОМ"], "ans": 1, "exp": "2=Б, 1=А, 5=Д → «БАД»."}, "tasks": [{"q": "В шифре Цезаря букву Д (она 5-я по счёту: А=1, Б=2, В=3, Г=4, Д=5) сдвигают на 1 вперёд. Каким по счёту станет зашифрованная буква?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Сдвиг на 1 прибавляет 1 к номеру буквы.", "5 + 1 = 6 — это буква Е."], "sol": "Номер Д — 5; сдвиг +1: 5+1 = 6 → буква Е."}, {"q": "Код: 1=А, 2=Б, 3=В… (в алфавите 33 буквы, Ё считается). Известно: 12=К, 10=И, 20=Т. Какое слово зашифровано числами 12, 10, 20?", "kind": "choice", "choices": ["ТИК", "КИТ", "КОТ", "КИВ"], "ans": 1, "tol": 0, "hints": ["Найди буквы по номерам: 12, 10, 20.", "12=К, 10=И, 20=Т."], "sol": "12=К, 10=И, 20=Т → «КИТ»."}]},
  {"id": 127, "title": "Графы и связи", "src": "Информатика · 5–6 класс · Графы и связи", "ico": "🕸️", "subj": "inf", "explain": ["Граф — это точки (вершины) и линии между ними (рёбра). Вершины — города, рёбра — дороги между ними.", "Три точки, соединённые попарно (каждая с каждой), образуют треугольник — у него 3 ребра.", "Если точек 4 и каждая связана с каждой, то из каждой точки выходит 3 ребра, но каждое ребро посчитано дважды: 4·3/2 = 6 рёбер.", "Совет Архимеда: рисуй точки по кругу и соединяй их по очереди — так ничего не забудешь."], "check": {"q": "Три точки соединены попарно: каждая с каждой. Сколько рёбер получилось?", "choices": ["2", "3", "4", "6"], "ans": 1, "exp": "Получается треугольник: 3·2/2 = 3 ребра."}, "tasks": [{"q": "Четыре точки соединены попарно (каждая с каждой). Сколько рёбер в таком графе?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Из каждой из 4 точек выходит 3 ребра.", "Но каждое ребро посчитано дважды: 4·3/2."], "sol": "4·3/2 = 6 рёбер."}, {"q": "У квадрата 4 вершины, соединённые по сторонам. Сколько рёбер выходит из одной вершины?", "kind": "choice", "choices": ["1", "3", "2", "4"], "ans": 2, "tol": 0, "hints": ["У каждой вершины квадрата ровно два соседа.", "Из угла выходят две стороны."], "sol": "Из вершины квадрата выходят 2 ребра-стороны."}]},
  {"id": 128, "title": "Высказывания с И, ИЛИ и НЕ", "src": "Информатика · 5–6 класс · Логика: И, ИЛИ, НЕ", "ico": "🧠", "subj": "inf", "explain": ["Высказывание — предложение, которое либо истинно, либо ложно. «2+2=4» — истина, «2+2=5» — ложь.", "И: верно, только когда верны обе части. «2+2=4 И 3>1» — истина, потому что истинны обе части.", "ИЛИ: верно, когда верна хотя бы одна часть. НЕ переворачивает смысл: НЕ(«летом идёт снег») — истина.", "Совет Архимеда: проверяй каждую часть отдельно, а потом соединяй по правилам И, ИЛИ, НЕ."], "check": {"q": "Высказывание «2+2=4 И 3>1» — истина или ложь?", "choices": ["Истина", "Ложь"], "ans": 0, "exp": "2+2=4 — истина, 3>1 — истина; И двух истин = истина."}, "tasks": [{"q": "Сколько из трёх высказываний истинны: «2+2=4», «5<3», «1=1»?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Проверь каждое: 2+2=4 — да, 5<3 — нет, 1=1 — да.", "Истинны два высказывания из трёх."], "sol": "Истинны «2+2=4» и «1=1» → 2 высказывания."}, {"q": "Какое высказывание ложно?", "kind": "choice", "choices": ["7+1=8", "3·3=9", "10−3=6", "4+4=8"], "ans": 2, "tol": 0, "hints": ["Посчитай каждое равенство отдельно.", "10−3 = 7, а не 6."], "sol": "10−3=6 — ложь, ведь 10−3 = 7."}]},
  {"id": 129, "title": "Последовательности и закономерности", "src": "Информатика · 5–6 класс · Последовательности и закономерности", "ico": "🔢", "subj": "inf", "explain": ["Закономерность — правило, по которому числа идут друг за другом. Нашёл правило — продолжил ряд.", "Ряд 2, 4, 6, 8: каждое следующее на 2 больше → дальше идёт 8+2 = 10.", "Ряд 1, 2, 4, 8: каждое следующее умножается на 2 → дальше идёт 8·2 = 16.", "Совет Архимеда: смотри, что происходит между соседями — плюс, минус или умножение? Одно правило на весь ряд!"], "check": {"q": "Продолжи ряд: 2, 4, 6, 8, …", "choices": ["9", "10", "11", "12"], "ans": 1, "exp": "Шаг «+2»: 8+2 = 10."}, "tasks": [{"q": "Продолжи ряд: 1, 2, 4, 8, …", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Каждое число умножается на 2.", "8·2 = 16."], "sol": "Шаг «умножить на 2»: 8·2 = 16."}, {"q": "Какой ряд построен по правилу «умножать на 2»?", "kind": "choice", "choices": ["1, 2, 3, 4", "1, 2, 4, 8", "1, 3, 5, 7", "10, 8, 6, 4"], "ans": 1, "tol": 0, "hints": ["Проверь, что получается из каждого числа.", "1·2=2, 2·2=4, 4·2=8."], "sol": "1·2=2, 2·2=4, 4·2=8 → подходит ряд 1, 2, 4, 8."}]},
  {"id": 130, "title": "Таблицы и схемы", "src": "Информатика · 5–6 класс · Таблицы и схемы", "ico": "📊", "subj": "inf", "explain": ["Таблица хранит данные в строках и столбцах. Чтобы ответить, найди нужную строку и нужный столбец.", "В таблице: Ваня — 5 книг, Катя — 8 книг, Миша — 3 книги. Напротив Кати стоит число 8 — значит, она прочитала 8 книг.", "Если сложить все числа строки, узнаем сумму: 5+8+3 = 16 книг ребята прочитали вместе.", "Совет Архимеда: сначала найди клетку на пересечении строки и столбца — и только потом читай число."], "check": {"q": "В таблице записано, сколько книг прочитали за месяц: Ваня — 5, Катя — 8, Миша — 3. Сколько книг прочитала Катя?", "choices": ["5", "8", "3", "16"], "ans": 1, "exp": "В строке Кати стоит число 8 → 8 книг."}, "tasks": [{"q": "По той же таблице: Ваня — 5 книг, Катя — 8, Миша — 3. Сколько книг ребята прочитали вместе?", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Сложи числа из таблицы.", "5+8 = 13, 13+3 = 16."], "sol": "5+8+3 = 16 книг."}, {"q": "В таблице уроков: понедельник — 6 уроков, вторник — 5, среда — 7, четверг — 5, пятница — 4. В какой день уроков больше всего?", "kind": "choice", "choices": ["Понедельник", "Вторник", "Среда", "Пятница"], "ans": 2, "tol": 0, "hints": ["Сравни числа 6, 5, 7, 5, 4.", "7 — самое большое, и стоит оно в строке среды."], "sol": "Больше всех 7 уроков — в среду."}]},
  {"id": 131, "title": "Безопасный интернет", "src": "Информатика · 5–6 класс · Безопасный интернет", "ico": "🛡️", "subj": "inf", "explain": ["В интернете, как и на улице, есть правила безопасности: личные данные незнакомцам не сообщают.", "Надёжный пароль — длинный и непредсказуемый: буквы разного регистра, цифры и знаки, например Dp7!k#9.", "Домашний адрес, номер школы, пароли и личные фото не выкладывают открыто и не отправляют тем, кого не знаешь лично.", "Совет Архимеда: если незнакомец просит что-то странное — не отвечай, а покажи переписку родителям или учителю."], "check": {"q": "Какой пароль самый надёжный?", "choices": ["123456", "qwerty", "Имя и дата рождения", "Dp7!k#9"], "ans": 3, "exp": "Случайный набор из букв, цифр и знаков (Dp7!k#9) — самый стойкий."}, "tasks": [{"q": "Что НЕЛЬЗЯ сообщать незнакомцу в интернете?", "kind": "choice", "choices": ["Свой домашний адрес и номер школы", "Свой любимый цвет", "Свою любимую книгу", "Любимый мультфильм"], "ans": 0, "tol": 0, "hints": ["Адрес и школа помогают найти тебя в реальном мире.", "Увлечения и вкусы — не секрет."], "sol": "Адрес и номер школы — личные данные, их незнакомцам не сообщают."}, {"q": "Незнакомец в чате просит прислать твоё фото и домашний адрес. Как поступить?", "kind": "choice", "choices": ["Прислать, чтобы не обидеть", "Ничего не отправлять и рассказать родителям", "Прислать, но попросить его фото", "Договориться о встрече"], "ans": 1, "tol": 0, "hints": ["Незнакомец не имеет права требовать личные данные.", "О подозрительной переписке всегда рассказывают взрослым."], "sol": "Правильно: ничего не отправлять и рассказать родителям."}]},
  {"id": 132, "title": "Восьмеричная и шестнадцатеричная системы", "src": "Информатика · 7 класс · Восьмеричная и шестнадцатеричная системы", "ico": "🧮", "subj": "inf", "explain": ["В восьмеричной системе 8 цифр (0–7), в шестнадцатеричной — 16: 0–9 и буквы A, B, C, D, E, F.", "Перевод простых чисел: 10₁₀ = одна восьмёрка и две единицы → 12₈; 8₁₀ = одна восьмёрка и ноль → 10₈.", "В шестнадцатеричной: 16₁₀ = 10₁₆ (одна «шестнадцатка» и ноль), а 15₁₀ = F₁₆.", "Совет Архимеда: смотри, сколько раз основание (8 или 16) помещается в числе: частное — старшая цифра, остаток — младшая."], "check": {"q": "Как записывается число 10 (десятичное) в восьмеричной системе?", "choices": ["12", "10", "11", "13"], "ans": 0, "exp": "10 = 1·8 + 2 → 12₈."}, "tasks": [{"q": "Как записывается число 8 (десятичное) в восьмеричной системе?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["8 — это одна восьмёрка и ноль единиц.", "8 = 1·8 + 0."], "sol": "8 = 1·8 + 0 → 10₈."}, {"q": "В шестнадцатеричной системе после цифры 9 идут буквы: A=10, B=11, C=12, D=13, E=14, F=15. Как записывается число 15 (десятичное)?", "kind": "choice", "choices": ["A", "E", "F", "10"], "ans": 2, "tol": 0, "hints": ["Считай по буквам: A=10, B=11, C=12, D=13, E=14, F=15.", "Пятнадцати соответствует F."], "sol": "15₁₀ = F₁₆."}]},
  {"id": 133, "title": "Таблицы истинности", "src": "Информатика · 7 класс · Таблицы истинности", "ico": "⚙️", "subj": "inf", "explain": ["В логике две величины: 0 (ложь) и 1 (истина). Таблица истинности показывает результат операции для всех вариантов.", "И равно 1, только когда оба операнда — 1: 1 И 1 = 1, а 1 И 0 = 0 и 0 И 0 = 0.", "ИЛИ равно 0, только когда оба нули: 0 ИЛИ 0 = 0, а 0 ИЛИ 1 = 1. НЕ меняет значение: НЕ 1 = 0, НЕ 0 = 1.", "Совет Архимеда: вычисляй по действиям — сначала скобки и НЕ, потом И, потом ИЛИ."], "check": {"q": "Чему равно 0 И 1?", "choices": ["0", "1"], "ans": 0, "exp": "И даёт 1 только при 1 и 1, а здесь есть 0 → 0 И 1 = 0."}, "tasks": [{"q": "Чему равно 0 ИЛИ 1?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["ИЛИ даёт 1, если есть хотя бы одна единица.", "0 ИЛИ 1 = 1."], "sol": "0 ИЛИ 1 = 1."}, {"q": "Чему равно НЕ (1 И 0)?", "kind": "choice", "choices": ["0", "1"], "ans": 1, "tol": 0, "hints": ["Сначала вычисли скобки: 1 И 0 = 0.", "Потом НЕ 0 = 1."], "sol": "1 И 0 = 0, затем НЕ 0 = 1."}]},
  {"id": 134, "title": "Программирование: переменные", "src": "Информатика · 7 класс · Программирование: переменные", "ico": "📦", "subj": "inf", "explain": ["Переменная — ячейка памяти с именем, где хранится число. Команда x = 5 кладёт в x число 5.", "Команда x = x + 3 читается так: возьми текущее значение x (5), прибавь 3 и положи обратно: x = 5+3 = 8.", "Переменная хранит только последнее значение: если после x = 8 выполнить x = 1, в x останется 1.", "Совет Архимеда: решай по шагам — подставляй текущее значение и записывай новое после каждой команды."], "check": {"q": "x = 5, затем выполняется команда x = x + 3. Чему теперь равно x?", "choices": ["5", "8", "3", "15"], "ans": 1, "exp": "x = 5+3 = 8."}, "tasks": [{"q": "x = 3; y = 2; затем выполняется x = x + y. Чему стало равно x?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Подставь текущие значения: x = 3, y = 2.", "3 + 2 = 5."], "sol": "x = 3+2 = 5."}, {"q": "Выполни команды по порядку: x = 10; x = x − 4; x = x · 2. Чему стало равно x?", "kind": "choice", "choices": ["12", "6", "16", "10"], "ans": 0, "tol": 0, "hints": ["Сначала x = 10−4 = 6.", "Потом x = 6·2 = 12."], "sol": "10−4 = 6, затем 6·2 = 12."}]},
  {"id": 135, "title": "Ветвления", "src": "Информатика · 7 класс · Ветвления", "ico": "🚦", "subj": "inf", "explain": ["Ветвление — конструкция «если … то …, иначе …»: программа выбирает одну из двух веток по условию.", "Правило: если x > 0, печатай «да», иначе печатай «нет». При x = 7 условие истинно → выводится «да».", "При x = −2 условие «x > 0» ложно → выполняется ветка «иначе»: выводится «нет».", "Совет Архимеда: сначала проверь условие, потом выполняй ТОЛЬКО выбранную ветку — вторая не выполняется."], "check": {"q": "Программа: если x > 0, печать «да», иначе печать «нет». x = 7. Что выведет программа?", "choices": ["да", "нет"], "ans": 0, "exp": "7 > 0 — истина → печать «да»."}, "tasks": [{"q": "x = 4. Выполняется: если x > 0, то x = x + 6, иначе x = x − 1. Чему стало равно x?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["Условие x > 0 истинно, ведь 4 > 0.", "Выполняется ветка «то»: 4 + 6 = 10."], "sol": "4 > 0 — истина → x = 4+6 = 10."}, {"q": "Программа: если x > 0, печать «да», иначе печать «нет». x = −2. Что выведет программа?", "kind": "choice", "choices": ["да", "нет"], "ans": 1, "tol": 0, "hints": ["Сравни −2 с нулём: −2 меньше нуля.", "Условие ложно → выполняется «иначе»."], "sol": "−2 > 0 — ложь → печать «нет»."}]},
  {"id": 136, "title": "Циклы", "src": "Информатика · 8–9 класс · Циклы", "ico": "🔁", "subj": "inf", "explain": ["Цикл «повтори N раз» выполняет команды несколько раз, чтобы не писать их вручную.", "Повтори 3 раза команду «сделай 4 шага»: робот пройдёт 3·4 = 12 шагов.", "Цикл с накоплением суммы: складываем 1, затем 2, и так до 5: 1+2+3+4+5 = 15.", "Совет Архимеда: сколько раз повторяется тело цикла — столько раз выполняется и каждая его команда."], "check": {"q": "Робот повторил 3 раза команду «сделай 4 шага». Сколько всего шагов он сделал?", "choices": ["7", "12", "34", "4"], "ans": 1, "exp": "3·4 = 12 шагов."}, "tasks": [{"q": "Цикл складывает числа от 1 до 5: к сумме добавляются 1, 2, 3, 4, 5. Чему равна получившаяся сумма?", "kind": "unit", "ans": 15, "tol": 0, "hints": ["Складывай по очереди: 1+2 = 3, 3+3 = 6…", "6+4 = 10, 10+5 = 15."], "sol": "1+2+3+4+5 = 15."}, {"q": "Робот повторил 4 раза команду «сделай 7 шагов». Сколько всего шагов он сделал?", "kind": "choice", "choices": ["28", "11", "7", "4"], "ans": 0, "tol": 0, "hints": ["Умножь число повторов на длину команды.", "4·7 = 28."], "sol": "4·7 = 28 шагов."}]},
  {"id": 137, "title": "Линейный и бинарный поиск", "src": "Информатика · 8–9 класс · Линейный и бинарный поиск", "ico": "🔍", "subj": "inf", "explain": ["Линейный поиск проверяет элементы по одному, а бинарный каждый вопрос «больше или меньше?» отбрасывает половину вариантов.", "Число от 1 до 8: вопрос «больше 4?» делит варианты пополам: 8 → 4 → 2 → 1 — всего 3 вопроса.", "Степени двойки подсказывают ответ: 2³ = 8 → 3 вопроса, 2⁴ = 16 → 4 вопроса, 2⁵ = 32 → 5 вопросов.", "Совет Архимеда: найди степень двойки, не меньшую числа вариантов, — её показатель и есть число вопросов."], "check": {"q": "Сколько вопросов «больше/меньше» нужно, чтобы гарантированно угадать число от 1 до 8?", "choices": ["2", "3", "4", "8"], "ans": 1, "exp": "2³ = 8 → 3 вопроса."}, "tasks": [{"q": "Сколько вопросов «больше/меньше» нужно, чтобы угадать число от 1 до 16?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Каждый вопрос вдвое сокращает число вариантов.", "2⁴ = 16."], "sol": "2⁴ = 16 → 4 вопроса."}, {"q": "Сколько вопросов «больше/меньше» нужно, чтобы угадать число от 1 до 32?", "kind": "choice", "choices": ["5", "4", "6", "32"], "ans": 0, "tol": 0, "hints": ["Для 16 вариантов нужно 4 вопроса — для 32 на один больше.", "2⁵ = 32."], "sol": "2⁵ = 32 → 5 вопросов."}]},
  {"id": 138, "title": "Простые сортировки", "src": "Информатика · 8–9 класс · Простые сортировки", "ico": "🫧", "subj": "inf", "explain": ["Сортировка расставляет числа по порядку. Пузырёк проходит по списку и меняет местами соседей, стоящих неправильно.", "Список 3, 1, 2: на первом проходе 3 и 1 меняются местами (1, 3, 2), затем 3 и 2 (1, 2, 3) — упорядочено.", "После каждого прохода самое большое число «всплывает» в конец и больше не трогается.", "Совет Архимеда: для n чисел пузырьку нужно не больше n−1 проходов — у последнего числа уже нет конкурентов."], "check": {"q": "Сколько проходов максимум нужно пузырьку, чтобы отсортировать 3 числа?", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "n−1 = 3−1 = 2 прохода."}, "tasks": [{"q": "Как выглядит список 3, 1, 2 после сортировки по возрастанию?", "kind": "choice", "choices": ["3, 1, 2", "1, 3, 2", "1, 2, 3", "2, 1, 3"], "ans": 2, "tol": 0, "hints": ["Наименьшее число должно стать первым.", "1 < 2 < 3."], "sol": "По возрастанию: 1, 2, 3."}, {"q": "Сколько проходов максимум нужно пузырьку, чтобы отсортировать 5 чисел?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Формула: n − 1 проход.", "5 − 1 = 4."], "sol": "5−1 = 4 прохода."}]},
  {"id": 139, "title": "Кратчайший путь в графе", "src": "Информатика · 8–9 класс · Кратчайший путь в графе", "ico": "🗺️", "subj": "inf", "explain": ["В графе дорог кратчайший путь — не всегда прямая: иногда выгоднее проехать через другие города.", "Из A в B напрямую 5, а через город C: A→C = 2 и C→B = 2, итого 2+2 = 4. Путь через C короче!", "Сравнивай все маршруты: длина кратчайшего — наименьшая из сумм длин его рёбер.", "Совет Архимеда: выпиши каждый маршрут в виде суммы и сравни результаты — не полагайся на глаз."], "check": {"q": "Из A в B ведут два пути: напрямую 5 и через город C: A→C = 2, C→B = 2. Чему равна длина кратчайшего пути?", "choices": ["5", "4", "2", "7"], "ans": 1, "exp": "Через C: 2+2 = 4, а 4 < 5 → кратчайший путь 4."}, "tasks": [{"q": "Из A в B напрямую 7, а через город C: A→C = 3 и C→B = 3. Какова длина кратчайшего пути?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Посчитай путь через C: 3+3.", "Сравни 6 и 7 — меньшее и есть ответ."], "sol": "3+3 = 6, а 6 < 7 → кратчайший путь 6."}, {"q": "Из A в B напрямую 10, а через города C и D: A→C = 4, C→D = 3, D→B = 2. Какой маршрут короче?", "kind": "choice", "choices": ["Прямой (10)", "Через C и D (4+3+2)", "Оба одинаковы"], "ans": 1, "tol": 0, "hints": ["Сложи длины трёх рёбер: 4, 3 и 2.", "4+3+2 = 9, а прямой путь — 10."], "sol": "Через C и D: 4+3+2 = 9, а 9 < 10 → короче через C и D."}]},
  {"id": 140, "title": "Исполнители алгоритмов", "src": "Информатика · 5–6 класс · Исполнители", "ico": "🤖", "subj": "inf", "explain": ["Алгоритм — это инструкция команда-за-командой: что делать и в каком порядке.", "Того, кто выполняет алгоритм, называют ИСПОЛНИТЕЛЕМ: человек (повар по рецепту) или устройство (робот, стиральная машина).", "У каждого исполнителя есть СИСТЕМА КОМАНД — список действий, которые он умеет. Робот «Квадрат» умеет: шаг вперёд, поворот, закрасить клетку.", "Пример: исполнитель-кузнечик умеет «+2» и «−1». Начал с 0 и выполнил +2, потом −1: 0 → 2 → 1.", "Если дать исполнителю команду, которой он не знает, он остановится и сообщит об ошибке.", "Совет Архимеда: сначала узнай, какие команды умеет исполнитель, — иначе алгоритм не выполнится."], "check": {"q": "Кузнечик умеет «+2» и «−1». Начал с 0, выполнил: +2, −1, +2. На каком числе он оказался?", "choices": ["2", "3", "4", "5"], "ans": 1, "exp": "Считаем по шагам: 0 + 2 = 2; 2 − 1 = 1; 1 + 2 = 3. Ответ — 3."}, "tasks": [{"q": "Кузнечик начал с 0 и выполнил: +2, +2, −1. На каком числе он оказался?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Сколько он всего прибавил, а сколько отнял?", "0 + 2 + 2 = 4, затем 4 − 1 = ?"], "sol": "0 + 2 = 2, 2 + 2 = 4, 4 − 1 = 3. Ответ: 3."}, {"q": "Робот умеет: шаг, поворот, закрасить. Какую команду он НЕ сможет выполнить?", "kind": "choice", "choices": ["Сделай шаг", "Спой песню", "Закрась клетку"], "ans": 1, "tol": 0, "hints": ["Вспомни его систему команд.", "Шаг, поворот и закраска есть, а песни в списке нет."], "sol": "В системе команд робота нет «пения», поэтому команду «Спой песню» он выполнить не сможет."}]},
  {"id": 141, "title": "Линейные алгоритмы: порядок действий", "src": "Информатика · 5–6 класс · Линейные алгоритмы", "ico": "📋", "subj": "inf", "explain": ["Если все команды идут одна за другой и не нужно выбирать или повторять — это ЛИНЕЙНЫЙ алгоритм.", "Порядок важен: поменяешь местами шаги — результат испортится (сначала носки, потом ботинки).", "Пример «Собраться в школу»: 1) встать, 2) умыться, 3) одеться, 4) позавтракать, 5) взять рюкзак, 6) выйти.", "В линейном алгоритме каждая команда выполняется ровно один раз.", "Совет Архимеда: пронумеруй шаги — легко проверить, ничего ли не забыл."], "check": {"q": "Каждая команда линейного алгоритма при одном проходе выполняется…", "choices": ["ровно 1 раз", "ровно 2 раза", "ровно 5 раз"], "ans": 0, "exp": "В линейном алгоритме команды идут по порядку, и каждая выполняется ровно один раз."}, "tasks": [{"q": "Сколько команд в линейном алгоритме: 1) взять чашку, 2) налить чай, 3) положить сахар, 4) размешать?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Посчитай пронумерованные шаги.", "Шаги 1–4 — их четыре."], "sol": "В алгоритме 4 пронумерованные команды."}, {"q": "Что будет, если в алгоритме «одеться» поменять местами «надеть носки» и «надеть ботинки»?", "kind": "choice", "choices": ["Ничего не изменится", "Будет неудобно: ботинки наденут без носков", "Алгоритм сломается совсем"], "ans": 1, "tol": 0, "hints": ["Что удобнее сначала?", "Сначала носки, потом ботинки — порядок важен."], "sol": "Порядок в линейном алгоритме важен: сначала носки, потом ботинки."}]},
  {"id": 142, "title": "Ветвления: если… то… иначе…", "src": "Информатика · 5–6 класс · Ветвления", "ico": "🌦", "subj": "inf", "explain": ["В жизни мы выбираем: если идёт дождь — берём зонт, иначе — не берём. Это ВЕТВЛЕНИЕ.", "В алгоритме: ЕСЛИ условие верно, ТО делаем одно, ИНАЧЕ делаем другое.", "Пример: если на улице мороз — надеть шапку, иначе — можно без шапки.", "Ветвление выбирает ОДИН из двух путей: выполняется либо ветка ТО, либо ветка ИНАЧЕ.", "Совет Архимеда: сначала сформулируй условие-вопрос с ответом да/нет, потом — что делать в каждом случае."], "check": {"q": "Алгоритм: если сегодня выходной, то идём в парк, иначе — в школу. Сегодня суббота (выходной). Куда идём?", "choices": ["В парк", "В школу", "Никуда"], "ans": 0, "exp": "Условие «сегодня выходной» верно, значит выполняется ветка ТО — идём в парк."}, "tasks": [{"q": "Сколько разных путей у алгоритма с одним ветвлением «если… то… иначе…»?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Сколько веток у развилки?", "Две: ТО и ИНАЧЕ."], "sol": "У одного ветвления два пути: ТО и ИНАЧЕ."}, {"q": "Алгоритм: если число больше 10, напиши «большое», иначе — «маленькое». Что напишет исполнитель для числа 7?", "kind": "choice", "choices": ["большое", "маленькое", "оба слова"], "ans": 1, "tol": 0, "hints": ["7 больше 10?", "Нет, значит ветка ИНАЧЕ — «маленькое»."], "sol": "7 не больше 10, условие ложно, выполняется ветка «иначе» — «маленькое»."}]},
  {"id": 143, "title": "Повторения: цикл «повтори N раз»", "src": "Информатика · 5–6 класс · Повторения", "ico": "🔁", "subj": "inf", "explain": ["Когда действие нужно повторить много раз, говорят: ПОВТОРИ 3 РАЗА: присесть.", "Такую конструкцию называют ЦИКЛОМ: «повтори N раз» — выполнить команду N раз подряд.", "Пример: «Повтори 4 раза: шаг вперёд» — робот сделает 4 шага.", "Если в одном повторе несколько действий, их считают умножением: «повтори 3 раза: два шага» — 3 × 2 = 6 шагов.", "Совет Архимеда: переводи «повтори N раз: …» в умножение — легко посчитать итог."], "check": {"q": "Робот выполнил «Повтори 5 раз: шаг вперёд». Сколько всего шагов он сделал?", "choices": ["5", "6", "10"], "ans": 0, "exp": "Повторили действие 5 раз — значит 5 шагов (5 × 1 = 5)."}, "tasks": [{"q": "Робот выполнил «Повтори 4 раза: два шага». Сколько всего шагов?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Сколько повторений и сколько шагов в одном?", "4 × 2 = ?"], "sol": "4 × 2 = 8 шагов."}, {"q": "Какой командой можно сделать ровно 6 приседаний?", "kind": "choice", "choices": ["Повтори 6 раз: присесть", "Повтори 3 раза: три приседания", "Повтори 5 раз: присесть"], "ans": 0, "tol": 0, "hints": ["Посчитай каждую команду.", "6 × 1 = 6 — то, что нужно; 3 × 3 = 9 и 5 × 1 = 5 не подходят."], "sol": "«Повтори 6 раз: присесть» даёт 6 приседаний."}]},
  {"id": 144, "title": "Ошибки в алгоритмах", "src": "Информатика · 5–6 класс · Ошибки в алгоритмах", "ico": "🐞", "subj": "inf", "explain": ["Ошибку в алгоритме или программе называют БАГОМ: что-то в инструкции не так.", "Ошибки бывают: перепутан порядок, забыт шаг, неверное условие, лишняя команда.", "Пример с ошибкой: «Сварить яйцо: 1) включить плиту, 2) положить яйцо, 3) налить воду, 4) варить» — шаги 2 и 3 перепутаны.", "Как искать баг: прочитай алгоритм буквально, шаг за шагом, как робот.", "Совет Архимеда: если алгоритм не работает — не переписывай всё сразу, найди сначала одно неверное место."], "check": {"q": "В алгоритме «Полить цветок»: 1) взять лейку, 2) полить цветок, 3) налить воду. Какая ошибка?", "choices": ["Лишний шаг", "Перепутан порядок: сначала надо налить воду", "Всё верно"], "ans": 1, "exp": "Сначала в лейку наливают воду и только потом поливают — шаги 2 и 3 нужно поменять местами."}, "tasks": [{"q": "Сколько ошибок в алгоритме «Одеться зимой»: 1) надеть куртку, 2) надеть варежки, 3) надеть футболку?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Что надевают раньше куртки?", "Футболку надевают до куртки — порядок шагов 1 и 3 нарушен."], "sol": "Ошибка одна: футболку нужно надеть до куртки."}, {"q": "Что лучше всего сделать, когда алгоритм не работает?", "kind": "choice", "choices": ["Выбросить его", "Проверить шаг за шагом и найти ошибку", "Выполнять быстрее"], "ans": 1, "tol": 0, "hints": ["Как находят баги?", "Читают алгоритм по шагам и ищут неверное место."], "sol": "Правильно — проверить алгоритм по шагам и найти ошибку."}]},
  {"id": 145, "title": "Система команд исполнителя", "src": "Информатика · 5–6 класс · Команды исполнителя", "ico": "🎛", "subj": "inf", "explain": ["У каждого исполнителя есть свой список разрешённых команд — СИСТЕМА КОМАНД (СКИ).", "Команды бывают простые («шаг») и с параметрами («поверни на 90°»).", "Пример: «Чертёжник» умеет: линия вверх, вниз, вправо, влево. Команды «нарисовать круг» у него нет.", "Если действия нет в СКИ, его составляют из разрешённых команд: квадрат = 4 линии с поворотами.", "Совет Архимеда: сверяй каждую команду алгоритма со СКИ исполнителя."], "check": {"q": "«Кузнечик» умеет: +1, +2, −1. Какой команды у него НЕТ?", "choices": ["+3", "+1", "−1"], "ans": 0, "exp": "В списке есть +1, +2 и −1, а команды +3 нет — её надо составить из нескольких команд."}, "tasks": [{"q": "Исполнитель умеет: «шаг» и «поворот». Сколько разных простых команд в его СКИ?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Перечисли разрешённые команды.", "Их две: шаг и поворот."], "sol": "В системе команд два действия: «шаг» и «поворот»."}, {"q": "Какая команда точно должна быть в СКИ чертёжника, чтобы он нарисовал квадрат?", "kind": "choice", "choices": ["Повернуть", "Спеть", "Умножить"], "ans": 0, "tol": 0, "hints": ["Что нужно делать в углах квадрата?", "Поворачивать."], "sol": "Для квадрата нужны повороты, значит команда «повернуть» обязательна."}]},
  {"id": 146, "title": "Кодирование информации", "src": "Информатика · 5–6 класс · Кодирование", "ico": "🏷", "subj": "inf", "explain": ["КОДИРОВАНИЕ — запись информации с помощью заранее оговорённых знаков: букв, цифр, сигналов.", "Примеры кодов: номерок в гардеробе, буквы азбуки Морзе, номера спортсменов на футболках.", "Своя таблица: 1=А, 2=Б, 3=В, 4=Г, 5=Д. Слово «ВД» кодируется как «3 5» (В=3, Д=5).", "Сколько знаков в коде, столько информации передано: слово из 3 букв = 3 числа.", "Совет Архимеда: договорись о кодовой таблице заранее — без неё не расшифровать."], "check": {"q": "По таблице 1=А, 2=Б, 3=В слово «БА» записывается как?", "choices": ["«1 2»", "«2 1»", "«3 1»"], "ans": 1, "exp": "Б = 2, А = 1, поэтому «БА» = «2 1»."}, "tasks": [{"q": "Сколько чисел понадобится, чтобы закодировать слово «КОТ» по таблице (буква = одно число)?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Сколько букв в слове?", "Три буквы — три числа."], "sol": "В слове 3 буквы, каждая — одно число: всего 3."}, {"q": "Для чего нужны номера спортсменам на футболках?", "kind": "choice", "choices": ["Для красоты", "Чтобы различать игроков по номеру", "Чтобы футболки не пачкались"], "ans": 1, "tol": 0, "hints": ["Зачем на одежде номер?", "Номер заменяет длинное имя."], "sol": "Номер — это код, по которому легко отличить одного игрока от другого."}]},
  {"id": 147, "title": "Шифр Цезаря", "src": "Информатика · 5–6 класс · Шифр Цезаря", "ico": "🗝", "subj": "inf", "explain": ["Шифр Цезаря — древний способ тайного письма: каждая буква заменяется на букву через несколько шагов по алфавиту.", "Сдвиг на 1: А→Б, Б→В; сдвиг на 2: А→В, Б→Г.", "Зашифруем «МАК» со сдвигом 1: М→Н, А→Б, К→Л — получится «НБЛ».", "Чтобы расшифровать, сдвигаем буквы НАЗАД на то же число шагов.", "Совет Архимеда: напиши алфавит в строчку и двигай палец по буквам."], "check": {"q": "Слово «КОТ» зашифровали со сдвигом 1 (А→Б, Б→В, …). Что получилось?", "choices": ["ЛПУ", "ЙНС", "КПУ"], "ans": 0, "exp": "К→Л, О→П, Т→У — получается «ЛПУ»."}, "tasks": [{"q": "Буква «Д» (5-я, если А=1) сдвигается на 2 вперёд. Каким по счёту станет новая буква?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Прибавь сдвиг к номеру буквы.", "5 + 2 = ?"], "sol": "5 + 2 = 7 — новая буква 7-я по счёту."}, {"q": "Чтобы расшифровать сообщение со сдвигом 2, нужно…", "kind": "choice", "choices": ["Сдвинуть буквы на 2 назад", "Сдвинуть буквы на 2 вперёд", "Оставить как есть"], "ans": 0, "tol": 0, "hints": ["Шифровали вперёд — как вернуться?", "Назад на то же число шагов."], "sol": "Расшифровка — обратное действие: сдвигаем буквы назад на 2."}]},
  {"id": 148, "title": "Шифр-перестановка", "src": "Информатика · 5–6 класс · Шифр-перестановка", "ico": "🔀", "subj": "inf", "explain": ["Перестановка — шифрование, при котором буквы остаются теми же, но меняются местами.", "Правило 123→312: на 1-е место ставим 3-ю букву, на 2-е — 1-ю, на 3-е — 2-ю.", "Пример: слово «КОТ» (1=К, 2=О, 3=Т) → порядок 3-1-2: Т, К, О = «ТКО».", "Чтобы расшифровать, применяем обратную перестановку.", "Совет Архимеда: подпиши номера 1-2-3 над буквами и переставляй по правилу."], "check": {"q": "Слово «МАК» переставили по правилу 123→312 (3-я буква на 1-е место, 1-я на 2-е, 2-я на 3-е). Что получилось?", "choices": ["АКМ", "КМА", "МКА"], "ans": 1, "exp": "Буквы: 1=М, 2=А, 3=К. Новый порядок 3-1-2: К, М, А → «КМА»."}, "tasks": [{"q": "Сколько букв в слове, если для шифрования использовали правило 123→312?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Что означает «312»?", "Три позиции — три буквы."], "sol": "Правило из трёх номеров переставляет слово из 3 букв."}, {"q": "Что нужно знать, чтобы расшифровать перестановку?", "kind": "choice", "choices": ["Правило перестановки", "Сколько букв в алфавите", "Длину слова в сантиметрах"], "ans": 0, "tol": 0, "hints": ["Без чего нельзя восстановить порядок букв?", "Без правила, как их переставляли."], "sol": "Чтобы расшифровать, нужно знать правило перестановки букв."}]},
  {"id": 149, "title": "Декодирование сообщений", "src": "Информатика · 5–6 класс · Декодирование", "ico": "📨", "subj": "inf", "explain": ["ДЕКОДИРОВАНИЕ — обратное кодированию действие: по коду восстанавливаем сообщение.", "Если таблица 1=А, 2=Б, 3=В, 4=Г, 5=Д, то «4 1 3» читается как «ГАВ».", "Расшифровываем по одному знаку: каждое число заменяем буквой из таблицы.", "Совет Архимеда: держи таблицу перед глазами и иди слева направо."], "check": {"q": "По таблице 1=А, 2=Б, 3=В, 4=Г, 5=Д расшифруй «2 1 5».", "choices": ["БАД", "ДАБ", "АБД"], "ans": 0, "exp": "2=Б, 1=А, 5=Д — получается «БАД»."}, "tasks": [{"q": "Сообщение состоит из 6 чисел (по одному на букву). Сколько букв в расшифрованном слове?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Сколько кодов — столько и букв.", "6 чисел = 6 букв."], "sol": "Каждое число — одна буква, значит букв 6."}, {"q": "Какое слово скрыто в коде «5 1 3 4» при таблице 1=А, 2=Б, 3=В, 4=Г, 5=Д?", "kind": "choice", "choices": ["ДАВГ", "ГВАД", "ВГДА"], "ans": 0, "tol": 0, "hints": ["Замени каждое число буквой по порядку.", "5=Д, 1=А, 3=В, 4=Г."], "sol": "5=Д, 1=А, 3=В, 4=Г — слово «ДАВГ»."}]},
  {"id": 150, "title": "Бит и байт", "src": "Информатика · 5–6 класс · Единицы информации", "ico": "⚖️", "subj": "inf", "explain": ["Самая маленькая единица информации — БИТ: один ответ да/нет, 0 или 1.", "8 бит собираются в БАЙТ: 1 байт = 8 бит: несколько маленьких единиц (бит) собраны в одну большую (байт) — как 12 месяцев собираются в 1 год.", "Перевод умножением: в 2 байтах — 2 × 8 = 16 бит, в 3 байтах — 24 бита.", "Совет Архимеда: запомни пару «1 байт = 8 бит» и переводи умножением или делением."], "check": {"q": "Сколько бит в 2 байтах?", "choices": ["8", "16", "24"], "ans": 1, "exp": "1 байт = 8 бит, значит в 2 байтах 2 × 8 = 16 бит."}, "tasks": [{"q": "Сколько бит в 3 байтах?", "kind": "unit", "ans": 24, "tol": 0, "hints": ["Сколько бит в одном байте?", "3 × 8 = ?"], "sol": "3 байта = 3 × 8 = 24 бита."}, {"q": "Сколько байтов в 16 битах?", "kind": "choice", "choices": ["1", "2", "16"], "ans": 1, "tol": 0, "hints": ["16 бит — это сколько раз по 8?", "16 : 8 = 2."], "sol": "16 бит : 8 = 2 байта."}]},
  {"id": 151, "title": "Двоичная система: первые шаги", "src": "Информатика · 5–6 класс · Двоичная система", "ico": "💻", "subj": "inf", "explain": ["Компьютер «думает» только нулями и единицами — это ДВОИЧНАЯ система.", "Правило: как только набралось две единицы — превращаем их в нолик с переносом влево.", "Маленькие числа: 1 = 1₂, 2 = 10₂, 3 = 11₂, 4 = 100₂, 5 = 101₂, 6 = 110₂, 7 = 111₂, 8 = 1000₂.", "5 = 101₂ — это одна четвёрка + ноль двоек + одна единица = 4 + 0 + 1 = 5.", "Совет Архимеда: выучи числа 0–7 — они строятся как лесенка."], "check": {"q": "Как число 5 записывается в двоичной системе?", "choices": ["101₂", "110₂", "100₂"], "ans": 0, "exp": "5 = 4 + 1: одна четвёрка и одна единица → 101₂."}, "tasks": [{"q": "Какому десятичному числу равно 110₂?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Разряды справа налево: единицы, двойки, четвёрки.", "110₂ = 4 + 2 + 0 = ?"], "sol": "110₂ = 4 + 2 = 6."}, {"q": "Как число 8 записывается в двоичной системе?", "kind": "choice", "choices": ["111₂", "1000₂", "100₂"], "ans": 1, "tol": 0, "hints": ["8 — это единица в каком разряде?", "В разряде восьмёрок: 1000₂."], "sol": "8 — это единица в разряде восьмёрок: 1000₂."}]},
  {"id": 152, "title": "Кодирование рисунков: пиксели", "src": "Информатика · 5–6 класс · Пиксели", "ico": "🖼", "subj": "inf", "explain": ["Рисунок на экране состоит из точек-ПИКСЕЛЕЙ, у каждого свой цвет.", "Если рисунок чёрно-белый, каждый пиксель — 1 бит: 0 = белый, 1 = чёрный.", "Сколько бит нужно: ширина × высота. Рисунок 4×4 = 16 пикселей = 16 бит.", "Совет Архимеда: «сколько клеточек — столько бит»: умножь ширину на высоту."], "check": {"q": "Сколько бит нужно для чёрно-белой картинки 3×3 пикселя?", "choices": ["6", "9", "12"], "ans": 1, "exp": "3 × 3 = 9 пикселей, каждый занимает 1 бит → 9 бит."}, "tasks": [{"q": "Для чёрно-белой картинки 2×4 пикселя нужно … бит.", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Сколько всего пикселей?", "2 × 4 = 8."], "sol": "2 × 4 = 8 пикселей = 8 бит."}, {"q": "Чёрно-белая картинка 1×1 пиксель занимает…", "kind": "choice", "choices": ["1 бит", "8 бит", "0 бит"], "ans": 0, "tol": 0, "hints": ["Сколько клеток и сколько бит на клетку?", "1 клетка × 1 бит = 1 бит."], "sol": "Один пиксель чёрно-белой картинки — 1 бит."}]},
  {"id": 153, "title": "Высказывания: истина и ложь", "src": "Информатика · 5–6 класс · Истина и ложь", "ico": "✅", "subj": "inf", "explain": ["ВЫСКАЗЫВАНИЕ — предложение, о котором можно сказать: истинное оно или ложное.", "Истинные: «Зимой холодно», «2 + 2 = 4». Ложные: «Летом идёт снег», «2 + 2 = 5».", "Вопрос («Сколько будет 2+2?») высказыванием не является — его нельзя назвать ни истинным, ни ложным.", "Совет Архимеда: проверяй высказывание, как судья: всегда верно — истина, хоть в одном случае не так — ложь."], "check": {"q": "Какое высказывание истинное?", "choices": ["«2 + 2 = 5»", "«Солнце встаёт на востоке»", "«У треугольника 4 стороны»"], "ans": 1, "exp": "«Солнце встаёт на востоке» — верное; остальные ложные."}, "tasks": [{"q": "Сколько истинных высказываний в списке: «1 + 1 = 2», «3 > 7», «В году 12 месяцев»?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Проверь каждое по отдельности.", "Верны «1+1=2» и «12 месяцев»."], "sol": "Истинны два высказывания."}, {"q": "Почему предложение «Какой сегодня день?» — не высказывание?", "kind": "choice", "choices": ["Оно слишком длинное", "Его нельзя назвать истинным или ложным", "В нём нет чисел"], "ans": 1, "tol": 0, "hints": ["Что нужно, чтобы назвать предложение высказыванием?", "Возможность сказать «верно/неверно»."], "sol": "Вопрос нельзя оценить как истину или ложь, поэтому он не высказывание."}]},
  {"id": 154, "title": "Высказывания со словом И", "src": "Информатика · 5–6 класс · Слово И", "ico": "➕", "subj": "inf", "explain": ["Сложное высказывание со словом И истинно, только если истинны ОБЕ части.", "«А И Б» — истина, когда А истинно И Б истинно; если хоть одна часть ложная — всё ложно.", "Пример: «2 + 2 = 4 И 3 > 1» — обе части верны → истина.", "Пример ложного: «2 + 2 = 4 И 3 < 1» — вторая часть ложна → ложно.", "Совет Архимеда: слово И строгое — требует обе истинные части."], "check": {"q": "Чему равно «2 + 2 = 4 И 3 > 1»?", "choices": ["Истина", "Ложь"], "ans": 0, "exp": "Обе части истинны, значит «И» даёт истину."}, "tasks": [{"q": "Сколько истинно высказывание «А И Б», если А истинно, а Б ложно? (1 — истина, 0 — ложь)", "kind": "unit", "ans": 0, "tol": 0, "hints": ["Что требует слово И?", "Обе части должны быть истинны."], "sol": "Раз Б ложно, «А И Б» ложно — ответ 0."}, {"q": "Какое высказывание истинно?", "kind": "choice", "choices": ["«5 > 3 И 2 < 1»", "«5 > 3 И 2 > 1»", "«5 < 3 И 2 > 1»"], "ans": 1, "tol": 0, "hints": ["Проверь обе части в каждом варианте.", "Верны обе части только у «5 > 3 И 2 > 1»."], "sol": "У «5 > 3 И 2 > 1» обе части верны — истина; в остальных одна часть ложная."}]},
  {"id": 155, "title": "Высказывания со словом ИЛИ", "src": "Информатика · 5–6 класс · Слово ИЛИ", "ico": "🟰", "subj": "inf", "explain": ["Высказывание со словом ИЛИ истинно, если истинна ХОТЯ БЫ ОДНА часть.", "«А ИЛИ Б» ложно только тогда, когда ложны обе части сразу.", "Пример: «Сегодня дождь ИЛИ снег» истинно, если идёт хотя бы одно.", "Пример: «2 + 2 = 5 ИЛИ 3 > 1» — вторая часть верна → истина.", "Совет Архимеда: слово ИЛИ доброе — ему достаточно одной верной части."], "check": {"q": "Чему равно «2 + 2 = 5 ИЛИ 3 > 1»?", "choices": ["Истина", "Ложь"], "ans": 0, "exp": "Вторая часть (3 > 1) истинна — для ИЛИ этого достаточно."}, "tasks": [{"q": "«А ИЛИ Б» истинно? (1 — да, 0 — нет), если А ложно и Б ложно.", "kind": "unit", "ans": 0, "tol": 0, "hints": ["Когда ИЛИ ложно?", "Только когда ложны обе части."], "sol": "Обе части ложны — «А ИЛИ Б» ложно (0)."}, {"q": "Какое высказывание ложно?", "kind": "choice", "choices": ["«5 > 3 ИЛИ 2 < 1»", "«5 < 3 ИЛИ 2 < 1»", "«5 > 3 ИЛИ 2 > 1»"], "ans": 1, "tol": 0, "hints": ["Когда ИЛИ ложно?", "Когда ложны обе части."], "sol": "У «5 < 3 ИЛИ 2 < 1» обе части ложны — ложно; в остальных одна часть верна."}]},
  {"id": 156, "title": "Слово НЕ (отрицание)", "src": "Информатика · 5–6 класс · Слово НЕ", "ico": "🚫", "subj": "inf", "explain": ["Слово НЕ превращает высказывание в противоположное: истину — в ложь, ложь — в истину.", "Правило: НЕ(истина) = ложь; НЕ(ложь) = истина.", "Пример: «НЕ (2 + 2 = 5)» — внутри ложь, НЕ превращает её в истину.", "Пример: «НЕ (Зимой холодно)» — внутри истина, после НЕ — ложь.", "Совет Архимеда: НЕ — выключатель: нажал — и наоборот."], "check": {"q": "Чему равно «НЕ (2 + 2 = 4)»?", "choices": ["Истина", "Ложь"], "ans": 1, "exp": "Внутри истина (2+2=4), а НЕ переворачивает — получается ложь."}, "tasks": [{"q": "«НЕ (5 < 3)» — истина или ложь? Ответь числом: 1 — истина, 0 — ложь.", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Сначала проверь, что внутри: 5 < 3?", "Внутри ложь, НЕ даёт истину."], "sol": "Внутри ложь, НЕ превращает в истину → 1."}, {"q": "Какое высказывание истинно?", "kind": "choice", "choices": ["«НЕ (Снег белый)»", "«НЕ (1 + 1 = 3)»", "«НЕ (Летом тепло)»"], "ans": 1, "tol": 0, "hints": ["Найди, где внутри ложь — НЕ даст истину.", "1+1=3 — ложь, НЕ переворачивает."], "sol": "Внутри «1+1=3» ложь, НЕ превращает в истину."}]},
  {"id": 157, "title": "Логические задачи-детективы", "src": "Информатика · 5–6 класс · Задачи-детективы", "ico": "🕵️", "subj": "inf", "explain": ["В детективе рассуждают по шагам: что известно и что из этого следует.", "Приём: подставь число в каждое утверждение и проверь, что получилось.", "Пример: про число от 1 до 6 сказали: «оно чётное», «оно больше 3», «оно меньше 5». Число 4: чётное (да), больше 3 (да), меньше 5 (да) — все три верны!", "Если бы загадали 2: чётное (да), но больше 3 (нет) — не подходит.", "Совет Архимеда: проверяй каждый вариант по всем условиям по очереди — как детектив проверяет алиби."], "check": {"q": "Загадали число от 1 до 6. Верны все три утверждения: «оно чётное», «оно больше 3», «оно меньше 5». Какое это число?", "choices": ["3", "4", "6"], "ans": 1, "exp": "Проверяем 4: чётное — да, больше 3 — да, меньше 5 — да. Число 3 — нечётное; 6 — не меньше 5. Подходит только 4."}, "tasks": [{"q": "Сколько чисел от 1 до 6 подходят под условия «чётное И больше 3»?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Какие чётные числа от 1 до 6?", "2, 4, 6; из них больше 3 — 4 и 6."], "sol": "Чётные от 1 до 6: 2, 4, 6. Больше 3: 4 и 6 — два числа."}, {"q": "Загадали 6. Сколько из утверждений «чётное», «больше 3», «меньше 5» верны?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Проверь 6 по каждому условию.", "Чётное — да, больше 3 — да, меньше 5 — нет."], "sol": "6 чётное (да), больше 3 (да), меньше 5 (нет) — верны 2 утверждения."}]},
  {"id": 158, "title": "Закономерности в числовых рядах", "src": "Информатика · 5–6 класс · Закономерности", "ico": "🔢", "subj": "inf", "explain": ["В числовом ряду числа часто меняются по одному и тому же правилу.", "Найди правило: посмотри, что прибавляют или на что умножают от числа к числу.", "Ряд 1, 4, 7, 10, … — каждый раз прибавляем 3: 1+3=4, 4+3=7, 7+3=10, следующее 10+3=13.", "Бывают ряды с умножением: 2, 4, 8, 16 — каждое число умножаем на 2.", "Совет Архимеда: сначала проверь «плюс одно и то же число», потом «умножить на одно и то же»."], "check": {"q": "Продолжи ряд: 1, 4, 7, 10, …", "choices": ["12", "13", "14"], "ans": 1, "exp": "Правило: +3. 10 + 3 = 13."}, "tasks": [{"q": "Продолжи ряд: 2, 6, 10, 14, …", "kind": "unit", "ans": 18, "tol": 0, "hints": ["Какое правило у ряда?", "Каждый раз +4; 14 + 4 = 18."], "sol": "14 + 4 = 18."}, {"q": "Какой ряд построен по правилу «+2»?", "kind": "choice", "choices": ["1, 2, 4, 8", "2, 4, 6, 8", "5, 4, 3, 2"], "ans": 1, "tol": 0, "hints": ["Прибавь 2 к каждому числу и проверь.", "2+2=4, 4+2=6, 6+2=8 — подходит только этот ряд."], "sol": "2, 4, 6, 8 — каждое следующее на 2 больше; ряд 1,2,4,8 умножается на 2, а не прибавляет."}]},
  {"id": 159, "title": "Таблицы: читаем и сравниваем", "src": "Информатика · 5–6 класс · Таблицы", "ico": "🗓", "subj": "inf", "explain": ["Таблица хранит данные в строках и столбцах — читать её легко, если знать, что в шапке.", "Сначала посмотри на названия столбцов, потом ищи нужную строку.", "Пример: в расписании 5 класса математика стоит в понедельник, среду и пятницу — значит 3 раза в неделю.", "Чтобы сравнить, вычти меньшее из большего.", "Совет Архимеда: всегда смотри, что написано в шапке таблицы, — не перепутаешь строки и столбцы."], "check": {"q": "В расписании математика: понедельник, среда, пятница. Сколько раз в неделю математика?", "choices": ["2", "3", "4"], "ans": 1, "exp": "Три дня: понедельник, среда, пятница — 3 раза."}, "tasks": [{"q": "По таблице у Кати 5 книг, у Вани 8, у Миши 3. Сколько книг всего у троих?", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Сложи все числа в столбце «книги».", "5 + 8 + 3 = ?"], "sol": "5 + 8 + 3 = 16 книг."}, {"q": "У кого книг больше всех: Катя 5, Ваня 8, Миша 3?", "kind": "choice", "choices": ["У Кати", "У Вани", "У Миши"], "ans": 1, "tol": 0, "hints": ["Сравни числа 5, 8 и 3.", "8 — самое большое."], "sol": "8 больше 5 и 3 — больше всех у Вани."}]},
  {"id": 160, "title": "Диаграммы: сравниваем столбики", "src": "Информатика · 5–6 класс · Диаграммы", "ico": "📊", "subj": "inf", "explain": ["Столбчатая диаграмма показывает числа высотой столбиков: чем выше столбик, тем больше число.", "Опросили класс: мороженое любят 10 человек, пирожное — 6.", "Чтобы узнать, на сколько больше, вычти: 10 − 6 = 4 — мороженое любят на 4 человека больше.", "Чтобы узнать всего, сложи столбики: 10 + 6 = 16.", "Совет Архимеда: подписи под столбиками — что это, а цифры — сколько. Читай оба."], "check": {"q": "На диаграмме: мороженое — 10, пирожное — 6. На сколько больше детей любят мороженое?", "choices": ["3", "4", "6"], "ans": 1, "exp": "10 − 6 = 4 — мороженое любят на 4 человека больше."}, "tasks": [{"q": "Сколько всего детей опросили, если мороженое любят 10, а пирожное 6?", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Сложи оба столбика.", "10 + 6 = ?"], "sol": "10 + 6 = 16 детей."}, {"q": "Какой столбик выше: мороженое — 10 или пирожное — 6?", "kind": "choice", "choices": ["Мороженое", "Пирожное", "Одинаковые"], "ans": 0, "tol": 0, "hints": ["Чем больше число, тем выше столбик.", "10 больше 6."], "sol": "10 > 6 — столбик «мороженое» выше."}]},
  {"id": 161, "title": "Сортировка: расставляем по порядку", "src": "Информатика · 5–6 класс · Сортировка", "ico": "📶", "subj": "inf", "explain": ["СОРТИРОВКА — расстановка данных по порядку: по возрастанию (от меньшего к большему) или по убыванию.", "Возьмём числа 5, 2, 8 и расставим по возрастанию: самое маленькое 2, затем 5, затем 8 → 2, 5, 8.", "Приём: найди самое маленькое число, поставь первым, потом следующее и так далее.", "Совет Архимеда: сравнивай по одному: сначала выбери самое маленькое — остальное само встанет на место."], "check": {"q": "Расставь числа 5, 2, 8 по возрастанию.", "choices": ["8, 5, 2", "2, 5, 8", "2, 8, 5"], "ans": 1, "exp": "По возрастанию: сначала самое маленькое 2, потом 5, потом 8 → 2, 5, 8."}, "tasks": [{"q": "Сколько чисел в отсортированном списке 1, 3, 5, 7?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Просто посчитай числа в списке.", "Их четыре."], "sol": "В списке 4 числа."}, {"q": "Какой список уже отсортирован по возрастанию?", "kind": "choice", "choices": ["3, 2, 1", "1, 2, 3", "2, 1, 3"], "ans": 1, "tol": 0, "hints": ["По возрастанию — каждое следующее больше.", "1 < 2 < 3 — верно."], "sol": "1, 2, 3 — каждое следующее число больше предыдущего."}]},
  {"id": 162, "title": "Поиск в списке", "src": "Информатика · 5–6 класс · Поиск", "ico": "🔎", "subj": "inf", "explain": ["ЛИНЕЙНЫЙ поиск — проверяем элементы списка по одному, пока не найдём нужный.", "Список: 3, 9, 7, 4, 1. Ищем 7: проверяем 3 (нет), 9 (нет), 7 (да!) — нашли с 3-й проверки.", "Если числа в списке нет, придётся проверить все элементы до конца.", "Совет Архимеда: считай проверки вслух: первая, вторая, третья… — не собьёшься."], "check": {"q": "Список: 3, 9, 7, 4, 1. Сколько проверок нужно, чтобы найти число 7?", "choices": ["2", "3", "4"], "ans": 1, "exp": "Проверяем: 3 (нет), 9 (нет), 7 (да) — 3 проверки."}, "tasks": [{"q": "Список: 2, 9, 4, 7, 5. На какой по счёту позиции стоит число 7? (первая позиция — 1)", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Пройди по списку и посчитай позиции.", "2 (1), 9 (2), 4 (3), 7 (4)."], "sol": "7 стоит на 4-й позиции."}, {"q": "В списке из 6 чисел нужного числа нет. Сколько проверок сделает линейный поиск?", "kind": "choice", "choices": ["3", "6", "0"], "ans": 1, "tol": 0, "hints": ["Если числа нет, когда поиск остановится?", "Только проверив все элементы — 6."], "sol": "Элемента нет — проверим все 6 элементов."}]},
  {"id": 163, "title": "Пути в графе: ищем короткий маршрут", "src": "Информатика · 5–6 класс · Пути в графе", "ico": "🛤", "subj": "inf", "explain": ["Граф — это точки (вершины) и линии (рёбра) между ними; на рёбрах пишут длину пути.", "Из точки А в точку В можно добраться разными путями — надо выбрать самый короткий.", "Пример: А→В напрямую = 7, а через С: А→С = 2 и С→В = 3, вместе 2 + 3 = 5. Путь через С короче (5 < 7).", "Длину пути считаем сложением длин его рёбер.", "Совет Архимеда: посчитай длину каждого пути и сравни — как при выборе дороги до школы."], "check": {"q": "А→В напрямую — 7. Через С: А→С = 2, С→В = 3. Какой путь короче?", "choices": ["Напрямую", "Через С", "Одинаковые"], "ans": 1, "exp": "Через С: 2 + 3 = 5, а 5 < 7 — путь через С короче."}, "tasks": [{"q": "Найди длину пути А→С→В, если А→С = 3, а С→В = 4.", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Сложи длины двух рёбер.", "3 + 4 = ?"], "sol": "3 + 4 = 7 — длина пути 7."}, {"q": "Какой маршрут короче: А→В = 10 или А→С (4) → В (5)?", "kind": "choice", "choices": ["Напрямую А→В", "Через С", "Одинаково"], "ans": 1, "tol": 0, "hints": ["Посчитай путь через С.", "4 + 5 = 9, а 9 < 10."], "sol": "Через С: 4 + 5 = 9 — меньше 10, значит короче через С."}]},
  {"id": 164, "title": "Из чего состоит компьютер", "src": "Информатика · 5–6 класс · Устройство компьютера", "ico": "🖥", "subj": "inf", "explain": ["Компьютер состоит из устройств: ввода (через них мы даём данные), вывода (они показывают результат) и памяти с процессором.", "Ввод: клавиатура, мышь, микрофон. Вывод: монитор, колонки, принтер.", "Процессор — «мозг», который выполняет команды, память хранит программы и данные.", "Пример: набрали текст на клавиатуре (ввод) — он появился на мониторе (вывод).", "Совет Архимеда: устройство само говорит, для чего оно: даём данные — ввод, получаем результат — вывод."], "check": {"q": "Что из перечисленного — устройство ВВОДА?", "choices": ["Монитор", "Клавиатура", "Колонки"], "ans": 1, "exp": "Клавиатурой мы вводим текст — это устройство ввода; монитор и колонки выводят."}, "tasks": [{"q": "Сколько устройств вывода в списке: монитор, мышь, колонки, клавиатура?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Что выводит информацию?", "Монитор и колонки."], "sol": "Выводят монитор и колонки — 2 устройства."}, {"q": "Какое устройство называют «мозгом» компьютера?", "kind": "choice", "choices": ["Процессор", "Монитор", "Мышь"], "ans": 0, "tol": 0, "hints": ["Что выполняет команды?", "Процессор."], "sol": "Процессор выполняет команды — «мозг» компьютера."}]},
  {"id": 165, "title": "Файлы и папки", "src": "Информатика · 5–6 класс · Файлы и папки", "ico": "📁", "subj": "inf", "explain": ["ФАЙЛ — это сохранённая информация: рисунок, текст, музыка, программа. У каждого файла есть имя.", "ПАПКА (каталог) — контейнер для файлов и других папок, чтобы навести порядок.", "Пример: в папке «Рисунки» лежат 3 рисунка, в папке «Тексты» — 2 текста. Всего файлов 3 + 2 = 5.", "Совет Архимеда: считай файлы по одному и не забывай про папки внутри папок."], "check": {"q": "В папке 3 рисунка и 2 текста. Сколько всего файлов в папке?", "choices": ["4", "5", "6"], "ans": 1, "exp": "3 + 2 = 5 файлов."}, "tasks": [{"q": "В каждой из двух папок по 3 файла. Сколько всего файлов?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Умножь: 2 папки по 3 файла.", "2 × 3 = ?"], "sol": "2 × 3 = 6 файлов."}, {"q": "Где удобнее хранить 10 файлов, чтобы не путаться?", "kind": "choice", "choices": ["Всё в одной куче на рабочем столе", "Разложить по папкам по темам", "Не сохранять файлы"], "ans": 1, "tol": 0, "hints": ["Что помогает навести порядок?", "Папки по темам."], "sol": "Папки по темам помогают быстро находить файлы."}]},
  {"id": 166, "title": "Интернет: браузер и адрес сайта", "src": "Информатика · 5–6 класс · Интернет", "ico": "🌐", "subj": "inf", "explain": ["Чтобы открыть сайт, нужен БРАУЗЕР — программа для просмотра страниц (Chrome, Firefox, Яндекс.Браузер).", "У каждого сайта есть АДРЕС — например, teramont.pro. Адрес набирают в адресной строке браузера.", "По ссылке (слову или картинке) можно перейти на другую страницу одним кликом.", "Совет Архимеда: проверяй адрес сайта: опечатка может привести на совсем другой сайт."], "check": {"q": "Чем открывают сайты в интернете?", "choices": ["Браузером", "Калькулятором", "Игрой"], "ans": 0, "exp": "Сайты открывают в браузере — специальной программе для просмотра страниц."}, "tasks": [{"q": "Сколько раз нужно кликнуть по ссылке, чтобы перейти на другую страницу?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Ссылка — это переход одним действием.", "Один клик."], "sol": "Один клик по ссылке — переход на страницу."}, {"q": "Что делать, если адрес сайта набран с опечаткой?", "kind": "choice", "choices": ["Всё равно открывать", "Проверить адрес и исправить", "Закрыть браузер навсегда"], "ans": 1, "tol": 0, "hints": ["Что может быть из-за опечатки?", "Можно попасть не на тот сайт."], "sol": "Опечатка может привести не туда — проверь и исправь адрес."}]},
  {"id": 167, "title": "Надёжные пароли", "src": "Информатика · 5–6 класс · Пароли", "ico": "🔐", "subj": "inf", "explain": ["ПАРОЛЬ защищает твои данные, как ключ — дверь. Слабый пароль — как оставленный в двери ключ.", "Надёжный пароль: длинный (8 символов и больше), с буквами разного регистра, цифрами и знаками.", "Не используй имя, день рождения и слова вроде «password» — их легко угадать.", "Совет Архимеда: придумай фразу и возьми из неё первые буквы с цифрой — запомнить легко, угадать трудно."], "check": {"q": "Какой пароль самый надёжный?", "choices": ["12345", "password", "Q9#zX4!m7"], "ans": 2, "exp": "«Q9#zX4!m7» длинный, с буквами разного регистра, цифрой и знаком — самый надёжный."}, "tasks": [{"q": "Сколько символов минимум должно быть в надёжном пароле?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Что говорят о длине пароля?", "8 символов и больше."], "sol": "Надёжный пароль — от 8 символов."}, {"q": "Какой пароль НЕ стоит использовать?", "kind": "choice", "choices": ["Q9#zX4!m7", "Дата рождения 0101", "123456"], "ans": 1, "tol": 0, "hints": ["Что легко угадать?", "Имя и дату рождения."], "sol": "Дату рождения легко угадать — такой пароль не используют."}]},
  {"id": 168, "title": "Безопасность в сети", "src": "Информатика · 5–6 класс · Безопасность в сети", "ico": "🛡", "subj": "inf", "explain": ["В интернете, как и в жизни, действуют правила безопасности.", "Не сообщай незнакомцам личные данные: полное имя, адрес, школу, пароли.", "Если в чате просят что-то странное или обижают — расскажи взрослым, это не «ябедничество», а защита.", "Не переходи по подозрительным ссылкам и не скачивай файлы из неизвестных источников.", "Совет Архимеда: в сети общайся, как с незнакомцем на улице: вежливо, но осторожно."], "check": {"q": "Что НЕ стоит сообщать незнакомцу в интернете?", "choices": ["Свой домашний адрес", "Что ты любишь читать", "Своё любимое блюдо"], "ans": 0, "exp": "Домашний адрес — личные данные, их незнакомцам сообщать нельзя."}, "tasks": [{"q": "Сколько личных данных из списка нельзя сообщать незнакомцам: имя, пароль, адрес школы, любимый цвет?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Что из списка — личное и секретное?", "Имя, пароль и адрес школы."], "sol": "Нельзя сообщать имя, пароль и адрес школы — 3 пункта."}, {"q": "В чате незнакомец просит прислать твою фотографию. Что делать?", "kind": "choice", "choices": ["Отправить", "Рассказать родителям и не отправлять", "Попросить его прислать свою"], "ans": 1, "tol": 0, "hints": ["Что делают при опасности в сети?", "Советуются со взрослыми."], "sol": "О таких просьбах нужно рассказать родителям и ничего не отправлять."}]},
  {"id": 169, "title": "Повторение: алгоритмы и информация", "src": "Информатика · 5–6 класс · Повторение", "ico": "🧠", "subj": "inf", "explain": ["Подведём итог: алгоритм — инструкция из команд; линейный идёт по порядку, ветвление выбирает путь, цикл повторяет.", "Информацию кодируют и хранят в битах и байтах; 1 байт = 8 бит.", "Высказывания бывают истинными и ложными, а слова И, ИЛИ и НЕ меняют их смысл.", "Всё это — основа информатики: умение думать по шагам, как компьютер.", "Совет Архимеда: повторяй через примеры, а не наизусть — тогда навык останется с тобой."], "check": {"q": "Сколько бит в одном байте?", "choices": ["2", "8", "16"], "ans": 1, "exp": "1 байт = 8 бит."}, "tasks": [{"q": "Робот выполнил «Повтори 3 раза: 2 шага». Сколько всего шагов?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Умножь число повторений на шаги.", "3 × 2 = ?"], "sol": "3 × 2 = 6 шагов."}, {"q": "Чему равно «НЕ (5 > 3)»?", "kind": "choice", "choices": ["Истина", "Ложь"], "ans": 1, "tol": 0, "hints": ["5 > 3 — истина или ложь?", "Истина; НЕ превращает в ложь."], "sol": "5 > 3 истинно, НЕ даёт ложь."}]},
  {"id": 170, "title": "Порядок действий со скобками", "src": "Математика · 5 класс · Порядок действий", "ico": "🧮", "subj": "math", "explain": ["Представь: два друга посчитали пример 20 − 3 · 4 и получили разные ответы (68 и 8). Кто прав? Чтобы таких споров не было, математики договорились о порядке действий.", "Правило: 1) сначала всё в СКОБКАХ; 2) потом умножение и деление; 3) в конце сложение и вычитание — и слева направо.", "Разберём 20 − 3 · (7 − 4): сначала скобки: 7 − 4 = 3. Теперь умножение: 3 · 3 = 9. Осталось 20 − 9 = 11.", "Почему умножение раньше сложения? Умножение — это «быстрое сложение одинаковых кучек», его считают одним действием: 3 · 4 — это 4+4+4.", "Ловушка: если нет скобок, умножение и деление выполняют до сложения и вычитания: 12 + 3 · 2 = 12 + 6 = 18, а не (12+3)·2.", "Совет Архимеда: подчёркивай действие, которое выполняешь, — и порядок не потеряется."], "check": {"q": "Чему равно 20 − 3 · (7 − 4)?", "choices": ["9", "11", "17"], "ans": 1, "exp": "Сначала скобки: 7 − 4 = 3. Потом умножение: 3 · 3 = 9. Затем 20 − 9 = 11."}, "tasks": [{"q": "Чему равно 30 − 2 · (9 − 4)?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Что делаем сначала?", "Скобки: 9 − 4 = 5; потом 2 · 5 = 10; затем 30 − 10 = 20."], "sol": "9 − 4 = 5; 2 · 5 = 10; 30 − 10 = 20."}, {"q": "Чему равно 12 + 3 · 2?", "kind": "choice", "choices": ["18", "30", "17"], "ans": 0, "tol": 0, "hints": ["Сначала умножение или сложение?", "Сначала 3 · 2 = 6, потом 12 + 6 = 18."], "sol": "3 · 2 = 6; 12 + 6 = 18."}]},
  {"id": 171, "title": "Свойства сложения: считаем удобно", "src": "Математика · 5 класс · Свойства сложения", "ico": "➕", "subj": "math", "explain": ["Складывать можно в любом порядке — результат не изменится (переместительное свойство).", "А ещё можно группировать слагаемые: (a + b) + c = a + (b + c) — сочетательное свойство.", "Зачем? Чтобы получить «круглые» числа: 37 + 48 + 63 — сложим 37 + 63 = 100, и останется 100 + 48 = 148. Считать легко!", "Проверь: 37 + 48 + 63 = 85 + 63 = 148 — тот же ответ, просто дольше.", "Ловушка: не переставляй числа в вычитании! 20 − 5 ≠ 5 − 20. Свойства перестановки работают только у сложения и умножения.", "Совет Архимеда: ищи пары, которые дают 10, 100 или 1000, — и считай в уме быстрее калькулятора."], "check": {"q": "Вычисли удобно: 37 + 48 + 63.", "choices": ["138", "148", "158"], "ans": 1, "exp": "37 + 63 = 100, затем 100 + 48 = 148."}, "tasks": [{"q": "Вычисли удобно: 25 + 77 + 75.", "kind": "unit", "ans": 177, "tol": 0, "hints": ["Какие два числа удобно сложить?", "25 + 75 = 100, затем 100 + 77 = 177."], "sol": "25 + 75 = 100; 100 + 77 = 177."}, {"q": "Как удобнее вычислить 19 + 45 + 11?", "kind": "choice", "choices": ["75", "85", "84"], "ans": 0, "tol": 0, "hints": ["Какая пара даёт круглое число?", "19 + 11 = 30, затем 30 + 45 = 75."], "sol": "19 + 11 = 30; 30 + 45 = 75."}]},
  {"id": 172, "title": "Умножение и деление на 10, 100, 1000", "src": "Математика · 5 класс · Десять и сто", "ico": "✨", "subj": "math", "explain": ["Умножить на 10 — значит приписать к числу один ноль: 47 · 10 = 470.", "Умножить на 100 — приписать два нуля: 47 · 100 = 4700. На 1000 — три нуля: 47 · 1000 = 47000.", "Деление наоборот — убираем нули: 3500 : 100 = 35 (зачёркиваем два нуля).", "Почему так? 47 · 10 — это десять раз по 47: 47 · 10 = 470: каждая цифра сдвинулась на разряд влево, а справа появился 0.", "Ловушка: 3500 : 10 = 350, а 3500 : 100 = 35 — смотри, сколько нулей убираем (столько, сколько у делителя).", "Совет Архимеда: считай нули: умножаем — дописываем, делим — убираем столько же нулей."], "check": {"q": "Чему равно 47 · 100?", "choices": ["470", "4700", "47000"], "ans": 1, "exp": "Приписываем два нуля: 47 · 100 = 4700."}, "tasks": [{"q": "Чему равно 3500 : 100?", "kind": "unit", "ans": 35, "tol": 0, "hints": ["Сколько нулей у 100?", "Два — убираем два нуля: 35."], "sol": "3500 : 100 = 35."}, {"q": "Чему равно 5 · 1000?", "kind": "choice", "choices": ["500", "5000", "50000"], "ans": 1, "tol": 0, "hints": ["У 1000 три нуля.", "Приписываем три нуля: 5000."], "sol": "5 · 1000 = 5000."}]},
  {"id": 173, "title": "Степень: квадрат и куб числа", "src": "Математика · 5 класс · Степень", "ico": "🟦", "subj": "math", "explain": ["КВАДРАТ числа — это число, умноженное само на себя: 5² = 5 · 5 = 25. Маленькая двойка говорит: «возьми число два раза» (5·5).", "КУБ числа — число, взятое три раза: 2³ = 2 · 2 · 2 = 8.", "Почему так называются? 5² — это площадь квадрата со стороной 5, а 2³ — объём куба с ребром 2.", "Пример: 3² + 2² = 9 + 4 = 13. Сначала возводим в степень, потом складываем.", "Ловушка: 2³ ≠ 6! Это не умножение на 3, а 2 · 2 · 2 = 8.", "Совет Архимеда: запиши степень развёрнуто (5 · 5) и перемножь — не ошибёшься."], "check": {"q": "Чему равен квадрат числа 5 (5²)?", "choices": ["10", "20", "25"], "ans": 2, "exp": "5² = 5 · 5 = 25."}, "tasks": [{"q": "Чему равен куб числа 2 (2³)?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Куб — число взятое три раза.", "2 · 2 · 2 = 8."], "sol": "2³ = 2 · 2 · 2 = 8."}, {"q": "Чему равно 3² + 2²?", "kind": "choice", "choices": ["10", "13", "25"], "ans": 1, "tol": 0, "hints": ["Сначала степени: 3² = 9, 2² = 4.", "9 + 4 = 13."], "sol": "3² = 9, 2² = 4, 9 + 4 = 13."}]},
  {"id": 174, "title": "Простые уравнения", "src": "Математика · 5 класс · Уравнения", "ico": "⚖️", "subj": "math", "explain": ["Уравнение — это «весы в равновесии»: x + 27 = 52 значит «неизвестное число и 27 вместе дают 52».", "Чтобы найти неизвестное слагаемое, от суммы отнимают известное: x = 52 − 27 = 25.", "Если неизвестен множитель, произведение делят на известный множитель: 8 · x = 96, значит x = 96 : 8 = 12.", "Почему так? На весах: если снять с обеих чашек по 27, равновесие сохранится — останется x = 25.", "Ловушка: после решения ВСЕГДА проверяй подстановкой: 25 + 27 = 52 ✓, 8 · 12 = 96 ✓.", "Совет Архимеда: назови неизвестное вслух («сколько было?») — уравнение сразу станет простой задачей."], "check": {"q": "Реши уравнение: x + 27 = 52.", "choices": ["25", "79", "35"], "ans": 0, "exp": "x = 52 − 27 = 25. Проверка: 25 + 27 = 52."}, "tasks": [{"q": "Реши уравнение: 8 · x = 96.", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Что неизвестно: множитель.", "x = 96 : 8 = 12; проверка 8 · 12 = 96."], "sol": "x = 96 : 8 = 12."}, {"q": "Реши уравнение: x − 14 = 30.", "kind": "choice", "choices": ["16", "44", "34"], "ans": 1, "tol": 0, "hints": ["Что нужно сделать с 30 и 14?", "x = 30 + 14 = 44; проверка 44 − 14 = 30."], "sol": "x = 30 + 14 = 44."}]},
  {"id": 175, "title": "Периметр и площадь прямоугольника", "src": "Математика · 5 класс · Площадь и периметр", "ico": "📐", "subj": "math", "explain": ["ПЕРИМЕТР — длина границы фигуры: P = 2 · (a + b). У прямоугольника 7 на 3: P = 2 · (7 + 3) = 20.", "ПЛОЩАДЬ — сколько квадратиков помещается внутри: S = a · b. Тот же прямоугольник: S = 7 · 3 = 21.", "Разница: периметр в единицах длины (см), площадь — в квадратных единицах (см²).", "Квадрат — прямоугольник с равными сторонами: S = a · a. У квадрата 5×5 площадь 25, периметр 20.", "Ловушка: не путай формулы: периметр — складываем и умножаем на 2, площадь — перемножаем стороны.", "Совет Архимеда: представь пол из плиток 1×1: сколько плиток уложишь — такая и площадь."], "check": {"q": "Чему равна площадь прямоугольника со сторонами 7 и 3?", "choices": ["20", "21", "24"], "ans": 1, "exp": "S = 7 · 3 = 21 (квадратных единиц). А 20 — это периметр."}, "tasks": [{"q": "Найди периметр прямоугольника со сторонами 6 и 4.", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Периметр = 2 · (a + b).", "2 · (6 + 4) = 2 · 10 = 20."], "sol": "P = 2 · (6 + 4) = 20."}, {"q": "Чему равна площадь квадрата со стороной 5?", "kind": "choice", "choices": ["20", "25", "30"], "ans": 1, "tol": 0, "hints": ["Площадь квадрата = сторона × сторона.", "5 · 5 = 25."], "sol": "S = 5 · 5 = 25."}]},
  {"id": 176, "title": "Объём прямоугольного параллелепипеда", "src": "Математика · 5 класс · Объём", "ico": "📦", "subj": "math", "explain": ["Объём показывает, сколько кубиков помещается внутри коробки.", "Формула: V = a · b · c — длина × ширина × высота.", "Пример: коробка 2 × 3 × 4 см: V = 2 · 3 · 4 = 24 см³ (кубических сантиметра).", "Почему так? На дне укладывается a · b кубиков, а таких слоёв — c, значит всего a · b · c.", "Единицы объёма: см³, м³ — маленькая тройка означает «кубические».", "Совет Архимеда: умножай по шагам: сначала a · b, потом результат на c."], "check": {"q": "Чему равен объём коробки 2 × 3 × 4?", "choices": ["24", "9", "20"], "ans": 0, "exp": "V = 2 · 3 · 4 = 24 кубических единицы."}, "tasks": [{"q": "Чему равен объём параллелепипеда 3 × 2 × 5?", "kind": "unit", "ans": 30, "tol": 0, "hints": ["Перемножь длину, ширину и высоту.", "3 · 2 = 6, 6 · 5 = 30."], "sol": "V = 3 · 2 · 5 = 30."}, {"q": "Коробка 10 × 10 × 10. Чему равен её объём?", "kind": "choice", "choices": ["100", "1000", "30"], "ans": 1, "tol": 0, "hints": ["Это куб со стороной 10.", "10 · 10 · 10 = 1000."], "sol": "V = 10 · 10 · 10 = 1000."}]},
  {"id": 177, "title": "Доли: половина, треть, четверть числа", "src": "Математика · 5 класс · Доли", "ico": "🍰", "subj": "math", "explain": ["Доля — это часть целого. Половина (1/2) — целое, разделённое на 2 равные части.", "Чтобы найти долю числа, делим: половина от 60 = 60 : 2 = 30; треть (1/3) от 60 = 60 : 3 = 20; четверть (1/4) от 40 = 40 : 4 = 10.", "Почему так? Если торт разделить на 3 равные части, каждая часть — треть торта, а её «размер» — треть числа.", "Совет Архимеда: знаменатель дроби говорит, на сколько частей делим: /2 — на 2, /3 — на 3, /4 — на 4."], "check": {"q": "Чему равна четверть числа 40?", "choices": ["10", "20", "4"], "ans": 0, "exp": "Четверть — делим на 4: 40 : 4 = 10."}, "tasks": [{"q": "Чему равна треть числа 60?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Треть — раздели на 3.", "60 : 3 = 20."], "sol": "60 : 3 = 20."}, {"q": "Чему равна половина числа 50?", "kind": "choice", "choices": ["20", "25", "50"], "ans": 1, "tol": 0, "hints": ["Половина — раздели на 2.", "50 : 2 = 25."], "sol": "50 : 2 = 25."}]},
  {"id": 178, "title": "Сравнение дробей с одинаковыми знаменателями", "src": "Математика · 5 класс · Сравнение дробей", "ico": "⚖️", "subj": "math", "explain": ["Дроби с одинаковым знаменателем — это доли одного размера: 3/7 и 2/7 — это три седьмых и две седьмых одного торта.", "Из долей одинакового размера больше та, у которой больше числитель: 3/7 > 2/7.", "Почему? Семь одинаковых кусков: три куска больше, чем два.", "Правило: сравниваем числители, знаменатели одинаковые — их не трогаем.", "Ловушка: не сравнивай знаменатели! 3/7 и 3/5: больше 3/5, потому что пятые доли крупнее.", "Совет Архимеда: представь пиццу, нарезанную на 7 кусков: 3 куска или 2 — что больше?"], "check": {"q": "Какая дробь больше: 3/7 или 2/7?", "choices": ["3/7", "2/7", "Они равны"], "ans": 0, "exp": "Знаменатели одинаковые (7), сравниваем числители: 3 > 2, значит 3/7 > 2/7."}, "tasks": [{"q": "Сравни: 5/9 и 7/9. Какая дробь меньше?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Знаменатели одинаковые — сравни числители.", "5 < 7, меньше дробь 5/9."], "sol": "5/9 < 7/9, меньше — 5/9 (числитель 5)."}, {"q": "Какая дробь больше: 2/5 или 3/5?", "kind": "choice", "choices": ["2/5", "3/5", "Они равны"], "ans": 1, "tol": 0, "hints": ["Пятые доли одинаковые, сравни числители.", "3 > 2 — больше 3/5."], "sol": "3 > 2, значит 3/5 > 2/5."}]},
  {"id": 179, "title": "Правильные, неправильные дроби и смешанные числа", "src": "Математика · 5 класс · Виды дробей", "ico": "🍕", "subj": "math", "explain": ["Если числитель меньше знаменателя (3/4) — дробь ПРАВИЛЬНАЯ, она меньше единицы.", "Если числитель больше или равен знаменателю (7/4, 5/5) — дробь НЕПРАВИЛЬНАЯ: в ней больше одной целой.", "Неправильную дробь записывают как смешанное число: 7/4 — сколько четвёрок в 7? Одна целая (4) и остаток 3 → 1 3/4.", "5/5 = 1 — пять пятых это ровно одно целое.", "Перевод в другую сторону: 2 1/3 = 2 целых по 3 трети + 1 = (2·3 + 1)/3 = 7/3.", "Совет Архимеда: задай вопрос «сколько целых спрятано?» — дели числитель на знаменатель."], "check": {"q": "Запиши 7/4 в виде смешанного числа.", "choices": ["1 3/4", "1 1/4", "2 3/4"], "ans": 0, "exp": "В 7 четвёрках одна целая (4/4) и остаётся 3 четвёртых: 7/4 = 1 3/4."}, "tasks": [{"q": "Чему равно 5/5?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Пять пятых — сколько целых?", "5 : 5 = 1."], "sol": "5/5 = 1."}, {"q": "Запиши 2 1/3 неправильной дробью.", "kind": "choice", "choices": ["7/3", "6/3", "5/3"], "ans": 0, "tol": 0, "hints": ["Две целые — это сколько третей?", "2 · 3 = 6 третей, плюс 1 = 7/3."], "sol": "2 1/3 = (2·3 + 1)/3 = 7/3."}]},
  {"id": 180, "title": "Сложение дробей с разными знаменателями", "src": "Математика · 5 класс · Сложение дробей", "ico": "🧩", "subj": "math", "explain": ["Дроби с разными знаменателями — это доли разного размера, складывать их сразу нельзя: 1/2 + 1/3 ≠ 2/5!", "Сначала приводим к ОБЩЕМУ знаменателю — числу, которое делится на оба знаменателя.", "1/2 + 1/3: общий знаменатель 6. 1/2 = 3/6 (домножили на 3), 1/3 = 2/6 (домножили на 2).", "Теперь доли одинаковые: 3/6 + 2/6 = 5/6.", "Почему 1/2 = 3/6? Половину пиццы можно нарезать на 6 кусков — тогда это 3 куска из 6.", "Ловушка: знаменатели НЕ складываем: 1/2 + 1/3 ≠ 2/5 — это меньше половины, а на самом деле почти целая пицца (5/6).", "Совет Архимеда: всегда проверяй ответ по смыслу: половина плюс треть — больше половины, а 2/5 — меньше."], "check": {"q": "Чему равно 1/2 + 1/3?", "choices": ["2/5", "5/6", "2/6"], "ans": 1, "exp": "Общий знаменатель 6: 1/2 = 3/6, 1/3 = 2/6; 3/6 + 2/6 = 5/6."}, "tasks": [{"q": "Чему равен числитель результата 1/4 + 1/6?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Найди общий знаменатель для 4 и 6 (маленький).", "12: 1/4 = 3/12, 1/6 = 2/12; 3/12 + 2/12 = 5/12 — числитель 5."], "sol": "1/4 + 1/6 = 3/12 + 2/12 = 5/12."}, {"q": "Чему равно 1/3 + 1/6?", "kind": "choice", "choices": ["1/2", "2/9", "1/3"], "ans": 0, "tol": 0, "hints": ["Общий знаменатель 6: 1/3 = 2/6.", "2/6 + 1/6 = 3/6 = 1/2."], "sol": "1/3 + 1/6 = 2/6 + 1/6 = 3/6 = 1/2."}]},
  {"id": 181, "title": "Умножение десятичных дробей на 10 и 100", "src": "Математика · 5 класс · Десятичные дроби", "ico": "🔟", "subj": "math", "explain": ["Умножить десятичную дробь на 10 — значит перенести запятую на 1 цифру вправо: 3,25 · 10 = 32,5.", "На 100 — переносим запятую на 2 цифры вправо: 3,25 · 100 = 325.", "0,4 · 100 = 40: запятая «перескочила» две цифры, и на конце добавился ноль.", "Почему так? 3,25 · 10 = 32,5, потому что каждая цифра стала в 10 раз «тяжелее» и сдвинулась на разряд.", "Если цифр не хватает — дописываем нули: 0,5 · 100 = 50.", "Совет Архимеда: считай, на сколько цифр перенести запятую: на 10 — одна, на 100 — две."], "check": {"q": "Чему равно 3,25 · 10?", "choices": ["32,5", "3,250", "0,325"], "ans": 0, "exp": "Переносим запятую на одну цифру вправо: 3,25 · 10 = 32,5."}, "tasks": [{"q": "Чему равно 0,4 · 100?", "kind": "unit", "ans": 40, "tol": 0, "hints": ["На сколько цифр перенести запятую при ·100?", "На две: 0,4 → 40 (дописали ноль)."], "sol": "0,4 · 100 = 40."}, {"q": "Чему равно 1,05 · 10?", "kind": "choice", "choices": ["10,5", "1,050", "105"], "ans": 0, "tol": 0, "hints": ["Перенеси запятую на одну цифру вправо.", "1,05 → 10,5."], "sol": "1,05 · 10 = 10,5."}]},
  {"id": 182, "title": "Деление десятичной дроби на натуральное число", "src": "Математика · 5 класс · Деление десятичных", "ico": "➗", "subj": "math", "explain": ["Делим десятичную дробь на натуральное число почти как обычные числа.", "Главное: когда доходим до запятой в делимом, ставим запятую в ответе и продолжаем делить.", "Пример: 7,5 : 3. Делим 7 на 3 — берём 2 (остаток 1). Сносим 5 — но перед этим ставим запятую: получаем 2,5. Проверка: 2,5 · 3 = 7,5.", "6,4 : 8 = 0,8, потому что 6 на 8 не делится — берём 0 целых, потом 64 десятых : 8 = 8.", "Проверка умножением — лучший друг: 0,8 · 8 = 6,4 ✓.", "Совет Архимеда: если делимое меньше делителя, ответ начинается с 0 целых — не теряй запятую."], "check": {"q": "Чему равно 7,5 : 3?", "choices": ["2,5", "25", "0,25"], "ans": 0, "exp": "7,5 : 3 = 2,5; проверка: 2,5 · 3 = 7,5."}, "tasks": [{"q": "Чему равно 6,4 : 8?", "kind": "choice", "choices": ["0,8", "8", "0,08"], "ans": 0, "tol": 0, "hints": ["6 на 8 не делится — берём 0 целых.", "64 десятых : 8 = 8 десятых → 0,8."], "sol": "6,4 : 8 = 0,8; проверка: 0,8 · 8 = 6,4."}, {"q": "Чему равно 12,6 : 6?", "kind": "choice", "choices": ["2,1", "21", "2,01"], "ans": 0, "tol": 0, "hints": ["12 : 6 = 2, затем 6 десятых : 6 = 1 десятая.", "Ответ 2,1; проверка 2,1 · 6 = 12,6."], "sol": "12,6 : 6 = 2,1."}]},
  {"id": 183, "title": "Округление десятичных дробей", "src": "Математика · 5 класс · Округление", "ico": "🔄", "subj": "math", "explain": ["Округлить — значит заменить число близким, но более простым.", "Правило: смотрим на цифру ПОСЛЕ разряда, до которого округляем. Если она 5, 6, 7, 8, 9 — цифру разряда увеличиваем на 1; если 0–4 — оставляем.", "До десятых: 2,36 → смотрим на сотые (6) → 2,4. До целых: 7,5 → смотрим на десятые (5) → 8.", "Почему 5 округляет вверх? Договорились: 5 — ровно середина, её относят к большему.", "Ловушка: 4,71 до десятых — смотрим на сотые (1 < 5) → 4,7, а не 4,8.", "Совет Архимеда: подчеркни разряд округления и посмотри на соседа справа — он решает всё."], "check": {"q": "Округли 2,36 до десятых.", "choices": ["2,3", "2,4", "2,5"], "ans": 1, "exp": "Смотрим на сотые: 6 ≥ 5, значит десятые увеличиваем: 2,36 ≈ 2,4."}, "tasks": [{"q": "Округли 7,5 до целых.", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Смотрим на десятые: 5.", "5 округляет вверх: 8."], "sol": "7,5 ≈ 8 (5 округляет вверх)."}, {"q": "Округли 4,71 до десятых.", "kind": "choice", "choices": ["4,7", "4,8", "5"], "ans": 0, "tol": 0, "hints": ["Смотрим на сотые: 1.", "1 < 5 — десятые не меняем: 4,7."], "sol": "4,71 ≈ 4,7."}]},
  {"id": 184, "title": "Среднее арифметическое чисел", "src": "Математика · 5 класс · Среднее", "ico": "📏", "subj": "math", "explain": ["Среднее арифметическое — это «ровно поровну на всех»: сложили все числа и разделили на их количество.", "Пример: оценки 5, 7, 9 → сумма 21, чисел три → 21 : 3 = 7. Среднее 7.", "Зачем? Чтобы одним числом сказать «в целом сколько»: средний рост, средняя оценка.", "Если чисел четыре, делим сумму на 4; если пять — на 5.", "Совет Архимеда: сначала сложи ВСЕ числа, потом посчитай, сколько их, — и раздели."], "check": {"q": "Найди среднее арифметическое чисел 5, 7 и 9.", "choices": ["7", "8", "6"], "ans": 0, "exp": "Сумма 5 + 7 + 9 = 21, чисел три: 21 : 3 = 7."}, "tasks": [{"q": "Найди среднее арифметическое чисел 4 и 8.", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Сложи и раздели на количество (2).", "4 + 8 = 12; 12 : 2 = 6."], "sol": "(4 + 8) : 2 = 6."}, {"q": "За четыре дня турист прошёл 6, 8, 5 и 9 км. Сколько км в среднем в день?", "kind": "choice", "choices": ["6", "7", "8"], "ans": 1, "tol": 0, "hints": ["Сложи все четыре числа.", "6+8+5+9 = 28; 28 : 4 = 7."], "sol": "(6 + 8 + 5 + 9) : 4 = 28 : 4 = 7 км."}]},
  {"id": 185, "title": "Отрицательные числа и их сравнение", "src": "Математика · 6 класс · Отрицательные числа", "ico": "🌡", "subj": "math", "explain": ["Числа меньше нуля — ОТРИЦАТЕЛЬНЫЕ: −1, −5, −10. Они стоят на числовой прямой слева от нуля.", "Где холоднее: −5° или −2°? На прямой −5 левее −2, а «чем левее, тем меньше» → −5 < −2.", "Любое отрицательное число меньше нуля, а ноль меньше любого положительного: −7 < 0 < 3.", "Примеры из жизни: температура, долг (−50 ₽ — ты должен), этажи под землёй.", "Ловушка: «−10 больше −2»? Нет! −10 левее −2, значит −10 < −2. Больше то, что ПРАВЕЕ на прямой.", "Совет Архимеда: рисуй числовую прямую: чем правее число, тем оно больше — и сравнение всегда верное."], "check": {"q": "Какое число больше: −5 или −2?", "choices": ["−5", "−2", "Они равны"], "ans": 1, "exp": "На прямой −2 правее −5, значит −2 > −5."}, "tasks": [{"q": "Сколько отрицательных чисел в ряду: −3, 0, 5, −1, 7?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Какие числа меньше нуля?", "−3 и −1 — два числа."], "sol": "Отрицательные: −3 и −1 — всего 2."}, {"q": "Какая запись верна?", "kind": "choice", "choices": ["−7 > 0", "−7 < 0", "0 < −7"], "ans": 1, "tol": 0, "hints": ["Отрицательное меньше нуля.", "−7 < 0."], "sol": "Любое отрицательное число меньше нуля: −7 < 0."}]},
  {"id": 186, "title": "Сложение отрицательных и положительных чисел", "src": "Математика · 6 класс · Сложение чисел", "ico": "🧊", "subj": "math", "explain": ["Складываем числа с разными знаками как «долг и деньги»: −4 + 9 — был долг 4, пришли 9 денег, отдали долг — осталось 5.", "Правило: если знаки разные — вычитаем из большего модуля меньший и ставим знак большего: 9 − 4 = 5 → ответ 5.", "Если знаки одинаковые — складываем модули и ставим общий знак: −6 + (−3) = −9.", "Пример: 7 + (−10) — из 10 вычитаем 7, знак большего (−) → −3.", "−5 + 5 = 0: число и его «противоположное» гасят друг друга.", "Совет Архимеда: представляй температуру: было −4°, стало теплее на 9° — стало 5°."], "check": {"q": "Чему равно −4 + 9?", "choices": ["5", "−5", "13"], "ans": 0, "exp": "Знаки разные: 9 − 4 = 5, знак большего (9) положительный → 5."}, "tasks": [{"q": "Чему равно −6 + (−3)?", "kind": "unit", "ans": -9, "tol": 0, "hints": ["Знаки одинаковые — что делаем?", "Складываем 6 + 3 = 9 и ставим минус: −9."], "sol": "−6 + (−3) = −9."}, {"q": "Чему равно 7 + (−10)?", "kind": "choice", "choices": ["−3", "3", "−17"], "ans": 0, "tol": 0, "hints": ["Знаки разные — вычитаем модули.", "10 − 7 = 3, знак большего (−) → −3."], "sol": "7 + (−10) = −3."}]},
  {"id": 187, "title": "Вычитание чисел с разными знаками", "src": "Математика · 6 класс · Вычитание", "ico": "🌡", "subj": "math", "explain": ["Секрет: вычитание числа — это сложение с ПРОТИВОПОЛОЖНЫМ числом: 9 − (−4) = 9 + 4 = 13.", "«Минус на минус даёт плюс»: два минуса подряд превращаются в плюс.", "Пример: −3 − 5 = −3 + (−5) = −8 (было −3°, стало холоднее на 5° → −8°).", "4 − 7 = 4 + (−7) = −3: из 4 вычитаем 7 — не хватает 3, ответ −3.", "Температура: было 9°, стало теплее на 4° (минус −4) → 13°.", "Совет Архимеда: увидел «число − (−число)» — сразу превращай в «число + число»."], "check": {"q": "Чему равно 9 − (−4)?", "choices": ["5", "13", "−5"], "ans": 1, "exp": "Вычитание минуса — сложение: 9 − (−4) = 9 + 4 = 13."}, "tasks": [{"q": "Чему равно −3 − 5?", "kind": "unit", "ans": -8, "tol": 0, "hints": ["Это сложение с противоположным: −3 + (−5).", "−3 + (−5) = −8."], "sol": "−3 − 5 = −3 + (−5) = −8."}, {"q": "Чему равно 4 − 7?", "kind": "choice", "choices": ["−3", "3", "−11"], "ans": 0, "tol": 0, "hints": ["4 − 7 = 4 + (−7).", "7 − 4 = 3, знак большего (−) → −3."], "sol": "4 − 7 = −3."}]},
  {"id": 188, "title": "Умножение и деление чисел с разными знаками", "src": "Математика · 6 класс · Знаки", "ico": "✖️", "subj": "math", "explain": ["Правило знаков при умножении и делении: одинаковые знаки дают ПЛЮС, разные — МИНУС.", "Плюс на плюс — плюс (4·6=24); минус на минус — плюс ((−5)·(−3)=15); плюс на минус — минус ((−4)·6=−24).", "Почему минус на минус даёт плюс? Долг (−) отдать долг (−) — значит получить выгоду (+). Проще запомнить: «друг моего друга — друг, враг моего врага — друг».", "Деление так же: (−20) : 5 = −4, а (−18) : (−6) = 3.", "Ловушка: не путай знаки при сложении (там другие правила) — умножение и деление живут по своему правилу знаков.", "Совет Архимеда: сначала посчитай число без знаков, потом реши знак: одинаковые → +, разные → −."], "check": {"q": "Чему равно (−4) · 6?", "choices": ["24", "−24", "−10"], "ans": 1, "exp": "Знаки разные (минус и плюс) → минус: 4 · 6 = 24, ответ −24."}, "tasks": [{"q": "Чему равно (−5) · (−3)?", "kind": "unit", "ans": 15, "tol": 0, "hints": ["Знаки одинаковые — какой знак у ответа?", "Минус на минус — плюс: 5 · 3 = 15."], "sol": "(−5) · (−3) = 15."}, {"q": "Чему равно (−20) : 5?", "kind": "choice", "choices": ["4", "−4", "−15"], "ans": 1, "tol": 0, "hints": ["Знаки разные — знак минус.", "20 : 5 = 4, ответ −4."], "sol": "(−20) : 5 = −4."}]},
  {"id": 189, "title": "Координатная прямая и координаты точек", "src": "Математика · 6 класс · Координатная прямая", "ico": "📈", "subj": "math", "explain": ["Координатная прямая — прямая с началом отсчёта (0), на ней отмечены положительные числа справа и отрицательные слева.", "Координата точки — её «адрес»: точка A(−3) стоит на 3 шага левее нуля, точка B(2) — на 2 шага правее.", "Расстояние между точками считаем как разность координат: 2 − (−3) = 5 — расстояние 5.", "Почему так? От −3 до 0 — 3 шага, от 0 до 2 — ещё 2, всего 3 + 2 = 5.", "Ловушка: не считай −3 + 2 = −1 — это не расстояние! Расстояние всегда положительное.", "Совет Архимеда: нарисуй прямую и посчитай шаги пальцем — расстояние не ошибёшься."], "check": {"q": "Чему равно расстояние между точками A(−3) и B(2)?", "choices": ["1", "5", "−1"], "ans": 1, "exp": "2 − (−3) = 5 — расстояние 5 (от −3 до 0 три шага и от 0 до 2 ещё два)."}, "tasks": [{"q": "Сколько единиц между точками −1 и 4?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["От −1 до 0 один шаг, от 0 до 4 четыре.", "1 + 4 = 5."], "sol": "4 − (−1) = 5."}, {"q": "Какая координата у точки на 3 левее точки с координатой 2?", "kind": "choice", "choices": ["5", "−1", "−5"], "ans": 1, "tol": 0, "hints": ["Левее — значит вычитаем.", "2 − 3 = −1."], "sol": "2 − 3 = −1."}]},
  {"id": 190, "title": "Модуль числа", "src": "Математика · 6 класс · Модуль", "ico": "📏", "subj": "math", "explain": ["МОДУЛЬ числа — это расстояние от числа до нуля, поэтому он всегда неотрицательный.", "Модуль отрицательного числа — число без минуса: |−7| = 7. Модуль положительного — само число: |5| = 5. |0| = 0.", "Зачем? Модуль говорит «сколько» без учёта направления: долг −50 ₽ по модулю — 50 ₽.", "Сравниваем модули: |−9| = 9, |−4| = 4, значит |−9| > |−4|.", "Ловушка: |−7| ≠ −7! Модуль не бывает отрицательным.", "Совет Архимеда: модуль — это «сними минус, если он есть»."], "check": {"q": "Чему равен |−7|?", "choices": ["7", "−7", "0"], "ans": 0, "exp": "Модуль — расстояние до нуля: |−7| = 7."}, "tasks": [{"q": "Чему равно |−9| − |−4|?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Сначала найди модули.", "9 − 4 = 5."], "sol": "|−9| = 9, |−4| = 4; 9 − 4 = 5."}, {"q": "Что больше: |−9| или |−4|?", "kind": "choice", "choices": ["|−9|", "|−4|", "Они равны"], "ans": 0, "tol": 0, "hints": ["Найди модули и сравни.", "9 > 4, значит |−9| больше."], "sol": "|−9| = 9, |−4| = 4; 9 > 4."}]},
  {"id": 191, "title": "Пропорция: основное свойство", "src": "Математика · 6 класс · Пропорции", "ico": "⚖️", "subj": "math", "explain": ["Пропорция — равенство двух отношений: a : b = c : d, например 2 : 3 = 10 : 15.", "Основное свойство: произведение крайних членов равно произведению средних: a · d = b · c.", "Проверим: 2 · 15 = 30 и 3 · 10 = 30 — верно!", "Находим неизвестное: 2 : 3 = 10 : x → 2 · x = 3 · 10 = 30 → x = 30 : 2 = 15.", "Почему так? Отношение 2:3 означает «2 части на 3 части»: если 2 — это 10, то 3 — это 15 (обе части выросли в 5 раз).", "Совет Архимеда: умножь «крест-накрест» (крайний на крайний) — и уравнение готово."], "check": {"q": "Реши пропорцию: 2 : 3 = 10 : x.", "choices": ["12", "15", "20"], "ans": 1, "exp": "2 · x = 3 · 10 = 30, значит x = 30 : 2 = 15."}, "tasks": [{"q": "Реши пропорцию: 4 : 5 = x : 20.", "kind": "unit", "ans": 16, "tol": 0, "hints": ["Произведение крайних = средних.", "4 · 20 = 5 · x = 80, x = 16."], "sol": "4 · 20 = 80; x = 80 : 5 = 16."}, {"q": "Реши пропорцию: 3 : x = 6 : 10.", "kind": "choice", "choices": ["5", "6", "8"], "ans": 0, "tol": 0, "hints": ["3 · 10 = 6 · x.", "30 = 6x, x = 5."], "sol": "3 · 10 = 30; x = 30 : 6 = 5."}]},
  {"id": 192, "title": "Проценты: сколько процентов одно число от другого", "src": "Математика · 6 класс · Проценты", "ico": "％", "subj": "math", "explain": ["Процент — это сотая часть: 1% = 1/100. Вся величина — 100%.", "Чтобы узнать, сколько процентов составляет число A от числа B, делим A на B и умножаем на 100.", "Пример: 15 от 60: 15 : 60 = 1/4 = 25% (потому что 15 — четвёртая часть 60).", "По-другому: (15 : 60) · 100 = 0,25 · 100 = 25%.", "Ловушка: не путай, от чего считаем: 15 от 60 — это 25%, а 60 от 15 — 400%!", "Совет Архимеда: сначала спроси «какая это часть?», потом умножай на 100."], "check": {"q": "Сколько процентов составляет 15 от 60?", "choices": ["20%", "25%", "40%"], "ans": 1, "exp": "15 : 60 = 0,25 = 25% (15 — четверть от 60)."}, "tasks": [{"q": "Сколько процентов составляет 24 от 80?", "kind": "unit", "ans": 30, "tol": 0, "hints": ["24 : 80 = ?", "24 : 80 = 0,3 = 30%."], "sol": "24 : 80 = 0,3 = 30%."}, {"q": "Сколько процентов составляет 6 от 30?", "kind": "choice", "choices": ["15%", "20%", "25%"], "ans": 1, "tol": 0, "hints": ["6 : 30 = ?", "6 : 30 = 0,2 = 20%."], "sol": "6 : 30 = 0,2 = 20%."}]},
  {"id": 193, "title": "Проценты: увеличить и уменьшить", "src": "Математика · 6 класс · Проценты", "ico": "📈", "subj": "math", "explain": ["Увеличить на 10% — значит добавить десятую часть: 200 + 10% = 200 + 20 = 220.", "Как считать: сначала найди процент от числа (10% от 200 = 20), потом прибавь или отними.", "Уменьшить на 20%: 300 − 20% от 300 = 300 − 60 = 240.", "Почему так? Цена со скидкой 20% — это 100% − 20% = 80% от цены: 300 · 0,8 = 240 — тот же результат.", "Ловушка: 10% от 200 — это 20, а не 10! Процент всегда считаем от того числа, про которое говорится.", "Совет Архимеда: «увеличить на N%» = умножить на (1 + N/100); «уменьшить» — на (1 − N/100)."], "check": {"q": "Число 200 увеличили на 10%. Что получилось?", "choices": ["210", "220", "240"], "ans": 1, "exp": "10% от 200 = 20; 200 + 20 = 220."}, "tasks": [{"q": "Число 300 уменьшили на 20%. Что получилось?", "kind": "unit", "ans": 240, "tol": 0, "hints": ["20% от 300 = ?", "20% от 300 = 60; 300 − 60 = 240."], "sol": "300 · 0,8 = 240 (или 300 − 60)."}, {"q": "Число 50 увеличили на 100%. Что получилось?", "kind": "choice", "choices": ["100", "150", "75"], "ans": 0, "tol": 0, "hints": ["100% от 50 — это само 50.", "50 + 50 = 100."], "sol": "100% от 50 = 50; 50 + 50 = 100."}]},
  {"id": 194, "title": "Задачи на части и отношения", "src": "Математика · 6 класс · Отношения", "ico": "🍬", "subj": "math", "explain": ["«Разделить в отношении 2:3» значит: всего 2 + 3 = 5 равных частей, одна часть — 1/5 числа.", "Пример: разделить 60 в отношении 2:3. Одна часть: 60 : 5 = 12. Тогда первая доля 2 · 12 = 24, вторая 3 · 12 = 36.", "Проверка: 24 + 36 = 60 — всё сходится!", "Зачем так? Конфеты 60 шт делят в отношении 2:3 — младшему 24, старшему 36.", "Ловушка: не дели сразу 60 на 2 и на 3! Сначала сложи части отношения.", "Совет Архимеда: «отношение 2:3» читай как «2 части и 3 части» — всего 5 частей."], "check": {"q": "Число 60 разделили в отношении 2 : 3. Чему равна БОЛЬШАЯ часть?", "choices": ["24", "36", "12"], "ans": 1, "exp": "Всего 2 + 3 = 5 частей; одна часть 60 : 5 = 12; большая 3 · 12 = 36."}, "tasks": [{"q": "Число 40 разделили в отношении 1 : 3. Чему равна МЕНЬШАЯ часть?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["Сколько всего частей?", "1 + 3 = 4; 40 : 4 = 10 — меньшая часть."], "sol": "40 : 4 = 10."}, {"q": "Число 100 разделили в отношении 2 : 3. Чему равна большая часть?", "kind": "choice", "choices": ["40", "60", "50"], "ans": 1, "tol": 0, "hints": ["Всего 5 частей: 100 : 5 = 20.", "Большая: 3 · 20 = 60."], "sol": "100 : 5 = 20; 3 · 20 = 60."}]},
  {"id": 195, "title": "Длина окружности", "src": "Математика · 6 класс · Окружность", "ico": "⭕", "subj": "math", "explain": ["Длина окружности — это длина «обода» круга (например, длина обруча).", "Формула: C = 2 · π · r, где r — радиус (расстояние от центра до края), π ≈ 3,14, но для простоты возьмём π ≈ 3.", "Пример: радиус 4: C = 2 · 3 · 4 = 24.", "Почему 2πr? Длина окружности примерно в 6 раз больше радиуса (2π ≈ 6): радиус 4 → обод ≈ 24.", "Диаметр d = 2r — «ширина» круга через центр: C = π · d.", "Совет Архимеда: подставляй по шагам: сначала 2 · r, потом умножь на π."], "check": {"q": "Чему равна длина окружности радиуса 4 (π ≈ 3)?", "choices": ["24", "12", "16"], "ans": 0, "exp": "C = 2 · π · r = 2 · 3 · 4 = 24."}, "tasks": [{"q": "Чему равна длина окружности радиуса 5 (π ≈ 3)?", "kind": "unit", "ans": 30, "tol": 0, "hints": ["Подставь в формулу 2 · π · r.", "2 · 3 · 5 = 30."], "sol": "C = 2 · 3 · 5 = 30."}, {"q": "Чему равна длина окружности радиуса 3 (π ≈ 3)?", "kind": "choice", "choices": ["18", "9", "6"], "ans": 0, "tol": 0, "hints": ["2 · π · r = ?", "2 · 3 · 3 = 18."], "sol": "C = 2 · 3 · 3 = 18."}]},
  {"id": 196, "title": "Площадь круга", "src": "Математика · 6 класс · Площадь круга", "ico": "🔵", "subj": "math", "explain": ["Площадь круга — сколько квадратиков помещается внутри круга.", "Формула: S = π · r², где r² = r · r. При π ≈ 3: S ≈ 3 · r · r.", "Пример: радиус 3: S = 3 · 3 · 3 = 27 (π ≈ 3).", "Почему так? Если вписать в круг квадраты, их примерно π · r² — у площади «квадратная» размерность, поэтому радиус в квадрате.", "Ловушка: не умножай r на 2! В площади радиус умножаем сам на себя: r².", "Совет Архимеда: сначала посчитай r · r, потом умножь на π."], "check": {"q": "Чему равна площадь круга радиуса 3 (π ≈ 3)?", "choices": ["9", "27", "18"], "ans": 1, "exp": "S = π · r² = 3 · 3 · 3 = 27."}, "tasks": [{"q": "Чему равна площадь круга радиуса 2 (π ≈ 3)?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Сначала r · r = 4.", "3 · 4 = 12."], "sol": "S = 3 · 2 · 2 = 12."}, {"q": "Чему равна площадь круга радиуса 4 (π ≈ 3)?", "kind": "choice", "choices": ["36", "48", "16"], "ans": 1, "tol": 0, "hints": ["4 · 4 = 16; π · 16.", "3 · 16 = 48."], "sol": "S = 3 · 4 · 4 = 48."}]},
  {"id": 197, "title": "Углы и сумма углов треугольника", "src": "Математика · 6 класс · Углы", "ico": "📐", "subj": "math", "explain": ["Угол измеряют в градусах. Острый угол меньше 90°, прямой — ровно 90°, тупой — больше 90° (но меньше 180°).", "Сумма углов любого треугольника равна 180°.", "Если два угла известны, третий находим вычитанием: 180° − 40° − 60° = 80°.", "Почему 180°? Разрежь треугольник и сложи углы вместе — они образуют развёрнутый угол 180°.", "У прямоугольного треугольника один угол 90°, сумма двух других тоже 90°: 90° и 30° → третий 60°.", "Совет Архимеда: проверка — сложи все три угла, должно получиться ровно 180°."], "check": {"q": "Два угла треугольника равны 40° и 60°. Чему равен третий?", "choices": ["80°", "100°", "60°"], "ans": 0, "exp": "180° − 40° − 60° = 80°."}, "tasks": [{"q": "В прямоугольном треугольнике один угол 90°, второй 30°. Чему равен третий?", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Сумма острых углов прямоугольного треугольника 90°.", "90° − 30° = 60°."], "sol": "180° − 90° − 30° = 60°."}, {"q": "Каким называют угол 120°?", "kind": "choice", "choices": ["Острым", "Прямым", "Тупым"], "ans": 2, "tol": 0, "hints": ["90° < 120° < 180°.", "Больше 90° — тупой."], "sol": "Угол больше 90° и меньше 180° — тупой."}]},
  {"id": 198, "title": "Параллельные и перпендикулярные прямые", "src": "Математика · 6 класс · Прямые", "ico": "〰", "subj": "math", "explain": ["Параллельные прямые никогда не пересекаются — как рельсы поезда.", "Перпендикулярные прямые пересекаются под прямым углом (90°) — как пол и стена.", "Примеры: противоположные края тетрадного листа параллельны, соседние — перпендикулярны.", "Через точку, не лежащую на прямой, проходит ровно одна прямая, параллельная данной.", "Совет Архимеда: используй угольник: прямой угол — перпендикуляр, одинаковое расстояние — параллель."], "check": {"q": "Как называются прямые, которые не пересекаются?", "choices": ["Параллельные", "Перпендикулярные", "Пересекающиеся"], "ans": 0, "exp": "Прямые, которые не пересекаются, — параллельные."}, "tasks": [{"q": "Сколько прямых, параллельных данной, можно провести через точку, не лежащую на ней?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Вспомни аксиому параллельных.", "Ровно одну."], "sol": "Через точку вне прямой проходит ровно одна параллельная прямая."}, {"q": "Под каким углом пересекаются перпендикулярные прямые?", "kind": "choice", "choices": ["45°", "90°", "180°"], "ans": 1, "tol": 0, "hints": ["Вспомни определение.", "Под прямым углом — 90°."], "sol": "Перпендикулярные прямые пересекаются под углом 90°."}]},
  {"id": 199, "title": "Уравнения с переносом слагаемых", "src": "Математика · 6 класс · Уравнения", "ico": "🎯", "subj": "math", "explain": ["Если неизвестное есть в обеих частях уравнения, переносим слагаемые: при переносе через «равно» знак меняется на противоположный.", "Пример: 3x − 7 = 2x + 5. Перенесём 2x влево, −7 вправо: 3x − 2x = 5 + 7.", "Считаем: x = 12. Проверка: 3 · 12 − 7 = 36 − 7 = 29 и 2 · 12 + 5 = 24 + 5 = 29 — обе части равны!", "Почему знак меняется? Уравнение — весы: чтобы убрать 2x справа, вычитаем 2x из обеих чашек — слева появится −2x.", "Ловушка: не забывай менять знак переносимого слагаемого — главная ошибка в таких уравнениях.", "Совет Архимеда: собери все «иксы» слева, числа справа — и решай простое уравнение."], "check": {"q": "Реши уравнение: 3x − 7 = 2x + 5.", "choices": ["2", "12", "−12"], "ans": 1, "exp": "Переносим: 3x − 2x = 5 + 7 → x = 12. Проверка: 3·12 − 7 = 29 = 2·12 + 5."}, "tasks": [{"q": "Реши уравнение: 5x − 8 = 2x + 7.", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Перенеси 2x влево, −8 вправо.", "5x − 2x = 7 + 8 → 3x = 15 → x = 5."], "sol": "3x = 15; x = 5. Проверка: 25 − 8 = 17 = 10 + 7."}, {"q": "Реши уравнение: 2x + 5 = x + 9.", "kind": "choice", "choices": ["4", "6", "14"], "ans": 0, "tol": 0, "hints": ["Перенеси x влево, 5 вправо.", "2x − x = 9 − 5 → x = 4."], "sol": "x = 9 − 5 = 4. Проверка: 8 + 5 = 13 = 4 + 9."}]},
  {"id": 200, "title": "Свойства алгоритма: понятность, конечность, результативность", "src": "Информатика · 7 класс · Свойства алгоритма", "ico": "🧭", "subj": "inf", "explain": ["Представь, что даёшь роботу рецепт бутерброда. Если шаги неясные или их бесконечно много, робот ничего не сделает — поэтому у алгоритма есть строгие свойства.", "Три главных свойства: понятность — каждый шаг понятен исполнителю; конечность — число шагов ограничено; результативность — после последнего шага получается нужный результат.", "Разберём алгоритм «увеличь x на 2» при x = 3. Шаг 1: посмотри x = 3. Шаг 2: вычисли 3 + 2 = 5. Шаг 3: запиши ответ 5 и остановись. Шагов ровно 3 — алгоритм конечен, ответ 5 получен — он результативен.", "Почему это важно: алгоритм с шагом «называй числа, пока не надоест» не заканчивается никогда — он не конечный, значит, настоящим алгоритмом не является.", "Типичная ошибка: думать, что алгоритм должен быть длинным. Наоборот, короткий текст с понятными шагами и конечным числом действий — хороший алгоритм.", "Проверка: пройди алгоритм на бумаге — все ли шаги понятны, закончится ли он и будет ли в конце ответ.", "Совет Архимеда: проверяй алгоритм по трём буквам П: Понятно, Предельно (конечно), с Правильным результатом."], "check": {"q": "Алгоритм «называй числа, пока не надоест» никогда не завершится. Какое свойство алгоритма он нарушает?", "choices": ["Понятность", "Конечность", "Результативность", "Массовость"], "ans": 1, "exp": "Верно — конечность: алгоритм обязан завершаться за конечное число шагов, а здесь остановки нет. Понятность не нарушена (шаг ясен), результативность — про получение ответа после завершения (а завершения нет), массовость — про применимость к разным наборам данных."}, "tasks": [{"q": "В конспекте перечислены свойства алгоритма: понятность, конечность, результативность. Сколько свойств перечислено?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Пересчитай названия, разделённые запятыми", "Их три: понятность, конечность и результативность", "Имена свойств уже почти все в вопросе"], "sol": "Считаем по порядку: 1 — понятность, 2 — конечность, 3 — результативность. Итого: 3 свойства. Ответ: 3."}, {"q": "Учитель добавил к трём свойствам ещё одно — дискретность (алгоритм состоит из отдельных шагов). Сколько свойств стало в списке?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Сколько свойств было сначала?", "Добавь к ним дискретность", "3 + 1 = 4"], "sol": "Было 3 свойства, добавили ещё 1: 3 + 1 = 4. Ответ: 4."}, {"q": "Инструкцию одинаково понимает любой исполнитель: каждый шаг ясен. О каком свойстве идёт речь?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Какое свойство отвечает за ясность шагов?", "Понятность — шаги ясны исполнителю", "Дискретность — про отдельные шаги, а не про их ясность"], "sol": "Шаги ясны каждому исполнителю — это понятность. Конечность про завершение, результативность про получение ответа, дискретность про разбиение на шаги. Ответ: понятность.", "choices": ["Конечность", "Понятность", "Результативность", "Дискретность"]}]},
  {"id": 201, "title": "Способы записи алгоритмов: словесный, блок-схема, псевдокод, программа", "src": "Информатика · 7 класс · Способы записи алгоритмов", "ico": "📝", "subj": "inf", "explain": ["Один и тот же алгоритм можно записать по-разному: рассказать словами, нарисовать, записать «почти программой» или самой программой — выбирай удобный способ.", "Основных способов четыре: словесный (обычный текст), блок-схема (фигуры и стрелки), псевдокод (похоже на программу, но без строгих правил) и программа (на языке программирования).", "Пример словесной записи: «Открой дверь, войди, закрой дверь». Та же запись блок-схемой: прямоугольник «Открой дверь» → стрелка → прямоугольник «Войди» → стрелка → прямоугольник «Закрой дверь».", "Зачем разные способы: блок-схема наглядно показывает порядок шагов и ветвления, а программа нужна, чтобы алгоритм выполнил компьютер.", "Типичная ошибка: путать псевдокод с программой — псевдокод пишут свободно, по-русски, а программу — по строгим правилам языка.", "Проверка: скажи, каким способом записан текст: обычные предложения — словесный; фигуры со стрелками — блок-схема; команды без строгих правил, похожие на язык, — псевдокод.", "Совет Архимеда: для задач на бумаге чаще всего удобна блок-схема — на ней сразу видна вся логика."], "check": {"q": "Сколько основных способов записи алгоритмов перечислено: словесный, блок-схема, псевдокод, программа?", "choices": ["2", "3", "4", "5"], "ans": 2, "exp": "Пересчитываем: 1 — словесный, 2 — блок-схема, 3 — псевдокод, 4 — программа. Итого 4 способа. Варианты «2» и «3» — неполные списки, а пяти способов в перечне нет."}, "tasks": [{"q": "На контрольной Коля записал один и тот же алгоритм тремя способами: словесно, блок-схемой и программой. Сколько способов записи использовал Коля?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Пересчитай перечисленные способы", "Словесный, блок-схема, программа — это три способа", "Псевдокод Коля не использовал"], "sol": "Считаем: 1 — словесный, 2 — блок-схема, 3 — программа. Итого 3 способа. Ответ: 3."}, {"q": "Что из перечисленного НЕ является способом записи алгоритма?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Вспомни четыре способа из учебника", "Словесный, блок-схема и псевдокод — настоящие способы", "Танцем алгоритм не записывают"], "sol": "Четыре способа: словесный, блок-схема, псевдокод, программа. «Танец исполнителя» среди них нет — это не способ записи алгоритма. Ответ: танец исполнителя.", "choices": ["Словесный", "Танец исполнителя", "Блок-схема", "Псевдокод"]}, {"q": "Какой способ записи показывает порядок шагов и ветвления стрелками и фигурами?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["Какой способ использует фигуры и стрелки?", "Прямоугольники, ромбы и стрелки — это блок-схема", "Словесный способ — просто текст"], "sol": "Фигуры (прямоугольник — действие, ромб — условие) и стрелки-переходы — это блок-схема. Ответ: блок-схема.", "choices": ["Словесный", "Псевдокод", "Блок-схема", "Устный рассказ"]}]},
  {"id": 202, "title": "Ветвление с несколькими условиями: если… иначе если…", "src": "Информатика · 7 класс · Ветвление с несколькими условиями", "ico": "🔀", "subj": "inf", "explain": ["Когда выборов больше двух — пятёрка, четвёрка или тройка — одного «если… иначе…» мало. Нужна цепочка «иначе если».", "Правило: условия проверяют по порядку сверху вниз. Как только условие истинно, выполняют его действие и сразу выходят из всего ветвления.", "Пример: если балл ≥ 90 — «5»; иначе если балл ≥ 75 — «4»; иначе — «3». Ученик набрал 80. Проверяем: 80 ≥ 90? Нет. 80 ≥ 75? Да. Значит, оценка «4».", "Почему порядок важен: если поменять условия местами (сначала ≥ 75), то 80 получило бы «5» — ведь 80 ≥ 75 тоже верно. Поэтому идём от большего порога к меньшему.", "Типичная ошибка: проверить все условия и «выбрать лучшее». Так нельзя: выполняется только первое истинное условие, дальше ветвление не идёт.", "Проверка: подставь свой балл в первое условие, затем во второе и так далее, пока какое-то условие не станет истинным.", "Совет Архимеда: рисуй такие ветвления блок-схемой — цепочка ромбов сама подскажет правильный порядок проверок."], "check": {"q": "Алгоритм выставления оценки: если балл ≥ 90 — «5»; иначе если балл ≥ 75 — «4»; иначе — «3». Ученик набрал 80 баллов. Какую оценку он получит?", "choices": ["«5»", "«4»", "«3»", "«2»"], "ans": 1, "exp": "Проверяем по порядку: 80 ≥ 90 — ложно, идём дальше; 80 ≥ 75 — истинно, значит, оценка «4». «5» требует не меньше 90; «3» даётся только если оба условия ложны, а второе истинно; оценки «2» в этом алгоритме нет вообще."}, "tasks": [{"q": "В алгоритме: если балл ≥ 90 — «5»; иначе если балл ≥ 75 — «4»; иначе — «3». Сколько всего веток (вариантов ответа) в этом ветвлении?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Пересчитай варианты результата алгоритма", "Ветки дают «5», «4» или «3»", "Условий два, а вот веток — три"], "sol": "Ветвление выдаёт один из трёх результатов: «5», «4» или «3». Значит, веток 3. Ответ: 3."}, {"q": "По тому же алгоритму ученик набрал 92 балла. Какую оценку он получит?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Проверь первое условие: 92 ≥ 90?", "Да, значит, сразу «5»", "Дальше ветвление не выполняется"], "sol": "92 ≥ 90 — истинно, выполняется первая ветка, и ветвление завершается. Ответ: «5».", "choices": ["«5»", "«4»", "«3»", "«2»"]}, {"q": "По тому же алгоритму ученик набрал 60 баллов. Какую оценку он получит?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["60 ≥ 90? Нет. 60 ≥ 75? Нет", "Оба условия ложны — срабатывает «иначе»", "Оценка «3»"], "sol": "60 ≥ 90 — ложно; 60 ≥ 75 — ложно; оба условия не выполнились, поэтому срабатывает последняя ветка «иначе — «3»». Ответ: «3».", "choices": ["«5»", "«4»", "«3»", "«2»"]}]},
  {"id": 203, "title": "Цикл «пока» (с предусловием)", "src": "Информатика · 7 класс · Цикл «пока» с предусловием", "ico": "🔁", "subj": "inf", "explain": ["Считать «пока не сделал» удобнее, чем считать заранее: например, «пока есть детали — собирай».", "Цикл с предусловием «пока»: сначала проверяется условие; если оно истинно — выполняется тело цикла, и условие проверяется снова; если ложно — цикл завершается.", "Пример: x = 1; пока x < 10: x = x · 2. Шаги: 1 < 10 → x = 2; 2 < 10 → x = 4; 4 < 10 → x = 8; 8 < 10 → x = 16. 16 < 10 — ложно, стоп. Тело выполнилось 4 раза, x = 16.", "Почему «с предусловием»: условие проверяется ДО выполнения тела, поэтому если оно сразу ложно, тело не выполнится ни разу.", "Типичная ошибка: забыть изменить переменную в теле цикла — условие останется истинным навсегда, и цикл станет бесконечным.", "Проверка: записывай каждое изменение x столбиком и считай строки — их число равно числу повторений.", "Совет Архимеда: «прогоняй» цикл на бумаге — так ты увидишь, когда условие станет ложным."], "check": {"q": "Выполни цикл: x = 1; пока x < 10: x = x · 2. Сколько раз выполнится тело цикла?", "choices": ["3", "4", "5", "6"], "ans": 1, "exp": "Значения x: 2 (1-й раз), 4 (2-й), 8 (3-й), 16 (4-й). При x = 16 условие 16 < 10 ложно — цикл останавливается. Тело выполнилось 4 раза. Три раза — если бы остановились на 8, а 5 и 6 — лишние повторения, которых не происходит."}, "tasks": [{"q": "a = 5. Выполняется цикл: пока a < 40: a = a + 7. Каким станет a после завершения цикла?", "kind": "unit", "ans": 40, "tol": 0, "hints": ["Прибавляй 7, пока a не станет 40 или больше", "5 → 12 → 19 → 26 → 33 → 40", "При a = 40 условие 40 < 40 ложно — цикл остановится"], "sol": "5 + 7 = 12; 12 + 7 = 19; 19 + 7 = 26; 26 + 7 = 33; 33 + 7 = 40. Проверяем: 40 < 40 — ложно, цикл завершён. Ответ: a = 40."}, {"q": "n = 1. Выполняется цикл: пока n < 100: n = n · 5. Сколько раз выполнится тело цикла?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Записывай n после каждого повторения", "n = 5, 25, 125; при 125 условие 125 < 100 ложно", "Тело выполнилось 3 раза"], "sol": "n = 5 (1-й раз), n = 25 (2-й раз), n = 125 (3-й раз). 125 < 100 — ложно, цикл завершён. Тело выполнилось 3 раза. Ответ: 3.", "choices": ["2", "3", "4", "5"]}, {"q": "a = 50. Выполняется цикл: пока a > 10: a = a − 12. Каким станет a после завершения цикла?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Вычитай 12, пока a не станет 10 или меньше", "50 → 38 → 26 → 14 → 2", "При a = 2 условие 2 > 10 ложно — цикл остановится"], "sol": "50 − 12 = 38; 38 − 12 = 26; 26 − 12 = 14; 14 − 12 = 2. Проверяем: 2 > 10 — ложно, цикл завершён. Ответ: a = 2."}]},
  {"id": 204, "title": "Цикл «до» (с постусловием)", "src": "Информатика · 7 класс · Цикл «до» с постусловием", "ico": "🔂", "subj": "inf", "explain": ["Иногда нужно сделать хотя бы один раз и только потом проверять: «налей воду, а потом смотри, хватает ли».", "Цикл «до» (с постусловием): тело выполняется всегда хотя бы один раз, затем проверяется условие; если оно истинно — цикл заканчивается.", "Пример: n = 5; повторять: n = n + 3, пока n не станет ≥ 20. Ходы: 8 (1-й), 11 (2-й), 14 (3-й), 17 (4-й), 20 (5-й). n = 20 ≥ 20 — стоп. Тело выполнилось 5 раз, n стало 20.", "Отличие от цикла «пока»: там условие проверяется до тела (тело может не выполниться ни разу), здесь — после тела (минимум одно выполнение).", "Типичная ошибка: путать условие выхода — в цикле «до» останавливаемся, когда условие СТАНОВИТСЯ истинным.", "Проверка: переписывай n после каждого шага и останавливайся, как только условие выполнится.", "Совет Архимеда: запомни — «пока» работает, пока условие верно, а «до» — пока условие не станет верным."], "check": {"q": "n = 5. Повторять: n = n + 3, пока n не станет ≥ 20. Сколько раз выполнится тело цикла?", "choices": ["4", "5", "6", "7"], "ans": 1, "exp": "Значения n после повторений: 8, 11, 14, 17, 20. При n = 20 условие 20 ≥ 20 истинно — стоп. Тело выполнилось 5 раз. Четырёх повторений хватило бы только до 17 (17 < 20), а 6 и 7 повторений не происходит."}, "tasks": [{"q": "n = 3. Повторять: n = n + 5, пока n не станет ≥ 21. Каким станет n после завершения цикла?", "kind": "unit", "ans": 23, "tol": 0, "hints": ["Прибавляй 5, пока n не станет 21 или больше", "3 → 8 → 13 → 18 → 23", "При n = 23 условие n ≥ 21 истинно — цикл завершится"], "sol": "3 + 5 = 8; 8 + 5 = 13; 13 + 5 = 18; 18 + 5 = 23. Проверяем: 23 ≥ 21 — истинно, цикл завершён. Ответ: n = 23."}, {"q": "m = 2. Повторять: m = m + 4, пока m не станет ≥ 25. Сколько раз выполнится тело цикла?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Записывай m после каждого повторения", "m = 6, 10, 14, 18, 22, 26 — остановка на 26", "Тело выполнилось 6 раз"], "sol": "m = 6 (1-й), 10 (2-й), 14 (3-й), 18 (4-й), 22 (5-й), 26 (6-й). При m = 26 условие 26 ≥ 25 истинно — стоп. Тело выполнилось 6 раз. Ответ: 6.", "choices": ["5", "6", "7", "8"]}, {"q": "n = 30. Повторять: n = n − 7, пока n не станет ≤ 5. Сколько раз выполнится тело цикла?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Вычитай 7 и проверяй условие после каждого шага", "n = 23, 16, 9, 2 — остановка на 2", "Тело выполнилось 4 раза"], "sol": "n = 23 (1-й), 16 (2-й), 9 (3-й), 2 (4-й). При n = 2 условие 2 ≤ 5 истинно — стоп. Тело выполнилось 4 раза. Ответ: 4.", "choices": ["3", "4", "5", "6"]}]},
  {"id": 205, "title": "Вспомогательные алгоритмы (подпрограммы)", "src": "Информатика · 7 класс · Вспомогательные алгоритмы", "ico": "🧩", "subj": "inf", "explain": ["Если в алгоритме много раз повторяется один и тот же блок команд, его выносят в отдельную подпрограмму и вызывают по имени.", "Подпрограмма (вспомогательный алгоритм) — это именованный набор команд. В основном алгоритме вместо повторения команд пишут одно имя — вызов.", "Пример: процедура «квадрат» рисует 4 линии. Вызвали «квадрат» 3 раза: робот нарисует 4 · 3 = 12 линий, а в записи всего 3 вызова, а не 12 команд.", "Зачем это нужно: текст короче, ошибку исправляют в одном месте, и главный алгоритм легко читать.", "Типичная ошибка: копировать одни и те же команды много раз — текст разрастается, и найти ошибку в повторениях очень трудно.", "Проверка: найди повторяющийся фрагмент команд, дай ему имя и замени все повторения вызовами подпрограммы.", "Совет Архимеда: называй подпрограммы по делу — «квадрат», а не «процедура1», и алгоритм будет понятен другим."], "check": {"q": "Робот рисует квадрат: подпрограмма «квадрат» проводит 4 линии. Сколько линий он проведёт, вызвав «квадрат» 3 раза?", "choices": ["4", "7", "12", "16"], "ans": 2, "exp": "4 линии · 3 вызова = 12 линий. Вариант «4» — это один вызов; «7» — сумма 4 + 3 (линии и вызовы складывать нельзя); «16» — это 4 · 4."}, "tasks": [{"q": "Процедура «треугольник» рисует 3 линии. Её вызвали 5 раз. Сколько всего линий нарисует робот?", "kind": "unit", "ans": 15, "tol": 0, "hints": ["Каждый вызов добавляет 3 линии", "Умножь 3 на число вызовов", "3 · 5 = 15"], "sol": "3 линии · 5 вызовов = 15 линий. Ответ: 15."}, {"q": "Подпрограмма «дом» рисует 8 линий. Сколько линий нарисует робот, вызвав её 3 раза?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["Умножь 8 на число вызовов", "8 · 3 = 24", "Вариант «8» — это один вызов, а их три"], "sol": "8 линий · 3 вызова = 24 линии. Ответ: 24.", "choices": ["8", "11", "24", "16"]}, {"q": "Для забора робот 4 раза вызвал подпрограмму «секция», каждая рисует 5 линий. Сколько всего линий в заборе?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Умножь 5 на число вызовов", "5 · 4 = 20", "Каждый вызов — это 5 линий"], "sol": "5 линий · 4 вызова = 20 линий. Ответ: 20."}]},
  {"id": 206, "title": "Переменные в алгоритмах", "src": "Информатика · 7 класс · Переменные в алгоритмах", "ico": "📦", "subj": "inf", "explain": ["В алгоритмах нужна «память» для чисел — это переменные: у имени есть значение, которое можно менять.", "Запись x = x + y читается так: взять текущее значение x, прибавить значение y и записать результат в x. Старое значение x при этом стирается.", "Пример: x = 7; y = 2; x = x + y. В правой части x = 7 (старое значение), y = 2; 7 + 2 = 9; теперь x = 9.", "Почему так: в правой части всегда берутся значения ДО этого присваивания, поэтому порядок команд важен — поменяй команды местами, и ответ изменится.", "Типичная ошибка: считать, что «x = x + y» — это уравнение. Нет: это команда записать новое значение в ячейку x.", "Проверка: веди таблицу и записывай значение каждой переменной после каждой команды.", "Совет Архимеда: держи под рукой таблицу значений переменных — она спасает в любой задаче с алгоритмами."], "check": {"q": "Выполни команды: x = 7; y = 2; x = x + y. Чему стало равно x?", "choices": ["5", "7", "9", "14"], "ans": 2, "exp": "В правой части берётся старое значение x = 7: 7 + 2 = 9, и 9 записывается в x. «5» — это 7 − 2; «7» — значение x до присваивания; «14» — произведение 7 · 2."}, "tasks": [{"q": "a = 10; b = 3; a = a − b. Чему стало равно a?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Возьми текущее значение a", "Вычисли 10 − 3", "Новое значение записывается в a, стирая 10"], "sol": "a = a − b: берём старое a = 10, вычитаем b = 3: 10 − 3 = 7. Теперь a = 7. Ответ: 7."}, {"q": "k = 4; k = k · 3; k = k + 5. Чему стало равно k?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["Выполняй команды строго по порядку", "k = 4 · 3 = 12, затем k = 12 + 5 = 17", "17 — конечное значение k"], "sol": "Сначала k = 4 · 3 = 12 (старое значение 4 стирается), затем k = 12 + 5 = 17. Ответ: 17.", "choices": ["9", "12", "17", "21"]}, {"q": "m = 6; n = 6; m = m + n; n = m − 2. Чему стало равно n?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["Сначала найди новое m", "m = 6 + 6 = 12", "n = 12 − 2 = 10"], "sol": "m = 6 + 6 = 12; теперь n = m − 2 = 12 − 2 = 10. Ответ: 10.", "choices": ["4", "6", "10", "12"]}]},
  {"id": 207, "title": "Перевод двоичного числа в десятичное", "src": "Информатика · 7 класс · Перевод двоичного числа в десятичное", "ico": "🔢", "subj": "inf", "explain": ["Компьютер «мыслит» нулями и единицами, поэтому полезно уметь читать двоичные числа.", "Правило перевода: разряды двоичного числа справа налево имеют веса 1, 2, 4, 8, 16… Умножь каждую цифру на её вес и сложи результаты.", "Пример: 1010₂. Разряды: 1·8 + 0·4 + 1·2 + 0·1 = 8 + 0 + 2 + 0 = 10. Значит, 1010₂ = 10.", "Почему так: каждый следующий разряд вдвое тяжелее предыдущего — это двоичная система, в отличие от десятичной, где веса 1, 10, 100…", "Типичная ошибка: начинать считать веса слева направо. Веса всегда идут справа налево, начиная с 1.", "Проверка: подпиши под цифрами веса 8 4 2 1, перемножь, сложи и сверь результат.", "Совет Архимеда: выучи первые веса наизусть: 1, 2, 4, 8, 16 — и перевод станет делом секунд."], "check": {"q": "Переведи 1101₂ в десятичную систему счисления.", "choices": ["11", "13", "14", "15"], "ans": 1, "exp": "1101₂ = 1·8 + 1·4 + 0·2 + 1·1 = 8 + 4 + 0 + 1 = 13. «11» — это 1011₂, «14» — 1110₂, «15» — 1111₂."}, "tasks": [{"q": "Переведи 1011₂ в десятичную систему счисления.", "kind": "unit", "ans": 11, "tol": 0, "hints": ["Подпиши веса разрядов: 8 4 2 1", "1011 = 1·8 + 0·4 + 1·2 + 1·1", "8 + 2 + 1 = 11"], "sol": "1011₂ = 1·8 + 0·4 + 1·2 + 1·1 = 8 + 0 + 2 + 1 = 11. Ответ: 11."}, {"q": "Переведи 11001₂ в десятичную систему счисления.", "kind": "choice", "ans": 0, "tol": 0, "hints": ["У числа пять разрядов: веса 16 8 4 2 1", "1·16 + 1·8 + 0·4 + 0·2 + 1·1", "16 + 8 + 1 = 25"], "sol": "11001₂ = 1·16 + 1·8 + 0·4 + 0·2 + 1·1 = 16 + 8 + 0 + 0 + 1 = 25. Ответ: 25.", "choices": ["25", "21", "19", "27"]}, {"q": "Переведи 1001₂ в десятичную систему счисления.", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Веса четырёх разрядов: 8 4 2 1", "1·8 + 0·4 + 0·2 + 1·1", "8 + 1 = 9"], "sol": "1001₂ = 1·8 + 0·4 + 0·2 + 1·1 = 8 + 0 + 0 + 1 = 9. Ответ: 9.", "choices": ["5", "9", "10", "12"]}]},
  {"id": 208, "title": "Перевод десятичного числа в двоичное делением на 2", "src": "Информатика · 7 класс · Перевод десятичного числа в двоичное", "ico": "🧮", "subj": "inf", "explain": ["Обратная задача — десятичное число записать нулями и единицами. Надёжный способ — деление на 2.", "Правило: делим число на 2 и записываем остатки (0 или 1), пока не получим частное 0. Остатки читаем снизу вверх.", "Пример: 13₁₀. 13 : 2 = 6 (ост. 1); 6 : 2 = 3 (ост. 0); 3 : 2 = 1 (ост. 1); 1 : 2 = 0 (ост. 1). Читаем остатки снизу вверх: 1101₂. Проверка: 8 + 4 + 0 + 1 = 13. Верно.", "Почему читаем снизу вверх: последний остаток — самый старший разряд двоичного числа.", "Типичная ошибка: читать остатки сверху вниз — получится 1011₂, а это уже 11, а не 13.", "Проверка: всегда переводи ответ обратно: 1101₂ = 8 + 4 + 1 = 13 — сходится.", "Совет Архимеда: деление заканчивается, когда частное становится 0, — не останавливайся раньше."], "check": {"q": "Переведи 13₁₀ в двоичную систему счисления делением на 2.", "choices": ["1011₂", "1101₂", "1110₂", "1001₂"], "ans": 1, "exp": "13 : 2 = 6 (ост. 1); 6 : 2 = 3 (ост. 0); 3 : 2 = 1 (ост. 1); 1 : 2 = 0 (ост. 1). Остатки снизу вверх: 1101₂. Проверка: 8 + 4 + 1 = 13. 1011₂ = 11, 1110₂ = 14, 1001₂ = 9 — это другие числа."}, "tasks": [{"q": "Переведи 6₁₀ в двоичную систему счисления делением на 2.", "kind": "unit", "ans": 110, "tol": 0, "hints": ["Дели 6 на 2 и записывай остатки", "6 : 2 = 3 (ост. 0); 3 : 2 = 1 (ост. 1); 1 : 2 = 0 (ост. 1)", "Прочитай остатки снизу вверх: 110"], "sol": "6 : 2 = 3, остаток 0; 3 : 2 = 1, остаток 1; 1 : 2 = 0, остаток 1. Читаем снизу вверх: 110₂. Проверка: 110₂ = 4 + 2 = 6. Ответ: 110₂ (записываем 110)."}, {"q": "Переведи 19₁₀ в двоичную систему счисления.", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Дели 19 на 2 до частного 0", "19 : 2 = 9 (ост. 1); 9 : 2 = 4 (ост. 1); 4 : 2 = 2 (ост. 0); 2 : 2 = 1 (ост. 0); 1 : 2 = 0 (ост. 1)", "Остатки снизу вверх: 10011"], "sol": "Остатки: 1, 1, 0, 0, 1; читаем снизу вверх: 10011₂. Проверка: 16 + 0 + 0 + 2 + 1 = 19. Ответ: 10011₂.", "choices": ["10011₂", "11001₂", "10101₂", "11011₂"]}, {"q": "Переведи 10₁₀ в двоичную систему счисления.", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Дели 10 на 2 до частного 0", "10 : 2 = 5 (ост. 0); 5 : 2 = 2 (ост. 1); 2 : 2 = 1 (ост. 0); 1 : 2 = 0 (ост. 1)", "Остатки снизу вверх: 1010"], "sol": "Остатки: 0, 1, 0, 1; снизу вверх получаем 1010₂. Проверка: 8 + 0 + 2 + 0 = 10. Ответ: 1010₂.", "choices": ["1001₂", "1010₂", "1100₂", "1101₂"]}]},
  {"id": 209, "title": "Сложение двоичных чисел", "src": "Информатика · 7 класс · Сложение двоичных чисел", "ico": "➕", "subj": "inf", "explain": ["Складывать двоичные числа можно столбиком, как десятичные, но помни: 1 + 1 = 10₂ — это двойка: пишем 0 и переносим 1.", "Правило: складывай разряды справа налево; в каждом разряде учитывай и перенос из предыдущего.", "Пример: 101₂ + 11₂. Единицы: 1 + 1 = 10₂ — пишем 0, перенос 1. Двойки: 0 + 1 + 1 (перенос) = 10₂ — пишем 0, перенос 1. Четвёрки: 1 + 1 (перенос) = 10₂ — пишем 0, перенос 1. Новый разряд: 1. Итог: 1000₂. Проверка: 5 + 3 = 8 = 1000₂.", "Почему так: в двоичной системе всего две цифры, поэтому 1 + 1 = 2 записывается как 10 — так же, как в десятичной 9 + 1 = 10.", "Типичная ошибка: считать, что 1 + 1 = 2, и записывать цифру 2 — в двоичной записи цифры 2 не существует.", "Проверка: переведи оба слагаемых в десятичную, сложи и сравни с переводом результата.", "Совет Архимеда: не забудь про последний перенос — если он остался, допиши единицу слева."], "check": {"q": "Выполни сложение: 110₂ + 10₂. Ответ запиши в двоичной системе.", "choices": ["1010₂", "1000₂", "1100₂", "1001₂"], "ans": 1, "exp": "110₂ = 6, 10₂ = 2, а 6 + 2 = 8 = 1000₂. Столбиком: единицы 0 + 0 = 0; двойки 1 + 1 = 10₂ — пишем 0, переносим 1; четвёрки 1 + 1 (перенос) = 10₂ — пишем 0, переносим 1; новый разряд 1. Итог 1000₂. 1010₂ = 10, 1100₂ = 12, 1001₂ = 9."}, "tasks": [{"q": "Выполни сложение 101₂ + 1₂. Ответ дай в десятичной системе счисления.", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Переведи оба числа в десятичную", "101₂ = 5, а 1₂ = 1", "5 + 1 = 6"], "sol": "101₂ = 4 + 1 = 5; 1₂ = 1. Складываем в десятичной: 5 + 1 = 6. Ответ: 6."}, {"q": "Выполни сложение: 11₂ + 11₂. Ответ запиши в двоичной системе.", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Вспомни: 1 + 1 = 10₂ — пишем 0, переносим 1", "11₂ = 3, значит, 3 + 3 = 6", "6 в двоичной системе — это 110"], "sol": "11₂ + 11₂: единицы 1 + 1 = 10₂ — пишем 0, переносим 1; двойки 1 + 1 (перенос) = 10₂ — пишем 0, переносим 1; новый разряд 1. Итог 110₂. Проверка: 3 + 3 = 6 = 110₂. Ответ: 110₂.", "choices": ["110₂", "111₂", "100₂", "101₂"]}, {"q": "Выполни сложение: 111₂ + 10₂. Ответ запиши в двоичной системе.", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Переведи в десятичную для проверки: 111₂ = 7, 10₂ = 2", "7 + 2 = 9", "9 в двоичной системе — это 1001"], "sol": "Столбиком: единицы 1 + 0 = 1; двойки 1 + 1 = 10₂ — пишем 0, переносим 1; четвёрки 1 + 1 (перенос) = 10₂ — пишем 0, переносим 1; новый разряд 1. Итог 1001₂. Проверка: 7 + 2 = 9 = 1001₂. Ответ: 1001₂.", "choices": ["1001₂", "1011₂", "1101₂", "1111₂"]}]},
  {"id": 210, "title": "Восьмеричная система счисления", "src": "Информатика · 7 класс · Системы счисления", "ico": "8️⃣", "subj": "inf", "explain": ["Мы привыкли считать десятками — на руках десять пальцев. А компьютеру удобна двойка, и чтобы двоичные числа не были слишком длинными, люди придумали восьмеричную систему: ведь 8 = 2³.", "В восьмеричной системе только 8 цифр: 0, 1, 2, 3, 4, 5, 6, 7. Цифр 8 и 9 здесь не бывает! Разряды — это степени числа 8: единицы (8⁰), восьмёрки (8¹), шестьдесят четвёрки (8²) и так далее.", "Переведём 15₁₀. Шаг 1: делим 15 на 8: 15 = 1·8 + 7. Шаг 2: остаток 7 записываем в конец. Шаг 3: неполное частное 1 меньше 8 — это первая цифра. Получаем 17₈.", "Проверяем: 17₈ = 1·8 + 7 = 15₁₀ — верно! Точно так же 10₁₀ = 12₈ (10 = 1·8 + 2), а 8₁₀ = 10₈ (8 = 1·8 + 0).", "Частая ошибка — писать 15₁₀ = 18₈. Так нельзя: цифры 8 в восьмеричной системе не существует, а 18₈ означало бы 1·8 + 8 = 16₁₀.", "Как проверить себя: всегда переводи ответ обратно — разложи по разрядам (первая цифра · 8 + вторая) и сравни с исходным числом.", "Совет Архимеда: пока не уверен — рисуй. Представь 15 монет и раскладывай их кучками по 8: останется одна кучка и 7 монет — вот тебе 17₈!"], "check": {"q": "Переведи число 9₁₀ в восьмеричную систему счисления.", "choices": ["11₈", "9₈", "10₈", "17₈"], "ans": 0, "exp": "9 = 1·8 + 1, поэтому 9₁₀ = 11₈. Вариант 9₈ неверен: цифры 9 в восьмеричной системе нет. 10₈ — это 8₁₀ (1·8 + 0), а 17₈ = 1·8 + 7 = 15₁₀."}, "tasks": [{"q": "Переведи число 16₁₀ в восьмеричную систему счисления.", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Раздели 16 на 8 с остатком.", "Неполное частное меньше 8 — это первая цифра, а остаток — вторая."], "sol": "16 = 2·8 + 0. Частное 2, остаток 0 → записываем 20₈. Проверка: 2·8 + 0 = 16. Ответ: 20₈."}, {"q": "Переведи число 12₁₀ в восьмеричную систему счисления.", "kind": "unit", "ans": 14, "tol": 0, "hints": ["Сколько восьмёрок помещается в 12?", "12 = 1·8 + … — найди остаток."], "sol": "12 = 1·8 + 4. Частное 1, остаток 4 → 14₈. Проверка: 1·8 + 4 = 12. Ответ: 14₈."}]},
  {"id": 211, "title": "Шестнадцатеричная система счисления", "src": "Информатика · 7 класс · Системы счисления", "ico": "🔠", "subj": "inf", "explain": ["Восьмеричная система хороша, но 8 = 2³, а программистам удобнее, когда одна цифра хранит ровно 4 бита. Поэтому используется шестнадцатеричная система: 16 = 2⁴.", "В ней 16 знаков: цифры 0–9 и буквы A = 10, B = 11, C = 12, D = 13, E = 14, F = 15. Буквы — это просто «цифры-великаны» для чисел от 10 до 15.", "Переведём 15₁₀: 15 — это буква F, поэтому 15₁₀ = F₁₆. А 16₁₀ = 10₁₆: одна «шестнадцатка» (16¹) и ноль единиц.", "Почему так? Разряд единиц отвечает за 16⁰ = 1, следующий — за 16¹ = 16. Проверим: 10₁₆ = 1·16 + 0 = 16₁₀, а 12₁₀ = C₁₆, ведь 12 — это буква C.", "Ошибка — путать 10₁₆ и A₁₆: 10₁₆ — это шестнадцать («одна шестнадцатка и ноль»), а A₁₆ = 10₁₀.", "Проверяй обратным переводом: замени буквы числами и умножь разряды — F₁₆ = 15, 10₁₆ = 1·16 + 0 = 16.", "Совет Архимеда: запомни цепочку A = 10, B = 11, C = 12, D = 13, E = 14, F = 15 — это просто алфавитный порядок сразу после девятки."], "check": {"q": "Какое число в шестнадцатеричной системе соответствует числу 15₁₀?", "choices": ["F₁₆", "15₁₆", "A₁₆", "E₁₆"], "ans": 0, "exp": "Число 15 обозначается буквой F, поэтому 15₁₀ = F₁₆. 15₁₆ означало бы 1·16 + 5 = 21₁₀, A₁₆ = 10₁₀, а E₁₆ = 14₁₀."}, "tasks": [{"q": "Чему равно число 10₁₀ в шестнадцатеричной системе?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Число 10₁₀ лежит между 10 и 15, значит ему соответствует буква.", "A = 10, B = 11, C = 12…"], "sol": "Число 10 в шестнадцатеричной системе обозначается буквой A: 10₁₀ = A₁₆. Обрати внимание: 10₁₆ — это уже 16₁₀, а не 10!", "choices": ["A₁₆", "10₁₆", "B₁₆", "F₁₆"]}, {"q": "Какой буквой записывается число 12₁₀ в шестнадцатеричной системе?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Считай по порядку: A = 10, B = 11, …", "После буквы B идёт буква для числа 12."], "sol": "A = 10, B = 11, C = 12, значит 12₁₀ = C₁₆.", "choices": ["C", "B", "D", "A"]}, {"q": "Как записывается число 16₁₀ в шестнадцатеричной системе?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["16₁₀ — это одна «шестнадцатка» и ноль единиц.", "Разложи: 16 = 1·16 + 0."], "sol": "16 = 1·16 + 0, поэтому запись 10₁₆. Варианты-ловушки: 16₁₆ = 1·16 + 6 = 22₁₀, A₁₆ = 10₁₀, 1F₁₆ = 1·16 + 15 = 31₁₀.", "choices": ["10₁₆", "A₁₆", "1F₁₆", "16₁₆"]}]},
  {"id": 212, "title": "Умножение двоичных чисел на 2", "src": "Информатика · 7 класс · Двоичная арифметика", "ico": "✖️", "subj": "inf", "explain": ["В десятичной системе умножить число на 10 — просто дописать ноль: 23 → 230. В двоичной системе та же «магия» работает при умножении на 2.", "При умножении двоичного числа на 2 нужно дописать справа один ноль. Почему? Каждая цифра сдвигается в разряд вдвое старше — как при умножении числа на основание системы.", "Умножим 101₂ на 2. Шаг 1: дописываем ноль справа — 1010₂. Шаг 2: проверяем: 101₂ = 1·4 + 0·2 + 1 = 5₁₀, а 1010₂ = 1·8 + 0·4 + 1·2 + 0 = 10₁₀. Действительно, 5·2 = 10!", "Возьмём 11₂ · 2: дописываем ноль → 110₂. Проверка: 11₂ = 3₁₀, 110₂ = 6₁₀, а 3·2 = 6. Сходится!", "Ошибка — дописывать ноль слева: 101₂ · 2 ≠ 0101₂, ведь ноль слева ничего не меняет, число останется тем же. Ноль нужен только справа!", "Всегда проверяй через десятичную систему: переведи двоичное число, умножь на 2 и сравни с переводом ответа.", "Совет Архимеда: запомни, что сдвиг каждой цифры на один разряд влево — это умножение на 2, точно как добавление нуля при умножении на 10 в десятичной системе."], "check": {"q": "Сколько будет 11₂ · 2? Ответ запиши в двоичной системе.", "choices": ["110₂", "111₂", "101₂", "100₂"], "ans": 0, "exp": "11₂ = 3₁₀, 3·2 = 6₁₀ = 110₂. По правилу: дописываем ноль к 11₂ и получаем 110₂. Остальные варианты — другие числа: 111₂ = 7₁₀, 101₂ = 5₁₀, 100₂ = 4₁₀."}, "tasks": [{"q": "Вычисли 110₂ · 2. Ответ запиши в двоичной системе.", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Просто допиши один ноль справа к числу 110₂.", "Проверка: 110₂ = 6₁₀, а 6·2 = 12₁₀."], "sol": "110₂ · 2 = 1100₂. Проверка в десятичной: 110₂ = 6₁₀, 6·2 = 12₁₀, а 12₁₀ = 8 + 4 = 1100₂.", "choices": ["1100₂", "1010₂", "1110₂", "110₂"]}, {"q": "Вычисли 1₂ · 2. Ответ запиши в двоичной системе.", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Дописываем ноль справа к числу 1₂.", "Проверка: 1₂ = 1₁₀, а 1·2 = 2₁₀."], "sol": "1₂ · 2 = 10₂. В десятичной системе: 1·2 = 2, а число 2₁₀ записывается в двоичной системе как 10₂.", "choices": ["10₂", "11₂", "100₂", "1₂"]}]},
  {"id": 213, "title": "Логические переменные и операции", "src": "Информатика · 7 класс · Основы логики", "ico": "🧩", "subj": "inf", "explain": ["В жизни мы часто отвечаем «да» или «нет». В информатике для этого есть логические переменные — они принимают только два значения: истина или ложь.", "Три главные операции: И (конъюнкция) — истина, только если истинны оба высказывания; ИЛИ (дизъюнкция) — истина, если истинно хотя бы одно; НЕ (отрицание) — превращает истину в ложь, а ложь в истину.", "Пусть A = истина, B = ложь. A И B: одно высказывание ложно, значит результат — ложь. A ИЛИ B: истина есть, значит результат — истина. НЕ A: истина превращается в ложь.", "Разберём A И (НЕ B). Сначала НЕ B: не ложь = истина. Теперь A И истина: обе части истинны, значит итог — истина.", "Ошибка — путать И и ИЛИ: И строгая (нужны обе истины), а ИЛИ добрая (достаточно одной).", "Проверка: придумай свои A и B и посчитай выражение по шагам, начиная с самых внутренних скобок.", "Совет Архимеда: представь, что истина — это 1, а ложь — 0. Тогда И похоже на умножение (1·0 = 0), а ИЛИ — на сложение (1 + 0 = 1)."], "check": {"q": "A = истина, B = ложь. Чему равно выражение A И (НЕ B)?", "choices": ["истина", "ложь", "нельзя определить", "зависит от порядка"], "ans": 0, "exp": "Сначала вычисляем НЕ B: не ложь = истина. Затем A И истина = истина И истина = истина. Значение выражения не зависит от порядка — ответ всегда можно вычислить."}, "tasks": [{"q": "A = ложь, B = истина. Чему равно A И B?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Операция И требует, чтобы обе части были истинны.", "A = ложь — значит первая часть уже не истина."], "sol": "A И B истинно только тогда, когда истинны обе переменные. Здесь A = ложь, поэтому A И B = ложь.", "choices": ["ложь", "истина", "нельзя вычислить"]}, {"q": "A = ложь, B = истина. Чему равно A ИЛИ B?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["ИЛИ истинно, если истинно хотя бы одно высказывание.", "B = истина — этого уже достаточно."], "sol": "Для ИЛИ достаточно одной истины. B = истина, поэтому A ИЛИ B = истина, даже несмотря на то, что A = ложь.", "choices": ["истина", "ложь", "нельзя вычислить"]}, {"q": "A = истина, B = истина. Чему равно A И (НЕ B)?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Сначала вычисли НЕ B: истина превращается в ложь.", "Теперь найди A И ложь."], "sol": "НЕ B = ложь (отрицание истины). Теперь A И ложь = ложь, ведь И требует двух истин, а у нас одна часть ложная. Ответ: ложь.", "choices": ["ложь", "истина", "нельзя вычислить"]}]},
  {"id": 214, "title": "Таблицы истинности: считаем строки", "src": "Информатика · 7 класс · Основы логики", "ico": "📊", "subj": "inf", "explain": ["Чтобы не запутаться, какие значения дают операции при разных A и B, логики строят таблицу истинности — в ней сразу видны все варианты.", "Сколько строк в таблице истинности (кроме шапки)? Для N переменных их 2ᴺ: каждая переменная принимает 2 значения (истина/ложь), а вариантов всего 2·2·…·2 — N множителей.", "Для двух переменных A и B строк 2² = 4. Запишем все варианты: (и, и); (и, л); (л, и); (л, л).", "Для одной переменной строк 2¹ = 2 — истина или ложь. Для трёх переменных 2³ = 8: от (и, и, и) до (л, л, л).", "Ошибка — забыть вариант «обе ложны» или посчитать строки вместе с шапкой. Шапка строкой данных не является.", "Проверка: перебери варианты по одному. Для двух переменных у первой — 2 значения, у второй тоже 2, всего 2·2 = 4 комбинации.", "Совет Архимеда: запоминай степени двойки: 2¹ = 2, 2² = 4, 2³ = 8, 2⁴ = 16 — именно столько строк дают 1, 2, 3 и 4 переменные."], "check": {"q": "Сколько строк (без учёта шапки) будет в таблице истинности для двух переменных A и B?", "choices": ["4", "2", "8", "16"], "ans": 0, "exp": "Для N переменных строк 2ᴺ. Для двух переменных 2² = 4. Число 2 подходит для одной переменной, 8 — для трёх, а 16 — для четырёх."}, "tasks": [{"q": "Сколько строк будет в таблице истинности для одной переменной?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["У одной переменной всего 2 значения: истина и ложь.", "Используй формулу 2ᴺ при N = 1."], "sol": "Число строк равно 2ᴺ. Для одной переменной 2¹ = 2 строки: истина и ложь."}, {"q": "Сколько строк будет в таблице истинности для трёх переменных?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Используй формулу 2ᴺ, где N = 3.", "Вычисли 2·2·2."], "sol": "2³ = 2·2·2 = 8 строк."}, {"q": "А сколько строк будет для четырёх переменных A, B, C, D?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Четыре переменные — это 2⁴.", "2·2·2·2 = …"], "sol": "2⁴ = 2·2·2·2 = 16 строк.", "choices": ["16", "8", "4", "32"]}]},
  {"id": 215, "title": "Табличные информационные модели", "src": "Информатика · 7 класс · Информационные модели", "ico": "📋", "subj": "inf", "explain": ["Расписание уроков, дневник погоды, прайс-лист магазина — всё это таблицы. Таблица — самый наглядный способ хранить однотипные данные.", "В табличной модели строка — это запись (один объект, например один ученик), а столбец — поле (одно свойство, например «рост»). Ячейка на пересечении строки и столбца хранит значение поля для конкретной записи.", "Возьмём таблицу «Погода»: в шапке поля «День», «Температура», «Осадки». Каждая строка ниже шапки — запись об одном дне. Записей столько, сколько строк данных, а шапка не считается.", "Если в таблице 3 поля и 5 записей, то ячеек 3·5 = 15: ячейка есть на пересечении каждой записи с каждым полем.", "Ошибка — считать шапку таблицы записью. Шапка лишь называет поля, но не описывает никакой объект.", "Проверка: число записей — это количество строк ниже шапки, а число ячеек равно произведению полей и записей.", "Совет Архимеда: представь таблицу как журнал: каждая строчка — один ученик (запись), каждый столбик — одно свойство (поле): имя, оценка, рост."], "check": {"q": "В таблице 6 строк данных, не считая шапки. Сколько записей в этой таблице?", "choices": ["6", "5", "7", "12"], "ans": 0, "exp": "Каждая строка данных — одна запись. Строк 6, значит записей 6. Число 7 получилось бы, если посчитать ещё и шапку, а 5 или 12 взяты произвольно."}, "tasks": [{"q": "В таблице 3 поля и 5 записей. Сколько всего ячеек в этой таблице?", "kind": "unit", "ans": 15, "tol": 0, "hints": ["Ячейка — это пересечение строки и столбца.", "Умножь число полей на число записей: 3·5."], "sol": "Ячеек = число полей · число записей = 3·5 = 15."}, {"q": "Столбец таблицы (например, «Фамилия», «Класс», «Рост») называют…", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Строка — запись, а столбец — …", "Столбец хранит одно свойство всех объектов."], "sol": "Столбец хранит одно свойство всех объектов — это поле. Запись — строка об одном объекте, ячейка — пересечение строки и столбца.", "choices": ["полем", "записью", "ячейкой", "схемой"]}]},
  {"id": 216, "title": "Графические информационные модели", "src": "Информатика · 7 класс · Информационные модели", "ico": "📐", "subj": "inf", "explain": ["Иногда рисунок понятнее ста слов: схему метро или генеалогическое древо читать гораздо легче, чем длинный список.", "Графические модели — это схемы, чертежи, карты, деревья, графы. В дереве есть корень (начальная вершина), ветви (рёбра) и листья (конечные вершины).", "Пусть на рисунке от ствола отходят 2 ветки, а на каждой ветке по 3 листа. Сколько всего листьев? Умножаем: 2 ветки · 3 листа = 6 листьев.", "Листья — это вершины, из которых больше ничего не выходит. Схема-дерево хорошо показывает связь «часть — целое»: дерево «Расписание» → ветви — дни недели → листья — уроки.", "Ошибка — складывать вместо умножения: 2 + 3 = 5, но это неверно. Если на каждой из 2 веток по 3 листа, это 3 + 3, то есть 2·3 = 6.", "Проверка: пересчитай листья по одному: ветка 1 — листья 1, 2, 3; ветка 2 — листья 4, 5, 6. Всего 6.", "Совет Архимеда: рисуй деревья сверху вниз — корень наверху, листья внизу. Тогда сразу видно, что лист — это тупиковая вершина, до которой дошёл путь."], "check": {"q": "От ствола дерева отходят 2 ветки, на каждой ветке по 3 листа. Сколько всего листьев у дерева?", "choices": ["6", "5", "9", "3"], "ans": 0, "exp": "На каждой из 2 веток по 3 листа, значит всего 2·3 = 6. Вариант 3 учитывает только одну ветку, 5 — это ошибочное сложение 2 + 3, а 9 получится, если взять 3 ветки по 3 листа, но веток у нас две."}, "tasks": [{"q": "От ствола дерева отходят 3 ветки, на каждой по 4 листа. Сколько всего листьев у дерева?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["На каждой ветке одинаковое число листьев — значит, умножаем.", "Вычисли 3 ветки · 4 листа."], "sol": "3·4 = 12 листьев. Проверка пересчётом: 4 + 4 + 4 = 12."}, {"q": "На схеме-дереве корнем называют…", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Корень — это точка старта схемы.", "Листья, наоборот, находятся на концах ветвей."], "sol": "Корень — начальная вершина, от которой расходятся все ветви. Листья — конечные вершины на концах ветвей, а ветка между вершинами называется ребром.", "choices": ["начальную вершину, из которой выходят все ветви", "любой лист дерева", "ветку между двумя вершинами", "самую нижнюю вершину"]}]},
  {"id": 217, "title": "Деревья: вершины и рёбра", "src": "Информатика · 7 класс · Информационные модели", "ico": "🌳", "subj": "inf", "explain": ["Дерево на схеме состоит из вершин (кружочков) и рёбер (линий между ними). Оказывается, число вершин и рёбер связано простой формулой!", "В дереве, у которого N вершин, ровно N − 1 рёбер. Чтобы связать N вершин без петель и лишних линий, нужна N − 1 связь: каждая новая вершина присоединяется одним ребром.", "Возьмём дерево из 5 вершин. Первую вершину соединяем с четырьмя остальными — по одному ребру на каждую новую. Рёбер получается 5 − 1 = 4.", "В дереве из 8 вершин рёбер 8 − 1 = 7. Например, в семейном древе из 8 человек линий-связей будет 7.", "Ошибка — считать рёбер столько же, сколько вершин, или добавлять лишнее ребро между «соседями». Лишнее ребро создаст цикл, и тогда схема деревом уже не будет.", "Проверка рисунком: нарисуй любое дерево и пересчитай рёбра — их всегда окажется на 1 меньше, чем вершин.", "Совет Архимеда: запомни фразу «дерево связывает N вершин N − 1 ребром» — и подставляй в неё любое число вершин."], "check": {"q": "Сколько рёбер в дереве, у которого 8 вершин?", "choices": ["7", "8", "9", "6"], "ans": 0, "exp": "Рёбер всегда на 1 меньше, чем вершин: 8 − 1 = 7. Вариант 8 — это число вершин, 9 = 8 + 1 (перепутан знак), а 6 просто не соответствует формуле."}, "tasks": [{"q": "Сколько рёбер в дереве, у которого 5 вершин?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Вспомни формулу: рёбер = N − 1.", "Вычисли 5 − 1."], "sol": "Рёбер = N − 1 = 5 − 1 = 4."}, {"q": "Сколько рёбер в дереве, у которого 10 вершин?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Вспомни формулу: рёбер = N − 1.", "Вычисли 10 − 1."], "sol": "Рёбер = 10 − 1 = 9."}]},
  {"id": 218, "title": "Кодирование текста", "src": "Информатика · 7 класс · Кодирование информации", "ico": "🔤", "subj": "inf", "explain": ["Компьютер хранит только нули и единицы, но мы видим буквы и целые тексты. Секрет — в кодировках: каждому символу назначен свой числовой код.", "В кодировке ASCII каждый символ занимает 1 байт (8 бит) — этого хватает для латиницы и служебных знаков. В кодировке Unicode один символ обычно занимает 2 байта — хватает на буквы всех языков мира, включая русские.", "Слово из 8 букв в кодировке по 1 байту на символ: 8 символов · 1 байт = 8 байт.", "Почему Unicode занимает больше? Чтобы поместились тысячи разных символов, их кодам нужно больше разрядов. Поэтому 5 букв в Unicode — это 5·2 = 10 байт.", "Ошибка — путать биты и байты: 1 байт = 8 бит, а не наоборот. И не забывай умножать число символов на размер одного символа.", "Проверка: объём = число символов · байт на символ. При 1 байте на символ объём в байтах просто равен длине текста.", "Совет Архимеда: считай по шагам — сначала узнай, сколько байт стоит один символ в твоей кодировке, потом умножь на число символов. Пробел и знаки препинания — тоже символы!"], "check": {"q": "Сколько байт занимает слово из 8 букв в кодировке, где каждый символ занимает 1 байт?", "choices": ["8", "16", "4", "64"], "ans": 0, "exp": "8 символов · 1 байт = 8 байт. Число 16 получилось бы при 2 байтах на символ, 4 — если 8 разделить на 2, а 64 — если 8 умножить на 8."}, "tasks": [{"q": "Сколько байт занимает слово из 5 букв в кодировке Unicode, если каждый символ занимает 2 байта?", "kind": "unit", "ans": 10, "tol": 0, "hints": ["Сколько всего символов в слове?", "Вычисли 5 символов · 2 байта."], "sol": "5 символов · 2 байта = 10 байт."}, {"q": "В какой кодировке один символ обычно занимает 2 байта и поддерживает буквы многих языков мира?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["В ASCII на символ отводится 1 байт.", "Кодировка, охватывающая алфавиты разных языков, называется Unicode."], "sol": "Unicode отводит символу 2 байта и охватывает буквы разных языков, включая русские. ASCII — это 1 байт на символ и в основном латиница.", "choices": ["Unicode", "ASCII", "двоичный код", "азбука Морзе"]}]},
  {"id": 219, "title": "Единицы измерения информации", "src": "Информатика · 7 класс · Единицы измерения информации", "ico": "💾", "subj": "inf", "explain": ["Ты узнал, что один символ занимает байты. А когда текстов, картинок и программ много, объём считают уже не байтами, а килобайтами и мегабайтами.", "В информатике 1 Кбайт = 1024 байта (а не 1000!), потому что компьютер считает степенями двойки: 1024 = 2¹⁰. Дальше по той же лестнице: 1 Мбайт = 1024 Кбайт, 1 Гбайт = 1024 Мбайт.", "Сколько байт в 2 Кбайт? Умножаем: 2·1024 = 2048 байт.", "Решим обратную задачу: 2048 байт — это 2048 : 1024 = 2 Кбайт. А 3 Кбайт — это 3·1024 = 3072 байта.", "Ошибка — умножать на 1000, как в десятичной системе: тогда 2 Кбайт «получатся» 2000 байт. В информатике множитель всегда 1024!", "Проверка: спускаясь вниз по лестнице (Кбайт → байт), умножай на 1024; поднимаясь вверх (байт → Кбайт), дели на 1024.", "Совет Архимеда: запомни волшебное число 1024 — это 2¹⁰. Каждый следующий шаг лестницы байт → Кбайт → Мбайт умножает предыдущий на 1024."], "check": {"q": "Сколько байт в 2 Кбайт?", "choices": ["2048", "2000", "1024", "4096"], "ans": 0, "exp": "1 Кбайт = 1024 байта, значит 2 Кбайт = 2·1024 = 2048 байт. 2000 — ошибка умножения на 1000, 1024 — это всего 1 Кбайт, а 4096 — это 4 Кбайт."}, "tasks": [{"q": "Сколько байт в 3 Кбайт?", "kind": "unit", "ans": 3072, "tol": 0, "hints": ["Вспомни: 1 Кбайт = 1024 байта.", "Вычисли 3·1024."], "sol": "3 Кбайт = 3·1024 = 3072 байта."}, {"q": "Сколько Кбайт в 2048 байтах?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Чтобы перейти от байтов к Кбайтам, дели на 1024.", "Вычисли 2048 : 1024."], "sol": "2048 : 1024 = 2 Кбайт, ведь 2·1024 = 2048."}, {"q": "Сколько Кбайт в 1 Мбайт?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Мбайт — следующий шаг лестницы после Кбайта.", "Каждый шаг вверх умножает на 1024."], "sol": "1 Мбайт = 1024 Кбайт. Вариант 2048 — это 2 Мбайт, 1000 — десятичное приближение, которого в информатике нет, а 512 — половина Кбайта.", "choices": ["1024", "1000", "2048", "512"]}]},
  {"id": 220, "title": "Переменные и присваивание", "src": "Информатика · 7 класс · Начала программирования", "ico": "📦", "subj": "inf", "explain": ["Программе нужно запоминать числа, с которыми она считает, — для этого в языках программирования есть ПЕРЕМЕННЫЕ.", "Переменная — это «коробочка» с именем, в которой лежит одно значение. Команда x = 5 кладёт число 5 в коробочку с именем x.", "Пример шагами: сначала x = 5, затем выполняем x = x + 2. Программа берёт старое значение x (это 5), прибавляет 2 и кладёт результат обратно: теперь x = 7.", "Знак = здесь означает не «равно», а «запиши в переменную». Поэтому запись x = x + 2 законна: справа читаем старое значение, слева указываем, куда кладём новое.", "Типичная ошибка — рассуждать как в алгебре: «x не может равняться x + 2». В программе это просто команда: взять 5, прибавить 2, положить 7 обратно в x.", "Проверь себя: выполни команды x = 10; x = x − 3 и назови новое значение переменной x.", "Совет Архимеда: представляй переменную коробочкой — новое значение всегда стирает старое."], "check": {"q": "В программе записали две команды: x = 5, а затем x = x + 2. Какое значение хранит переменная x после выполнения?", "choices": ["5", "6", "7", "10"], "ans": 2, "exp": "Сначала в x лежит 5. Команда x = x + 2 берёт старое значение 5, прибавляет 2 и кладёт результат обратно: 5 + 2 = 7."}, "tasks": [{"q": "Выполни команды: x = 10; x = x − 3. Каким станет значение переменной x?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Какое значение лежит в x перед выполнением второй команды?", "x = x − 3 означает x = 10 − 3 — посчитай."], "sol": "Сначала x = 10. Затем x = x − 3 = 10 − 3 = 7. Ответ: 7."}, {"q": "Выполни команды: x = 4; x = x * 3. Каким станет значение переменной x?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Сначала в x лежит 4.", "x = x * 3 означает 4 * 3 = ?"], "sol": "x = x * 3 = 4 * 3 = 12. Ответ: 12."}]},
  {"id": 221, "title": "Выражения и порядок действий", "src": "Информатика · 7 класс · Выражения и порядок в программе", "ico": "🧮", "subj": "inf", "explain": ["Выражения в программе считаются по строгим правилам: от порядка действий зависит, какой ответ получит компьютер.", "Порядок действий такой же, как в математике: сначала скобки, потом умножение и деление, затем сложение и вычитание.", "Пример шагами: a = 3, b = 4. Считаем c = (a + b) * 2. Шаг 1 — скобки: a + b = 3 + 4 = 7. Шаг 2 — умножение: 7 * 2 = 14. Получили c = 14.", "Убери скобки — и ответ изменится: c = a + b * 2 = 3 + 4 * 2 = 3 + 8 = 11. Вот почему скобки так важны!", "Есть и целочисленное деление: 7 // 2 = 3 — это целая часть, а 7 % 2 = 1 — остаток. Проверка: 2 * 3 + 1 = 7.", "Типичная ошибка — считать действия просто слева направо: тогда a + b * 2 дало бы (3 + 4) * 2 = 14, хотя на самом деле будет 11.", "Проверь себя: чему равен остаток 7 % 2? Затем реши задачи про a * 2 + b и 7 // 2."], "check": {"q": "Дано: 7 // 2 = 3 и 7 % 2 = 1. Чему равен остаток от деления 7 на 2?", "choices": ["1", "2", "3", "3.5"], "ans": 0, "exp": "7 = 2 * 3 + 1, значит, остаток равен 1. Число 3 — это целая часть (7 // 2), а 3.5 получилось бы при обычном делении 7 на 2."}, "tasks": [{"q": "a = 5, b = 2. Чему равно c, если c = a * 2 + b?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Сначала выполни умножение: a * 2 = 5 * 2 = ?", "Теперь прибавь b: 10 + 2 = ?"], "sol": "Сначала умножение: a * 2 = 5 * 2 = 10. Затем сложение: c = 10 + b = 10 + 2 = 12. Ответ: 12."}, {"q": "Чему равна целая часть от деления 7 на 2 (запись 7 // 2)?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Сколько раз число 2 целиком помещается в 7?", "2 * 3 = 6, а 2 * 4 = 8 — уже больше 7, значит, помещается 3 раза."], "sol": "7 = 2 * 3 + 1, поэтому целая часть равна 3. Ответ: 3."}]},
  {"id": 222, "title": "Условный оператор if/else", "src": "Информатика · 7 класс · Условный оператор", "ico": "🔀", "subj": "inf", "explain": ["Компьютер умеет принимать решения: сравнить число и выбрать, что делать дальше. Для этого нужен условный оператор.", "Условный оператор проверяет условие: если оно ИСТИННО, выполняется ветка if, а если ЛОЖНО — ветка else.", "Пример шагами: условие «если число > 10». Берём число 15: 15 > 10 — истина, поэтому печатаем «большое», ветку else пропускаем.", "А для числа 7 условие 7 > 10 ложно, поэтому выполняется else: программа печатает «маленькое».", "Так же проверяют чётность: условие число % 2 == 0 для 8 даёт 8 % 2 = 0 — условие истинно, печатаем «чётное».", "Типичная ошибка — писать в условии один знак = вместо ==: один знак присваивает значение, а два знака сравнивают.", "Проверь себя: что напечатает программа для x = −3, если в ней условие x < 0? Затем реши задачи."], "check": {"q": "Программа: если число > 10, печатай «большое», иначе — «маленькое». Что она напечатает для числа 15?", "choices": ["большое", "маленькое", "ничего", "ошибка"], "ans": 0, "exp": "15 > 10 — условие истинно, поэтому выполняется первая ветка (if) и на экране появится «большое»."}, "tasks": [{"q": "Программа проверяет: если число % 2 == 0, печатай «чётное», иначе — «нечётное». Что появится на экране для числа 8?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Посчитай остаток: 8 % 2 = ?", "8 % 2 = 0, а 0 == 0 — истина, значит, выполняется первая ветка."], "sol": "8 % 2 = 0, условие истинно, поэтому программа печатает «чётное».", "choices": ["чётное", "нечётное", "ошибка"]}, {"q": "Условие: если x < 0, печатай «отрицательное», иначе — «неотрицательное». x = −3. Что выведет программа?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Сравни −3 с нулём: −3 < 0 — это правда?", "Да, −3 меньше 0, значит, выполняется ветка if."], "sol": "−3 < 0 — условие истинно, поэтому программа выводит «отрицательное».", "choices": ["отрицательное", "неотрицательное", "ошибка"]}]},
  {"id": 223, "title": "Цикл for: сумма чисел", "src": "Информатика · 7 класс · Циклы", "ico": "🔁", "subj": "inf", "explain": ["Когда одно действие нужно повторить много раз — например, сложить все числа от 1 до 5, — на помощь приходит цикл.", "Цикл for выполняет тело цикла для каждого числа из диапазона: в for i in range(1, 6) переменная i по очереди принимает значения 1, 2, 3, 4, 5.", "Пример шагами: накапливаем сумму в s, начиная с s = 0. i = 1: s = 1; i = 2: s = 3; i = 3: s = 6; i = 4: s = 10; i = 5: s = 15. Сумма чисел от 1 до 5 равна 15.", "Почему так получается, видно по парам: 1 + 5 = 6, 2 + 4 = 6, и ещё 3 — всего 15. А сумма чисел от 1 до 10 равна 55.", "Типичная ошибка — забыть обнулить сумму перед циклом (s = 0): тогда к результату добавится лишнее число.", "Проверь себя: прогони цикл мысленно и найди сумму чисел от 1 до 4 — должно получиться 10.", "Совет Архимеда: веди таблицу «i → s» и записывай новое значение суммы на каждом шаге — не собьёшься."], "check": {"q": "Цикл складывает все числа от 1 до 4. Чему равна сумма?", "choices": ["8", "9", "10", "15"], "ans": 2, "exp": "Считаем по шагам: 1 + 2 = 3; 3 + 3 = 6; 6 + 4 = 10. Сумма чисел от 1 до 4 равна 10. (15 — это сумма от 1 до 5 из примера.)"}, "tasks": [{"q": "Цикл складывает все числа от 1 до 6. Чему равна сумма?", "kind": "unit", "ans": 21, "tol": 0, "hints": ["Считай по шагам: 1 + 2 + 3 + 4 + 5 + 6.", "Или быстро по парам: (1 + 6) * 3 = 7 * 3 = ?"], "sol": "1 + 2 + 3 + 4 + 5 + 6 = 21 (или (1 + 6) * 3 = 21). Ответ: 21."}, {"q": "Цикл складывает все числа от 1 до 3. Чему равна сумма?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Сначала 1 + 2 = 3.", "Теперь прибавь 3: 3 + 3 = ?"], "sol": "1 + 2 + 3 = 6. Ответ: 6."}]},
  {"id": 224, "title": "Списки: индексы и длина", "src": "Информатика · 7 класс · Списки (массивы)", "ico": "📋", "subj": "inf", "explain": ["Программе часто нужно хранить сразу много значений: оценки за четверть, цены, очки игроков. Для этого есть СПИСКИ (массивы).", "Список — это несколько значений в одной переменной: a = [10, 20, 30]. К каждому значению обращаются по ИНДЕКСУ.", "Важное правило: индексы начинаются с 0. В списке [10, 20, 30]: a[0] = 10, a[1] = 20, a[2] = 30. То есть элемент с индексом 1 — это 20, а не 10!", "Длину списка показывает функция len: len([10, 20, 30]) = 3. Индекс последнего элемента всегда на 1 меньше длины: 3 − 1 = 2.", "Типичная ошибка — считать, что первый элемент имеет индекс 1. Тогда вместо a[1] = 20 возьмёшь a[0] = 10 и получишь не тот элемент.", "Проверь себя: чему равен элемент с индексом 1 в списке [10, 20, 30]? Найди ответ в вопросе ниже.", "Совет Архимеда: запомни — индекс это «номер начиная с нуля», поэтому первый элемент всегда a[0]."], "check": {"q": "Дан список a = [10, 20, 30]. Чему равен элемент a[1]?", "choices": ["10", "20", "30"], "ans": 1, "exp": "Индексы считаются с нуля: a[0] = 10, a[1] = 20, a[2] = 30. Поэтому элемент с индексом 1 — это 20."}, "tasks": [{"q": "Найди сумму всех элементов списка [5, 7, 9].", "kind": "unit", "ans": 21, "tol": 0, "hints": ["Сложи первые два элемента: 5 + 7 = ?", "К результату прибавь третий: 12 + 9 = ?"], "sol": "5 + 7 + 9 = 21. Ответ: 21."}, {"q": "В списке [5, 7, 9] три элемента. Индексы начинаются с нуля: какой индекс у последнего элемента?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Индексы списка из трёх элементов: 0, 1, 2.", "Последний элемент — третий по счёту, значит, его индекс на 1 меньше длины: 3 − 1 = ?"], "sol": "Элементы имеют индексы 0, 1 и 2, значит, у последнего элемента индекс 2. Ответ: 2."}]},
  {"id": 225, "title": "Скорость передачи данных", "src": "Информатика · 8–9 класс · Передача данных", "ico": "⚡", "subj": "inf", "explain": ["Когда ты скачиваешь файл или смотришь видео, данные «едут» по сети с определённой скоростью, которую измеряют в битах в секунду.", "Главное правило: 1 байт = 8 бит. Чтобы перевести биты в байты, делим на 8, а чтобы байты в биты — умножаем на 8.", "Пример шагами: скорость канала 16 бит/с, время 3 секунды. Шаг 1: за 3 секунды передано 16 * 3 = 48 бит. Шаг 2: переводим в байты: 48 / 8 = 6 байт.", "Зачем такой перевод? Один символ текста занимает примерно 1 байт, поэтому в байтах удобно оценивать, сколько информации успело передаться.", "Типичная ошибка — ответить «48», забыв перевести биты в байты, хотя в вопросе спрашивали про байты.", "Проверь себя: 24 бита — это сколько байт? А 2 байта — сколько бит?", "Совет Архимеда: выучи пары-помощники: 8 бит = 1 байт, 16 бит = 2 байта, 24 бита = 3 байта, 32 бита = 4 байта."], "check": {"q": "Скорость передачи 16 бит/с. Сколько БАЙТ передастся за 3 секунды?", "choices": ["3 байта", "6 байт", "16 байт", "48 байт"], "ans": 1, "exp": "За 3 секунды передаётся 16 * 3 = 48 бит. Переводим в байты: 48 / 8 = 6 байт."}, "tasks": [{"q": "Сколько байт в 24 битах?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Вспомни, сколько бит в одном байте.", "24 / 8 = ?"], "sol": "1 байт = 8 бит, значит, 24 / 8 = 3. Ответ: 3 байта."}, {"q": "Сколько бит в 2 байтах?", "kind": "unit", "ans": 16, "tol": 0, "hints": ["В одном байте 8 бит.", "2 * 8 = ?"], "sol": "2 байта = 2 * 8 = 16 бит. Ответ: 16 бит."}]},
  {"id": 226, "title": "Оценка количества информации", "src": "Информатика · 8–9 класс · Количество информации", "ico": "🎲", "subj": "inf", "explain": ["У каждого символа алфавита есть «цена» — сколько бит нужно, чтобы его закодировать и отличить от остальных.", "Правило: если в алфавите N символов, то на один символ нужно i бит, где N = 2^i (i — степень двойки).", "Пример шагами: алфавит из 8 символов. Ищем степень двойки, равную 8: 2³ = 2 * 2 * 2 = 8, значит, на один символ нужно 3 бита.", "Проверим другие алфавиты: 2¹ = 2, 2² = 4, 2³ = 8, 2⁴ = 16, 2⁵ = 32, 2⁶ = 64. Алфавиту из 16 символов нужно 4 бита, из 32 — 5 бит.", "Работает и в обратную сторону: 3 битами можно закодировать 2³ = 8 разных символов — каждый лишний бит удваивает число вариантов.", "Типичная ошибка — считать, что для 8 символов нужно 8 бит. Нет: нужно такое i, чтобы 2^i = 8, а это i = 3.", "Проверь себя: 2² = 4, значит, алфавиту из 4 символов хватит 2 бит. Сверься с вопросом ниже."], "check": {"q": "Алфавит состоит из 4 символов. Сколько бит нужно, чтобы закодировать один символ такого алфавита?", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "Ищем i, при котором 2^i = 4: 2¹ = 2, 2² = 4. Значит, на один символ понадобится 2 бита."}, "tasks": [{"q": "Сколько бит нужно для одного символа алфавита из 32 символов?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Какую степень двойки нужно взять, чтобы получить 32?", "2 * 2 * 2 * 2 * 2 = 32, то есть 2⁵."], "sol": "2⁵ = 32, значит, на один символ понадобится 5 бит. Ответ: 5."}, {"q": "Сколько различных символов можно закодировать 3 битами?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Каждый бит удваивает число вариантов.", "2³ = 2 * 2 * 2 = ?"], "sol": "2³ = 8, поэтому 3 битами можно закодировать 8 различных символов. Ответ: 8."}]},
  {"id": 227, "title": "Бинарный поиск", "src": "Информатика · 8–9 класс · Бинарный поиск", "ico": "🔎", "subj": "inf", "explain": ["Сможешь угадать задуманное число от 1 до 16 меньше чем за 10 попыток? Бинарный поиск справится всего за 4 вопроса!", "Идея: каждый вопрос «число больше или меньше?» делит область поиска пополам, и лишняя половина отбрасывается.", "Пример шагами: загадано число от 1 до 16. Спрашиваем: «Оно больше 8?» Если да — остаются числа 9–16 (8 чисел), если нет — 1–8 (тоже 8 чисел). Половина отброшена!", "Считаем деления: 16 → 8 → 4 → 2 → 1. Область сужается до одного числа за 4 шага, значит, число от 1 до 16 угадывается за 4 вопроса.", "Для диапазона 1–32 получится 5 вопросов: 32 → 16 → 8 → 4 → 2 → 1. Число вопросов — это показатель степени двойки: 2⁴ = 16, 2⁵ = 32.", "Типичная ошибка — спрашивать по одному числу («это 1? это 2?»): это линейный поиск, и в худшем случае вопросов будет 16.", "Проверь себя: 8 → 4 → 2 → 1 — три деления пополам, значит, число от 1 до 8 угадывается за 3 вопроса."], "check": {"q": "Бинарный поиск делит область пополам. Сколько вопросов нужно, чтобы гарантированно угадать число от 1 до 8?", "choices": ["2", "3", "4", "8"], "ans": 1, "exp": "Делим пополам: 8 → 4 → 2 → 1 — это три шага, поэтому достаточно 3 вопросов. За 2 вопроса остались бы два неразличимых числа."}, "tasks": [{"q": "Сколько вопросов нужно бинарному поиску, чтобы угадать число от 1 до 64?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Считай деления пополам: 64 → 32 → 16 → 8 → 4 → 2 → 1.", "64 — это 2⁶, значит, шагов 6."], "sol": "64 делится пополам 6 раз, пока не останется одно число (2⁶ = 64), поэтому нужно 6 вопросов. Ответ: 6."}, {"q": "Сколько вопросов нужно бинарному поиску, чтобы угадать число от 1 до 4?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Сколько раз число 4 можно делить пополам, пока не останется одно число?", "4 → 2 → 1 — это два деления."], "sol": "4 → 2 → 1: за два деления пополам остаётся одно число, значит, нужно 2 вопроса. Ответ: 2."}]},
  {"id": 228, "title": "Сортировка выбором", "src": "Информатика · 8–9 класс · Сортировка выбором", "ico": "📊", "subj": "inf", "explain": ["Компьютеру часто нужно расставить данные по порядку: числа от меньшего к большему, фамилии по алфавиту. Это и есть сортировка.", "Сортировка выбором работает просто: каждый раз находим самый маленький элемент и ставим его на ближайшее свободное место в начале списка.", "Пример шагами: список [5, 3, 4, 1]. Проход 1: минимум 1, меняем с первым числом → [1, 3, 4, 5]. Проход 2: среди оставшихся [3, 4, 5] минимум 3 — уже стоит на месте. Проход 3: среди [4, 5] минимум 4 — тоже на месте.", "Почему так: после каждого прохода один элемент встаёт на своё место. Когда все, кроме последнего, уже на местах, последний автоматически оказывается правильным.", "Поэтому проходов всегда на один меньше, чем чисел: для 4 чисел нужно 3 прохода, для 5 чисел — 4, а для 3 чисел — 2.", "Типичная ошибка — делать лишний, n-й проход: последний элемент уже стоит правильно, и проходить список ещё раз не нужно.", "Проверь себя: сколько проходов сделает сортировка выбором со списком из 4 чисел?"], "check": {"q": "Сортировка выбором каждый раз ставит минимум в начало. Сколько проходов по списку нужно для 4 чисел?", "choices": ["2", "3", "4", "5"], "ans": 1, "exp": "Каждый проход ставит на место один элемент. После 3 проходов четвёртый элемент остаётся последним и уже стоит правильно: 4 − 1 = 3 прохода."}, "tasks": [{"q": "Сколько проходов нужно сортировке выбором для списка из 5 чисел?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Проходов всегда на один меньше, чем чисел.", "5 − 1 = ?"], "sol": "На место нужно поставить 4 первых элемента, а пятый встанет сам: 5 − 1 = 4 прохода. Ответ: 4."}, {"q": "Сколько проходов нужно сортировке выбором для списка из 3 чисел?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Последний элемент ставится на своё место сам.", "3 − 1 = ?"], "sol": "После двух проходов первые два элемента на местах, третий встаёт сам: 3 − 1 = 2 прохода. Ответ: 2."}]},
  {"id": 229, "title": "Графы и сети: IP-адрес и домены", "src": "Информатика · 8–9 класс · Графы и сети", "ico": "🌐", "subj": "inf", "explain": ["Когда ты отправляешь сообщение или открываешь сайт, компьютер должен найти адрес другого устройства в сети.", "У каждого устройства в сети есть IP-адрес — четыре числа от 0 до 255, разделённые точками. Пример: 192.168.1.10.", "Каждое из четырёх чисел называют ОКТЕТОМ. В адресе 192.168.1.10 четыре октета: 192, 168, 1 и 10.", "Почему числа не больше 255? Октет хранится в одном байте (8 бит), а 8 битами можно записать числа от 0 до 255 — всего 2⁸ = 256 значений.", "Цепочки цифр запоминать трудно, поэтому для людей придумали доменные имена: за именем school.ru скрывается настоящий IP-адрес.", "Типичная ошибка — считать, что в IP-адресе бывает число больше 255 или только три числа: такого адреса в интернете не существует.", "Проверь себя: сколько чисел в IP-адресе 192.168.1.10? Ответь на вопрос ниже."], "check": {"q": "Сколько чисел (октетов) входит в IP-адрес, например 192.168.1.10?", "choices": ["2", "3", "4", "8"], "ans": 2, "exp": "IP-адрес состоит из четырёх чисел, разделённых точками: 192, 168, 1, 10. Значит, октетов ровно 4."}, "tasks": [{"q": "Зачем нужны доменные имена вроде school.ru, если у компьютеров уже есть IP-адреса?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Что проще запомнить: school.ru или 185.23.101.7?", "Доменное имя — удобное имя, за которым скрывается IP-адрес."], "sol": "Доменное имя — это удобное для человека имя, за которым скрывается настоящий IP-адрес: school.ru запомнить и набрать проще, чем 185.23.101.7.", "choices": ["Их легче запомнить и набрать, чем длинные цепочки цифр", "Они увеличивают скорость передачи данных", "Без них невозможно зашифровать сообщения", "Они заменяют собой пароль"]}, {"q": "Каждое число IP-адреса называют октетом. Сколько октетов в адресе 10.0.0.1?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Посчитай числа, разделённые точками.", "10, 0, 0 и 1 — это четыре числа."], "sol": "В адресе 10.0.0.1 четыре числа: 10, 0, 0, 1. Значит, октетов 4. Ответ: 4."}]},
  {"id": 230, "title": "Комбинаторика: правило умножения", "src": "Информатика · 8–9 класс · Комбинаторика", "ico": "🔢", "subj": "inf", "explain": ["Крючок: нужно придумать пароль из двух цифр. Сколькими способами это можно сделать? Перебирать все варианты долго — комбинаторика даёт быстрый способ.", "Правило: если первый выбор можно сделать n способами, а второй — m способами независимо, то всего вариантов n·m.", "Пример шагами: код из двух цифр, каждая может быть 1, 2 или 3. Первая цифра — 3 варианта, вторая — 3 варианта: 3·3 = 9 кодов. Перебор: 11, 12, 13, 21, 22, 23, 31, 32, 33 — ровно 9.", "Почему так: каждую первую цифру можно соединить с любой из вторых, поэтому варианты перемножаются, а не складываются.", "Типичная ошибка: сложить варианты (3 + 3 = 6) вместо умножения. Складывают тогда, когда выборы исключают друг друга, а здесь они комбинируются.", "Проверка: для двух позиций результат легко пересчитать перебором, как в примере с кодами — получится то же число.", "Совет: рисуй дерево вариантов — по числу ветвей видно, что варианты перемножаются."], "check": {"q": "Код состоит из двух цифр, и каждая цифра может быть 1, 2 или 3. Сколько всего разных кодов можно составить?", "choices": ["6", "8", "9", "12"], "ans": 2, "exp": "По правилу умножения: 3 варианта первой цифры и 3 варианта второй → 3·3 = 9. 6 — результат сложения 3 + 3, а 8 и 12 получились бы при других правилах счёта."}, "tasks": [{"q": "Составляем двухсимвольный код: первая часть — буква А или Б (2 варианта), вторая часть — цифра 1, 2 или 3 (3 варианта). Сколько всего разных кодов можно составить?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Примени правило умножения: перемножь число вариантов для первой и второй позиций."], "sol": "2 буквы × 3 цифры = 2·3 = 6 кодов: А1, А2, А3, Б1, Б2, Б3."}, {"q": "Подбрасывают три монеты; каждая может выпасть орлом (О) или решкой (Р). Сколько всего различных последовательностей исходов может получиться?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["У каждой монеты 2 исхода, монеты независимы — перемножь 2 три раза."], "sol": "2·2·2 = 2³ = 8 последовательностей: ООО, ООР, ОРО, ОРР, РОО, РОР, РРО, РРР."}, {"q": "В каком случае число вариантов находят умножением, а не сложением?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Вспомни: варианты перемножаются, когда каждый выбор можно соединить с любым другим."], "sol": "Правило умножения работает, когда выборы независимы и сочетаются друг с другом. Если выборы исключают друг друга — варианты складывают.", "choices": ["когда выборы делаются независимо друг за другом и комбинируются", "когда выборы исключают друг друга", "когда доступен только один выбор", "когда вариантов бесконечно много"]}]},
  {"id": 231, "title": "Перестановки: факториал n!", "src": "Информатика · 8–9 класс · Комбинаторика: перестановки", "ico": "🔀", "subj": "inf", "explain": ["Крючок: сколькими способами можно расставить на полке 3 любимые книги? Кажется, что немного, но перестановок больше, чем ожидаешь.", "Правило: перестановка — это порядок, в котором расставлены n разных объектов. Число перестановок равно n! = n·(n−1)·…·2·1.", "Пример шагами: 4 книги. На 1-е место — 4 варианта, на 2-е — 3, на 3-е — 2, на 4-е — 1. Итого 4! = 4·3·2·1 = 24 способа.", "Почему так: с каждым занятым местом остаётся на одну книгу меньше, поэтому множители убывают от n до 1.", "Типичная ошибка: путать перестановку с выбором нескольких объектов — n! учитывает порядок всех n объектов; также забывают, что 1! = 1 и 0! = 1.", "Проверка: для 3 книг 3! = 3·2·1 = 6 — все 6 порядков можно выписать и убедиться.", "Совет: факториал растёт очень быстро: 5! = 120, 6! = 720. Оценивай ответ: он не может быть меньше числа объектов."], "check": {"q": "Сколькими способами можно расставить на полке 3 разные книги?", "choices": ["3", "6", "9", "12"], "ans": 1, "exp": "3! = 3·2·1 = 6. 3 — это просто число книг, а не число способов; 9 и 12 получились бы при других правилах счёта."}, "tasks": [{"q": "Сколькими способами можно поставить в очередь 2 разных учеников?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Число перестановок двух объектов — 2! = 2·1."], "sol": "2! = 2·1 = 2: порядки (А, Б) и (Б, А)."}, {"q": "Сколькими способами можно выстроить в ряд 5 разных спортсменов?", "kind": "unit", "ans": 120, "tol": 0, "hints": ["Перемножь числа от 5 до 1: 5·4·3·2·1."], "sol": "5! = 5·4·3·2·1 = 120 способов."}, {"q": "Сколько перестановок можно составить из 4 разных книг?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["4! = 4·3·2·1."], "sol": "4! = 4·3·2·1 = 24. 16 — это 4·4 или 2⁴, а 12 и 48 — неверные расчёты факториала.", "choices": ["12", "16", "24", "48"]}]},
  {"id": 232, "title": "Базы данных: таблицы, записи и поля", "src": "Информатика · 8–9 класс · Базы данных", "ico": "🗄️", "subj": "inf", "explain": ["Крючок: школьный журнал, список контактов в телефоне, каталог библиотеки — всё это базы данных, и чаще всего они устроены как таблицы.", "Правило: в таблице базы данных строка — это запись (данные об одном объекте), а столбец — это поле (один вид данных, например «Фамилия» или «Оценка»).", "Пример шагами: таблица «Ученики» с полями Имя, Класс, Оценка и 4 записями: 4 строки данных, в каждой по 3 значения → всего 4·3 = 12 ячеек.", "Почему так: разделение на поля позволяет искать и сортировать данные по одному признаку, например вывести всех учеников одного класса.", "Типичная ошибка: называть записью столбец или считать строку с заголовками за запись. Заголовки — это имена полей, а не данные.", "Проверка: сколько строк с данными — столько записей; сколько столбцов — столько полей; ячеек в таблице: поля × записи.", "Совет: представляй таблицу как классный журнал: одна строка — один ученик, один столбец — один предмет."], "check": {"q": "В таблице базы данных 7 строк с данными (строка заголовков не считается) и 4 столбца. Сколько записей в таблице?", "choices": ["4", "7", "11", "28"], "ans": 1, "exp": "Запись — это строка с данными об одном объекте, поэтому записей 7. 4 — число полей, 11 — сумма строк и столбцов, 28 — их произведение."}, "tasks": [{"q": "В таблице «Ученики» 3 поля (Имя, Класс, Оценка) и 4 записи. Сколько всего ячеек (значений) содержит таблица?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Ячеек столько же, сколько пересечений строк и столбцов: число полей умножь на число записей."], "sol": "3 поля × 4 записи = 12 ячеек."}, {"q": "Как в таблице базы данных называется столбец?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Столбец хранит один вид данных — например, «Фамилия» сразу для всех записей."], "sol": "Столбец называется полем, а строка — записью. Заголовок — это лишь имя поля в первой строке.", "choices": ["запись", "поле", "ключ", "заголовок"]}, {"q": "У таблицы такие заголовки столбцов: Номер, Название, Автор, Год. Сколько полей в таблице?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Каждый заголовок соответствует одному полю — столбцу."], "sol": "Поля: Номер, Название, Автор, Год — всего 4."}]},
  {"id": 233, "title": "Сетевые протоколы и адресация", "src": "Информатика · 8–9 класс · Компьютерные сети", "ico": "🌐", "subj": "inf", "explain": ["Крючок: когда ты открываешь сайт, за секунды обмениваются данными тысячи компьютеров. Как они понимают друг друга и находят нужный адрес?", "Правило: протокол — это набор правил обмена данными в сети. У каждого устройства есть IP-адрес: у IPv4 — 4 числа через точки. У сайта — доменное имя с доменом верхнего уровня, например .ru или .com.", "Пример шагами: адрес 192.168.1.10 — это IPv4: числа 192, 168, 1 и 10, всего 4 числа. Адрес arhimed.ru: домен верхнего уровня — .ru, имя сайта — arhimed.", "Почему так: числовой IP-адрес понимают машины, а доменное имя удобно человеку; протоколы вроде HTTP задают, как браузер запрашивает веб-страницу и как сервер отвечает.", "Типичная ошибка: считать, что в IPv4-адресе 3 или 8 чисел. В IPv4 всегда ровно 4 числа от 0 до 255.", "Проверка: посчитай точки в адресе 192.168.0.1 — их 3, значит чисел 4, на одно больше числа точек.", "Совет: не путай: http — протокол передачи веб-страниц, а www — лишь часто встречающееся имя сервера сайта."], "check": {"q": "Сколько чисел содержит IPv4-адрес, например 192.168.1.1?", "choices": ["3", "4", "6", "8"], "ans": 1, "exp": "IPv4-адрес записывается как 4 числа, разделённых точками: 192.168.1.1. 3 — это число точек, а 6 и 8 — форматы других адресов, не IPv4."}, "tasks": [{"q": "Какой протокол использует браузер для получения веб-страниц?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["В начале адреса сайта стоит именно он: http://… или https://…"], "sol": "HTTP (и его защищённая версия HTTPS) — протокол передачи гипертекста, по которому браузер получает веб-страницы. FTP служит для передачи файлов, а SMTP — для отправки почты.", "choices": ["HTTP/HTTPS", "FTP", "SMTP", "POP3"]}, {"q": "В адресе сайта arhimed.ru какой домен верхнего уровня?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Домен верхнего уровня стоит в самом конце адреса, после последней точки."], "sol": ".ru — домен верхнего уровня (российская зона). arhimed — доменное имя второго уровня. www — служебное имя, а не домен.", "choices": [".ru", ".arhimed", "arhimed", "www"]}, {"q": "Что такое сетевой протокол?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Протокол отвечает на вопрос «как передавать данные», а не «куда» или «по чему»."], "sol": "Протокол — это согласованный набор правил обмена данными: как разбивать сообщения, как подтверждать получение, какой у них формат. Кабель, адрес и игры — другие понятия.", "choices": ["набор правил, по которым устройства обмениваются данными в сети", "вид сетевого кабеля", "адрес сайта в интернете", "программа для игр по сети"]}]},
  {"id": 234, "title": "Поиск информации в интернете", "src": "Информатика · 8–9 класс · Поиск информации", "ico": "🔍", "subj": "inf", "explain": ["Крючок: поисковик за доли секунды находит миллионы страниц. Чтобы среди них оказалось нужное, важно правильно сформулировать запрос.", "Правило: ключевые слова — самые важные слова темы. Фраза в кавычках «...» ищется как точная последовательность слов, идущих подряд.", "Пример шагами: запрос олимпиада по математике 2025 состоит из 4 слов: олимпиада, по, математике, 2025. Запрос «Книга знаний» в кавычках найдёт страницы именно с этой фразой, без перестановки слов.", "Почему так: поисковик сравнивает слова запроса со словами на страницах; кавычки отсекают лишние результаты, где нужные слова стоят в другом порядке.", "Типичная ошибка: писать целый вопрос («а где можно найти рецепт...») — каждое лишнее слово ухудшает выдачу.", "Проверка: посчитай слова в своём запросе — сколько слов указал, столько ключевых слов учитывает поиск.", "Совет: если результатов слишком много — добавь ещё одно точное слово или заключи ключевую фразу в кавычки."], "check": {"q": "Что произойдёт, если заключить фразу в кавычки — «Книга знаний»?", "choices": ["найдутся страницы, где слова стоят подряд именно в таком порядке", "кавычки будут удалены, и поиск не изменится", "найдутся синонимы этой фразы", "поиск станет заметно медленнее"], "ans": 0, "exp": "Кавычки задают поиск точной фразы: слова должны идти подряд в том же порядке. Без кавычек поисковик ищет слова по отдельности, поэтому выдача была бы шире."}, "tasks": [{"q": "Сколько слов в поисковом запросе олимпиада по математике 2025?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Посчитай слова, разделённые пробелами."], "sol": "Слова: олимпиада, по, математике, 2025 — всего 4."}, {"q": "Какие ключевые слова лучше всего подойдут для поиска рецепта блинов?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Ключевые слова — короткие и точно описывают тему запроса."], "sol": "Короткий точный запрос «рецепт блинов» даёт лучший результат: лишние слова вроде «а как приготовить...» мешают поисковику.", "choices": ["рецепт блинов", "а как приготовить вкусные блинчики на сковороде чтобы они не пригорали", "еда кухня завтрак", "что сегодня поесть"]}, {"q": "Зачем к запросу олимпиада по математике добавили слово 2025?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Дополнительное слово сужает выдачу до нужного года."], "sol": "Слово 2025 — уточняющее ключевое слово: поиск ограничится страницами, где упомянут нужный год, и старые объявления о прошлых олимпиадах отсеются.", "choices": ["чтобы уточнить год и отсечь старые страницы", "чтобы замедлить работу поисковика", "это слово поисковик всегда игнорирует", "чтобы найти больше картинок"]}]},
  {"id": 235, "title": "Кодирование и сжатие информации", "src": "Информатика · 8–9 класс · Кодирование информации", "ico": "💾", "subj": "inf", "explain": ["Крючок: компьютер хранит всё — числа, буквы, цвета — только как 0 и 1. Бит — это одна такая двоичная цифра.", "Правило: n бит могут закодировать 2ⁿ разных значений. Чтобы закодировать 256 оттенков, нужно 8 бит, ведь 2⁸ = 256.", "Пример шагами: для 16 цветов палитры нужно 4 бита, потому что 2⁴ = 16. Для двух цветов (чёрный и белый) хватает 1 бита: 2¹ = 2.", "Почему так: каждый добавленный бит удваивает число возможных кодов: 1 бит — 2 значения, 2 бита — 4, 3 бита — 8, 4 бита — 16.", "Типичная ошибка: путать число бит и число значений. Для 256 значений нужно 8 бит, а не 256: значения = 2^биты.", "Проверка: сверяй с формулой: 2⁸ = 256, 2⁴ = 16, 2¹ = 2. Если число значений не равно степени двойки — пересчитай.", "Совет: выучи степени двойки до 2¹⁰ = 1024: 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024 — они встречаются в информатике повсюду."], "check": {"q": "Сколько бит нужно, чтобы закодировать 256 различных значений, например оттенков серого?", "choices": ["4", "6", "8", "256"], "ans": 2, "exp": "Нужно найти n, при котором 2ⁿ = 256: это 8, потому что 2⁸ = 256. 4 бита дают лишь 16 значений, а 256 — число значений, а не бит."}, "tasks": [{"q": "Сколько бит нужно, чтобы закодировать 16 различных цветов?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Найди степень двойки, равную 16: 2ⁿ = 16."], "sol": "2⁴ = 16, значит достаточно 4 бит."}, {"q": "Сколько бит нужно, чтобы закодировать 2 цвета — чёрный и белый?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["2 — это 2¹."], "sol": "2¹ = 2: один бит хранит 0 или 1, чего хватает на два цвета."}, {"q": "Сколько различных значений можно закодировать 3 битами?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Подставь в формулу 2ⁿ: 2³ = ..."], "sol": "2³ = 8 значений: 000, 001, 010, 011, 100, 101, 110, 111."}]},
  {"id": 236, "title": "Информационная безопасность", "src": "Информатика · 8–9 класс · Информационная безопасность", "ico": "🛡️", "subj": "inf", "explain": ["Крючок: письмо «от банка» просит срочно подтвердить пароль — именно так начинаются кражи данных. Защититься можно, зная простые правила.", "Правило: шифрование превращает данные в код, понятный только владельцу ключа; антивирус находит и обезвреживает вредоносные программы; фишинг — мошенничество, выманивающее пароли через поддельные письма и сайты.", "Пример шагами: признаки фишингового письма: 1) незнакомый отправитель; 2) просьба сообщить пароль или номер карты; 3) ссылка с опечаткой в адресе сайта. Встретил хотя бы один — насторожись.", "Почему так: пароль и личные данные — ключ к аккаунтам и деньгам, поэтому мошенники давят на доверие и спешку жертвы.", "Типичная ошибка: считать, что антивирус защищает от всего. Главная защита — сам пользователь: не переходить по подозрительным ссылкам и не сообщать пароли.", "Проверка: перед вводом пароля проверь адрес сайта в строке браузера и наличие https и значка замка рядом с адресом.", "Совет: настоящий банк никогда не просит прислать пароль письмом или по ссылке — запомни это правило-маркер фишинга."], "check": {"q": "Что такое фишинг?", "choices": ["мошенничество, выманивающее пароли и личные данные через поддельные письма и сайты", "программа, шифрующая файлы на компьютере", "разновидность антивируса", "способ ускорения работы интернета"], "ans": 0, "exp": "Фишинг (от англ. fishing — «рыбная ловля») — вид мошенничества: жертву заманивают на поддельный сайт или вынуждают ответить на поддельное письмо, чтобы выманить пароли и данные карт. Антивирус и шифрование — средства защиты, а не фишинг."}, "tasks": [{"q": "В списке признаков подозрительного письма три пункта: 1) незнакомый отправитель, 2) просьба сообщить пароль, 3) ссылка с опечаткой в домене. Сколько всего признаков фишинга перечислено?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Просто посчитай пункты списка — все три являются признаками фишинга."], "sol": "Все 3 пункта — признаки фишинга: незнакомый отправитель, просьба о пароле и подозрительная ссылка. Наличие любого из них — повод не доверять письму."}, {"q": "Что помогает защитить компьютер от вредоносных программ?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Вспомни, какая программа проверяет файлы и ссылки на вирусы."], "sol": "Антивирус проверяет файлы и ссылки, а обновления закрывают уязвимости, через которые проникают вирусы. Сложный пароль защищает аккаунт, но не от вирусов.", "choices": ["антивирус и регулярные обновления системы", "отключение монитора на ночь", "сложный пароль от Wi-Fi", "удаление всех файлов с компьютера"]}, {"q": "Что делать, если в письме «от банка» просят срочно отправить пароль по ссылке?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Настоящие организации никогда не запрашивают пароли по почте."], "sol": "Это классический фишинг: банк не просит пароли по почте. Ссылку открывать нельзя, письмо лучше удалить и при желании сообщить о нём взрослым.", "choices": ["не переходить по ссылке и не сообщать пароль — это фишинг", "перейти по ссылке, чтобы проверить письмо", "отправить пароль, раз письмо срочное", "переслать письмо всем друзьям"]}]},
  {"id": 237, "title": "Python: функции", "src": "Информатика · 8–9 класс · Python: функции", "ico": "🐍", "subj": "inf", "explain": ["Крючок: одна и та же формула — например «удвоить число и прибавить 1» — нужна много раз. Функция позволяет написать её один раз и использовать где угодно.", "Правило: def f(x): return x * 2 + 1 — это определение функции: f — имя, x — параметр, return — команда вернуть результат.", "Пример шагами: вызов f(4): подставляем x = 4 → 4·2 = 8, затем 8 + 1 = 9. Функция вернула 9.", "Почему так: функция — это «машина»: на вход подаётся значение параметра, внутри выполняются команды, а return передаёт результат наружу, где его печатают или используют в вычислениях.", "Типичная ошибка: путать return и print. print только показывает значение на экране, а return передаёт его из функции; без return функция вернёт None.", "Проверка: подставь значение параметра в тело функции и выполни вычисления по шагам: сначала умножение, потом сложение.", "Совет: проверяй функцию на простых значениях: f(0) = 0·2 + 1 = 1 — удобно, ведь умножение на ноль упрощает счёт."], "check": {"q": "Дана функция: def f(x): return x * 2 + 1. Чему равно f(4)?", "choices": ["6", "8", "9", "10"], "ans": 2, "exp": "Подставляем 4 вместо x: 4·2 = 8, затем 8 + 1 = 9. 8 — только удвоение без прибавления 1, а 6 и 10 — результаты ошибочного порядка действий."}, "tasks": [{"q": "def f(x): return x * 2 + 1. Чему равно f(3)?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["3·2 = 6, потом прибавь 1."], "sol": "f(3) = 3·2 + 1 = 6 + 1 = 7."}, {"q": "def f(x): return x * 2 + 1. Чему равно f(0)?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["0·2 = 0 — умножение на ноль даёт ноль."], "sol": "f(0) = 0·2 + 1 = 0 + 1 = 1."}, {"q": "Какая команда в Python возвращает значение из функции?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Это слово стоит в теле функции перед выражением результата."], "sol": "return передаёт значение из функции тому, кто её вызвал. print лишь выводит текст на экран, def объявляет функцию, а input считывает ввод.", "choices": ["return", "print", "def", "input"]}]},
  {"id": 238, "title": "Python: списки и циклы", "src": "Информатика · 8–9 класс · Python: списки и циклы", "ico": "📋", "subj": "inf", "explain": ["Крючок: нужно сложить оценки за четверть или посчитать книги, прочитанные за месяц. Для хранения ряда значений в Python есть список.", "Правило: список — упорядоченный набор значений в квадратных скобках: nums = [1, 2, 3, 4]. Цикл for x in nums: выполняет тело для каждого элемента по очереди.", "Пример шагами: считаем сумму: s = 0; for x in [1, 2, 3, 4]: s = s + x. Проход: 0 + 1 = 1, +2 = 3, +3 = 6, +4 = 10 → s = 10.", "Почему так: цикл пробегает список от начала до конца, а переменная-накопитель s копит сумму — код работает для списка любой длины без ручного перечисления.", "Типичная ошибка: забыть s = 0 до цикла или записать s = s + x вне цикла — тогда в s попадёт только последний элемент.", "Проверка: число шагов цикла равно числу элементов списка: для 4 элементов будет 4 прибавления.", "Совет: проверяй на коротком списке: сумму [2, 4, 6] = 12 легко пересчитать в уме."], "check": {"q": "Что будет в переменной s после выполнения кода: s = 0; for x in [1, 2, 3, 4]: s = s + x?", "choices": ["4", "10", "1234", "24"], "ans": 1, "exp": "Цикл прибавляет каждый элемент по очереди: 1 + 2 + 3 + 4 = 10. 4 — число элементов, 1234 — «склейка» чисел как строк, 24 — произведение, а не сумма."}, "tasks": [{"q": "Чему равна сумма элементов списка [2, 4, 6]?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Складывай по порядку: 2 + 4 = 6, затем + 6."], "sol": "2 + 4 + 6 = 12."}, {"q": "Сколько элементов в списке [7, 1, 9, 3, 5]?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Посчитай значения, разделённые запятыми, внутри квадратных скобок."], "sol": "Элементы: 7, 1, 9, 3, 5 — всего 5. Команда len([7, 1, 9, 3, 5]) вернёт 5."}, {"q": "Сколько раз выполнится тело цикла for x in [10, 20, 30]:?", "kind": "choice", "ans": 2, "tol": 0, "hints": ["Цикл выполняется по одному разу на каждый элемент списка."], "sol": "В списке 3 элемента — 10, 20, 30, поэтому тело цикла выполнится ровно 3 раза.", "choices": ["1", "2", "3", "ни разу"]}]},
  {"id": 239, "title": "Python: строки", "src": "Информатика · 8–9 класс · Python: строки", "ico": "🔤", "subj": "inf", "explain": ["Крючок: имя пользователя, название книги, текст сообщения — в Python это строки. Как узнать их длину и соединить две строки?", "Правило: строка — это текст в кавычках, например «АРХИМЕД». Команда len(s) возвращает число символов строки, а оператор + склеивает строки (конкатенация).", "Пример шагами: len(«АРХИМЕД»): считаем символы А, Р, Х, И, М, Е, Д — ровно 7. А «А» + «Б» даёт «АБ»: строки просто записываются друг за другом.", "Почему так: каждый символ строки имеет свою позицию, поэтому len пересчитывает символы по одному; конкатенация строит новую строку из двух исходных без добавления пробела.", "Типичная ошибка: считать, что + вставит пробел или что len считает слова. Пробел сам является символом: len(«А Б») = 3.", "Проверка: проверяй длину, записав строку по символам в столбик, как в примере с «АРХИМЕД».", "Совет: будь внимателен: в Python «1» + «2» даст «12» (строку), а не число 3 — для строк + склеивает, а не складывает."], "check": {"q": "Чему равно len(«АРХИМЕД»)?", "choices": ["6", "7", "8", "1"], "ans": 1, "exp": "В слове АРХИМЕД семь символов: А-Р-Х-И-М-Е-Д. 6 получилось бы для слова без последней буквы, 8 — с лишним символом, а 1 — если посчитать слово целиком за один символ."}, "tasks": [{"q": "Чему равно len(«Python»)?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Посчитай буквы: P-y-t-h-o-n."], "sol": "6 символов: P, y, t, h, o, n."}, {"q": "Какая строка получится в результате «А» + «Б»?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["+ для строк просто записывает вторую строку сразу после первой, без пробела."], "sol": "«А» + «Б» = «АБ». «БА» получилось бы при сложении в обратном порядке, пробел сам не добавляется, ошибки нет.", "choices": ["«АБ»", "«А + Б»", "«БА»", "ошибка"]}, {"q": "Сколько символов в строке, которая получится после склейки «А» и «Б»?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["В каждой из исходных строк по одному символу, при склейке они сохраняются оба."], "sol": "«А» + «Б» = «АБ» — строка из 2 символов, то есть len(«АБ») = 2."}]},
  {"id": 240, "title": "Вложенные условия и логические операторы", "src": "Информатика · 8–9 класс · Условия", "ico": "🔗", "subj": "inf", "explain": ["В программах условия соединяют операторами: and (И), or (ИЛИ), not (НЕ).", "and — истина, только если обе части истинны; or — если хотя бы одна; not — переворачивает.", "Пример: (5 > 3) and (2 < 4): обе части истинны → True.", "Пример: (7 > 10) or (3 > 1): вторая истинна → True.", "Ловушка: not(4 == 4) = False — НЕ от истины даёт ложь.", "Совет Архимеда: считай по частям: сначала скобки, потом not, потом and/or."], "check": {"q": "Чему равно (5 > 3) and (2 < 4)?", "choices": ["True", "False"], "ans": 0, "exp": "5 > 3 — истина и 2 < 4 — истина, значит and даёт True."}, "tasks": [{"q": "Чему равно (7 > 10) or (3 > 1)? (1 — True, 0 — False)", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Проверь вторую часть: 3 > 1.", "Истина → or даёт True (1)."], "sol": "(7>10) — ложь, но (3>1) — истина; or → True (1)."}, {"q": "Чему равно not (4 == 4)?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["4 == 4 — истина.", "not переворачивает → False."], "sol": "not(True) = False.", "choices": ["True", "False"]}]},
  {"id": 241, "title": "Типы ошибок в программах", "src": "Информатика · 8–9 класс · Ошибки", "ico": "🐞", "subj": "inf", "explain": ["Ошибки программ делят на три типа: синтаксические, логические и ошибки времени выполнения.", "СИНТАКСИЧЕСКАЯ: нарушены правила языка (забыли двоеточие, скобку) — программа не запустится.", "ЛОГИЧЕСКАЯ: программа работает, но делает не то (перепутали + и −) — самый коварный тип.", "ОШИБКА ВРЕМЕНИ ВЫПОЛНЕНИЯ: возникает во время работы (деление на ноль, выход за границы списка).", "Почему важно различать? Разные типы ищут по-разному: синтаксис ловит редактор, логику — тесты.", "Совет Архимеда: сначала добейся запуска (синтаксис), потом правильности (логика)."], "check": {"q": "Программа забыла двоеточие после if. Какой это тип ошибки?", "choices": ["Синтаксическая", "Логическая", "Времени выполнения"], "ans": 0, "exp": "Нарушено правило языка — синтаксическая ошибка, программа не запустится."}, "tasks": [{"q": "Сколько типов ошибок программ названо в уроке?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Перечисли типы.", "Синтаксические, логические, времени выполнения."], "sol": "Три типа ошибок."}, {"q": "Программа выводит 6 вместо 8, потому что перепутаны знаки. Какой это тип ошибки?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Программа работает, но неверно.", "Это логическая ошибка."], "sol": "Программа запускается, но считает неверно — логическая ошибка.", "choices": ["Логическая", "Синтаксическая", "Времени выполнения"]}]},
  {"id": 242, "title": "Отладка и тестирование", "src": "Информатика · 8–9 класс · Отладка", "ico": "🔧", "subj": "inf", "explain": ["ОТЛАДКА — поиск и исправление ошибок. Это навык, которому учатся, как и программированию.", "Шаги отладки: 1) предскажи, что должно быть; 2) пройди программу по шагам; 3) исправь ОДНУ ошибку; 4) проверь снова.", "ТЕСТИРОВАНИЕ — проверка на разных входных данных (тест-кейсах).", "Пример: ветвление с 2 условиями даёт 4 случая (обе истинны, первая да/вторая нет и т.д.) — нужно 4 теста.", "Почему не «компьютер ошибся»? Ошибся автор программы — и это нормально, ошибка — подсказка.", "Совет Архимеда: исправляй по одной ошибке и сразу проверяй — так проще понять, что изменилось."], "check": {"q": "Сколько тестов нужно, чтобы проверить ветвление с двумя независимыми условиями (все комбинации истина/ложь)?", "choices": ["2", "4", "6"], "ans": 1, "exp": "Комбинации: ИИ, ИЛ, ЛИ, ЛЛ — 4 теста."}, "tasks": [{"q": "Сколько тестов нужно, чтобы проверить одно условие (обе ветки)?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Какие варианты у одного условия?", "Истина и ложь — 2 теста."], "sol": "Два теста: условие истинно и ложно."}, {"q": "Что делать, если программа выдала неверный результат?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Кто автор результата?", "Программу написал человек — ищем ошибку в ней."], "sol": "Проходим по шагам и исправляем ошибку — это отладка.", "choices": ["Сказать «компьютер ошибся»", "Пройти по шагам и найти ошибку в программе", "Удалить программу"]}]},
  {"id": 243, "title": "Поиск максимума алгоритмом", "src": "Информатика · 8–9 класс · Алгоритмы", "ico": "🏆", "subj": "inf", "explain": ["Задача: найти наибольшее из чисел. Алгоритм: держим текущий максимум и сравниваем с каждым следующим.", "Для двух чисел нужно 1 сравнение; для трёх — 2 (первое со вторым, затем большее с третьим).", "Пример: 5, 9, 4: максимум = 5; сравниваем 5 и 9 → 9; сравниваем 9 и 4 → 9. Два сравнения.", "Почему N − 1? Каждое сравнение «вычёркивает» одного неудачника, чемпион остаётся один.", "Совет Архимеда: для N чисел максимум находится за N − 1 сравнение."], "check": {"q": "Сколько сравнений нужно, чтобы найти максимум среди 3 чисел?", "choices": ["2", "3", "1"], "ans": 0, "exp": "N − 1 = 3 − 1 = 2 сравнения."}, "tasks": [{"q": "Сколько сравнений нужно, чтобы найти максимум среди 2 чисел?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["N − 1 = 2 − 1.", "= 1."], "sol": "2 − 1 = 1 сравнение."}, {"q": "Найди максимум: 5, 9, 4. Что получится?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Сравни 5 и 9, потом с 4.", "9 — максимум."], "sol": "max(5,9,4) = 9.", "choices": ["9", "5", "4"]}]},
  {"id": 244, "title": "Рекурсия: факториал", "src": "Информатика · 8–9 класс · Рекурсия", "ico": "🌀", "subj": "inf", "explain": ["Факториал n! — произведение чисел от 1 до n: 3! = 1·2·3 = 6.", "Рекурсия — когда функция вызывает саму себя: n! = n · (n−1)!.", "Разберём 3!: 3! = 3 · 2! = 3 · (2 · 1!) = 3 · (2 · 1) = 6.", "Почему это работает? Каждый вызов сводит задачу к меньшей, пока не дойдём до базы 1! = 1.", "Ловушка: без базового случая рекурсия зациклится навсегда.", "Совет Архимеда: всегда проверяй маленькие значения: 2! = 2, 3! = 6, 4! = 24."], "check": {"q": "Чему равен факториал 3 (3!)?", "choices": ["6", "3", "9"], "ans": 0, "exp": "3! = 1·2·3 = 6."}, "tasks": [{"q": "Чему равен факториал 4 (4!)?", "kind": "unit", "ans": 24, "tol": 0, "hints": ["1·2·3·4.", "= 24."], "sol": "4! = 1·2·3·4 = 24."}, {"q": "Чему равен факториал 2 (2!)?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["1·2.", "= 2."], "sol": "2! = 1·2 = 2.", "choices": ["2", "4", "1"]}]},
  {"id": 245, "title": "Электронные таблицы: SUM и среднее", "src": "Информатика · 8–9 класс · Таблицы", "ico": "📊", "subj": "inf", "explain": ["Электронная таблица (Excel, Google Sheets) хранит данные в ячейках: A1, B2… Каждая ячейка — пересечение столбца и строки.", "Формулы начинаются со знака «=». Функция SUM складывает диапазон: =SUM(A1:A5).", "Пример: в ячейках 2, 3, 4, 5, 6 → SUM = 20.", "Среднее можно найти как =AVERAGE или суммой, делённой на количество: (2+4+6):3 = 4.", "Ловушка: не путай сумму и среднее: сумму делят на число значений.", "Совет Архимеда: сначала посчитай в уме, потом сверь с формулой."], "check": {"q": "Чему равна сумма чисел 2, 3, 4, 5, 6?", "choices": ["20", "21", "18"], "ans": 0, "exp": "2+3+4+5+6 = 20."}, "tasks": [{"q": "Чему равно среднее чисел 2, 4 и 6?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Сумма : количество.", "(2+4+6):3 = 12:3 = 4."], "sol": "(2 + 4 + 6) : 3 = 4."}, {"q": "Чему равна сумма чисел 10 и 20?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Просто сложи.", "10 + 20 = 30."], "sol": "10 + 20 = 30.", "choices": ["30", "15", "200"]}]},
  {"id": 246, "title": "Моделирование и численный эксперимент", "src": "Информатика · 8–9 класс · Моделирование", "ico": "🧪", "subj": "inf", "explain": ["МОДЕЛЬ — упрощённое описание реального объекта. Компьютерное моделирование — «эксперимент» на модели.", "Пример: модель роста популяции кроликов: каждый год число удваивается. Запустили на 3 года: 2→4→8→16.", "Прогон модели с разными числами называют численным экспериментом.", "Почему модели? Опасно или долго экспериментировать с реальностью — проще на модели.", "Ловушка: модель — упрощение; выводы модели надо проверять на практике.", "Совет Архимеда: меняй одно число за раз и сравнивай результаты — так видно, что на что влияет."], "check": {"q": "Модель: каждый год число кроликов удваивается. Было 2. Сколько станет через 3 года (после трёх удвоений)?", "choices": ["16", "8", "6"], "ans": 0, "exp": "2 → 4 → 8 → 16 (три удвоения)."}, "tasks": [{"q": "Число удваивается каждый год. Было 3. Сколько станет через 1 год?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Удвоить — умножить на 2.", "3 · 2 = 6."], "sol": "3 · 2 = 6."}, {"q": "Зачем строить компьютерные модели?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["Какая польза эксперимента на модели?", "Быстро, дёшево и безопасно."], "sol": "Модели позволяют безопасно и быстро проверять сценарии «что если».", "choices": ["Чтобы не рисковать в реальности и быстро проверять «что если»", "Чтобы компьютер был занят", "Чтобы не думать"]}]},
  {"id": 247, "title": "Большие данные и единицы", "src": "Информатика · 8–9 класс · Данные", "ico": "🗄", "subj": "inf", "explain": ["Большие данные (big data) — огромные массивы, которые обрабатывают программы.", "Объёмы измеряют в байтах и крупных единицах: 1 Кбайт = 1024 байта, 1 Мбайт = 1024 Кбайт, 1 Гбайт = 1024 Мбайт.", "Пример: файл 3 Кбайт = 3 · 1024 = 3072 байта.", "Почему 1024? Компьютер работает степенями двойки: 2¹⁰ = 1024.", "Совет Архимеда: при переводе вниз умножаем на 1024, вверх — делим."], "check": {"q": "Сколько байт в 1 Кбайте?", "choices": ["1000", "1024", "10240"], "ans": 1, "exp": "1 Кбайт = 1024 байта (2¹⁰)."}, "tasks": [{"q": "Сколько байт в 2 Кбайтах?", "kind": "unit", "ans": 2048, "tol": 0, "hints": ["Умножь на 1024.", "2 · 1024 = 2048."], "sol": "2 · 1024 = 2048 байт."}, {"q": "Сколько Кбайт в 1 Мбайте?", "kind": "choice", "ans": 1, "tol": 0, "hints": ["Как и Кбайт в Мбайте?", "1024."], "sol": "1 Мбайт = 1024 Кбайт.", "choices": ["1000", "1024", "2048"]}]},
  {"id": 248, "title": "Повторение: системы счисления и логика", "src": "Информатика · 8–9 класс · Повторение", "ico": "🔁", "subj": "inf", "explain": ["Повторим главное: двоичные числа читаем по разрядам 8 4 2 1.", "1101₂ = 8 + 4 + 1 = 13.", "В логике: A И (НЕ A) всегда ложь — высказывание и его отрицание не могут быть истинны вместе.", "Шестнадцатеричная система: 15₁₀ = F₁₆.", "Совет Архимеда: перед экзаменом повтори переводы и таблицу A–F."], "check": {"q": "Чему равно 1101₂ в десятичной системе?", "choices": ["11", "13", "15"], "ans": 1, "exp": "1101₂ = 8 + 4 + 0 + 1 = 13."}, "tasks": [{"q": "Чему равно A И (НЕ A), если A — любое высказывание? (1 — истина, 0 — ложь)", "kind": "unit", "ans": 0, "tol": 0, "hints": ["Что будет, если A истинно? НЕ A ложно.", "Истина и ложь вместе не бывают — всегда ложь."], "sol": "A И (НЕ A) = ложь всегда."}, {"q": "Чему равно 15 в шестнадцатеричной системе?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["F = 15.", "→ F₁₆."], "sol": "15₁₀ = F₁₆.", "choices": ["F₁₆", "15₁₆", "E₁₆"]}]},
  {"id": 249, "title": "Итоговый урок информатики", "src": "Информатика · 8–9 класс · Итоговый урок", "ico": "🎓", "subj": "inf", "explain": ["Соберём всё: единицы (1 байт = 8 бит), системы счисления, логику и алгоритмы.", "Проверь себя цепочкой: 2 байта = 16 бит; 101₂ + 1₂ = 110₂ (5 + 1 = 6); 3! = 6.", "Каждый навык проверяется обратным действием: перевод — обратным переводом, программа — тестами.", "Совет Архимеда: если что-то забыл — вернись к уроку темы: повторение закрепляет."], "check": {"q": "Сколько бит в 2 байтах?", "choices": ["16", "8", "20"], "ans": 0, "exp": "1 байт = 8 бит; 2 · 8 = 16."}, "tasks": [{"q": "Чему равно 101₂ + 1₂? (запиши без индекса)", "kind": "unit", "ans": 110, "tol": 0, "hints": ["5 + 1 = 6.", "6 = 110₂."], "sol": "101₂ + 1₂ = 110₂."}, {"q": "Чему равен 3! (факториал трёх)?", "kind": "choice", "ans": 0, "tol": 0, "hints": ["1·2·3.", "= 6."], "sol": "3! = 1 · 2 · 3 = 6.", "choices": ["6", "3", "9"]}]}
];
